def _dup_guard_enabled() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_GUARD", True)


def _dup_guard_fail_on_unresolved() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_GUARD_FAIL_ON_UNRESOLVED", True)


def _dup_guard_write_events() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_WRITE_EVENTS", True)


def _dup_guard_allow_bip30() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_ALLOW_BIP30", True)


def _dup_guard_auto_resolve() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_AUTO_RESOLVE", True)


def _dup_guard_require_canonical_proof() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_REQUIRE_CANONICAL_PROOF", True)


def _dup_guard_canonical_source() -> str:
    source = (_env_str("UTXO_REPLAY_DUP_CANONICAL_SOURCE", "off") or "off").strip().lower()
    if source not in {"off", "bitcoin_cli", "esplora"}:
        raise SystemExit("ERROR: UTXO_REPLAY_DUP_CANONICAL_SOURCE must be off, bitcoin_cli, or esplora")
    return source


def _dup_guard_block_filter() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_BLOCK_FILTER", True)


def _dup_guard_block_filter_always() -> bool:
    # Operational policy — intentionally configurable, not an accidental bypass.
    #
    # A full historical REBUILD can contain hundreds of thousands of blocks.
    # Verifying every block through a public Esplora endpoint is not operationally
    # feasible on large ranges: public services limit request volume and may rate
    # limit or temporarily block the client, while one HTTP lookup per block also
    # multiplies total calculation time. Therefore ALWAYS=0 means: keep duplicate
    # detection enabled, but request canonical block hashes only on days where the
    # existing duplicate guard actually finds duplicate transaction evidence.
    #
    # This does NOT disable UTXO_REPLAY_DUP_BLOCK_FILTER. On a duplicate-bearing
    # day, canonical lookup, atomic created/spends/block_meta filtering, lookup
    # coverage checks and fail-closed unresolved handling remain unchanged.
    return _env_bool("UTXO_REPLAY_DUP_BLOCK_FILTER_ALWAYS", True)


def _dup_guard_canonical_proof_scope() -> str:
    return (
        CANONICAL_PROOF_SCOPE_ALL_BLOCKS
        if _dup_guard_block_filter_always()
        else CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED
    )


def _dup_guard_scope_from_report(duplicate_guard: Dict[str, Any]) -> str:
    scope = str(duplicate_guard.get("canonical_proof_scope") or "").strip().upper()
    if scope in {CANONICAL_PROOF_SCOPE_ALL_BLOCKS, CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED}:
        return scope
    return (
        CANONICAL_PROOF_SCOPE_ALL_BLOCKS
        if duplicate_guard.get("block_filter_always") is True
        else CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED
    )


def _txid_map_canonical_block_filter() -> bool:
    return _env_bool("UTXO_TXID_MAP_CANONICAL_BLOCK_FILTER", True)


def _dup_guard_allow_unproven_modern() -> bool:
    return _env_bool("UTXO_REPLAY_DUP_ALLOW_UNPROVEN_MODERN", False)


def _stage_only_allow_blocked() -> bool:
    return _env_bool("UTXO_STAGE_ONLY_ALLOW_BLOCKED", True)


def _dup_guard_known_bip30_txids() -> set:
    default = (
        "e3bf3d07d4b0375638d5f1db5255fe07ba2c4cb067cd81b84ee974b6585fb468,"
        "d5d27987d2a3dfc724e359870c6644b40e497bdc0589a033220fe15429d88599"
    )
    raw = _env_str("UTXO_REPLAY_DUP_BIP30_KNOWN_TXIDS", default) or default
    return {x.strip().lower() for x in raw.split(",") if x.strip()}


