def _update_existing_json_no_create(path: Path, patch: Dict[str, Any], *, label: str) -> bool:
    """Update an existing JSON artifact only; never create synthetic artifacts."""
    if not path.exists():
        return False
    try:
        with open(path, "r", encoding="utf-8") as f:
            payload = json.load(f)
        if not isinstance(payload, dict):
            _warn(f"existing {label} update skipped path={path}: JSON root is not an object")
            return False
        payload = _deep_merge(payload, patch)
        payload["updated_at"] = _now_iso()
        _save_json_atomic(path, payload)
        return True
    except Exception as e:
        _warn(f"existing {label} update failed path={path}: {type(e).__name__}: {e}")
        return False


def _update_existing_manifest_no_create(day: str, patch: Dict[str, Any]) -> bool:
    """Update an existing stage manifest only; never create synthetic manifests."""
    return _update_existing_json_no_create(_manifest_path_no_create(day), patch, label=f"stage manifest day={day}")


def _update_existing_txid_map_manifest_no_create(day: str, patch: Dict[str, Any]) -> bool:
    """Update an existing txid-map manifest only; never create synthetic manifests."""
    return _update_existing_json_no_create(_txid_map_manifest_path_no_create(day), patch, label=f"txid_map manifest day={day}")


def _is_controlled_stop_reason(reason: str) -> bool:
    """True only for STOP-file controlled-stop reasons, not max-days/stop-after-day limits."""
    return str(reason or "").startswith("CONTROLLED_STOP ")


def _file_sha256_streaming(path: Path, chunk_size: int = 1024 * 1024) -> str:
    """Streaming SHA256 to avoid reading large or malformed STOP files into memory."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            h.update(chunk)
    return h.hexdigest()


def _read_json_regular_file_snapshot(path: Path) -> Tuple[Dict[str, Any], str, Dict[str, Any]]:
    """Read, hash and parse exactly one stable regular-file byte snapshot."""
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(str(path), flags)
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode):
            raise RuntimeError(f"JSON snapshot source is not a regular file: {path}")
        chunks: List[bytes] = []
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    if identity_before != identity_after:
        raise RuntimeError(
            f"JSON snapshot changed during read: path={path} "
            f"before={identity_before} after={identity_after}"
        )
    data = b"".join(chunks)
    if len(data) != int(after.st_size):
        raise RuntimeError(
            f"JSON snapshot size mismatch: path={path} read={len(data)} stat={after.st_size}"
        )
    payload = json.loads(data.decode("utf-8"))
    if not isinstance(payload, dict):
        raise TypeError("JSON snapshot is not an object")
    sha256 = hashlib.sha256(data).hexdigest()
    snapshot = {
        "path": str(path),
        "exists": True,
        "regular_file": True,
        "device": int(after.st_dev),
        "inode": int(after.st_ino),
        "size": int(after.st_size),
        "mtime_ns": int(after.st_mtime_ns),
        "sha256": sha256,
    }
    return payload, sha256, snapshot


def _controlled_stop_max_bytes() -> int:
    """Return STOP hash size policy. 0 disables hashing; -1 means explicit dangerous unbounded hash."""
    raw = _env_int("UTXO_CONTROLLED_STOP_MAX_BYTES", 1024 * 1024)
    if raw < 0:
        if _env_bool("UTXO_CONTROLLED_STOP_ALLOW_UNBOUNDED_HASH", False):
            _warn(
                "DANGEROUS: UTXO_CONTROLLED_STOP_MAX_BYTES is negative and "
                "UTXO_CONTROLLED_STOP_ALLOW_UNBOUNDED_HASH=1; STOP file hashing is unbounded"
            )
            return -1
        _warn(
            f"invalid negative UTXO_CONTROLLED_STOP_MAX_BYTES={raw}; "
            "STOP content hashing will be disabled. Set a positive byte limit for production."
        )
        return 0
    return raw


def _controlled_stop_request_payload(stop_file: Path) -> Dict[str, Any]:
    """Return safe STOP-file metadata without persisting user-provided content."""
    max_bytes = _controlled_stop_max_bytes()
    payload: Dict[str, Any] = {
        "stop_file": str(stop_file),
        "exists": stop_file.exists(),
        "mtime": None,
        "size_bytes": None,
        "content_sha256": None,
        "content_hash_mode": "sha256_streaming_regular_file",
        "max_bytes": int(max_bytes),
        "is_regular_file": None,
        "is_symlink": None,
        "hash_skipped_reason": None,
    }
    if not stop_file.exists():
        return payload
    try:
        st = stop_file.lstat()
        payload["mtime"] = datetime.fromtimestamp(st.st_mtime, timezone.utc).replace(microsecond=0).isoformat()
        payload["size_bytes"] = int(st.st_size)
        payload["is_symlink"] = bool(stat.S_ISLNK(st.st_mode))
        payload["is_regular_file"] = bool(stat.S_ISREG(st.st_mode))
    except Exception as e:
        payload["stat_error"] = f"{type(e).__name__}: {e}"
        payload["hash_skipped_reason"] = "stat_failed"
        return payload

    if payload.get("is_symlink"):
        payload["hash_skipped_reason"] = "not_regular_file:symlink"
        return payload
    if not payload.get("is_regular_file"):
        payload["hash_skipped_reason"] = "not_regular_file"
        return payload
    if max_bytes == 0:
        payload["content_hash_mode"] = "hash_disabled_by_max_bytes_0"
        payload["hash_skipped_reason"] = "hash_disabled_by_max_bytes_0"
        return payload
    if max_bytes > 0 and int(payload.get("size_bytes") or 0) > max_bytes:
        payload["hash_skipped_reason"] = f"size_exceeds_max_bytes:{max_bytes}"
        return payload
    try:
        payload["content_sha256"] = _file_sha256_streaming(stop_file)
    except Exception as e:
        payload["hash_error"] = f"{type(e).__name__}: {e}"
    return payload

def _write_controlled_stop_report_no_create(day: str, report: Dict[str, Any]) -> bool:
    """Write controlled-stop metadata to the relevant existing manifest, if any."""
    mode = _CURRENT_MODE or ""
    if mode in {MODE_TXID_MAP_ONLY, MODE_TXID_MAP_AUDIT_ONLY}:
        return _update_existing_txid_map_manifest_no_create(day, {"controlled_stop": report})
    return _update_existing_manifest_no_create(day, {"controlled_stop": report})


def _consume_controlled_stop_file(stop_file: Path) -> Optional[str]:
    if not _controlled_stop_consume_enabled():
        return None
    if not stop_file.exists():
        return None
    ts = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    target = stop_file.with_name(f"{stop_file.name}.consumed.{ts}.{os.getpid()}")
    i = 0
    while target.exists():
        i += 1
        target = stop_file.with_name(f"{stop_file.name}.consumed.{ts}.{os.getpid()}.{i}")
    try:
        stop_file.rename(target)
        return str(target)
    except FileNotFoundError:
        return None
    except Exception as e:
        _warn(f"controlled stop consume failed stop_file={stop_file}: {type(e).__name__}: {e}")
        return None


def _controlled_stop_grace_ms() -> int:
    raw = max(0, _env_int("UTXO_CONTROLLED_STOP_GRACE_MS", 100))
    max_ms = max(0, _env_int("UTXO_CONTROLLED_STOP_GRACE_MAX_MS", 1000))
    if max_ms > 0 and raw > max_ms:
        _warn(
            f"controlled stop grace clamped: requested={raw}ms "
            f"max={max_ms}ms via UTXO_CONTROLLED_STOP_GRACE_MAX_MS"
        )
        return max_ms
    return raw


def _controlled_stop_postcheck(
    day: str,
    next_day: Optional[str],
    *,
    reason: str,
    consumed_path: Optional[str] = None,
) -> Dict[str, Any]:
    """Warning-only operator diagnostics after a controlled stop request.

    v10_17_8_2: mode-aware, path-only checks. This function does not query the
    production DuckDB, does not create stage directories, and does not create a
    synthetic stage/txid-map manifest if the real artifact is missing/unreadable.
    """
    warnings: List[str] = []
    mode = _CURRENT_MODE or "<unknown>"
    txmap_mode = mode in {MODE_TXID_MAP_ONLY, MODE_TXID_MAP_AUDIT_ONLY}
    report: Dict[str, Any] = {
        "day": str(day),
        "next_day": str(next_day) if next_day else None,
        "mode": mode,
        "reason": str(reason),
        "consumed_path": consumed_path,
        "warnings": warnings,
        "checked_at": _now_iso(),
        "manifest_update_written": False,
    }

    manifest_loaded = False
    txmap_manifest_loaded = False
    manifest = None

    stage_manifest_path = _manifest_path_no_create(day)
    report["stage_manifest_path"] = str(stage_manifest_path)

    if txmap_mode:
        txmap_manifest_path = _txid_map_manifest_path_no_create(day)
        report["txid_map_manifest_path"] = str(txmap_manifest_path)
        if txmap_manifest_path.exists():
            try:
                txmap_manifest = json.loads(txmap_manifest_path.read_text(encoding="utf-8"))
                txmap_manifest_loaded = True
                report["txid_map_manifest_status"] = txmap_manifest.get("status")
                report["txid_map_manifest_partial"] = txmap_manifest.get("partial")
                report["txid_map_manifest_updated_at"] = txmap_manifest.get("updated_at")
                if txmap_manifest.get("status") != "ok":
                    warnings.append(f"txid_map_manifest_status_not_ok:{txmap_manifest.get('status')}")
                if bool(txmap_manifest.get("partial")):
                    warnings.append("txid_map_manifest_partial")
            except Exception as e:
                warnings.append(f"txid_map_manifest_unreadable:{type(e).__name__}: {e}")
        else:
            warnings.append("txid_map_manifest_missing")
    else:
        if stage_manifest_path.exists():
            try:
                with open(stage_manifest_path, "r", encoding="utf-8") as f:
                    manifest = json.load(f)
                manifest_loaded = True
            except Exception as e:
                warnings.append(f"manifest_unreadable:{type(e).__name__}: {e}")
        else:
            warnings.append("manifest_missing")

        if manifest_loaded and manifest is not None:
            status = str(manifest.get("status") or "")
            audit = manifest.get("audit") if isinstance(manifest.get("audit"), dict) else {}
            purge = manifest.get("purge") if isinstance(manifest.get("purge"), dict) else {}
            report["manifest_status"] = status
            report["audit_status"] = audit.get("status")
            report["audit_failed_count"] = len(audit.get("failed_checks") or []) if isinstance(audit.get("failed_checks"), list) else None
            report["purge"] = {
                "eligible": bool(purge.get("eligible", False)),
                "purged": bool(purge.get("purged", False)),
                "created_parquet_deleted": bool(purge.get("created_parquet_deleted", False)),
                "spends_parquet_deleted": bool(purge.get("spends_parquet_deleted", False)),
            }

            dangerous_statuses = {
                STATUS_BUILDING,
                STATUS_CLEANUP_CHECK,
                STATUS_CLEANUP_SPENT,
                STATUS_CLEANUP_CREATED,
                STATUS_CLEANUP_VERIFY,
                STATUS_READY,
                STATUS_APPLYING,
                STATUS_APPLIED,
                STATUS_FAILED,
                STATUS_AUDIT_FAIL,
                STATUS_BLOCKED_BEFORE_APPLY,
            }
            if status in dangerous_statuses:
                warnings.append(f"completed_day_manifest_status_suspicious:{status}")

            if mode in {MODE_REPLAY_DAY, MODE_STAGE_APPLY_AND_AUDIT_DAY, MODE_AUDIT_ONLY}:
                if audit:
                    if audit.get("status") != "ok":
                        warnings.append(f"completed_day_audit_status_not_ok:{audit.get('status')}")
                    failed_checks = audit.get("failed_checks") or []
                    if failed_checks:
                        warnings.append("completed_day_audit_failed_checks:" + ",".join(map(str, failed_checks[:20])))
                elif mode in {MODE_REPLAY_DAY, MODE_STAGE_APPLY_AND_AUDIT_DAY}:
                    warnings.append("completed_day_audit_missing")

            if bool(purge.get("eligible", False)):
                created_path = _created_stage_path_no_create(day)
                spends_path = _spends_stage_path_no_create(day)
                created_exists = created_path.exists()
                spends_exists = spends_path.exists()
                report["purge_artifacts"] = {
                    "created_path": str(created_path),
                    "created_exists": bool(created_exists),
                    "spends_path": str(spends_path),
                    "spends_exists": bool(spends_exists),
                }
                if created_exists:
                    warnings.append("created_stage_parquet_still_exists_after_purge")
                if spends_exists:
                    warnings.append("spends_stage_parquet_still_exists_after_purge")

    if next_day:
        if txmap_mode:
            next_txmap_dir = _txid_map_root_path_no_create() / f"date={next_day}"
            next_exists = next_txmap_dir.exists()
            next_manifest_path = next_txmap_dir / "manifest.json"
            next_info: Dict[str, Any] = {
                "path": str(next_txmap_dir),
                "exists": bool(next_exists),
                "manifest_path": str(next_manifest_path),
                "manifest_exists": next_manifest_path.exists(),
            }
            if next_manifest_path.exists():
                try:
                    next_manifest = json.loads(next_manifest_path.read_text(encoding="utf-8"))
                    next_info.update(
                        {
                            "status": next_manifest.get("status"),
                            "partial": next_manifest.get("partial"),
                            "updated_at": next_manifest.get("updated_at"),
                        }
                    )
                except Exception as e:
                    next_info["read_error"] = f"{type(e).__name__}: {e}"
            report["next_day_txid_map_dir"] = next_info
            if next_exists:
                warnings.append("possible_stale_or_unexpected_next_day_txid_map_dir_exists")
        else:
            next_stage_dir = _stage_day_dir_path_no_create(next_day)
            next_exists = next_stage_dir.exists()
            next_manifest_path = next_stage_dir / "manifest.json"
            next_info = {
                "path": str(next_stage_dir),
                "exists": bool(next_exists),
                "manifest_path": str(next_manifest_path),
                "manifest_exists": next_manifest_path.exists(),
            }
            if next_manifest_path.exists():
                try:
                    next_manifest = json.loads(next_manifest_path.read_text(encoding="utf-8"))
                    next_info.update(
                        {
                            "status": next_manifest.get("status"),
                            "pid": next_manifest.get("pid"),
                            "updated_at": next_manifest.get("updated_at"),
                        }
                    )
                except Exception as e:
                    next_info["read_error"] = f"{type(e).__name__}: {e}"
            report["next_day_stage_dir"] = next_info
            if next_exists:
                warnings.append("possible_stale_or_unexpected_next_day_stage_dir_exists")

    for warning in warnings:
        _warn(f"CONTROLLED_STOP postcheck warning day={day}: {warning}")
    _log(
        f"CONTROLLED_STOP postcheck day={day} next_day={next_day or '<none>'} "
        f"mode={mode} warnings={len(warnings)} reason={reason}"
    )

    manifest_report = dict(report)
    manifest_report["manifest_update_written"] = True
    update_ok = False
    if txmap_mode and txmap_manifest_loaded:
        update_ok = _update_existing_txid_map_manifest_no_create(day, {"controlled_stop_postcheck": manifest_report})
    elif (not txmap_mode) and manifest_loaded:
        update_ok = _update_existing_manifest_no_create(day, {"controlled_stop_postcheck": manifest_report})
    report["manifest_update_written"] = bool(update_ok)
    return report

def _controlled_stop_preflight_rw() -> None:
    """Best-effort control-dir RW/rename preflight before long runs.

    Enabled by UTXO_CONTROLLED_STOP_PREFLIGHT_RW=1. This catches permissions,
    filesystem, and cross-device surprises before DB-mutating work starts.
    """
    if not _controlled_stop_enabled():
        return
    if not _env_bool("UTXO_CONTROLLED_STOP_PREFLIGHT_RW", False):
        return
    stop_file = _controlled_stop_file(create_dir=True)
    control_dir = stop_file.parent
    token = f".stop-preflight.{os.getpid()}.{uuid.uuid4().hex}"
    probe = control_dir / token
    consumed = control_dir / f"{token}.consumed"
    try:
        with open(probe, "x", encoding="utf-8") as f:
            f.write(_now_iso() + " controlled-stop preflight\n")
        probe.rename(consumed)
        consumed.unlink()
        _log(f"controlled stop preflight rw ok control_dir={control_dir}")
    except Exception as e:
        for p in (probe, consumed):
            try:
                p.unlink(missing_ok=True)
            except Exception:
                pass
        raise RuntimeError(
            f"controlled stop preflight rw failed control_dir={control_dir}: {type(e).__name__}: {e}. "
            "Fix permissions/filesystem before long run or set UTXO_CONTROLLED_STOP_PREFLIGHT_RW=0."
        ) from e


def _controlled_stop_startup_guard() -> None:
    if not _controlled_stop_enabled() and not _signal_stop_requested():
        return
    stop_file = _controlled_stop_file(create_dir=True)
    if not stop_file.exists() and not _signal_stop_requested():
        return
    if stop_file.exists() and _env_bool("UTXO_CONTROLLED_STOP_ALLOW_EXISTING_AT_START", False):
        _warn(
            f"controlled stop file already exists at startup and will be honored after the first completed day: {stop_file}"
        )
        return
    source = _controlled_stop_source_payload()
    consumed = _consume_controlled_stop_for_write_mode()
    raise ControlledStopExit(
        "controlled stop request exists before run start; no stage or DB mutation started",
        exit_code=75,
        payload={"phase": "startup", "source": source, "consumed_path": consumed},
    )


def _check_controlled_stop_after_completed_day(
    day: str,
    completed_days: int,
    next_day: Optional[str] = None,
) -> Tuple[bool, str]:
    if not _controlled_stop_enabled():
        return False, ""
    stop_file = _controlled_stop_file(create_dir=True)
    if not stop_file.exists():
        return False, ""
    request = _controlled_stop_request_payload(stop_file)
    consumed_path = _consume_controlled_stop_file(stop_file)
    report = {
        "requested": True,
        "status": "CONTROLLED_STOP",
        "mode": "after_current_day",
        "pipeline_mode": _CURRENT_MODE,
        "completed_day": str(day),
        "next_day": str(next_day) if next_day else None,
        "completed_days": int(completed_days),
        "requested_at_observed": _now_iso(),
        "stop_file": str(stop_file),
        "consumed": bool(consumed_path),
        "consumed_path": consumed_path,
        "request": request,
    }
    if not _write_controlled_stop_report_no_create(day, report):
        _log(f"controlled stop manifest update skipped day={day}: no existing readable mode manifest")
    reason = (
        f"CONTROLLED_STOP stop_file={stop_file} completed_day={day} "
        f"next_day={next_day or '<none>'} consumed={bool(consumed_path)}"
    )
    _controlled_stop_postcheck(day, next_day, reason=reason, consumed_path=consumed_path)
    return True, reason

def _should_stop_after_completed_day(
    day: str,
    completed_days: int,
    next_day: Optional[str] = None,
) -> Tuple[bool, str]:
    # First consume real STOP-file requests. This prevents a coincident
    # UTXO_MAX_DAYS_PER_RUN / UTXO_STOP_AFTER_DAY stop from leaving a stale STOP
    # file that would block the next startup.
    controlled_stop_now, controlled_stop_reason = _check_controlled_stop_after_completed_day(
        day,
        completed_days,
        next_day,
    )
    if controlled_stop_now:
        return True, controlled_stop_reason

    limit_reason = ""
    stop_after_day = _stop_after_day_env()
    if stop_after_day and day >= stop_after_day:
        limit_reason = f"UTXO_STOP_AFTER_DAY={stop_after_day}"
    else:
        max_days = _max_days_per_run_env()
        if max_days > 0 and completed_days >= max_days:
            limit_reason = f"UTXO_MAX_DAYS_PER_RUN={max_days}"

    if limit_reason:
        grace_ms = _controlled_stop_grace_ms()
        if _controlled_stop_enabled() and grace_ms > 0:
            _log(
                f"controlled stop coincident grace sleep {grace_ms}ms after completed day={day} "
                f"before limit_stop={limit_reason}"
            )
            time.sleep(grace_ms / 1000.0)
            controlled_stop_now, controlled_stop_reason = _check_controlled_stop_after_completed_day(
                day,
                completed_days,
                next_day,
            )
            if controlled_stop_now:
                return True, controlled_stop_reason + f" coincident_limit={limit_reason} grace_ms={grace_ms}"
        return True, limit_reason

    grace_ms = _controlled_stop_grace_ms() if next_day else 0
    if _controlled_stop_enabled() and grace_ms > 0:
        _log(
            f"controlled stop grace sleep {grace_ms}ms after completed day={day} "
            f"before next_day={next_day}"
        )
        time.sleep(grace_ms / 1000.0)
        controlled_stop_now, controlled_stop_reason = _check_controlled_stop_after_completed_day(
            day,
            completed_days,
            next_day,
        )
        if controlled_stop_now:
            return True, controlled_stop_reason + f" grace_ms={grace_ms}"

    return False, ""


def _drop_cleanup_seq_table(con: duckdb.DuckDBPyConnection, table_name: str) -> None:
    con.execute(f"DROP TABLE IF EXISTS {table_name};")


def _current_replay_end_day() -> str:
    return _CURRENT_REPLAY_END_DAY or _CURRENT_REPLAY_START_DAY or "9999-12-31"


def _canonical_cleanup_delete_all_created(day: str) -> bool:
    """
    v10_5-canonical-stage-key-cleanup-r1

    In canonical_map mode we must remove every created row for the replayed
    SegWit-era day. Keeping rows whose spent_date is after replay_end would mix
    old wtxid keys with new canonical txid keys.
    """
    return _canonical_enabled_for_day(day) and _env_bool("UTXO_CANONICAL_DELETE_ALL_CREATED_FOR_DAY", True)


def _created_rows_replay_remaining(con: duckdb.DuckDBPyConnection, day: str) -> int:
    if _canonical_cleanup_delete_all_created(day):
        return int(con.execute("SELECT COUNT(*) FROM utxo WHERE created_date = ?::DATE", [day]).fetchone()[0])
    replay_end = _current_replay_end_day()
    return int(
        con.execute(
            "SELECT COUNT(*) FROM utxo WHERE created_date = ?::DATE AND (spent_date IS NULL OR spent_date <= ?::DATE)",
            [day, replay_end],
        ).fetchone()[0]
    )


def _build_cleanup_spent_seq_keys(con: duckdb.DuckDBPyConnection, day: str) -> Dict[str, Any]:
    t0 = _tic()
    _drop_cleanup_seq_table(con, "cleanup_spent_seq_keys")
    con.execute(
        """
        CREATE TEMP TABLE cleanup_spent_seq_keys AS
        SELECT
          ROW_NUMBER() OVER (ORDER BY txid, vout) AS seq,
          txid,
          vout
        FROM utxo
        WHERE spent_date = ?::DATE;
        """,
        [day],
    )
    seq_checks = _seq_checks(con, "cleanup_spent_seq_keys")
    return {
        "table": "cleanup_spent_seq_keys",
        "rows": int(seq_checks.get("count", 0)),
        "seq_checks": seq_checks,
        "elapsed_sec": _toc(t0),
    }


def _build_cleanup_created_seq_keys(con: duckdb.DuckDBPyConnection, day: str, replay_end: str) -> Dict[str, Any]:
    t0 = _tic()
    _drop_cleanup_seq_table(con, "cleanup_created_seq_keys")
    if _canonical_cleanup_delete_all_created(day):
        con.execute(
            """
            CREATE TEMP TABLE cleanup_created_seq_keys AS
            SELECT
              ROW_NUMBER() OVER (ORDER BY txid, vout) AS seq,
              txid,
              vout
            FROM utxo
            WHERE created_date = ?::DATE;
            """,
            [day],
        )
    else:
        con.execute(
            """
            CREATE TEMP TABLE cleanup_created_seq_keys AS
            SELECT
              ROW_NUMBER() OVER (ORDER BY txid, vout) AS seq,
              txid,
              vout
            FROM utxo
            WHERE created_date = ?::DATE
              AND (spent_date IS NULL OR spent_date <= ?::DATE);
            """,
            [day, replay_end],
        )
    seq_checks = _seq_checks(con, "cleanup_created_seq_keys")
    return {
        "table": "cleanup_created_seq_keys",
        "rows": int(seq_checks.get("count", 0)),
        "seq_checks": seq_checks,
        "canonical_delete_all_created": _canonical_cleanup_delete_all_created(day),
        "elapsed_sec": _toc(t0),
    }

def _fetch_cleanup_seq_batch(
    con: duckdb.DuckDBPyConnection,
    table_name: str,
    start_seq: int,
    end_seq: int,
) -> List[Tuple[str, int]]:
    return con.execute(
        f"""
        SELECT txid, vout
        FROM {table_name}
        WHERE seq BETWEEN ?::BIGINT AND ?::BIGINT
        ORDER BY seq;
        """,
        [start_seq, end_seq],
    ).fetchall()


def _fetch_cleanup_spent_batch(
    con: duckdb.DuckDBPyConnection,
    day: str,
    after_txid: Optional[str],
    after_vout: Optional[int],
    limit_rows: int,
) -> List[Tuple[str, int]]:
    if after_txid is None:
        return con.execute(
            """
            SELECT txid, vout
            FROM utxo
            WHERE spent_date = ?::DATE
            ORDER BY txid, vout
            LIMIT ?;
            """,
            [day, limit_rows],
        ).fetchall()
    return con.execute(
        """
        SELECT txid, vout
        FROM utxo
        WHERE spent_date = ?::DATE
          AND (txid > ?::VARCHAR OR (txid = ?::VARCHAR AND vout > ?::BIGINT))
        ORDER BY txid, vout
        LIMIT ?;
        """,
        [day, after_txid, after_txid, after_vout, limit_rows],
    ).fetchall()


def _fetch_cleanup_created_batch(
    con: duckdb.DuckDBPyConnection,
    day: str,
    replay_end: str,
    after_txid: Optional[str],
    after_vout: Optional[int],
    limit_rows: int,
) -> List[Tuple[str, int]]:
    if _canonical_cleanup_delete_all_created(day):
        if after_txid is None:
            return con.execute(
                """
                SELECT txid, vout
                FROM utxo
                WHERE created_date = ?::DATE
                ORDER BY txid, vout
                LIMIT ?;
                """,
                [day, limit_rows],
            ).fetchall()
        return con.execute(
            """
            SELECT txid, vout
            FROM utxo
            WHERE created_date = ?::DATE
              AND (txid > ?::VARCHAR OR (txid = ?::VARCHAR AND vout > ?::BIGINT))
            ORDER BY txid, vout
            LIMIT ?;
            """,
            [day, after_txid, after_txid, after_vout, limit_rows],
        ).fetchall()

    if after_txid is None:
        return con.execute(
            """
            SELECT txid, vout
            FROM utxo
            WHERE created_date = ?::DATE
              AND (spent_date IS NULL OR spent_date <= ?::DATE)
            ORDER BY txid, vout
            LIMIT ?;
            """,
            [day, replay_end, limit_rows],
        ).fetchall()
    return con.execute(
        """
        SELECT txid, vout
        FROM utxo
        WHERE created_date = ?::DATE
          AND (spent_date IS NULL OR spent_date <= ?::DATE)
          AND (txid > ?::VARCHAR OR (txid = ?::VARCHAR AND vout > ?::BIGINT))
        ORDER BY txid, vout
        LIMIT ?;
        """,
        [day, replay_end, after_txid, after_txid, after_vout, limit_rows],
    ).fetchall()

def _load_cleanup_chunk_keys(con: duckdb.DuckDBPyConnection, rows: Sequence[Tuple[str, int]]) -> int:
    con.execute("DELETE FROM cleanup_chunk_keys;")
    if not rows:
        return 0
    payload = [(i, txid, int(vout)) for i, (txid, vout) in enumerate(rows, start=1)]
    con.executemany(
        "INSERT INTO cleanup_chunk_keys(seq, txid, vout) VALUES (?, ?, ?)",
        payload,
    )
    return len(payload)


def _cleanup_spent_chunk_apply(con: duckdb.DuckDBPyConnection) -> None:
    con.execute(
        """
        UPDATE utxo AS u
        SET spent_ts=NULL, spent_date=NULL, spent_txid=NULL, spent_vin=NULL
        FROM cleanup_chunk_keys AS k
        WHERE u.txid = k.txid AND u.vout = k.vout AND u.spent_date IS NOT NULL;
        """
    )


def _cleanup_created_chunk_apply(con: duckdb.DuckDBPyConnection) -> None:
    con.execute(
        """
        DELETE FROM utxo AS u
        USING cleanup_chunk_keys AS k
        WHERE u.txid = k.txid AND u.vout = k.vout;
        """
    )


def _verify_cleanup(con: duckdb.DuckDBPyConnection, day: str) -> Dict[str, Any]:
    replay_end = _current_replay_end_day()
    spent_left = int(con.execute("SELECT COUNT(*) FROM utxo WHERE spent_date = ?::DATE", [day]).fetchone()[0])
    created_rows_left = _created_rows_replay_remaining(con, day)
    total_created_left = int(con.execute("SELECT COUNT(*) FROM utxo WHERE created_date = ?::DATE", [day]).fetchone()[0])
    ok = spent_left == 0 and created_rows_left == 0
    return {
        "ok": ok,
        "spent_rows_left": spent_left,
        "created_rows_left": created_rows_left,
        "total_created_rows_left": total_created_left,
        "replay_window_end": replay_end,
    }


def _cleanup_day_bulk(con: duckdb.DuckDBPyConnection, day: str, stats: Dict[str, int], future_stats: Dict[str, Optional[str]]) -> Dict[str, Any]:
    """
    v10_7-stop-after-day-safety-r1

    Opt-in fast cleanup path for lab replay.

    It performs the same logical cleanup as keyset mode:
      1. reset all rows whose spent_date == day;
      2. delete created rows for day. In canonical replay this means every
         created_date == day row, because keeping old wtxid-keyed rows would mix
         keyspaces. In non-canonical replay it follows the older replay_end rule.
      3. run _verify_cleanup() and fail if anything remains.

    The operations are split into two transactions to avoid one unnecessarily
    large transaction. If a crash happens between them, re-running the same
    replay window is expected and safe; cleanup is idempotent.
    """
    t0 = _tic()
    replay_end = _current_replay_end_day()
    canonical_delete_all_created = _canonical_cleanup_delete_all_created(day)

    _update_manifest(
        day,
        {
            "status": STATUS_CLEANUP_SPENT,
            "cleanup": {
                "cleanup_mode": "bulk_day",
                "day_presence": stats,
                "future_db_presence": future_stats,
                "started_at": _now_iso(),
                "replay_window_end": replay_end,
                "canonical_delete_all_created": canonical_delete_all_created,
            },
        },
    )

    spent_t0 = _tic()
    con.execute("BEGIN")
    try:
        con.execute(
            """
            UPDATE utxo
            SET spent_ts=NULL, spent_date=NULL, spent_txid=NULL, spent_vin=NULL
            WHERE spent_date = ?::DATE;
            """,
            [day],
        )
        con.execute("COMMIT")
    except Exception:
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        raise
    spent_elapsed = _toc(spent_t0)
    _log(f"cleanup bulk spent day={day} reset_old_spent_rows={int(stats.get('spent_rows', 0))} in {_fmt_s(spent_elapsed)}")

    _update_manifest(day, {"status": STATUS_CLEANUP_CREATED, "cleanup": {"bulk_spent_elapsed_sec": spent_elapsed}})

    created_t0 = _tic()
    con.execute("BEGIN")
    try:
        if canonical_delete_all_created:
            con.execute(
                """
                DELETE FROM utxo
                WHERE created_date = ?::DATE;
                """,
                [day],
            )
        else:
            con.execute(
                """
                DELETE FROM utxo
                WHERE created_date = ?::DATE
                  AND (spent_date IS NULL OR spent_date <= ?::DATE);
                """,
                [day, replay_end],
            )
        con.execute("COMMIT")
    except Exception:
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        raise
    created_elapsed = _toc(created_t0)
    _log(
        f"cleanup bulk created day={day} delete_old_created_rows={int(stats.get('created_rows', 0))} "
        f"canonical_delete_all_created={canonical_delete_all_created} in {_fmt_s(created_elapsed)}"
    )

    verify = _verify_cleanup(con, day)
    _update_manifest(day, {"status": STATUS_CLEANUP_VERIFY, "cleanup": {"bulk_created_elapsed_sec": created_elapsed, "verify": verify}})
    if not verify["ok"]:
        raise RuntimeError(f"cleanup bulk verify failed day={day}: {verify}")

    result = {
        "status": "ok",
        "cleanup_mode": "bulk_day",
        "day_presence": stats,
        "future_db_presence": future_stats,
        "fetch_mode": None,
        "spent_total": int(stats.get("spent_rows", 0)),
        "created_total": int(stats.get("created_rows", 0)),
        "spent_chunks_done": 1 if int(stats.get("spent_rows", 0)) > 0 else 0,
        "created_chunks_done": 1 if int(stats.get("created_rows", 0)) > 0 else 0,
        "bulk_spent_elapsed_sec": spent_elapsed,
        "bulk_created_elapsed_sec": created_elapsed,
        "canonical_delete_all_created": canonical_delete_all_created,
        "replay_window_end": replay_end,
        "verify": verify,
        "elapsed_sec": _toc(t0),
    }
    _update_manifest(day, {"status": STATUS_CLEANUP_DONE, "cleanup": result})
    return result


def _cleanup_day_safe(con: duckdb.DuckDBPyConnection, day: str) -> Dict[str, Any]:
    t0 = _tic()
    stats = _day_presence_stats(con, day)
    future_stats = _assert_safe_single_day_replay(con, day, stats)
    cleanup_mode = _cleanup_day_mode()
    fetch_mode = _cleanup_fetch_mode() if cleanup_mode == "keyset" else None
    _update_manifest(
        day,
        {
            "status": STATUS_CLEANUP_CHECK,
            "cleanup": {
                "day_presence": stats,
                "future_db_presence": future_stats,
                "started_at": _now_iso(),
                "cleanup_mode": cleanup_mode,
                "fetch_mode": fetch_mode,
            },
        },
    )
    if not _cleanup_needed(stats):
        result = {
            "status": "skipped",
            "cleanup_mode": cleanup_mode,
            "day_presence": stats,
            "future_db_presence": future_stats,
            "fetch_mode": fetch_mode,
            "verify": {"ok": True, "spent_rows_left": 0, "created_rows_left": 0},
            "elapsed_sec": _toc(t0),
        }
        _update_manifest(day, {"status": STATUS_CLEANUP_SKIPPED, "cleanup": result})
        return result

    if cleanup_mode == "bulk_day":
        return _cleanup_day_bulk(con, day, stats, future_stats)

    _create_cleanup_tables(con)
    _clear_cleanup_tables(con)
    _drop_cleanup_seq_table(con, "cleanup_spent_seq_keys")
    _drop_cleanup_seq_table(con, "cleanup_created_seq_keys")
    spent_chunk_rows = max(1, _env_int("UTXO_CLEANUP_SPENT_ROWS", 50000))
    created_chunk_rows = max(1, _env_int("UTXO_CLEANUP_CREATED_ROWS", 50000))
    checkpoint_every = max(0, _env_int("UTXO_CLEANUP_CHECKPOINT_EVERY_CHUNKS", 2))

    spent_total = 0
    spent_chunks_done = 0
    spent_materialize: Dict[str, Any] = {}
    after_txid: Optional[str] = None
    after_vout: Optional[int] = None
    _update_manifest(
        day,
        {
            "status": STATUS_CLEANUP_SPENT,
            "cleanup": {
                "cleanup_spent_batch_rows": spent_chunk_rows,
                "fetch_mode": fetch_mode,
            },
        },
    )
    if fetch_mode == "seq":
        spent_materialize = _build_cleanup_spent_seq_keys(con, day)
        if not spent_materialize.get("seq_checks", {}).get("ok", False):
            raise RuntimeError(f"cleanup spent seq materialize failed day={day}: {spent_materialize}")
        _update_manifest(day, {"cleanup": {"spent_materialize": spent_materialize}})
        spent_seq_rows = int(spent_materialize.get("rows", 0))
        start_seq = 1
        while start_seq <= spent_seq_rows:
            end_seq = min(start_seq + spent_chunk_rows - 1, spent_seq_rows)
            rows = _fetch_cleanup_seq_batch(con, "cleanup_spent_seq_keys", start_seq, end_seq)
            if not rows:
                break
            chunk_rows = _load_cleanup_chunk_keys(con, rows)
            con.execute("BEGIN")
            try:
                _cleanup_spent_chunk_apply(con)
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            spent_chunks_done += 1
            spent_total += chunk_rows
            _dbg(f"cleanup spent day={day} batch={spent_chunks_done} seq={start_seq}-{end_seq} fetched={chunk_rows}")
            if checkpoint_every > 0 and spent_chunks_done % checkpoint_every == 0:
                ck_t0 = _tic()
                con.execute("CHECKPOINT")
                _update_manifest(day, {"cleanup": {"spent_total": spent_total, "spent_chunks_done": spent_chunks_done, "last_checkpoint_at": _now_iso(), "last_checkpoint_elapsed_sec": _toc(ck_t0)}})
            start_seq = end_seq + 1
        _drop_cleanup_seq_table(con, "cleanup_spent_seq_keys")
    else:
        while True:
            rows = _fetch_cleanup_spent_batch(con, day, after_txid, after_vout, spent_chunk_rows)
            if not rows:
                break
            chunk_rows = _load_cleanup_chunk_keys(con, rows)
            con.execute("BEGIN")
            try:
                _cleanup_spent_chunk_apply(con)
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            spent_chunks_done += 1
            spent_total += chunk_rows
            last_txid, last_vout = rows[-1]
            after_txid = str(last_txid)
            after_vout = int(last_vout)
            _dbg(f"cleanup spent day={day} batch={spent_chunks_done} fetched={chunk_rows} last_key={after_txid}:{after_vout}")
            if checkpoint_every > 0 and spent_chunks_done % checkpoint_every == 0:
                ck_t0 = _tic()
                con.execute("CHECKPOINT")
                _update_manifest(day, {"cleanup": {"spent_total": spent_total, "spent_chunks_done": spent_chunks_done, "last_checkpoint_at": _now_iso(), "last_checkpoint_elapsed_sec": _toc(ck_t0)}})
    spent_verify = int(con.execute("SELECT COUNT(*) FROM utxo WHERE spent_date = ?::DATE", [day]).fetchone()[0])
    if spent_verify != 0:
        raise RuntimeError(f"cleanup spent verify failed day={day}: spent_rows_left={spent_verify}")

    replay_end = _current_replay_end_day()
    created_total = 0
    created_chunks_done = 0
    created_materialize: Dict[str, Any] = {}
    after_txid = None
    after_vout = None
    _update_manifest(
        day,
        {
            "status": STATUS_CLEANUP_CREATED,
            "cleanup": {
                "cleanup_created_batch_rows": created_chunk_rows,
                "created_replay_rows_only": not _canonical_cleanup_delete_all_created(day),
                "canonical_delete_all_created": _canonical_cleanup_delete_all_created(day),
                "replay_window_end": replay_end,
                "fetch_mode": fetch_mode,
                "spent_total": spent_total,
                "spent_chunks_done": spent_chunks_done,
                "spent_materialize": spent_materialize,
            },
        },
    )
    if fetch_mode == "seq":
        created_materialize = _build_cleanup_created_seq_keys(con, day, replay_end)
        if not created_materialize.get("seq_checks", {}).get("ok", False):
            raise RuntimeError(f"cleanup created seq materialize failed day={day}: {created_materialize}")
        _update_manifest(day, {"cleanup": {"created_materialize": created_materialize}})
        created_seq_rows = int(created_materialize.get("rows", 0))
        start_seq = 1
        while start_seq <= created_seq_rows:
            end_seq = min(start_seq + created_chunk_rows - 1, created_seq_rows)
            rows = _fetch_cleanup_seq_batch(con, "cleanup_created_seq_keys", start_seq, end_seq)
            if not rows:
                break
            chunk_rows = _load_cleanup_chunk_keys(con, rows)
            con.execute("BEGIN")
            try:
                _cleanup_created_chunk_apply(con)
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            created_chunks_done += 1
            created_total += chunk_rows
            _dbg(f"cleanup created day={day} batch={created_chunks_done} seq={start_seq}-{end_seq} fetched={chunk_rows}")
            if checkpoint_every > 0 and created_chunks_done % checkpoint_every == 0:
                ck_t0 = _tic()
                con.execute("CHECKPOINT")
                _update_manifest(day, {"cleanup": {"created_total": created_total, "created_chunks_done": created_chunks_done, "last_checkpoint_at": _now_iso(), "last_checkpoint_elapsed_sec": _toc(ck_t0)}})
            start_seq = end_seq + 1
        _drop_cleanup_seq_table(con, "cleanup_created_seq_keys")
    else:
        while True:
            rows = _fetch_cleanup_created_batch(con, day, replay_end, after_txid, after_vout, created_chunk_rows)
            if not rows:
                break
            chunk_rows = _load_cleanup_chunk_keys(con, rows)
            con.execute("BEGIN")
            try:
                _cleanup_created_chunk_apply(con)
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            created_chunks_done += 1
            created_total += chunk_rows
            last_txid, last_vout = rows[-1]
            after_txid = str(last_txid)
            after_vout = int(last_vout)
            _dbg(f"cleanup created day={day} batch={created_chunks_done} fetched={chunk_rows} last_key={after_txid}:{after_vout}")
            if checkpoint_every > 0 and created_chunks_done % checkpoint_every == 0:
                ck_t0 = _tic()
                con.execute("CHECKPOINT")
                _update_manifest(day, {"cleanup": {"created_total": created_total, "created_chunks_done": created_chunks_done, "last_checkpoint_at": _now_iso(), "last_checkpoint_elapsed_sec": _toc(ck_t0)}})

    verify = _verify_cleanup(con, day)
    _update_manifest(day, {"status": STATUS_CLEANUP_VERIFY, "cleanup": {"verify": verify}})
    if not verify["ok"]:
        raise RuntimeError(f"cleanup verify failed day={day}: {verify}")
    result = {
        "status": "ok",
        "cleanup_mode": "keyset",
        "day_presence": stats,
        "future_db_presence": future_stats,
        "fetch_mode": fetch_mode,
        "spent_materialize": spent_materialize,
        "created_materialize": created_materialize,
        "spent_total": spent_total,
        "created_total": created_total,
        "spent_chunks_done": spent_chunks_done,
        "created_chunks_done": created_chunks_done,
        "verify": verify,
        "elapsed_sec": _toc(t0),
    }
    _update_manifest(day, {"status": STATUS_CLEANUP_DONE, "cleanup": result})
    return result


def _run_cleanup_only_for_day(con: duckdb.DuckDBPyConnection, day: str) -> int:
    _prepare_day_for_replay(day)
    _cleanup_day_safe(con, day)
    return 0


def _cleanup_window(con: duckdb.DuckDBPyConnection, start_day: str, end_day: str) -> None:
    # compatibility shim; v8 uses per-day safe cleanup instead of bulk window cleanup.
    if start_day == end_day:
        _cleanup_day_safe(con, start_day)


def _pk_canary_or_die(con: duckdb.DuckDBPyConnection) -> None:
    if _env_bool("UTXO_SKIP_PK_CANARY", False):
        return
    txid = os.urandom(32).hex()
    con.execute("BEGIN")
    try:
        con.execute(
            """
            INSERT INTO utxo (txid, vout, address, value_btc, created_ts, created_date)
            VALUES (?::VARCHAR, 0::BIGINT, NULL, NULL, NULL, NULL)
            ON CONFLICT (txid, vout) DO NOTHING;
            """,
            [txid],
        )
    except Exception as e:
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        raise RuntimeError(
            "PK canary failed. The PK/UNIQUE index may be poisoned. "
            "Set UTXO_SKIP_PK_CANARY=1 only if you intentionally want to bypass this check. "
            f"Original error: {type(e).__name__}: {e}"
        ) from e
    else:
        con.execute("ROLLBACK")


# -----------------------------
# range / planning helpers
# -----------------------------

def _list_available_days(raw_base: str) -> List[str]:
    """Discover only valid physical raw partitions and fail on broken date dirs."""
    p = Path(raw_base)
    if not p.exists():
        return []
    if not p.is_dir() or p.is_symlink():
        raise RuntimeError(f"raw base must be a real directory, not symlink/file: {p}")
    out: List[str] = []
    problems: List[str] = []
    for d in sorted(p.glob("date=*")):
        if d.is_symlink() or not d.is_dir():
            problems.append(f"not_real_directory:{d}")
            continue
        day = d.name.split("=", 1)[1]
        try:
            _parse_date(day)
        except Exception:
            problems.append(f"invalid_iso_date:{d.name}")
            continue
        files = sorted(d.glob("part-*.parquet"))
        if not files:
            files = sorted(d.glob("*.parquet"))
        regular = [x for x in files if x.is_file() and not x.is_symlink()]
        if not regular:
            problems.append(f"no_regular_parquet:{d}")
            continue
        out.append(day)
    if problems:
        raise RuntimeError(
            "raw partition discovery failed before range planning: "
            + "; ".join(problems[:50])
            + (f"; total_problems={len(problems)}" if len(problems) > 50 else "")
        )
    if len(set(out)) != len(out):
        raise RuntimeError("raw partition discovery returned duplicate dates")
    out.sort()
    return out



def _resolve_processing_days(raw_base: str, window_days: int) -> List[str]:
    days = _list_available_days(raw_base)
    if not days:
        return []

    first_day = days[0]
    last_day = days[-1]
    start_env = _env_str("UTXO_START_DATE", None)
    end_env = _env_str("UTXO_END_DATE", None)

    if start_env:
        start_day = start_env
    else:
        last = _parse_date(last_day)
        start_day = (last - timedelta(days=window_days - 1)).isoformat()

    end_day = end_env if end_env else last_day

    if start_day < first_day:
        start_day = first_day
    if end_day > last_day:
        end_day = last_day
    if start_day > end_day:
        return []

    return [d for d in days if start_day <= d <= end_day]



def _day_parquet_files(raw_base: str, d: str) -> List[str]:
    files = sorted(glob.glob(os.path.join(raw_base, f"date={d}", "part-*.parquet")))
    if not files:
        files = sorted(glob.glob(os.path.join(raw_base, f"date={d}", "*.parquet")))
    return files


