def _tmp_path(path: Path, suffix: str = ".tmp") -> Path:
    return path.with_name(path.name + suffix + f".{os.getpid()}")


# -----------------------------
# manifest helpers
# -----------------------------

def _pipeline_version() -> str:
    return PIPELINE_VERSION



def _load_manifest(day: str) -> Optional[Dict[str, Any]]:
    p = _manifest_path(day)
    if not p.exists():
        return None
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)



def _save_json_atomic(path: Path, payload: Dict[str, Any]) -> None:
    """Durably publish JSON through a unique temp file and atomic replace."""
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(
        f".{path.name}.tmp.{os.getpid()}.{time.time_ns()}.{uuid.uuid4().hex}"
    )
    try:
        with open(tmp, "x", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2, sort_keys=True)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
        _fsync_directory(path.parent)
    except BaseException:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        raise




def _fsync_directory(path: Path) -> None:
    """Persist directory-entry updates after critical rename/replace operations."""
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    fd = os.open(str(path), flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _atomic_publish_copy(src: Path, dst: Path) -> None:
    """Copy, fsync, atomically replace, then fsync the parent directory."""
    dst.parent.mkdir(parents=True, exist_ok=True)
    tmp = dst.with_name(dst.name + f".publish.{os.getpid()}.tmp")
    tmp.unlink(missing_ok=True)
    shutil.copy2(src, tmp)
    with tmp.open("rb") as fh:
        os.fsync(fh.fileno())
    os.replace(tmp, dst)
    _fsync_directory(dst.parent)

def _manifest_base(day: str, mode: str) -> Dict[str, Any]:
    now = _now_iso()
    return {
        "day": day,
        "pipeline_version": _pipeline_version(),
        "run_id": _new_run_id(),
        "parent_run_id": _env_str("UTXO_PARENT_RUN_ID", None),
        "host": socket.gethostname(),
        "pid": os.getpid(),
        "mode": mode,
        "status": STATUS_BUILDING,
        "stage_semantics": "block_ordered",
        "causal_order": "block_number,tx_index",
        "date_semantics": "block_timestamp_utc_date",
        "raw_partition_date_semantics": "storage_only",
        "cleanup_semantics": "disabled_v11_r1_full_rebuild_only",
        "created_at": now,
        "updated_at": now,
        "raw": {},
        "cleanup": {},
        "stage": {},
        "apply": {},
        "audit": {},
        "source_units": {
            "output_value_unit": _env_str("UTXO_OUTPUT_VALUE_UNIT", None),
            "address_mode": _env_str("UTXO_ADDRESS_MODE", "auto"),
        },
        "semantic_audit": {},
        "canonical_proof": {},
        "coverage": {},
        "repair": {},
        "acceptance": {},
        "purge": {
            "eligible": False,
            "purged": False,
            "purged_at": None,
            "created_parquet_deleted": False,
            "spends_parquet_deleted": False,
        },
        "files": {
            "created_parquet": str(_created_stage_path(day)),
            "spends_parquet": str(_spends_stage_path(day)),
            "duplicate_events_parquet": str(_duplicate_events_path(day)),
            "duplicate_summary_json": str(_duplicate_summary_path(day)),
            "global_duplicate_conflicts_parquet": str(_global_duplicate_conflicts_path(day)),
            "discarded_block_events_parquet": str(_discarded_block_events_path(day)),
            "manifest_path": str(_manifest_path(day)),
        },
        "telemetry": {
            "checkpoint_elapsed_sec": None,
            "stage_bytes_total": 0,
        },
        "errors": [],
    }
def _update_manifest(day: str, patch: Dict[str, Any]) -> Dict[str, Any]:
    base_mode = _CURRENT_MODE or _resolve_mode(None)
    manifest = _load_manifest(day) or _manifest_base(day, base_mode)
    manifest = _deep_merge(manifest, patch)
    manifest["updated_at"] = _now_iso()
    _save_json_atomic(_manifest_path(day), manifest)
    return manifest



def _deep_merge(base: Dict[str, Any], patch: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(base)
    for k, v in patch.items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = _deep_merge(out[k], v)
        else:
            out[k] = v
    return out




def _source_fingerprint(raw_files: List[Dict[str, Any]]) -> str:
    payload = json.dumps(raw_files, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _schema_fingerprint(raw_files: List[Dict[str, Any]]) -> str:
    schema_view = [
        {
            "top_level": item.get("top_level", []),
            "output_fields": item.get("output_fields", []),
            "input_fields": item.get("input_fields", []),
            "has_outputs": item.get("has_outputs", False),
            "has_inputs": item.get("has_inputs", False),
            "output_has_address": item.get("output_has_address", False),
            "input_has_prevout": item.get("input_has_prevout", False),
            "has_tx_index": item.get("has_tx_index", False),
            "effective_has_tx_index": item.get("effective_has_tx_index", item.get("has_tx_index", False)),
            "tx_index_null_rows": item.get("tx_index_null_rows", 0),
            "tx_index_source": item.get("tx_index_source"),
        }
        for item in raw_files
    ]
    payload = json.dumps(schema_view, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()



def _v11_stage_payload_fingerprint(day: str, manifest: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Fingerprint the three stage payload files without hashing manifest bytes.

    The algorithm intentionally matches the existing ledger/stat trust model and
    avoids an additional full read of very large parquet files.
    """
    payload = manifest if isinstance(manifest, dict) else (_load_manifest(day) or {})
    files = payload.get("files") if isinstance(payload.get("files"), dict) else {}
    h = hashlib.sha256()
    entries: List[Dict[str, Any]] = []
    errors: List[str] = []
    for key in ("created_parquet", "spends_parquet", "block_meta_parquet"):
        raw = files.get(key)
        if not raw:
            errors.append(f"manifest_file_path_missing:{key}")
            continue
        fp = Path(str(raw))
        try:
            if not fp.is_file():
                errors.append(f"stage_file_missing_or_not_regular:{key}:{fp}")
                continue
            st = fp.stat()
        except Exception as exc:
            errors.append(f"stage_file_stat_failed:{key}:{type(exc).__name__}:{exc}")
            continue
        entry = {
            "key": key,
            "path": str(fp),
            "size": int(st.st_size),
            "mtime_ns": int(st.st_mtime_ns),
        }
        entries.append(entry)
        h.update(
            key.encode("utf-8") + b"\0"
            + str(fp).encode("utf-8") + b"\0"
            + str(st.st_size).encode("ascii") + b"\0"
            + str(st.st_mtime_ns).encode("ascii") + b"\0"
        )
    return {
        "algorithm": "sha256(stage_file_path+size+mtime_ns)",
        "sha256": h.hexdigest() if not errors and len(entries) == 3 else None,
        "entries": entries,
        "errors": errors,
    }


def _v11_contract_int(value: Any, field: str, failures: List[str], *, default: int = 0) -> int:
    """Parse a manifest/guard counter without allowing malformed JSON to crash the run.

    Counters are intentionally strict: booleans, floats, containers and numeric
    strings with decimal/exponent notation are rejected rather than silently
    truncated by int(). Plain integer strings remain accepted for compatibility.
    """
    if value is None or value == "":
        return int(default)
    if isinstance(value, bool):
        failures.append(f"{field}_not_integer:boolean")
        return int(default)
    if isinstance(value, int):
        return int(value)
    if isinstance(value, str) and re.fullmatch(r"[+-]?\d+", value.strip()):
        try:
            return int(value.strip())
        except (ValueError, OverflowError):
            pass
    failures.append(f"{field}_not_integer:{value!r}")
    return int(default)


def _v11_build_canonical_proof_contract(
    day: str,
    duplicate_guard: Dict[str, Any],
    *,
    stage_payload_fingerprint: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    failures: List[str] = []
    if not isinstance(duplicate_guard, dict):
        duplicate_guard = {}
        failures.append("duplicate_guard_missing_or_not_object")
    source = str(duplicate_guard.get("canonical_source") or "")
    scope = _dup_guard_scope_from_report(duplicate_guard)
    checked_blocks = _v11_contract_int(duplicate_guard.get("checked_blocks"), "checked_blocks", failures)
    lookup_ok = _v11_contract_int(duplicate_guard.get("canonical_lookup_ok_rows"), "canonical_lookup_ok_rows", failures)
    lookup_bad_hash = _v11_contract_int(duplicate_guard.get("canonical_lookup_bad_hash_rows"), "canonical_lookup_bad_hash_rows", failures)
    distinct_heights = _v11_contract_int(duplicate_guard.get("canonical_lookup_distinct_heights"), "canonical_lookup_distinct_heights", failures)
    duplicate_txids = _v11_contract_int(duplicate_guard.get("duplicate_txids"), "duplicate_txids", failures)
    lookup_errors = duplicate_guard.get("canonical_lookup_errors")
    if not isinstance(lookup_errors, list):
        lookup_errors = ["canonical_lookup_errors_not_list"]
    guard_failures = duplicate_guard.get("canonical_proof_failures")
    if not isinstance(guard_failures, list):
        guard_failures = ["canonical_proof_failures_not_list"]
    failures.extend(str(x) for x in guard_failures if str(x))
    if duplicate_guard.get("canonical_proof_complete") is not True:
        failures.append("legacy_canonical_proof_complete_not_true")
    if source not in {"bitcoin_cli", "esplora"}:
        failures.append(f"canonical_source_not_external:{source or '<missing>'}")
    if duplicate_guard.get("enabled") is not True:
        failures.append("duplicate_guard_not_enabled")
    if duplicate_guard.get("block_filter_enabled") is not True:
        failures.append("block_filter_not_enabled")
    if duplicate_guard.get("auto_resolve") is not True:
        failures.append("auto_resolve_not_enabled")
    if duplicate_guard.get("require_canonical_proof") is not True:
        failures.append("canonical_proof_requirement_not_enabled")
    if duplicate_guard.get("fail_on_unresolved") is not True:
        failures.append("fail_on_unresolved_not_enabled")
    if duplicate_guard.get("allow_unproven_modern") is not False:
        failures.append("allow_unproven_modern_not_false")
    if duplicate_guard.get("apply_allowed") is not True:
        failures.append("duplicate_guard_apply_not_allowed")

    block_filter_requested = duplicate_guard.get("block_filter_requested") is True
    block_filter_always = duplicate_guard.get("block_filter_always") is True
    duplicate_triggered_no_duplicates = bool(
        scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED
        and duplicate_txids == 0
    )
    if scope == CANONICAL_PROOF_SCOPE_ALL_BLOCKS:
        if not block_filter_requested:
            failures.append("block_filter_not_requested")
        if not block_filter_always:
            failures.append("block_filter_always_not_enabled")
    elif scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED:
        if block_filter_always:
            failures.append("duplicate_triggered_scope_with_block_filter_always")
        if duplicate_txids > 0 and not block_filter_requested:
            failures.append("duplicate_triggered_filter_not_requested_for_duplicates")
        if duplicate_txids == 0 and block_filter_requested:
            failures.append("duplicate_triggered_filter_unexpected_without_duplicates")
    else:
        failures.append(f"canonical_proof_scope_invalid:{scope}")

    unresolved_groups = _v11_contract_int(duplicate_guard.get("unresolved_groups"), "unresolved_groups", failures)
    if unresolved_groups != 0:
        failures.append(f"unresolved_groups:{duplicate_guard.get('unresolved_groups')}")
    noncanonical_blocks = _v11_contract_int(
        duplicate_guard.get("noncanonical_blocks"), "noncanonical_blocks", failures
    )
    replacements_raw = duplicate_guard.get("canonical_replacements")
    if isinstance(replacements_raw, list):
        canonical_replacements = len(replacements_raw)
    else:
        canonical_replacements = 0
        failures.append("canonical_replacements_not_list")
    if lookup_errors:
        failures.append(f"canonical_lookup_errors:{len(lookup_errors)}")
    if duplicate_triggered_no_duplicates:
        if checked_blocks != 0:
            failures.append(f"duplicate_triggered_checked_blocks_not_zero:{checked_blocks}")
        if lookup_ok != 0:
            failures.append(f"duplicate_triggered_lookup_ok_not_zero:{lookup_ok}")
        if distinct_heights != 0:
            failures.append(f"duplicate_triggered_distinct_heights_not_zero:{distinct_heights}")
    else:
        if checked_blocks <= 0:
            failures.append("no_local_blocks_checked")
        if lookup_ok != checked_blocks:
            failures.append(f"lookup_coverage:{lookup_ok}!={checked_blocks}")
        if distinct_heights <= 0:
            failures.append("no_distinct_heights_checked")
    if lookup_bad_hash != 0:
        failures.append(f"lookup_bad_hash_rows:{lookup_bad_hash}")

    fp = stage_payload_fingerprint if isinstance(stage_payload_fingerprint, dict) else {}
    fp_sha = str(fp.get("sha256") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", fp_sha):
        failures.append("stage_payload_fingerprint_missing_or_invalid")
    if fp.get("errors"):
        failures.append(f"stage_payload_fingerprint_errors:{fp.get('errors')}")
    failures = sorted(set(failures))
    complete = not failures
    block_identity_verified = bool(complete and not duplicate_triggered_no_duplicates)
    block_identity_status = (
        "NOT_REQUESTED_NO_DUPLICATES"
        if duplicate_triggered_no_duplicates
        else "VERIFIED_REQUIRED_BLOCK_SET"
    )
    return {
        "contract_version": CANONICAL_PROOF_CONTRACT_VERSION,
        "status": "COMPLETE" if complete else "INCOMPLETE",
        "complete": bool(complete),
        "policy_complete": bool(complete),
        "day": str(day),
        "source": source,
        "proof_level": CANONICAL_PROOF_LEVEL,
        "proof_scope": scope,
        "block_identity_verified": block_identity_verified,
        "block_identity_verification_status": block_identity_status,
        "payload_verified": False,
        "payload_verification_status": CANONICAL_PAYLOAD_STATUS,
        "local_block_rows": checked_blocks,
        "distinct_heights": distinct_heights,
        "lookup_ok_rows": lookup_ok,
        "lookup_error_rows": len(lookup_errors),
        "lookup_bad_hash_rows": lookup_bad_hash,
        "duplicate_txids": duplicate_txids,
        "noncanonical_blocks": noncanonical_blocks,
        "canonical_replacements": canonical_replacements,
        "unresolved_groups": unresolved_groups,
        "policy": {
            "proof_scope": scope,
            "duplicate_guard_enabled": duplicate_guard.get("enabled") is True,
            "block_filter_enabled": duplicate_guard.get("block_filter_enabled") is True,
            "block_filter_requested": block_filter_requested,
            "block_filter_always": block_filter_always,
            "lookup_skipped_no_duplicates": duplicate_triggered_no_duplicates,
            "auto_resolve": duplicate_guard.get("auto_resolve") is True,
            "require_canonical_proof": duplicate_guard.get("require_canonical_proof") is True,
            "fail_on_unresolved": duplicate_guard.get("fail_on_unresolved") is True,
            "allow_unproven_modern": duplicate_guard.get("allow_unproven_modern") is True,
            "apply_allowed": duplicate_guard.get("apply_allowed") is True,
        },
        "stage_payload_fingerprint": fp,
        "stage_payload_fingerprint_sha256": fp_sha or None,
        "failures": failures,
    }


def _v11_validate_canonical_proof_contract(payload: Any, *, day: str) -> List[str]:
    failed: List[str] = []
    if not isinstance(payload, dict):
        return ["canonical_proof_missing_or_not_object"]
    if payload.get("contract_version") != CANONICAL_PROOF_CONTRACT_VERSION:
        failed.append(f"canonical_proof_contract_version:{payload.get('contract_version')!r}")
    if payload.get("status") != "COMPLETE":
        failed.append(f"canonical_proof_status:{payload.get('status')!r}")
    if payload.get("complete") is not True:
        failed.append("canonical_proof_complete_not_true")
    if payload.get("policy_complete") is not True:
        failed.append("canonical_policy_complete_not_true")
    if str(payload.get("day") or "") != str(day):
        failed.append(f"canonical_proof_day_mismatch:{payload.get('day')!r}!={day}")
    if payload.get("source") not in {"bitcoin_cli", "esplora"}:
        failed.append(f"canonical_proof_source:{payload.get('source')!r}")
    if payload.get("proof_level") != CANONICAL_PROOF_LEVEL:
        failed.append(f"canonical_proof_level:{payload.get('proof_level')!r}")
    scope = str(payload.get("proof_scope") or "")
    if scope not in {CANONICAL_PROOF_SCOPE_ALL_BLOCKS, CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED}:
        failed.append(f"canonical_proof_scope:{scope!r}")
    if payload.get("payload_verified") is not False:
        failed.append("canonical_payload_verified_must_be_false_for_v1")
    if payload.get("payload_verification_status") != CANONICAL_PAYLOAD_STATUS:
        failed.append("canonical_payload_status_mismatch")

    policy = payload.get("policy") if isinstance(payload.get("policy"), dict) else {}
    expected_common = {
        "duplicate_guard_enabled": True,
        "block_filter_enabled": True,
        "auto_resolve": True,
        "require_canonical_proof": True,
        "fail_on_unresolved": True,
        "allow_unproven_modern": False,
        "apply_allowed": True,
    }
    for key, expected in expected_common.items():
        if policy.get(key) is not expected:
            failed.append(f"canonical_policy_{key}:{policy.get(key)!r}")
    if policy.get("proof_scope") != scope:
        failed.append(f"canonical_policy_scope:{policy.get('proof_scope')!r}!={scope}")

    local_rows = _v11_contract_int(payload.get("local_block_rows"), "local_block_rows", failed)
    lookup_ok = _v11_contract_int(payload.get("lookup_ok_rows"), "lookup_ok_rows", failed)
    lookup_error_rows = _v11_contract_int(payload.get("lookup_error_rows"), "lookup_error_rows", failed)
    lookup_bad_hash_rows = _v11_contract_int(payload.get("lookup_bad_hash_rows"), "lookup_bad_hash_rows", failed)
    distinct_heights = _v11_contract_int(payload.get("distinct_heights"), "distinct_heights", failed)
    duplicate_txids = _v11_contract_int(payload.get("duplicate_txids"), "duplicate_txids", failed)
    unresolved_groups = _v11_contract_int(payload.get("unresolved_groups"), "unresolved_groups", failed)

    if scope == CANONICAL_PROOF_SCOPE_ALL_BLOCKS:
        if policy.get("block_filter_requested") is not True:
            failed.append(f"canonical_policy_block_filter_requested:{policy.get('block_filter_requested')!r}")
        if policy.get("block_filter_always") is not True:
            failed.append(f"canonical_policy_block_filter_always:{policy.get('block_filter_always')!r}")
        if policy.get("lookup_skipped_no_duplicates") is not False:
            failed.append("canonical_policy_unexpected_lookup_skip")
        if payload.get("block_identity_verified") is not True:
            failed.append("canonical_block_identity_not_verified")
        if payload.get("block_identity_verification_status") != "VERIFIED_REQUIRED_BLOCK_SET":
            failed.append("canonical_block_identity_status_mismatch")
        if local_rows <= 0:
            failed.append("canonical_local_block_rows_not_positive")
        if distinct_heights <= 0:
            failed.append("canonical_distinct_heights_not_positive")
    elif scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED:
        if policy.get("block_filter_always") is not False:
            failed.append(f"canonical_policy_block_filter_always:{policy.get('block_filter_always')!r}")
        if duplicate_txids == 0:
            if policy.get("block_filter_requested") is not False:
                failed.append("canonical_duplicate_triggered_filter_requested_without_duplicates")
            if policy.get("lookup_skipped_no_duplicates") is not True:
                failed.append("canonical_duplicate_triggered_skip_marker_missing")
            if payload.get("block_identity_verified") is not False:
                failed.append("canonical_duplicate_triggered_identity_must_be_unverified_without_duplicates")
            if payload.get("block_identity_verification_status") != "NOT_REQUESTED_NO_DUPLICATES":
                failed.append("canonical_duplicate_triggered_identity_status_mismatch")
            if local_rows != 0 or lookup_ok != 0 or distinct_heights != 0:
                failed.append(
                    f"canonical_duplicate_triggered_nonzero_lookup_counters:{local_rows},{lookup_ok},{distinct_heights}"
                )
        else:
            if policy.get("block_filter_requested") is not True:
                failed.append("canonical_duplicate_triggered_filter_not_requested_for_duplicates")
            if policy.get("lookup_skipped_no_duplicates") is not False:
                failed.append("canonical_duplicate_triggered_lookup_skip_with_duplicates")
            if payload.get("block_identity_verified") is not True:
                failed.append("canonical_duplicate_triggered_identity_not_verified_for_duplicates")
            if payload.get("block_identity_verification_status") != "VERIFIED_REQUIRED_BLOCK_SET":
                failed.append("canonical_duplicate_triggered_identity_status_mismatch_for_duplicates")
            if local_rows <= 0:
                failed.append("canonical_duplicate_triggered_local_rows_not_positive")
            if distinct_heights <= 0:
                failed.append("canonical_duplicate_triggered_distinct_heights_not_positive")

    if lookup_ok != local_rows:
        failed.append(f"canonical_lookup_coverage:{lookup_ok}!={local_rows}")
    if lookup_error_rows != 0:
        failed.append(f"canonical_lookup_error_rows:{payload.get('lookup_error_rows')}")
    if lookup_bad_hash_rows != 0:
        failed.append(f"canonical_lookup_bad_hash_rows:{payload.get('lookup_bad_hash_rows')}")
    if unresolved_groups != 0:
        failed.append(f"canonical_unresolved_groups:{payload.get('unresolved_groups')}")
    failures = payload.get("failures")
    if not isinstance(failures, list):
        failed.append("canonical_failures_not_list")
    elif failures:
        failed.append(f"canonical_failures_nonempty:{failures}")
    fp_sha = str(payload.get("stage_payload_fingerprint_sha256") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", fp_sha):
        failed.append("canonical_stage_payload_fingerprint_invalid")
    return failed


def _v11_canonical_trust_boundary(scope: Optional[str] = None) -> Dict[str, Any]:
    resolved_scope = scope or _dup_guard_canonical_proof_scope()
    if resolved_scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED:
        message = (
            "Canonical block identity is verified through the external source on days where duplicate "
            "transaction evidence triggers the duplicate guard. Clean days intentionally skip per-block "
            "Esplora lookup because full historical HTTP verification can require hundreds of thousands "
            "of rate-limited requests and greatly extend rebuild time. Raw payload remains trusted from "
            "the configured source and is not independently reconstructed."
        )
        every_height = False
    else:
        message = (
            "Canonical block identity is verified by external block hash at every height. "
            "Raw transaction/input/output payload is trusted from the configured raw source "
            "and is not independently reconstructed from Bitcoin Core or Esplora."
        )
        every_height = True
    return {
        "block_identity_verified": every_height,
        "block_identity_verified_at_every_height": every_height,
        "transaction_payload_verified": False,
        "proof_level": CANONICAL_PROOF_LEVEL,
        "proof_scope": resolved_scope,
        "payload_status": CANONICAL_PAYLOAD_STATUS,
        "severity": "WARNING",
        "effect_on_exit_code": False,
        "message": message,
    }


def _v11_canonical_proof_summary(
    days: Sequence[str],
    stage_fingerprint: Dict[str, Any],
    *,
    context: str,
) -> Dict[str, Any]:
    failures: List[str] = []
    sources: set = set()
    scopes: set = set()
    complete_days = 0
    for day in days:
        manifest = _load_manifest(str(day))
        if not isinstance(manifest, dict):
            failures.append(f"manifest_missing:{day}")
            continue
        proof = manifest.get("canonical_proof")
        day_failures = _v11_validate_canonical_proof_contract(proof, day=str(day))
        if day_failures:
            failures.extend(f"{day}:{item}" for item in day_failures)
            continue
        sources.add(str(proof.get("source")))
        scopes.add(str(proof.get("proof_scope")))
        complete_days += 1
    if len(scopes) > 1:
        failures.append(f"mixed_canonical_proof_scopes:{sorted(scopes)}")
    manifest_set_sha = str(stage_fingerprint.get("sha256") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", manifest_set_sha):
        failures.append("manifest_set_fingerprint_missing_or_invalid")
    failures = sorted(set(failures))
    resolved_scope = next(iter(scopes), _dup_guard_canonical_proof_scope())
    report = {
        "contract_version": CANONICAL_PROOF_CONTRACT_VERSION,
        "proof_level": CANONICAL_PROOF_LEVEL,
        "proof_scope": resolved_scope,
        "payload_verified": False,
        "payload_verification_status": CANONICAL_PAYLOAD_STATUS,
        "days_expected": len(days),
        "days_complete": complete_days,
        "all_complete": bool(not failures and complete_days == len(days)),
        "sources": sorted(sources),
        "manifest_set_sha256": manifest_set_sha or None,
        "failures": failures,
        "trust_boundary": _v11_canonical_trust_boundary(resolved_scope),
    }
    if not report["all_complete"]:
        raise RuntimeError(f"{context} canonical proof summary failed: {report}")
    _warn("CANONICAL TRUST BOUNDARY: " + report["trust_boundary"]["message"])
    return report


def _v11_assert_rebuild_target_absent(db_path: str, *, context: str) -> None:
    candidates = [Path(db_path), Path(str(db_path) + ".wal")]
    existing = [str(path) for path in candidates if path.exists()]
    if existing:
        raise RuntimeError(
            f"{context} requires target DB and WAL to be absent before proof/write phase; existing={existing}. "
            "Quarantine/delete the artifact or select a new UTXO_DB_PATH."
        )


def _v11_target_state_snapshot(con: duckdb.DuckDBPyConnection, db_path: str) -> Dict[str, Any]:
    tail = _v11_db_tail_report(con, db_path)
    utxo_rows, spent_rows = con.execute(
        "SELECT COUNT(*), COUNT(*) FILTER (WHERE spent_height IS NOT NULL) FROM utxo"
    ).fetchone()
    keys = [
        "pipeline_family", "stage_semantics", "causal_order", "txid_mode",
        "output_value_unit", "canonical_proof_contract_version",
        "canonical_proof_required", "canonical_proof_level", "canonical_proof_scope",
        "canonical_payload_verified",
    ]
    meta = {key: _v11_pipeline_meta_get(con, key) for key in keys}
    try:
        st = Path(db_path).stat()
        file_state = {"size": int(st.st_size), "mtime_ns": int(st.st_mtime_ns), "inode": int(getattr(st, "st_ino", 0))}
    except Exception as exc:
        file_state = {"error": f"{type(exc).__name__}:{exc}"}
    logical = {
        "tail": tail,
        "utxo_rows": int(utxo_rows or 0),
        "spent_rows": int(spent_rows or 0),
        "pipeline_meta": meta,
    }
    return {
        "logical": logical,
        "logical_sha256": hashlib.sha256(json.dumps(logical, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest(),
        "file_state": file_state,
    }


def _v11_assert_target_snapshot_unchanged(before: Dict[str, Any], after: Dict[str, Any], *, context: str) -> None:
    if before.get("logical_sha256") != after.get("logical_sha256"):
        raise RuntimeError(f"{context} target DB logical state changed between read-only preflight and write phase: before={before} after={after}")
    before_file = before.get("file_state") if isinstance(before.get("file_state"), dict) else {}
    after_file = after.get("file_state") if isinstance(after.get("file_state"), dict) else {}
    for key in ("inode", "size", "mtime_ns"):
        if key in before_file and key in after_file and before_file.get(key) != after_file.get(key):
            raise RuntimeError(f"{context} target DB file state changed before write phase: {key} {before_file.get(key)}!={after_file.get(key)}")


def _classify_exception(exc: Exception) -> str:
    msg = f"{type(exc).__name__}: {exc}".lower()
    if "outofmemory" in msg or "out of memory" in msg or "oom" in msg:
        return "OOM"
    if "no space left" in msg or "disk full" in msg or "max_temp_directory_size" in msg:
        return "DISK_FULL"
    if "lock" in msg or "writer lock" in msg or "conflicting lock" in msg:
        return "LOCK_CONFLICT"
    if "internal error" in msg or "fatal" in msg:
        return "INTERNAL_ERROR"
    if "schema" in msg or "type mismatch" in msg or "binder" in msg:
        return "SCHEMA_DRIFT"
    if "audit" in msg:
        return "AUDIT_FAIL"
    return "RUNTIME_ERROR"




@dataclass(frozen=True)
class _V11StageGenerationLockHandle:
    primary: Path
    compatibility_locks: Tuple[Path, ...]


def _v11_acquire_stage_generation_lock(extra: Dict[str, Any]) -> _V11StageGenerationLockHandle:
    """Acquire one mutually exclusive lock contract across R41 and R44 names.

    R41 processes know only one of stage/append-stage/replay-suffix-stage. R44
    therefore holds all three legacy names for the entire operation, then also
    acquires the unified stage-generation lock. If any acquisition fails, every
    lock already acquired by this attempt is released before the error escapes.
    """
    identity = str(_stage_root_path_no_create().resolve())
    acquired: List[Path] = []
    compatibility_extra = dict(extra)
    compatibility_extra.update({
        "compatibility_guard_for": "stage-generation",
        "compatibility_contract": V11_STAGE_LOCK_COMPAT_CONTRACT_VERSION,
    })
    try:
        for kind in ("stage", "append-stage", "replay-suffix-stage"):
            acquired.append(
                _v11_acquire_dir_lock(kind, identity, compatibility_extra)
            )
        primary = _v11_acquire_dir_lock("stage-generation", identity, extra)
        return _V11StageGenerationLockHandle(
            primary=primary,
            compatibility_locks=tuple(acquired),
        )
    except BaseException as exc:
        release_errors: List[str] = []
        for lock_dir in reversed(acquired):
            try:
                _v11_release_dir_lock(lock_dir)
            except BaseException as release_exc:
                release_errors.append(
                    f"{lock_dir}:{type(release_exc).__name__}:{release_exc}"
                )
        if release_errors:
            raise RuntimeError(
                "stage-generation compatibility-lock acquisition failed and rollback "
                "was incomplete: " + "; ".join(release_errors)
            ) from exc
        raise


def _v11_release_stage_generation_lock(
    handle: Optional[_V11StageGenerationLockHandle],
) -> None:
    if handle is None:
        return
    errors: List[str] = []
    for lock_dir in (handle.primary, *reversed(handle.compatibility_locks)):
        try:
            _v11_release_dir_lock(lock_dir)
        except BaseException as exc:
            errors.append(f"{lock_dir}:{type(exc).__name__}:{exc}")
    if errors:
        raise RuntimeError(
            "stage-generation lock release failures: " + "; ".join(errors)
        )

def _lock_root(create: bool = True) -> Path:
    raw = _env_str("UTXO_LOCK_ROOT", LOCK_ROOT_DEFAULT) or LOCK_ROOT_DEFAULT
    p = Path(raw)
    if create:
        p.mkdir(parents=True, exist_ok=True)
        try:
            p.chmod(0o700)
        except Exception:
            pass
    return p


def _lock_key(value: str) -> str:
    return hashlib.sha256(str(value).encode("utf-8")).hexdigest()[:16]


def _lock_payload_file(lock_dir: Path) -> Path:
    return lock_dir / "payload.json"


def _read_lock_dir_payload(lock_dir: Path) -> Optional[Dict[str, Any]]:
    try:
        with open(_lock_payload_file(lock_dir), "r", encoding="utf-8") as f:
            payload = json.load(f)
        return payload if isinstance(payload, dict) else None
    except Exception:
        return None


def _v11_lock_dir(kind: str, identity: str) -> Path:
    safe_kind = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(kind)) if "re" in globals() else str(kind).replace("/", "_")
    return _lock_root(create=True) / f"utxo_v11_{safe_kind}.{_lock_key(identity)}.lock"


def _v11_lock_payload(kind: str, identity: str, extra: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    payload: Dict[str, Any] = {
        "lock_kind": str(kind),
        "identity": str(identity),
        "identity_sha256": hashlib.sha256(str(identity).encode("utf-8")).hexdigest(),
        "pid": os.getpid(),
        "host": socket.gethostname(),
        "cmdline": " ".join(sys.argv),
        "created_at": _now_iso(),
        "pipeline_version": _pipeline_version(),
        "mode": _CURRENT_MODE,
        "raw_base": _env_str("UTXO_RAW_BASE", RAW_BASE_DEFAULT),
        "db_path": _env_str("UTXO_DB_PATH", DB_PATH_DEFAULT),
        "stage_dir": str(_stage_root_path_no_create()),
        "lock_root": str(_lock_root(create=False)),
    }
    if extra:
        payload.update(extra)
    return payload


def _v11_payload_pid_alive(payload: Optional[Dict[str, Any]]) -> bool:
    if not payload:
        return False
    try:
        pid = int(payload.get("pid") or 0)
    except Exception:
        pid = 0
    return _pid_alive(pid)


def _v11_reclaim_lock_allowed(lock_dir: Path, payload: Optional[Dict[str, Any]]) -> bool:
    if not _env_bool("UTXO_RECLAIM_STALE_V11_LOCKS", False):
        return False
    min_age_sec = max(0, _env_int("UTXO_STALE_V11_LOCK_MINUTES", 60)) * 60
    age_sec = _lock_file_age_seconds(lock_dir)
    if age_sec is None or age_sec < min_age_sec:
        return False
    if payload and _v11_payload_pid_alive(payload):
        return False
    return True


def _v11_active_apply_worker_processes() -> List[Dict[str, Any]]:
    """Return live APPLY or recovery workers visible in /proc.

    The historical function name is retained for call-site compatibility. The
    scanner is intentionally independent of job/result files: a parent may die
    before publishing another lease artifact while an already-execed child can
    still have the DB open. Both worker command-line contracts therefore block
    stale lock reclaim until the child disappears.
    """
    workers: List[Dict[str, Any]] = []
    proc_root = Path("/proc")
    if not proc_root.is_dir():
        raise RuntimeError(
            "cannot inspect /proc before stale lock reclaim; active APPLY/recovery "
            "worker presence is unknown"
        )
    uncertain: List[str] = []
    try:
        entries = list(proc_root.iterdir())
    except OSError as exc:
        raise RuntimeError(
            f"cannot enumerate /proc before stale lock reclaim: {type(exc).__name__}:{exc}"
        ) from exc
    worker_flags = (
        ("--v11-apply-worker-job", "APPLY"),
        ("--v11-recovery-worker-job", "RECOVERY"),
    )
    for entry in entries:
        if not entry.name.isdigit():
            continue
        pid = int(entry.name)
        if pid == os.getpid():
            continue
        try:
            raw = (entry / "cmdline").read_bytes()
        except (FileNotFoundError, ProcessLookupError):
            continue
        except PermissionError as exc:
            uncertain.append(f"pid={pid}:PermissionError:{exc}")
            continue
        except OSError as exc:
            if getattr(exc, "errno", None) in {2, 3}:
                continue
            uncertain.append(f"pid={pid}:{type(exc).__name__}:{exc}")
            continue
        if not raw:
            continue
        args = [
            part.decode("utf-8", errors="replace")
            for part in raw.split(b"\x00")
            if part
        ]
        match: Optional[Tuple[str, str, int]] = None
        for flag, worker_kind in worker_flags:
            try:
                match = (flag, worker_kind, args.index(flag))
                break
            except ValueError:
                continue
        if match is None:
            continue
        flag, worker_kind, flag_index = match
        job_path = args[flag_index + 1] if flag_index + 1 < len(args) else None
        workers.append({
            "pid": pid,
            "worker_kind": worker_kind,
            "worker_flag": flag,
            "job_path": job_path,
            "cmdline": " ".join(args)[:2000],
        })
    if uncertain:
        raise RuntimeError(
            "cannot prove that no APPLY/recovery worker is active before stale lock reclaim; "
            f"proc_scan_errors={uncertain[:20]}"
        )
    return workers


def _v11_block_lock_reclaim_if_apply_worker_active(*, lock_kind: str, lock_path: Path) -> None:
    workers = _v11_active_apply_worker_processes()
    if not workers:
        return
    _emit_event(
        "W17922",
        "ACTIVE_APPLY_OR_RECOVERY_WORKER_BLOCKED_LOCK_RECLAIM "
        f"lock_kind={lock_kind} lock_path={lock_path} workers={workers[:10]}",
        stream=sys.stderr,
    )
    raise RuntimeError(
        "refusing to reclaim a stale pipeline lock while an APPLY or recovery "
        f"worker process is still visible; lock_kind={lock_kind} lock_path={lock_path} "
        f"workers={workers[:10]}"
    )


def _v11_acquire_dir_lock(kind: str, identity: str, extra: Optional[Dict[str, Any]] = None) -> Path:
    """Acquire a directory lock and roll back a partially created lock on payload failure."""
    lock_dir = _v11_lock_dir(kind, identity)
    payload = _v11_lock_payload(kind, identity, extra)
    while True:
        try:
            lock_dir.mkdir(mode=0o700)
            try:
                _save_json_atomic(_lock_payload_file(lock_dir), payload)
            except BaseException:
                try:
                    shutil.rmtree(lock_dir)
                    if lock_dir.exists():
                        raise RuntimeError(f"partial v11 lock directory still exists after rollback: {lock_dir}")
                    _fsync_directory(lock_dir.parent)
                except BaseException as cleanup_exc:
                    raise RuntimeError(
                        f"v11 lock payload write failed and partial-lock rollback failed: "
                        f"lock={lock_dir} cleanup={type(cleanup_exc).__name__}:{cleanup_exc}"
                    ) from cleanup_exc
                raise
            _fsync_directory(lock_dir.parent)
            _log(f"v11 lock acquired kind={kind} path={lock_dir}")
            return lock_dir
        except FileExistsError as e:
            existing = _read_lock_dir_payload(lock_dir)
            reclaim = False
            if existing:
                lock_host = str(existing.get("host") or "")
                try:
                    lock_pid = int(existing.get("pid") or 0)
                except Exception:
                    lock_pid = 0
                if lock_host == socket.gethostname() and not _pid_alive(lock_pid):
                    _v11_block_lock_reclaim_if_apply_worker_active(
                        lock_kind=f"v11:{kind}",
                        lock_path=lock_dir,
                    )
                    reclaim = True
                    _warn(f"reclaiming stale v11 lock kind={kind}: {lock_dir} pid={lock_pid} host={lock_host}")
            if not reclaim and _v11_reclaim_lock_allowed(lock_dir, existing):
                _v11_block_lock_reclaim_if_apply_worker_active(
                    lock_kind=f"v11:{kind}",
                    lock_path=lock_dir,
                )
                reclaim = True
                _warn(f"reclaiming stale v11 lock kind={kind}: {lock_dir}")
            if reclaim:
                shutil.rmtree(lock_dir)
                if lock_dir.exists():
                    raise RuntimeError(f"stale v11 lock reclaim did not remove directory: {lock_dir}")
                _fsync_directory(lock_dir.parent)
                continue
            raise RuntimeError(f"v11 lock already exists kind={kind}: {lock_dir} payload={existing}") from e



def _v11_release_dir_lock(lock_dir: Optional[Path]) -> None:
    """Release only a lock owned by this process; never log success while it remains."""
    if not lock_dir:
        return
    if not lock_dir.exists():
        return
    payload = _read_lock_dir_payload(lock_dir)
    if not isinstance(payload, dict):
        raise RuntimeError(f"cannot release v11 lock with missing/unreadable payload: {lock_dir}")
    try:
        payload_pid = int(payload.get("pid") or 0)
    except Exception:
        payload_pid = 0
    payload_host = str(payload.get("host") or "")
    if payload_pid != os.getpid() or payload_host not in {"", socket.gethostname(), "localhost"}:
        raise RuntimeError(
            f"refusing to release v11 lock owned by another process/host: "
            f"path={lock_dir} pid={payload_pid} host={payload_host!r} "
            f"expected_pid={os.getpid()} expected_host={socket.gethostname()!r}"
        )
    shutil.rmtree(lock_dir)
    if lock_dir.exists():
        raise RuntimeError(f"v11 lock release failed; directory still exists: {lock_dir}")
    _fsync_directory(lock_dir.parent)
    _log(f"v11 lock released path={lock_dir}")



def _v11_lock_preflight_rw() -> None:
    root = _lock_root(create=True)
    token = f".v11-lock-preflight.{os.getpid()}.{uuid.uuid4().hex}"
    probe = root / token
    moved = root / (token + ".renamed")
    try:
        with open(probe, "x", encoding="utf-8") as f:
            f.write(_now_iso() + " v11 lock preflight\n")
        probe.rename(moved)
        moved.unlink()
        _log(f"v11 lock_root preflight rw ok lock_root={root}")
    except Exception as e:
        for x in (probe, moved):
            try:
                x.unlink(missing_ok=True)
            except Exception:
                pass
        raise RuntimeError(f"v11 lock_root preflight failed lock_root={root}: {type(e).__name__}: {e}") from e


def _writer_lock_path() -> Path:
    stage_identity = str(_stage_root_path_no_create().resolve())
    return _lock_root(create=True) / f"utxo_v11_writer.{_lock_key(stage_identity)}.lock"


def _pid_alive(pid: Optional[int]) -> bool:
    if not pid or pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    else:
        return True


def _read_writer_lock_payload(path: Path) -> Optional[Dict[str, Any]]:
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _lock_file_age_seconds(path: Path) -> Optional[float]:
    try:
        return max(0.0, datetime.now().timestamp() - path.stat().st_mtime)
    except Exception:
        return None


def _should_reclaim_foreign_or_malformed_lock(path: Path, payload: Optional[Dict[str, Any]]) -> bool:
    if not _env_bool("UTXO_RECLAIM_STALE_WRITER_LOCKS", False):
        return False
    min_age_sec = max(0, _env_int("UTXO_STALE_WRITER_LOCK_MINUTES", 60)) * 60
    age_sec = _lock_file_age_seconds(path)
    if age_sec is None or age_sec < min_age_sec:
        return False
    if not payload:
        return True
    lock_pid_raw = payload.get("pid")
    try:
        lock_pid = int(lock_pid_raw) if lock_pid_raw is not None else None
    except Exception:
        lock_pid = None
    return not _pid_alive(lock_pid)


def _acquire_writer_lock(mode: str) -> Optional[Path]:
    """Acquire a durable, ownership-bound writer lock.

    The lock file and its parent directory are fsync-confirmed before the caller
    may proceed.  A failed payload write is rolled back so a zero-length lock can
    never become a permanent false owner.
    """
    if mode == MODE_VERIFY_MANIFESTS:
        return None
    path = _writer_lock_path()
    hostname = socket.gethostname()
    payload = {
        "pid": os.getpid(),
        "host": hostname,
        "run_id": _new_run_id(),
        "mode": str(mode),
        "at": _now_iso(),
        "pipeline_version": _pipeline_version(),
    }
    while True:
        try:
            fd = os.open(str(path), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            break
        except FileExistsError as e:
            existing = _read_writer_lock_payload(path)
            if existing:
                lock_host = str(existing.get("host") or "")
                lock_pid_raw = existing.get("pid")
                try:
                    lock_pid = int(lock_pid_raw) if lock_pid_raw is not None else None
                except Exception:
                    lock_pid = None
                if lock_host == hostname and not _pid_alive(lock_pid):
                    _v11_block_lock_reclaim_if_apply_worker_active(
                        lock_kind="writer",
                        lock_path=path,
                    )
                    _warn(f"reclaiming stale writer lock: {path} pid={lock_pid} host={lock_host}")
                    path.unlink()
                    _fsync_directory(path.parent)
                    continue
            if _should_reclaim_foreign_or_malformed_lock(path, existing):
                _v11_block_lock_reclaim_if_apply_worker_active(
                    lock_kind="writer",
                    lock_path=path,
                )
                _warn(f"reclaiming stale foreign/malformed writer lock: {path}")
                path.unlink()
                _fsync_directory(path.parent)
                continue
            raise RuntimeError(f"writer lock already exists: {path}") from e

    created = True
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            fd = -1
            json.dump(payload, f, ensure_ascii=False, sort_keys=True)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())
        _fsync_directory(path.parent)
    except BaseException as exc:
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                pass
        cleanup_error: Optional[BaseException] = None
        if created:
            try:
                path.unlink(missing_ok=True)
                _fsync_directory(path.parent)
            except BaseException as cleanup_exc:
                cleanup_error = cleanup_exc
        if cleanup_error is not None:
            raise RuntimeError(
                f"writer lock payload persistence failed: {type(exc).__name__}: {exc}; "
                f"partial-lock cleanup failed: {type(cleanup_error).__name__}: {cleanup_error}"
            ) from exc
        raise
    return path


def _release_writer_lock(lock_path: Optional[Path]) -> None:
    """Release only the current process' writer lock and persist the unlink."""
    if not lock_path:
        return
    if not lock_path.exists():
        return
    try:
        payload = json.loads(lock_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(
            f"cannot verify writer lock ownership before release path={lock_path}: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    if not isinstance(payload, dict):
        raise RuntimeError(f"writer lock payload is not an object: {lock_path}")
    try:
        owner_pid = int(payload.get("pid"))
    except Exception as exc:
        raise RuntimeError(f"writer lock pid is invalid path={lock_path}: {payload.get('pid')!r}") from exc
    local_hosts = {
        socket.gethostname(),
        socket.getfqdn(),
        os.uname().nodename if hasattr(os, "uname") else "",
        "localhost",
    }
    owner_host = str(payload.get("host") or "")
    if owner_pid != os.getpid() or owner_host not in local_hosts:
        raise RuntimeError(
            f"writer lock ownership changed path={lock_path}: "
            f"owner_pid={owner_pid} current_pid={os.getpid()} owner_host={owner_host!r}"
        )
    lock_path.unlink()
    _fsync_directory(lock_path.parent)
    if lock_path.exists():
        raise RuntimeError(f"writer lock still exists after release: {lock_path}")


def _remove_stage_day_dir(day: str, reason: str) -> None:
    day_dir = _stage_root() / f"date={day}"
    if day_dir.exists():
        shutil.rmtree(day_dir, ignore_errors=True)
        _log(f"replay stage cleanup day={day} reason={reason}")


def _prepare_day_for_replay(day: str) -> None:
    day_dir = _stage_root() / f"date={day}"
    if not day_dir.exists():
        return
    manifest_path = day_dir / "manifest.json"
    if not manifest_path.exists():
        _remove_stage_day_dir(day, "stage_without_manifest")
        return
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        _remove_stage_day_dir(day, "manifest_unreadable")
        return
    status = str(manifest.get("status") or "")
    replayable_statuses = {
        STATUS_BUILDING,
        STATUS_CLEANUP_CHECK,
        STATUS_CLEANUP_SKIPPED,
        STATUS_CLEANUP_SPENT,
        STATUS_CLEANUP_CREATED,
        STATUS_CLEANUP_VERIFY,
        STATUS_CLEANUP_DONE,
        STATUS_READY,
        STATUS_APPLYING,
        STATUS_APPLIED,
        STATUS_CHECKPOINTED,
        STATUS_FAILED,
        STATUS_PREAPPLY_GUARD,
        STATUS_DUPLICATE_GUARD,
        STATUS_DUPLICATE_GUARD_OK,
        STATUS_BLOCKED_BEFORE_APPLY,
        STATUS_RESOLVED_BIP30_EXCEPTION,
        STATUS_RESOLVED_CANONICAL_SELECTED,
        STATUS_RESOLVED_CANONICAL_BLOCK_FILTER,
        STATUS_RESOLVED_NO_DUPLICATES,
    }
    if status in replayable_statuses:
        _remove_stage_day_dir(day, f"replay_status={status}")
        return
    if status == STATUS_AUDIT_FAIL:
        if _env_bool("UTXO_FORCE_REPLAY_AUDIT_FAIL", False):
            _remove_stage_day_dir(day, "force_replay_audit_fail")
            return
        raise RuntimeError(f"day={day} has AUDIT_FAIL stage; set UTXO_FORCE_REPLAY_AUDIT_FAIL=1 to purge and replay")


def _verify_manifest_files(day: str) -> Dict[str, Any]:
    manifest = _load_manifest(day)
    if not manifest:
        return {"status": "fail", "failed_checks": ["manifest_missing"]}
    failed: List[str] = []
    files = manifest.get("files", {})
    status = str(manifest.get("status") or "")
    if not files.get("manifest_path"):
        failed.append("manifest_path_missing")
    if status in {STATUS_READY, STATUS_APPLYING, STATUS_APPLIED, STATUS_CHECKPOINTED, STATUS_AUDIT_FAIL, STATUS_FAILED}:
        if not Path(files.get("created_parquet", "")).exists() and not manifest.get("purge", {}).get("created_parquet_deleted", False):
            failed.append("created_stage_missing")
        if not Path(files.get("spends_parquet", "")).exists() and not manifest.get("purge", {}).get("spends_parquet_deleted", False):
            failed.append("spends_stage_missing")
        if not Path(files.get("block_meta_parquet", "")).exists():
            failed.append("block_meta_stage_missing")
    return {"status": "ok" if not failed else "fail", "failed_checks": failed, "status_value": status}
# -----------------------------
# cleanup / retention / preflight
# -----------------------------

def _gb_to_bytes(gb: float) -> int:
    return int(gb * 1024 * 1024 * 1024)



def _preflight_check_path(path: Path, min_free_gb: float, label: str) -> None:
    if min_free_gb <= 0:
        return
    target = path if path.exists() else path.parent
    usage = shutil.disk_usage(target)
    if usage.free < _gb_to_bytes(min_free_gb):
        raise RuntimeError(
            f"preflight failed for {label}: free={usage.free} bytes is below required minimum={_gb_to_bytes(min_free_gb)}"
        )



def _run_preflight(db_path: str) -> None:
    _preflight_check_path(Path(db_path), _env_float("UTXO_MIN_FREE_DB_GB", 0.0), "db")
    _preflight_check_path(_stage_root(), _env_float("UTXO_MIN_FREE_STAGE_GB", 0.0), "stage")
    tmpdir = Path(_env_str("DUCKDB_TMPDIR", "/tmp") or "/tmp")
    _preflight_check_path(tmpdir, _env_float("UTXO_MIN_FREE_TMP_GB", 0.0), "tmp")



def _cleanup_orphan_tmp_files() -> None:
    hours = _env_int("UTXO_STAGE_TMP_RETENTION_HOURS", 24)
    if hours <= 0:
        return
    cutoff = datetime.now() - timedelta(hours=hours)
    removed = 0
    for p in _stage_root().rglob("*.tmp.*"):
        try:
            mtime = datetime.fromtimestamp(p.stat().st_mtime)
            if mtime < cutoff:
                p.unlink(missing_ok=True)
                removed += 1
        except Exception:
            continue
    if removed:
        _log(f"cleanup tmp: removed={removed}")



def _cleanup_old_failed_stage() -> None:
    keep_days = _env_int("UTXO_STAGE_FAILED_RETENTION_DAYS", 14)
    if keep_days <= 0:
        return
    cutoff = datetime.now() - timedelta(days=keep_days)
    removed = 0
    removed_dirs = 0
    for manifest_path in _stage_root().rglob("manifest.json"):
        try:
            with open(manifest_path, "r", encoding="utf-8") as f:
                manifest = json.load(f)
            status = manifest.get("status")
            if status not in {STATUS_FAILED, STATUS_AUDIT_FAIL}:
                continue
            updated_at = manifest.get("updated_at")
            if not updated_at:
                continue
            updated_dt = datetime.fromisoformat(updated_at.replace("Z", "+00:00")).replace(tzinfo=None)
            if updated_dt >= cutoff:
                continue
            day_dir = manifest_path.parent
            for key in ("created_parquet", "spends_parquet"):
                path = manifest.get("files", {}).get(key)
                if path:
                    Path(path).unlink(missing_ok=True)
            if _env_bool("UTXO_PURGE_FAILED_STAGE_DIRS", False):
                shutil.rmtree(day_dir, ignore_errors=True)
                removed_dirs += 1
            removed += 1
        except Exception:
            continue
    if removed:
        _log(f"cleanup failed-stage: removed_stage_files={removed} removed_dirs={removed_dirs}")


# -----------------------------
# SQL builders
# -----------------------------

def _tx_scan_cte_sql(has_tx_index: bool, tx_index_map_path: Optional[Path] = None) -> str:
    """Return a tx CTE with stable tx_index for explicit, map, or fallback ordering."""
    if tx_index_map_path is not None:
        join_col = _tx_index_map_join_column(tx_index_map_path)
        return f"""
    WITH tx AS (
      SELECT t.*, im.canonical_tx_index::BIGINT AS __tx_index
      FROM read_parquet(?) t
      JOIN read_parquet({_quote_sql_string(str(tx_index_map_path))}) AS im
        ON im.block_number = t.block_number::BIGINT
       AND lower(im.block_hash::VARCHAR) = lower(t.block_hash::VARCHAR)
       AND lower(im.{join_col}::VARCHAR) = lower(t.hash::VARCHAR)
    )
    """
    if has_tx_index:
        return """
    WITH tx AS (
      SELECT t.*, t."index"::BIGINT AS __tx_index
      FROM read_parquet(?) t
    )
    """
    return """
    WITH tx_base AS (
      SELECT t.*, ROW_NUMBER() OVER () AS __scan_row
      FROM read_parquet(?) t
    ), tx AS (
      SELECT tx_base.*, ROW_NUMBER() OVER (PARTITION BY tx_base.block_number::BIGINT, lower(tx_base.block_hash::VARCHAR) ORDER BY tx_base.__scan_row) - 1 AS __tx_index
      FROM tx_base
    )
    """


def _created_insert_sql(output_has_address: bool, day: str, has_tx_index: bool = True, tx_index_map_path: Optional[Path] = None) -> str:
    address_expr = _created_address_expr(output_has_address)
    value_expr = _created_value_expr()
    txid_expr = _canonical_txid_expr(day, "t")
    map_join = _canonical_map_join_sql(day, "t")
    tx_cte = _tx_scan_cte_sql(has_tx_index, tx_index_map_path)
    return f"""
    {tx_cte}
    INSERT INTO created_stage_raw(txid, vout, address, value_btc, created_ts, created_date, block_number, block_hash, tx_index, raw_partition_date, is_coinbase)
    SELECT
      {txid_expr} AS txid,
      out.index::BIGINT AS vout,
      {address_expr} AS address,
      {value_expr} AS value_btc,
      t.block_timestamp AS created_ts,
      CAST(t.block_timestamp AS DATE) AS created_date,
      t.block_number::BIGINT AS block_number,
      lower(t.block_hash::VARCHAR) AS block_hash,
      t.__tx_index::BIGINT AS tx_index,
      CAST(t.date AS DATE) AS raw_partition_date,
      COALESCE(t.is_coinbase, false) AS is_coinbase
    FROM tx t
    {map_join}
    CROSS JOIN UNNEST(t.outputs) AS o(out)
    WHERE t.block_number::BIGINT <> 0
      AND lower(t.hash::VARCHAR) <> '4a5e1e4baab89f3a32518a88c31bc87f618f76673e2cc77ab2127b7afdeda33b';
    """



def _spends_insert_sql(day: str, has_tx_index: bool = True, tx_index_map_path: Optional[Path] = None) -> str:
    spent_txid_expr = _canonical_txid_expr(day, "t")
    map_join = _canonical_map_join_sql(day, "t")
    tx_cte = _tx_scan_cte_sql(has_tx_index, tx_index_map_path)
    return f"""
    {tx_cte}
    INSERT INTO spends_stage_raw(prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date, block_number, block_hash, tx_index, raw_partition_date, is_coinbase)
    SELECT prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date, block_number, block_hash, tx_index, raw_partition_date, is_coinbase
    FROM (
      SELECT
        lower(inp.spent_transaction_hash::VARCHAR) AS prev_txid,
        inp.spent_output_index::BIGINT AS prev_vout,
        {spent_txid_expr} AS spent_txid,
        inp.index::BIGINT AS spent_vin,
        t.block_timestamp AS spent_ts,
        CAST(t.block_timestamp AS DATE) AS spent_date,
        t.block_number::BIGINT AS block_number,
        lower(t.block_hash::VARCHAR) AS block_hash,
        t.__tx_index::BIGINT AS tx_index,
        CAST(t.date AS DATE) AS raw_partition_date,
        COALESCE(t.is_coinbase, false) AS is_coinbase,
        ROW_NUMBER() OVER (
          PARTITION BY lower(inp.spent_transaction_hash::VARCHAR), inp.spent_output_index
          ORDER BY t.block_number::BIGINT, t.__tx_index::BIGINT, inp.index
        ) AS rn
      FROM tx t
      {map_join}
      CROSS JOIN UNNEST(t.inputs) AS u(inp)
      WHERE NOT COALESCE(t.is_coinbase, false)
        AND inp.spent_transaction_hash IS NOT NULL
        AND inp.spent_output_index IS NOT NULL
    ) x
    WHERE rn = 1;
    """


def _created_dedup_sql(src_table: str, dst_table: str) -> str:
    return f"""
    CREATE OR REPLACE TEMP TABLE {dst_table} AS
    SELECT
      txid,
      vout,
      address,
      value_btc,
      created_ts,
      created_date,
      block_number,
      tx_index,
      block_hash,
      raw_partition_date
    FROM (
      SELECT
        *,
        ROW_NUMBER() OVER (
          PARTITION BY txid, vout
          ORDER BY block_number, tx_index, created_ts, raw_partition_date, block_hash
        ) AS rn
      FROM {src_table}
      WHERE txid IS NOT NULL AND vout IS NOT NULL
    ) x
    WHERE rn = 1;
    """




def _spends_dedup_sql(src_table: str, dst_table: str) -> str:
    return f"""
    CREATE OR REPLACE TEMP TABLE {dst_table} AS
    SELECT
      prev_txid,
      prev_vout,
      spent_txid,
      spent_vin,
      spent_ts,
      spent_date,
      block_number,
      tx_index,
      block_hash,
      raw_partition_date
    FROM (
      SELECT
        *,
        ROW_NUMBER() OVER (
          PARTITION BY prev_txid, prev_vout
          ORDER BY block_number, tx_index, spent_vin, spent_ts, raw_partition_date, block_hash
        ) AS rn
      FROM {src_table}
      WHERE prev_txid IS NOT NULL AND prev_vout IS NOT NULL
    ) x
    WHERE rn = 1;
    """



def _dup_count_sql(table_name: str, k1: str, k2: str) -> str:
    return f"""
    SELECT COALESCE(SUM(cnt - 1), 0)
    FROM (
      SELECT COUNT(*) AS cnt
      FROM {table_name}
      GROUP BY {k1}, {k2}
      HAVING COUNT(*) > 1
    ) d;
    """


