def _count_tx_rows(con: duckdb.DuckDBPyConnection, parquet_path: str) -> int:
    return int(con.execute("SELECT COUNT(*) FROM read_parquet(?)", [parquet_path]).fetchone()[0])


def _tx_index_null_rows(con: duckdb.DuckDBPyConnection, parquet_path: str) -> int:
    """Return rows where top-level transaction index is NULL.

    fix14-null-txindex-fallback-r1.

    Some AWS BTC parquet partitions expose a top-level `index` column in the
    schema, but the values can be NULL for a whole physical file. Treating
    mere column presence as causal tx_index availability makes v11 stage
    validation fail later with *_missing_causal_fields. This probe separates
    column presence from usable causal data. Call only after ParquetFeatures
    confirmed that the top-level index column exists.
    """
    return int(con.execute('SELECT COUNT(*) FROM read_parquet(?) WHERE "index" IS NULL', [parquet_path]).fetchone()[0] or 0)




def _tx_index_quality_from_counts(*, path: str, has_tx_index: bool, tx_rows: int, null_rows: int) -> Dict[str, Any]:
    """Classify raw top-level tx index quality for v11 causal ordering.

    fix15-stage-causal-preflight-r1.

    Policy:
      * all explicit index values present: production OK;
      * no top-level index column: legacy guarded scan-order fallback path;
      * top-level index exists but all rows are NULL: guarded scan-order fallback path;
      * top-level index exists and only some rows are NULL: RED fatal. This
        mixed state was proven unsafe by REPLAY_SUFFIX causal postcheck and now
        requires a future canonical tx_index resolver/map rather than blind
        scan-order fallback.
    """
    tx_rows_i = int(tx_rows or 0)
    null_rows_i = int(null_rows or 0)
    not_null_rows_i = max(0, tx_rows_i - null_rows_i) if has_tx_index else 0
    if not has_tx_index:
        mode = "missing_top_level_index"
        decision = "guarded_scan_order_fallback"
        severity = "yellow"
    elif tx_rows_i == 0:
        mode = "empty_file"
        decision = "ok_empty"
        severity = "ok"
    elif null_rows_i == 0:
        mode = "all_index_not_null"
        decision = "ok_top_level_index"
        severity = "ok"
    elif null_rows_i == tx_rows_i:
        mode = "all_index_null"
        decision = "guarded_scan_order_fallback"
        severity = "yellow"
    else:
        mode = "partial_index_null"
        decision = "red_fatal_requires_canonical_tx_index_resolver"
        severity = "red"
    return {
        "path": str(path),
        "has_tx_index": bool(has_tx_index),
        "tx_rows": tx_rows_i,
        "index_null_rows": null_rows_i if has_tx_index else None,
        "index_not_null_rows": not_null_rows_i if has_tx_index else None,
        "mode": mode,
        "decision": decision,
        "severity": severity,
    }


def _tx_index_audit(raw_base: str, days: Sequence[str]) -> int:
    """Audit raw parquet transaction-index quality without mutating UTXO DB."""
    rows: List[Dict[str, Any]] = []
    con = duckdb.connect()
    try:
        _apply_duckdb_pragmas(con, phase="stage")
        for day in days:
            files = _day_parquet_files(raw_base, str(day))
            if not files:
                rows.append({
                    "day": str(day),
                    "file": "",
                    "tx_rows": 0,
                    "has_tx_index": False,
                    "index_null_rows": "",
                    "index_not_null_rows": "",
                    "index_mode": "no_raw_files",
                    "decision": "red_no_raw_files",
                    "severity": "red",
                    "max_txs_per_block": "",
                })
                continue
            for fp in files:
                feats = _inspect_parquet_features(fp)
                tx_rows = _count_tx_rows(con, fp)
                null_rows = _tx_index_null_rows(con, fp) if feats.has_tx_index else int(tx_rows)
                q = _tx_index_quality_from_counts(path=fp, has_tx_index=feats.has_tx_index, tx_rows=tx_rows, null_rows=null_rows)
                max_txs_per_block = int(con.execute(
                    """
                    SELECT COALESCE(MAX(cnt), 0)
                    FROM (
                      SELECT block_number, lower(block_hash::VARCHAR) AS block_hash, COUNT(*) AS cnt
                      FROM read_parquet(?)
                      WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
                      GROUP BY 1, 2
                    ) g
                    """,
                    [fp],
                ).fetchone()[0] or 0)
                rows.append({
                    "day": str(day),
                    "file": fp,
                    "tx_rows": int(tx_rows),
                    "has_tx_index": bool(feats.has_tx_index),
                    "index_null_rows": q.get("index_null_rows"),
                    "index_not_null_rows": q.get("index_not_null_rows"),
                    "index_mode": q.get("mode"),
                    "decision": q.get("decision"),
                    "severity": q.get("severity"),
                    "max_txs_per_block": max_txs_per_block,
                })
    finally:
        con.close()

    logs_dir = Path(_env_str("UTXO_LOG_DIR", "/root/mybot/logs") or "/root/mybot/logs")
    logs_dir.mkdir(parents=True, exist_ok=True)
    ts = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    csv_path = Path(_env_str("UTXO_TX_INDEX_AUDIT_CSV", str(logs_dir / f"tx_index_audit_{days[0]}_{days[-1]}_{ts}.csv")) or str(logs_dir / f"tx_index_audit_{ts}.csv"))
    json_path = csv_path.with_suffix(".json")
    csv_path.parent.mkdir(parents=True, exist_ok=True)

    fieldnames = [
        "day", "file", "tx_rows", "has_tx_index", "index_null_rows", "index_not_null_rows",
        "index_mode", "decision", "severity", "max_txs_per_block",
    ]
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
    summary: Dict[str, Any] = {
        "mode": MODE_TX_INDEX_AUDIT,
        "pipeline_version": _pipeline_version(),
        "raw_base": raw_base,
        "days": len(days),
        "start_day": str(days[0]) if days else None,
        "end_day": str(days[-1]) if days else None,
        "rows": len(rows),
        "csv_path": str(csv_path),
        "json_path": str(json_path),
        "by_mode": {},
        "by_severity": {},
    }
    for row in rows:
        summary["by_mode"][str(row["index_mode"])] = int(summary["by_mode"].get(str(row["index_mode"]), 0)) + 1
        summary["by_severity"][str(row["severity"])] = int(summary["by_severity"].get(str(row["severity"]), 0)) + 1
    _save_json_atomic(json_path, summary)
    _log(f"TX_INDEX_AUDIT wrote csv={csv_path} json={json_path} summary={summary}")
    if _env_bool("UTXO_TX_INDEX_AUDIT_FAIL_ON_RED", False) and summary["by_severity"].get("red", 0):
        return 9
    return 0

def _export_temp_table_to_parquet(con: duckdb.DuckDBPyConnection, table_name: str, order_expr: str, path: Path) -> None:
    tmp = _tmp_path(path)
    con.execute(
        f"COPY (SELECT * FROM {table_name} ORDER BY {order_expr}) TO {_quote_sql_string(str(tmp))} (FORMAT PARQUET, COMPRESSION ZSTD)"
    )
    os.replace(tmp, path)


