def _fetch_tx_index_map_block_txids(block_hash: str) -> List[str]:
    source = _tx_index_map_source()
    if source == "bitcoin_cli":
        return _fetch_block_txids_bitcoin_cli(block_hash)
    return _fetch_block_txids_esplora(block_hash)


def _read_json_file(path: Path) -> Optional[Dict[str, Any]]:
    if not path.exists():
        return None
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def _tx_index_map_write_rows(path: Path, rows: Sequence[Tuple[int, str, str, str, int, str, str]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    con = duckdb.connect()
    try:
        con.execute("""CREATE OR REPLACE TEMP TABLE tx_index_map_out(
          block_number BIGINT, block_hash VARCHAR, raw_hash VARCHAR, canonical_txid VARCHAR,
          canonical_tx_index BIGINT, source VARCHAR, raw_date DATE)""")
        if rows:
            con.executemany("INSERT INTO tx_index_map_out VALUES (?, ?, ?, ?, ?, ?, ?::DATE)",
              [(int(bn),str(bh).lower(),str(rh).lower(),str(ct).lower(),int(idx),str(src),str(day)) for bn,bh,rh,ct,idx,src,day in rows])
        _export_temp_table_to_parquet(con, "tx_index_map_out", "block_number, canonical_tx_index", path)
    finally:
        con.close()


def _tx_index_map_raw_ordering_contract(con: duckdb.DuckDBPyConnection, files: Sequence[str], day: Optional[str] = None) -> Dict[str, Any]:
    """Validate day-wide raw ordering, identities and explicit-index trust policy."""
    resolved_day = str(day or _tx_index_map_day_from_files(files) or "") or None
    policy = _tx_index_map_explicit_order_policy(resolved_day)
    report: Dict[str, Any] = {
        "status": "ok", "required": False, "reasons": [], "failed_checks": [], "warnings": [],
        "files": [str(x) for x in files], "day": resolved_day,
        "explicit_index_order_policy": policy,
        "explicit_index_order_trust_status": None,
    }
    failed: List[str] = report["failed_checks"]
    if not files:
        report.update(status="fail", failed_checks=["raw_files_missing"])
        return report
    files_sql = _quote_sql_list([str(x) for x in files])
    try:
        desc = con.execute(f"DESCRIBE SELECT * FROM read_parquet({files_sql}, union_by_name=true)").fetchall()
        columns = {str(r[0]).lower() for r in desc}
    except Exception as exc:
        report.update(status="fail", failed_checks=[f"raw_schema_read_failed:{type(exc).__name__}:{exc}"])
        return report
    required_columns = {"block_number", "block_hash", "hash", "is_coinbase"}
    missing = sorted(required_columns - columns)
    if missing:
        report.update(status="fail", failed_checks=[f"raw_required_columns_missing:{missing}"])
        return report
    has_index = "index" in columns
    index_expr = 'CAST("index" AS BIGINT)' if has_index else 'NULL::BIGINT'
    con.execute("DROP TABLE IF EXISTS txim_raw_order_contract")
    try:
        con.execute(f"""CREATE TEMP TABLE txim_raw_order_contract AS
            SELECT block_number::BIGINT AS block_number,
                   lower(block_hash::VARCHAR) AS block_hash,
                   lower(hash::VARCHAR) AS raw_hash,
                   COALESCE(is_coinbase,false) AS is_coinbase,
                   {index_expr} AS tx_index
            FROM read_parquet({files_sql}, union_by_name=true)""")
        row = con.execute("""SELECT COUNT(*),
            SUM(CASE WHEN block_number IS NULL THEN 1 ELSE 0 END),
            SUM(CASE WHEN block_number < 0 THEN 1 ELSE 0 END),
            SUM(CASE WHEN block_hash IS NULL THEN 1 ELSE 0 END),
            SUM(CASE WHEN raw_hash IS NULL THEN 1 ELSE 0 END),
            SUM(CASE WHEN block_hash IS NOT NULL AND NOT regexp_full_match(block_hash,'^[0-9a-f]{64}$') THEN 1 ELSE 0 END),
            SUM(CASE WHEN raw_hash IS NOT NULL AND NOT regexp_full_match(raw_hash,'^[0-9a-f]{64}$') THEN 1 ELSE 0 END),
            SUM(CASE WHEN tx_index IS NULL THEN 1 ELSE 0 END),
            SUM(CASE WHEN tx_index IS NOT NULL THEN 1 ELSE 0 END)
          FROM txim_raw_order_contract""").fetchone()
        keys=("raw_total_rows","raw_null_block_number_rows","raw_negative_block_number_rows",
              "raw_null_block_hash_rows","raw_null_hash_rows","raw_invalid_block_hash_rows",
              "raw_invalid_hash_rows","index_null_rows","index_not_null_rows")
        report.update({k:int(v or 0) for k,v in zip(keys,row)})
        for key in ("raw_null_block_number_rows","raw_negative_block_number_rows","raw_null_block_hash_rows",
                    "raw_null_hash_rows","raw_invalid_block_hash_rows","raw_invalid_hash_rows"):
            if report[key]: failed.append(f"{key}:{report[key]}")
        duplicate_raw_rows=int(con.execute("""SELECT COUNT(*) FROM (
            SELECT block_number,block_hash,raw_hash FROM txim_raw_order_contract GROUP BY 1,2,3 HAVING COUNT(*)>1) q""").fetchone()[0] or 0)
        block_hash_multi_height=int(con.execute("""SELECT COUNT(*) FROM (
            SELECT block_hash FROM txim_raw_order_contract WHERE block_hash IS NOT NULL GROUP BY 1 HAVING COUNT(DISTINCT block_number)>1) q""").fetchone()[0] or 0)
        coinbase_cardinality_bad=int(con.execute("""SELECT COUNT(*) FROM (
            SELECT block_number,block_hash FROM txim_raw_order_contract
            WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
            GROUP BY 1,2 HAVING SUM(CASE WHEN is_coinbase THEN 1 ELSE 0 END)<>1) q""").fetchone()[0] or 0)
        report.update(duplicate_raw_transaction_groups=duplicate_raw_rows,
                      block_hash_multi_height=block_hash_multi_height,
                      coinbase_cardinality_bad_blocks=coinbase_cardinality_bad)
        if duplicate_raw_rows: failed.append(f"duplicate_raw_transaction_groups:{duplicate_raw_rows}")
        if block_hash_multi_height: failed.append(f"block_hash_multi_height:{block_hash_multi_height}")
        if coinbase_cardinality_bad: failed.append(f"coinbase_cardinality_bad_blocks:{coinbase_cardinality_bad}")
        total=report["raw_total_rows"]; nulls=report["index_null_rows"]; reasons: List[str]=[]
        if not has_index:
            mode="missing_top_level_index"
            max_txs=int(con.execute("SELECT COALESCE(MAX(cnt),0) FROM (SELECT block_number,block_hash,COUNT(*) cnt FROM txim_raw_order_contract GROUP BY 1,2) q").fetchone()[0] or 0)
            if max_txs>1: reasons.append("missing_top_level_index_multi_tx_block")
            if len(files)>1: reasons.append("missing_top_level_index_multi_file_fallback")
        elif total>0 and nulls==total:
            mode="all_index_null"
            max_txs=int(con.execute("SELECT COALESCE(MAX(cnt),0) FROM (SELECT block_number,block_hash,COUNT(*) cnt FROM txim_raw_order_contract GROUP BY 1,2) q").fetchone()[0] or 0)
            if max_txs>1: reasons.append("all_null_multi_tx_block")
            if len(files)>1: reasons.append("all_null_multi_file_fallback")
        elif 0<nulls<total:
            mode="partial_index_null"; reasons.append("partial_index_null")
        elif total==0:
            mode="empty_day"
        else:
            mode="all_index_not_null"
            explicit = con.execute("""SELECT
                SUM(CASE WHEN tx_index<0 THEN 1 ELSE 0 END),
                (SELECT COUNT(*) FROM (SELECT block_number,block_hash,tx_index FROM txim_raw_order_contract GROUP BY 1,2,3 HAVING COUNT(*)>1) q),
                (SELECT COUNT(*) FROM (SELECT block_number,block_hash FROM txim_raw_order_contract GROUP BY 1,2 HAVING MIN(tx_index)<>0 OR MAX(tx_index)+1<>COUNT(*) OR COUNT(DISTINCT tx_index)<>COUNT(*)) q),
                SUM(CASE WHEN is_coinbase AND tx_index<>0 THEN 1 ELSE 0 END),
                SUM(CASE WHEN NOT is_coinbase AND tx_index=0 THEN 1 ELSE 0 END)
              FROM txim_raw_order_contract""").fetchone()
            ekeys=("negative_tx_index_rows","duplicate_tx_index_position_groups","explicit_index_dense_bad_blocks",
                   "coinbase_not_index_zero_rows","noncoinbase_index_zero_rows")
            report.update({k:int(v or 0) for k,v in zip(ekeys,explicit)})
            if any(report[k] for k in ekeys):
                reasons.append("explicit_index_invalid")
                report["explicit_index_order_trust_status"]="STRUCTURALLY_INVALID"
            elif policy == "require_canonical_map":
                reasons.append("explicit_index_canonical_order_not_independently_verified")
                report["explicit_index_order_trust_status"]="CANONICAL_MAP_REQUIRED"
            else:
                report["explicit_index_order_trust_status"]="TRUSTED_FROM_RAW_NOT_INDEPENDENTLY_VERIFIED"
                report["warnings"].append("explicit_index_order_trusted_from_raw_not_independently_verified")
        report.update(has_top_level_index=has_index,index_mode=mode,reasons=sorted(set(reasons)),required=bool(reasons))
        if failed: report["status"]="fail"
        return report
    except Exception as exc:
        report["status"]="fail"; failed.append(f"raw_order_contract_query_failed:{type(exc).__name__}:{exc}")
        return report
    finally:
        try: con.execute("DROP TABLE IF EXISTS txim_raw_order_contract")
        except Exception: pass


def _tx_index_map_raw_blocks(con: duckdb.DuckDBPyConnection, files: Sequence[str], day: Optional[str] = None) -> List[Tuple[int, str, int]]:
    """Return raw block cardinalities after strict day-wide source validation."""
    contract=_tx_index_map_raw_ordering_contract(con,files,day=day)
    if contract.get("status")!="ok":
        raise RuntimeError(f"tx_index_map raw ordering/source contract failed: {contract}")
    files_sql = _quote_sql_list([str(x) for x in files])
    return [(int(bn),str(bh).lower(),int(cnt)) for bn,bh,cnt in con.execute(f"""
        SELECT block_number::BIGINT,lower(block_hash::VARCHAR),COUNT(*)
        FROM read_parquet({files_sql},union_by_name=true)
        GROUP BY 1,2 ORDER BY 1,2""").fetchall()]





TX_INDEX_MAP_LEDGER_CONTRACT_V1 = "tx-index-map-generation-ledger-v1"
TX_INDEX_MAP_LEDGER_CONTRACT_V2 = "tx-index-map-generation-ledger-v2"
TX_INDEX_MAP_LEDGER_ACTION_PUBLISH = "PUBLISH"
TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK = "ROLLBACK"
TX_INDEX_MAP_LEDGER_ACTION_REVOKE = "REVOKE"
TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V1 = "tx-index-map-publication-transaction-v1"
TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2 = "tx-index-map-publication-transaction-v2"
TX_INDEX_MAP_ATOMIC_PUBLICATION_CONTRACT = "tx-index-map-atomic-publication-r35"
TX_INDEX_MAP_PUBLICATION_PHASES = ("PREPARED", "FILES_PUBLISHED", "LEDGER_COMMITTED", "FINAL_AUDIT_OK")
_TX_INDEX_MAP_PUBLICATION_PHASE_ORDER = {name: idx for idx, name in enumerate(TX_INDEX_MAP_PUBLICATION_PHASES)}


def _tx_index_map_explicit_order_policy(day: Optional[str]) -> str:
    """Resolve the trust boundary for structurally valid explicit raw indexes.

    auto (default): trust pre-canonical raw indexes, require an externally built
    canonical tx_index_map on/after UTXO_CANONICAL_REPLACE_FROM.
    """
    policy = (_env_str("UTXO_TX_INDEX_EXPLICIT_ORDER_POLICY", "auto") or "auto").strip().lower()
    if policy not in {"auto", "trust_raw", "require_canonical_map"}:
        raise SystemExit(
            "ERROR: UTXO_TX_INDEX_EXPLICIT_ORDER_POLICY must be auto, trust_raw, or require_canonical_map"
        )
    if policy != "auto":
        return policy
    if day and str(day) >= _canonical_replace_from():
        return "require_canonical_map"
    return "trust_raw"


def _tx_index_map_day_from_files(files: Sequence[str]) -> Optional[str]:
    days = set()
    for raw in files:
        match = re.search(r"(?:^|/)date=(\d{4}-\d{2}-\d{2})(?:/|$)", str(raw))
        if match:
            days.add(match.group(1))
    return next(iter(days)) if len(days) == 1 else None


def _tx_index_map_ledger_lock_identity() -> str:
    return f"tx_index_map_generation_ledger:{_tx_index_map_root_path_no_create().expanduser().resolve(strict=False)}"


def _tx_index_map_ledger_lock_path() -> Path:
    return _v11_lock_dir("tx-index-map-ledger", _tx_index_map_ledger_lock_identity())


def _tx_index_map_publication_marker_path(day: str) -> Path:
    root = _lock_root(create=True)
    identity = f"tx_index_map_publish:{_tx_index_map_root_path_no_create().expanduser().resolve(strict=False)}:date={day}"
    return root / f"utxo_v11_tx_index_map_publish.{_lock_key(identity)}.json"


def _tx_index_map_marker_hash(payload: Dict[str, Any]) -> str:
    body = {k: v for k, v in payload.items() if k != "marker_sha256"}
    return hashlib.sha256(
        json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("utf-8")
    ).hexdigest()


def _tx_index_map_validate_publication_marker(
    day: str,
    payload: Any,
    *,
    day_dir: Path,
    final_path: Path,
    manifest_path: Path,
    progress_path: Path,
) -> List[str]:
    failed: List[str] = []
    if not isinstance(payload, dict):
        return ["publication_marker_not_object"]
    contract = payload.get("marker_contract")
    # R35 recovery is intentionally strict: legacy markers were not bound to the
    # complete atomic-publication identity and therefore cannot authorize any
    # automatic restore, delete, revoke, or finalize action. Keep the V1 constant
    # only for diagnostics; an operator must quarantine a legacy marker manually.
    if contract != TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2:
        failed.append(f"publication_marker_contract_not_r35:{contract!r}")
    if str(payload.get("day") or "") != str(day):
        failed.append(f"publication_marker_day_mismatch:{payload.get('day')!r}!={day}")
    phase = str(payload.get("phase") or "")
    if phase not in TX_INDEX_MAP_PUBLICATION_PHASES:
        failed.append(f"publication_marker_phase_invalid:{phase!r}")
    generation_id = str(payload.get("generation_id") or "")
    if not re.fullmatch(r"[0-9a-f]{32}", generation_id):
        failed.append(f"publication_marker_generation_id_invalid:{generation_id!r}")
    marker_version = payload.get("pipeline_version")
    if not isinstance(marker_version, str) or not marker_version.startswith("v11-block-order-causal-rebuild"):
        failed.append(f"publication_marker_pipeline_version_invalid:{marker_version!r}")
    candidate_sha = payload.get("candidate_parquet_sha256")
    if contract == TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2:
        if not re.fullmatch(r"[0-9a-f]{64}", str(candidate_sha or "")):
            failed.append(f"publication_marker_candidate_parquet_sha256_invalid:{candidate_sha!r}")
        if payload.get("atomic_publication_contract") != TX_INDEX_MAP_ATOMIC_PUBLICATION_CONTRACT:
            failed.append(
                f"publication_marker_atomic_contract_invalid:{payload.get('atomic_publication_contract')!r}"
            )
    elif candidate_sha not in {None, ""} and not re.fullmatch(r"[0-9a-f]{64}", str(candidate_sha)):
        failed.append(f"publication_marker_candidate_parquet_sha256_invalid:{candidate_sha!r}")
    try:
        dt = datetime.fromisoformat(str(payload.get("updated_at") or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            failed.append("publication_marker_updated_at_not_timezone_aware")
    except Exception:
        failed.append(f"publication_marker_updated_at_invalid:{payload.get('updated_at')!r}")
    expected_paths = {
        "final_path": final_path.expanduser().resolve(strict=False),
        "manifest_path": manifest_path.expanduser().resolve(strict=False),
        "progress_path": progress_path.expanduser().resolve(strict=False),
    }
    for key, expected in expected_paths.items():
        raw = payload.get(key)
        if contract == TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2 and not isinstance(raw, str):
            failed.append(f"publication_marker_{key}_missing")
            continue
        if raw is not None and str(raw).strip():
            observed = Path(str(raw)).expanduser().resolve(strict=False)
            if observed != expected:
                failed.append(f"publication_marker_{key}_mismatch:{observed}!={expected}")
    backup_raw = payload.get("previous_generation_backup")
    backup: Optional[Path] = None
    if backup_raw not in {None, ""}:
        backup = Path(str(backup_raw)).expanduser().resolve(strict=False)
        expected_parent = day_dir.expanduser().resolve(strict=False)
        if backup.parent != expected_parent or not backup.name.startswith("quarantine.prebuild_generation."):
            failed.append(f"publication_marker_backup_path_invalid:{backup}")
    previous_generation_id = payload.get("previous_generation_id")
    if previous_generation_id not in {None, ""} and not re.fullmatch(r"[0-9a-f]{32}", str(previous_generation_id)):
        failed.append(f"publication_marker_previous_generation_id_invalid:{previous_generation_id!r}")
    previous_restorable = payload.get("previous_generation_restorable")
    if contract == TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2:
        if not isinstance(previous_restorable, bool):
            failed.append(f"publication_marker_previous_generation_restorable_invalid:{previous_restorable!r}")
        elif previous_restorable:
            if backup is None:
                failed.append("publication_marker_restorable_backup_missing")
            elif not backup.is_dir():
                failed.append(f"publication_marker_restorable_backup_not_directory:{backup}")
            if not re.fullmatch(r"[0-9a-f]{32}", str(previous_generation_id or "")):
                failed.append("publication_marker_previous_generation_id_required_for_restorable_backup")
    ledger_sha = payload.get("ledger_record_sha256")
    if phase in {"LEDGER_COMMITTED", "FINAL_AUDIT_OK"}:
        if not re.fullmatch(r"[0-9a-f]{64}", str(ledger_sha or "")):
            failed.append(f"publication_marker_ledger_record_sha256_invalid:{ledger_sha!r}")
    elif ledger_sha not in {None, ""}:
        failed.append(f"publication_marker_ledger_record_sha256_before_commit:{phase}:{ledger_sha!r}")
    if contract == TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2:
        marker_sha = str(payload.get("marker_sha256") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", marker_sha):
            failed.append("publication_marker_sha256_missing_or_invalid")
        elif marker_sha != _tx_index_map_marker_hash(payload):
            failed.append("publication_marker_sha256_mismatch")
    return sorted(set(failed))


def _tx_index_map_lock_path_state(path: Path) -> Dict[str, Any]:
    if not path.exists():
        return {"status": "CLEAR", "busy": False, "path": str(path)}
    payload = _read_lock_dir_payload(path) if path.is_dir() else (_read_json_file(path) or {})
    if not isinstance(payload, dict) or not payload:
        return {"status": "BUSY_UNKNOWN", "busy": True, "path": str(path), "payload": payload}
    try:
        pid = int(payload.get("pid") or 0)
    except Exception:
        pid = 0
    host = str(payload.get("host") or payload.get("hostname") or "")
    local_names = {"", "localhost", socket.gethostname()}
    try:
        local_names.add(os.uname().nodename)
    except Exception:
        pass
    try:
        local_names.add(socket.getfqdn())
    except Exception:
        pass
    local = host in local_names
    if local and _pid_alive(pid):
        status, busy = "BUSY_LIVE_LOCAL", True
    elif host and not local:
        status, busy = "BUSY_FOREIGN_OR_UNKNOWN", True
    elif pid <= 0:
        status, busy = "BUSY_MALFORMED", True
    else:
        status, busy = "STALE_DEAD_LOCAL", False
    return {"status": status, "busy": busy, "path": str(path), "payload": payload, "pid": pid, "host": host or None}


def _tx_index_map_snapshot_token(path: Path, *, include_sha256: bool = True) -> Dict[str, Any]:
    try:
        st = path.stat()
        token: Dict[str, Any] = {
            "exists": True, "size": int(st.st_size), "mtime_ns": int(st.st_mtime_ns),
            "inode": int(getattr(st, "st_ino", 0)),
        }
        if include_sha256:
            token["sha256"] = _file_sha256_streaming(path)
        return token
    except FileNotFoundError:
        return {"exists": False}
    except Exception as exc:
        return {"exists": None, "error": f"{type(exc).__name__}:{exc}"}


def _tx_index_map_save_publication_marker(day: str, payload: Dict[str, Any]) -> Path:
    """Durably advance one publication transaction without identity mutation."""
    path = _tx_index_map_publication_marker_path(day)
    existing: Dict[str, Any] = {}
    if path.exists():
        loaded = _read_json_file(path)
        if not isinstance(loaded, dict):
            raise RuntimeError(f"existing publication marker is not a JSON object: {path}")
        existing = dict(loaded)

    update = dict(payload)
    old_phase = str(existing.get("phase") or "")
    requested_phase = str(update.get("phase") or old_phase)
    if not existing:
        if requested_phase != "PREPARED":
            raise RuntimeError(
                f"new publication marker must start at PREPARED day={day}: {requested_phase!r}"
            )
    else:
        if old_phase not in _TX_INDEX_MAP_PUBLICATION_PHASE_ORDER:
            raise RuntimeError(f"existing publication marker phase is invalid: {old_phase!r}")
        if requested_phase not in _TX_INDEX_MAP_PUBLICATION_PHASE_ORDER:
            raise RuntimeError(f"requested publication marker phase is invalid: {requested_phase!r}")
        old_index = _TX_INDEX_MAP_PUBLICATION_PHASE_ORDER[old_phase]
        new_index = _TX_INDEX_MAP_PUBLICATION_PHASE_ORDER[requested_phase]
        if new_index < old_index:
            raise RuntimeError(f"publication marker phase regression: {old_phase}->{requested_phase}")
        if new_index > old_index + 1:
            raise RuntimeError(f"publication marker phase skip: {old_phase}->{requested_phase}")

    identity_fields = (
        "generation_id",
        "candidate_parquet_sha256",
        "final_path",
        "manifest_path",
        "progress_path",
        "previous_generation_backup",
        "previous_generation_id",
        "previous_generation_restorable",
    )
    if existing:
        for key in identity_fields:
            if key in update and update.get(key) != existing.get(key):
                raise RuntimeError(
                    f"publication marker immutable field changed day={day} key={key}: "
                    f"{existing.get(key)!r}!={update.get(key)!r}"
                )

    old_ledger_sha = existing.get("ledger_record_sha256")
    if "ledger_record_sha256" in update:
        new_ledger_sha = update.get("ledger_record_sha256")
        if old_ledger_sha not in {None, ""} and new_ledger_sha != old_ledger_sha:
            raise RuntimeError(
                f"publication marker immutable field changed day={day} key=ledger_record_sha256: "
                f"{old_ledger_sha!r}!={new_ledger_sha!r}"
            )
        if old_ledger_sha in {None, ""} and new_ledger_sha not in {None, ""}:
            if requested_phase not in {"LEDGER_COMMITTED", "FINAL_AUDIT_OK"}:
                raise RuntimeError(
                    f"publication marker ledger hash introduced before commit day={day} "
                    f"phase={requested_phase}"
                )
        if old_ledger_sha not in {None, ""} and new_ledger_sha in {None, ""}:
            raise RuntimeError(f"publication marker ledger hash cannot be cleared day={day}")

    body = dict(existing)
    body.update(update)
    body.update({
        "marker_contract": TX_INDEX_MAP_PUBLICATION_MARKER_CONTRACT_V2,
        "day": str(day),
        "pipeline_version": _pipeline_version(),
        "atomic_publication_contract": TX_INDEX_MAP_ATOMIC_PUBLICATION_CONTRACT,
        "updated_at": _now_iso(),
    })
    body["marker_sha256"] = _tx_index_map_marker_hash(body)
    day_dir = _tx_index_map_day_dir_path_no_create(day)
    marker_failed = _tx_index_map_validate_publication_marker(
        day,
        body,
        day_dir=day_dir,
        final_path=_tx_index_map_path_no_create(day),
        manifest_path=day_dir / "manifest.json",
        progress_path=day_dir / "progress.json",
    )
    if marker_failed:
        raise RuntimeError(f"refusing invalid publication marker day={day}: {marker_failed}")
    _save_json_atomic(path, body)
    return path


def _tx_index_map_clear_publication_marker(day: str, *, expected_generation_id: Optional[str] = None) -> None:
    path = _tx_index_map_publication_marker_path(day)
    if path.exists() and expected_generation_id:
        payload = _read_json_file(path)
        if not isinstance(payload, dict):
            raise RuntimeError(f"cannot clear unreadable publication marker: {path}")
        if str(payload.get("generation_id") or "") != str(expected_generation_id):
            raise RuntimeError(
                f"refusing to clear publication marker for another generation: "
                f"actual={payload.get('generation_id')!r} expected={expected_generation_id!r}"
            )
    path.unlink(missing_ok=True)
    _fsync_directory(path.parent)
    if path.exists():
        raise RuntimeError(f"publication marker still exists after clear: {path}")


def _tx_index_map_validate_ledger_record(item: Dict[str, Any], line_no: int) -> List[str]:
    failed: List[str] = []
    contract = item.get("ledger_contract")
    if contract not in {TX_INDEX_MAP_LEDGER_CONTRACT_V1, TX_INDEX_MAP_LEDGER_CONTRACT_V2}:
        failed.append(f"ledger_contract_invalid:{line_no}:{contract!r}")
    action = item.get("action") if contract == TX_INDEX_MAP_LEDGER_CONTRACT_V2 else TX_INDEX_MAP_LEDGER_ACTION_PUBLISH
    if contract == TX_INDEX_MAP_LEDGER_CONTRACT_V2 and "action" not in item:
        failed.append(f"ledger_action_missing:{line_no}")
    if action not in {TX_INDEX_MAP_LEDGER_ACTION_PUBLISH, TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK, TX_INDEX_MAP_LEDGER_ACTION_REVOKE}:
        failed.append(f"ledger_action_invalid:{line_no}:{action!r}")
    try:
        parsed_day = _parse_date(str(item.get("day") or ""))
        if parsed_day.isoformat() != str(item.get("day")):
            failed.append(f"ledger_day_not_canonical_iso:{line_no}:{item.get('day')!r}")
    except Exception:
        failed.append(f"ledger_day_invalid:{line_no}:{item.get('day')!r}")
    generation_id = str(item.get("generation_id") or "")
    if not re.fullmatch(r"[0-9a-f]{32}", generation_id):
        failed.append(f"ledger_generation_id_invalid:{line_no}:{item.get('generation_id')!r}")
    from_generation_id = item.get("from_generation_id")
    if action == TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK:
        if not re.fullmatch(r"[0-9a-f]{32}", str(from_generation_id or "")):
            failed.append(f"ledger_from_generation_id_invalid:{line_no}:{from_generation_id!r}")
        if not isinstance(item.get("reason"), str) or not str(item.get("reason") or "").strip():
            failed.append(f"ledger_reason_missing:{line_no}:{action}")
    elif from_generation_id not in {None, ""} and not re.fullmatch(r"[0-9a-f]{32}", str(from_generation_id)):
        failed.append(f"ledger_from_generation_id_invalid:{line_no}:{from_generation_id!r}")
    if action == TX_INDEX_MAP_LEDGER_ACTION_REVOKE:
        if not isinstance(item.get("reason"), str) or not str(item.get("reason") or "").strip():
            failed.append(f"ledger_reason_missing:{line_no}:{action}")
    previous = item.get("previous_record_sha256")
    if previous is not None and not re.fullmatch(r"[0-9a-f]{64}", str(previous)):
        failed.append(f"ledger_previous_sha_invalid:{line_no}")
    if not re.fullmatch(r"[0-9a-f]{64}", str(item.get("record_sha256") or "")):
        failed.append(f"ledger_record_sha_invalid:{line_no}")
    active = action in {TX_INDEX_MAP_LEDGER_ACTION_PUBLISH, TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK}
    if active:
        for field in ("map_path", "manifest_path"):
            value = item.get(field)
            if not isinstance(value, str) or not value.strip() or not Path(value).is_absolute():
                failed.append(f"ledger_{field}_invalid:{line_no}:{value!r}")
        for field in ("parquet_sha256", "manifest_sha256", "canonical_order_sha256"):
            if not re.fullmatch(r"[0-9a-f]{64}", str(item.get(field) or "")):
                failed.append(f"ledger_{field}_invalid:{line_no}:{item.get(field)!r}")
        if item.get("source") not in {"esplora", "bitcoin_cli"}:
            failed.append(f"ledger_source_invalid:{line_no}:{item.get('source')!r}")
        for field in ("map_rows", "total_blocks"):
            value = item.get(field)
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                failed.append(f"ledger_{field}_invalid:{line_no}:{value!r}")
    else:
        if item.get("source") is not None:
            failed.append(f"ledger_revoke_source_must_be_null:{line_no}:{item.get('source')!r}")
        for field in ("map_rows", "total_blocks"):
            if item.get(field) is not None:
                failed.append(f"ledger_revoke_{field}_must_be_null:{line_no}:{item.get(field)!r}")
        for field in ("parquet_sha256", "manifest_sha256", "canonical_order_sha256"):
            if item.get(field) is not None:
                failed.append(f"ledger_revoke_{field}_must_be_null:{line_no}")
    version = item.get("pipeline_version")
    if not isinstance(version, str) or not version.startswith("v11-block-order-causal-rebuild"):
        failed.append(f"ledger_pipeline_version_invalid:{line_no}:{version!r}")
    try:
        dt = datetime.fromisoformat(str(item.get("published_at") or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            failed.append(f"ledger_published_at_not_timezone_aware:{line_no}")
    except Exception:
        failed.append(f"ledger_published_at_invalid:{line_no}:{item.get('published_at')!r}")
    return failed


def _tx_index_map_generation_ledger_path() -> Path:
    root=_lock_root(create=True)
    identity=str(_tx_index_map_root_path_no_create().expanduser().resolve(strict=False))
    return root / f"utxo_v11_tx_index_map_generation_ledger.{_lock_key(identity)}.jsonl"


def _tx_index_map_ledger_record_hash(payload: Dict[str, Any]) -> str:
    body={k:v for k,v in payload.items() if k!="record_sha256"}
    return hashlib.sha256(json.dumps(body,sort_keys=True,separators=(",",":"),ensure_ascii=True).encode("utf-8")).hexdigest()


def _tx_index_map_read_generation_ledger(path: Optional[Path] = None) -> Dict[str, Any]:
    path = path or _tx_index_map_generation_ledger_path()
    records: List[Dict[str, Any]] = []
    failed: List[str] = []
    previous: Optional[str] = None
    effective: Dict[str, Optional[Dict[str, Any]]] = {}
    published: Dict[str, Dict[str, Dict[str, Any]]] = {}
    seen_v2 = False
    if not path.exists():
        return {
            "status": "missing", "path": str(path), "records": [],
            "effective_by_day": {}, "published_by_day": {},
            "failed_checks": ["generation_ledger_missing"], "tail_sha256": None,
        }
    try:
        with path.open("r", encoding="utf-8") as fh:
            for line_no, line in enumerate(fh, 1):
                if not line.strip():
                    continue
                record_failed: List[str] = []
                try:
                    item = json.loads(line)
                except Exception as exc:
                    failed.append(f"record_json_invalid:{line_no}:{type(exc).__name__}:{exc}")
                    continue
                if not isinstance(item, dict):
                    failed.append(f"record_not_object:{line_no}")
                    continue
                contract = item.get("ledger_contract")
                if contract == TX_INDEX_MAP_LEDGER_CONTRACT_V1 and seen_v2:
                    record_failed.append(f"ledger_v1_downgrade_after_v2:{line_no}")
                if contract == TX_INDEX_MAP_LEDGER_CONTRACT_V2:
                    seen_v2 = True
                record_failed.extend(_tx_index_map_validate_ledger_record(item, line_no))
                if item.get("previous_record_sha256") != previous:
                    record_failed.append(f"chain_previous_mismatch:{line_no}")
                observed = _tx_index_map_ledger_record_hash(item)
                if item.get("record_sha256") != observed:
                    record_failed.append(f"record_sha256_mismatch:{line_no}")
                previous = item.get("record_sha256")
                normalized = dict(item)
                if contract == TX_INDEX_MAP_LEDGER_CONTRACT_V1:
                    normalized["action"] = TX_INDEX_MAP_LEDGER_ACTION_PUBLISH
                action = normalized.get("action")
                rec_day = str(normalized.get("day") or "")
                generation_id = str(normalized.get("generation_id") or "")
                day_published = published.setdefault(rec_day, {})
                current = effective.get(rec_day)
                if not record_failed:
                    if action == TX_INDEX_MAP_LEDGER_ACTION_PUBLISH:
                        if generation_id in day_published:
                            record_failed.append(f"generation_republished:{line_no}:{rec_day}:{generation_id}")
                        else:
                            day_published[generation_id] = normalized
                            effective[rec_day] = normalized
                    elif action == TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK:
                        target = day_published.get(generation_id)
                        if target is None:
                            record_failed.append(f"rollback_target_not_previously_published:{line_no}:{generation_id}")
                        current_generation = str((current or {}).get("generation_id") or "")
                        if not current_generation:
                            record_failed.append(f"rollback_without_active_generation:{line_no}")
                        elif str(normalized.get("from_generation_id") or "") != current_generation:
                            record_failed.append(
                                f"rollback_from_generation_mismatch:{line_no}:"
                                f"{normalized.get('from_generation_id')!r}!={current_generation!r}"
                            )
                        if target is not None:
                            for key in (
                                "map_path", "manifest_path", "parquet_sha256", "manifest_sha256",
                                "canonical_order_sha256", "map_rows", "total_blocks", "source",
                            ):
                                if normalized.get(key) != target.get(key):
                                    record_failed.append(f"rollback_target_artifact_mismatch:{line_no}:{key}")
                        if not record_failed:
                            effective[rec_day] = normalized
                    elif action == TX_INDEX_MAP_LEDGER_ACTION_REVOKE:
                        current_generation = str((current or {}).get("generation_id") or "")
                        if not current_generation:
                            record_failed.append(f"revoke_without_active_generation:{line_no}:{generation_id}")
                        elif generation_id != current_generation:
                            record_failed.append(
                                f"revoke_generation_not_active:{line_no}:{generation_id}!={current_generation}"
                            )
                        if not record_failed:
                            effective[rec_day] = None
                failed.extend(record_failed)
                records.append(dict(item))
    except Exception as exc:
        failed.append(f"generation_ledger_read_failed:{type(exc).__name__}:{exc}")
    return {
        "status": "ok" if not failed else "fail", "path": str(path), "records": records,
        "effective_by_day": effective, "published_by_day": published,
        "failed_checks": sorted(set(failed)), "tail_sha256": previous,
    }


def _tx_index_map_append_generation_ledger(
    day: str,
    manifest_path: Path,
    map_path: Path,
    *,
    action: str = TX_INDEX_MAP_LEDGER_ACTION_PUBLISH,
    reason: Optional[str] = None,
    from_generation_id: Optional[str] = None,
    revoked_generation_id: Optional[str] = None,
) -> Dict[str, Any]:
    if action not in {TX_INDEX_MAP_LEDGER_ACTION_PUBLISH, TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK, TX_INDEX_MAP_LEDGER_ACTION_REVOKE}:
        raise ValueError(f"invalid generation ledger action: {action}")
    ledger_lock = _v11_acquire_dir_lock("tx-index-map-ledger", _tx_index_map_ledger_lock_identity())
    primary_exc: Optional[BaseException] = None
    try:
        ledger_path = _tx_index_map_generation_ledger_path()
        state = _tx_index_map_read_generation_ledger(ledger_path) if ledger_path.exists() else {
            "status": "ok", "records": [], "effective_by_day": {}, "published_by_day": {},
            "tail_sha256": None, "failed_checks": [],
        }
        if state.get("status") != "ok":
            raise RuntimeError(f"generation ledger is invalid: {state}")
        manifest = _read_json_file(manifest_path) or {}
        current = (state.get("effective_by_day") or {}).get(str(day))
        current_generation = str((current or {}).get("generation_id") or "") or None
        active_artifacts = action != TX_INDEX_MAP_LEDGER_ACTION_REVOKE
        if active_artifacts:
            generation_id = manifest.get("generation_id")
        else:
            generation_id = revoked_generation_id or current_generation
        if action == TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK:
            if from_generation_id is None:
                from_generation_id = current_generation
            target = ((state.get("published_by_day") or {}).get(str(day)) or {}).get(str(generation_id or ""))
            if target is None:
                raise RuntimeError(f"rollback target was never published day={day} generation_id={generation_id!r}")
        if action == TX_INDEX_MAP_LEDGER_ACTION_REVOKE:
            if not current_generation:
                raise RuntimeError(f"cannot append REVOKE without an active generation day={day}")
            if generation_id != current_generation:
                raise RuntimeError(
                    f"cannot revoke a non-active generation day={day}: "
                    f"requested={generation_id!r} active={current_generation!r}"
                )
        record = {
            "ledger_contract": TX_INDEX_MAP_LEDGER_CONTRACT_V2,
            "action": action,
            "day": str(day),
            "generation_id": generation_id,
            "from_generation_id": from_generation_id,
            "reason": reason,
            "map_path": str(map_path.expanduser().resolve(strict=False)),
            "manifest_path": str(manifest_path.expanduser().resolve(strict=False)),
            "parquet_sha256": _file_sha256_streaming(map_path) if active_artifacts and map_path.is_file() else None,
            "manifest_sha256": _file_sha256_streaming(manifest_path) if active_artifacts and manifest_path.is_file() else None,
            "canonical_order_sha256": manifest.get("canonical_order_sha256") if active_artifacts else None,
            "map_rows": manifest.get("map_rows") if active_artifacts else None,
            "total_blocks": manifest.get("total_blocks") if active_artifacts else None,
            "source": manifest.get("source") if active_artifacts else None,
            "previous_record_sha256": state.get("tail_sha256"),
            "published_at": _now_iso(),
            "pipeline_version": _pipeline_version(),
        }
        record["record_sha256"] = _tx_index_map_ledger_record_hash(record)
        schema_failed = _tx_index_map_validate_ledger_record(record, len(state.get("records", [])) + 1)
        if schema_failed:
            raise RuntimeError(f"refusing invalid generation ledger record: {schema_failed}")
        # Build and validate the complete next ledger in the same directory. The
        # final commit is one atomic os.replace, so a crash cannot leave a torn
        # JSONL tail that permanently blocks recovery.
        ledger_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = ledger_path.with_name(
            f".{ledger_path.name}.publish.{os.getpid()}.{time.time_ns()}.{uuid.uuid4().hex}.tmp"
        )
        try:
            with tmp_path.open("x", encoding="utf-8") as fh:
                try:
                    os.chmod(tmp_path, 0o600)
                except OSError:
                    pass
                for existing in state.get("records", []):
                    fh.write(json.dumps(existing, sort_keys=True, separators=(",", ":"), ensure_ascii=True) + "\n")
                fh.write(json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=True) + "\n")
                fh.flush()
                os.fsync(fh.fileno())
            prospective = _tx_index_map_read_generation_ledger(tmp_path)
            if prospective.get("status") != "ok":
                raise RuntimeError(
                    f"refusing invalid generation ledger transition: {prospective.get('failed_checks')}"
                )
            os.replace(tmp_path, ledger_path)
            _fsync_directory(ledger_path.parent)
        finally:
            tmp_path.unlink(missing_ok=True)
        return record
    except BaseException as exc:
        primary_exc = exc
        raise
    finally:
        try:
            _v11_release_dir_lock(ledger_lock)
        except BaseException as release_exc:
            if primary_exc is not None:
                raise RuntimeError(
                    "generation-ledger operation failed and ledger-lock release also failed: "
                    f"original={type(primary_exc).__name__}:{primary_exc}; "
                    f"release={type(release_exc).__name__}:{release_exc}"
                ) from primary_exc
            raise


def _tx_index_map_validate_generation_ledger(day: str, manifest: Dict[str, Any], manifest_path: Path, map_path: Path) -> Dict[str, Any]:
    lock_before = _tx_index_map_lock_path_state(_tx_index_map_ledger_lock_path())
    ledger_path = _tx_index_map_generation_ledger_path()
    token_before = _tx_index_map_snapshot_token(ledger_path, include_sha256=True)
    failed: List[str] = []
    if lock_before.get("busy"):
        failed.append(f"generation_ledger_busy_retry:{lock_before.get('status')}")
        return {
            "status": "fail", "failed_checks": failed, "path": str(ledger_path),
            "lock_before": lock_before, "snapshot_before": token_before,
        }
    state = _tx_index_map_read_generation_ledger(ledger_path)
    failed.extend(state.get("failed_checks", []))
    effective = state.get("effective_by_day", {}).get(str(day)) if isinstance(state.get("effective_by_day"), dict) else None
    if effective is None:
        failed.append("generation_ledger_active_generation_missing_or_revoked")
    else:
        if str(effective.get("generation_id")) != str(manifest.get("generation_id")):
            failed.append(
                f"generation_ledger_active_generation_mismatch:"
                f"{effective.get('generation_id')!r}!={manifest.get('generation_id')!r}"
            )
        expected = {
            "map_path": str(map_path.expanduser().resolve(strict=False)),
            "manifest_path": str(manifest_path.expanduser().resolve(strict=False)),
            "parquet_sha256": _file_sha256_streaming(map_path) if map_path.is_file() else None,
            "manifest_sha256": _file_sha256_streaming(manifest_path) if manifest_path.is_file() else None,
            "canonical_order_sha256": manifest.get("canonical_order_sha256"),
            "map_rows": manifest.get("map_rows"), "total_blocks": manifest.get("total_blocks"),
            "source": manifest.get("source"),
        }
        for key, value in expected.items():
            if effective.get(key) != value:
                failed.append(f"generation_ledger_mismatch:{key}")
    token_after = _tx_index_map_snapshot_token(ledger_path, include_sha256=True)
    lock_after = _tx_index_map_lock_path_state(_tx_index_map_ledger_lock_path())
    if token_before != token_after:
        failed.append("generation_ledger_changed_during_validation_retry")
    if lock_after.get("busy"):
        failed.append(f"generation_ledger_lock_appeared_during_validation_retry:{lock_after.get('status')}")
    return {
        "status": "ok" if not failed else "fail", "failed_checks": sorted(set(failed)),
        "path": state.get("path"), "record": effective, "tail_sha256": state.get("tail_sha256"),
        "lock_before": lock_before, "lock_after": lock_after,
        "snapshot_before": token_before, "snapshot_after": token_after,
    }


def _tx_index_map_order_digest_table(con: duckdb.DuckDBPyConnection, table_name: str) -> str:
    h=hashlib.sha256(); cur=con.execute(f"SELECT block_number,lower(block_hash),canonical_tx_index,lower(canonical_txid) FROM {table_name} ORDER BY 1,2,3")
    while True:
        batch=cur.fetchmany(10000)
        if not batch: break
        for bn,bh,idx,ct in batch: h.update(f"{int(bn)}\t{str(bh)}\t{int(idx)}\t{str(ct)}\n".encode("ascii"))
    return h.hexdigest()


def _audit_tx_index_map_day(
    raw_base: str,
    day: str,
    *,
    require_manifest_ok: bool = True,
    map_path: Optional[Path] = None,
    manifest_override: Optional[Dict[str, Any]] = None,
    emit_success_event: bool = True,
    emit_neutral_success_event: bool = True,
    allow_publication_marker: bool = False,
) -> Dict[str, Any]:
    files=_day_parquet_files(raw_base,day); path=map_path or _tx_index_map_path(day)
    manifest_path=(path.parent/"manifest.json") if manifest_override is None else (path.parent/"manifest.json")
    manifest=manifest_override if manifest_override is not None else (_read_json_file(manifest_path) or {})
    progress_path=path.parent/"progress.json"
    report={"day":day,"path":str(path),"manifest_path":str(manifest_path),"progress_path":str(progress_path),
            "manifest_status":manifest.get("status"),"failed_checks":[],"warnings":[],"status":"fail"}
    failed=report["failed_checks"]
    if not files: failed.append("raw_files_missing"); return report
    if not path.exists(): failed.append("tx_index_map_missing"); return report
    if require_manifest_ok and manifest.get("status")!="ok": failed.append(f"manifest_status_not_ok:{manifest.get('status')}")
    if str(manifest.get("day") or "")!=str(day): failed.append(f"manifest_day_mismatch:{manifest.get('day')!r}!={day}")
    generation_id=str(manifest.get("generation_id") or "")
    if not re.fullmatch(r"[0-9a-f]{32}",generation_id): failed.append("generation_id_missing_or_invalid")
    detected=_detect_tx_index_map_contract(path,manifest); report["map_contract"]=detected["contract"]; report["map_columns"]=detected["columns"]
    report["warnings"].extend(detected.get("warnings",[])); failed.extend(detected["failed_checks"])
    if detected["contract"]==TX_INDEX_MAP_CONTRACT_LEGACY_V1: failed.append("legacy_tx_index_map_contract_not_allowed_for_production")
    identity_contract = str(manifest.get("canonical_txid_reconstruction_contract") or "")
    if detected["contract"]==TX_INDEX_MAP_CONTRACT_DUAL_V2:
        if str(manifest.get("output_value_unit") or "").lower()!=_get_output_value_unit(): failed.append("output_value_unit_mismatch")
        allowed_identity_contracts = {
            TX_INDEX_MAP_IDENTITY_CONTRACT_SERIALIZED_V1,
            TX_INDEX_MAP_IDENTITY_CONTRACT_PRESEGWIT_RAWHASH_V1,
        }
        if identity_contract not in allowed_identity_contracts:
            failed.append("canonical_txid_reconstruction_contract_invalid")
        if (
            identity_contract == TX_INDEX_MAP_IDENTITY_CONTRACT_PRESEGWIT_RAWHASH_V1
            and _parse_date(str(day)) >= _parse_date(_canonical_replace_from())
        ):
            failed.append("presegwit_rawhash_identity_contract_after_boundary")
    progress=_read_json_file(progress_path) or {}
    report["progress_status"]=progress.get("status")
    if not progress: failed.append("progress_missing_or_invalid")
    else:
        if str(progress.get("day") or "")!=str(day): failed.append("progress_day_mismatch")
        if str(progress.get("generation_id") or "")!=generation_id: failed.append("progress_generation_id_mismatch")
    con=duckdb.connect()
    try:
        ordering=_tx_index_map_raw_ordering_contract(con,files,day=day); report["raw_ordering_contract"]=ordering
        if ordering.get("status")!="ok": failed.extend(f"raw_ordering_contract:{x}" for x in ordering.get("failed_checks",[]))
        files_sql=_quote_sql_list(files)
        con.execute(f"""CREATE OR REPLACE TEMP TABLE raw_tx_index_audit AS
            SELECT lower(hash::VARCHAR) raw_hash,version,lock_time,block_number::BIGINT block_number,
                   lower(block_hash::VARCHAR) block_hash,COALESCE(is_coinbase,false) is_coinbase,
                   inputs,outputs,input_count
            FROM read_parquet({files_sql},union_by_name=true)""")
        identity_col="raw_hash" if detected["contract"]==TX_INDEX_MAP_CONTRACT_DUAL_V2 else "txid"
        canonical_expr="lower(canonical_txid::VARCHAR)" if detected["contract"]==TX_INDEX_MAP_CONTRACT_DUAL_V2 else "lower(txid::VARCHAR)"
        con.execute(f"""CREATE OR REPLACE TEMP TABLE map_tx_index_audit AS
            SELECT block_number::BIGINT block_number,lower(block_hash::VARCHAR) block_hash,
                   lower({identity_col}::VARCHAR) raw_hash,{canonical_expr} canonical_txid,
                   canonical_tx_index::BIGINT canonical_tx_index,lower(source::VARCHAR) AS source,CAST(raw_date AS VARCHAR) AS raw_date
            FROM read_parquet({_quote_sql_string(str(path))})""")
        row=con.execute("""SELECT
          (SELECT count(*) FROM raw_tx_index_audit),(SELECT count(*) FROM map_tx_index_audit),
          (SELECT count(*) FROM (SELECT DISTINCT block_number,block_hash FROM raw_tx_index_audit)),
          (SELECT count(*) FROM (SELECT DISTINCT block_number,block_hash FROM map_tx_index_audit)),
          (SELECT count(*) FROM raw_tx_index_audit r LEFT JOIN map_tx_index_audit m USING(block_number,block_hash,raw_hash) WHERE m.raw_hash IS NULL),
          (SELECT count(*) FROM map_tx_index_audit m LEFT JOIN raw_tx_index_audit r USING(block_number,block_hash,raw_hash) WHERE r.raw_hash IS NULL),
          (SELECT count(*) FROM (SELECT block_number,block_hash,raw_hash FROM map_tx_index_audit GROUP BY 1,2,3 HAVING count(*)>1)),
          (SELECT count(*) FROM (SELECT block_number,block_hash,canonical_tx_index FROM map_tx_index_audit GROUP BY 1,2,3 HAVING count(*)>1)),
          (SELECT count(*) FROM map_tx_index_audit WHERE block_number IS NULL OR block_hash IS NULL OR raw_hash IS NULL OR canonical_txid IS NULL OR canonical_tx_index IS NULL OR source IS NULL OR raw_date IS NULL),
          (SELECT count(*) FROM (SELECT block_number,block_hash FROM map_tx_index_audit GROUP BY 1,2 HAVING min(canonical_tx_index)<>0 OR count(distinct canonical_tx_index)<>count(*) OR max(canonical_tx_index)+1<>count(*))),
          (SELECT count(*) FROM map_tx_index_audit WHERE block_number<0 OR canonical_tx_index<0),
          (SELECT count(*) FROM (SELECT block_hash FROM map_tx_index_audit GROUP BY 1 HAVING count(distinct block_number)>1)),
          (SELECT count(*) FROM map_tx_index_audit WHERE source NOT IN ('esplora','bitcoin_cli')),
          (SELECT count(*) FROM map_tx_index_audit WHERE raw_date<>?),
          (SELECT count(distinct source) FROM map_tx_index_audit)""",[day]).fetchone()
        keys=("raw_rows","map_rows","raw_blocks","map_blocks","missing_raw_rows_in_map","extra_map_rows_not_in_raw",
              "duplicate_block_raw_hash_keys","duplicate_block_index_keys","null_map_rows","dense_bad_blocks",
              "negative_causal_rows","block_hash_multi_height","invalid_source_rows","raw_date_mismatch_rows","distinct_sources")
        stats={k:int(v or 0) for k,v in zip(keys,row)}; report.update(stats)
        if stats["raw_rows"]!=stats["map_rows"]: failed.append("raw_rows_ne_map_rows")
        if stats["raw_blocks"]!=stats["map_blocks"]: failed.append("raw_blocks_ne_map_blocks")
        for key in keys[4:14]:
            if stats[key]: failed.append(f"{key}:{stats[key]}")
        if stats["distinct_sources"]!=1: failed.append(f"distinct_sources:{stats['distinct_sources']}")
        source=str(manifest.get("source") or "").lower()
        if source not in {"esplora","bitcoin_cli"}: failed.append(f"manifest_source_invalid:{source!r}")
        elif int(con.execute("SELECT count(*) FROM map_tx_index_audit WHERE source<>?",[source]).fetchone()[0] or 0): failed.append("manifest_source_mismatch_rows")
        # Bind manifest/progress counters to observed data.
        observed={"map_rows":stats["map_rows"],"raw_tx_rows":stats["raw_rows"],"total_blocks":stats["raw_blocks"],"completed_blocks":stats["map_blocks"],"completed_tx_rows":stats["map_rows"]}
        for key,value in observed.items():
            raw=manifest.get(key)
            if isinstance(raw,bool) or not isinstance(raw,int): failed.append(f"manifest_counter_not_integer:{key}:{raw!r}")
            elif raw!=value: failed.append(f"manifest_counter_mismatch:{key}:{raw}!={value}")
            praw=progress.get(key)
            if isinstance(praw,bool) or not isinstance(praw,int): failed.append(f"progress_counter_not_integer:{key}:{praw!r}")
            elif praw!=value: failed.append(f"progress_counter_mismatch:{key}:{praw}!={value}")
        expected_policy=ordering.get("explicit_index_order_policy")
        expected_trust=ordering.get("explicit_index_order_trust_status")
        if manifest.get("explicit_index_order_policy")!=expected_policy:
            failed.append(f"manifest_explicit_index_order_policy_mismatch:{manifest.get('explicit_index_order_policy')!r}!={expected_policy!r}")
        if manifest.get("explicit_index_order_trust_status")!=expected_trust:
            failed.append("manifest_explicit_index_order_trust_status_mismatch")
        if progress.get("explicit_index_order_policy")!=expected_policy:
            failed.append("progress_explicit_index_order_policy_mismatch")
        if progress.get("explicit_index_order_trust_status")!=expected_trust:
            failed.append("progress_explicit_index_order_trust_status_mismatch")
        if progress and progress.get("status") not in ({"complete"} if require_manifest_ok else {"complete","complete_pending_audit"}):
            failed.append(f"progress_status_invalid:{progress.get('status')!r}")
        if detected["contract"]==TX_INDEX_MAP_CONTRACT_DUAL_V2:
            if identity_contract == TX_INDEX_MAP_IDENTITY_CONTRACT_PRESEGWIT_RAWHASH_V1:
                vals = con.execute("""SELECT
                  (SELECT count(*) FROM map_tx_index_audit WHERE canonical_txid<>raw_hash),
                  (SELECT count(*) FROM raw_tx_index_audit WHERE NOT is_coinbase AND inputs IS NULL),
                  (SELECT count(*) FROM (
                     SELECT block_number,block_hash
                     FROM raw_tx_index_audit
                     GROUP BY 1,2
                     HAVING count(*) FILTER (WHERE is_coinbase)<>1
                  )),
                  (SELECT count(*) FROM raw_tx_index_audit
                   WHERE is_coinbase AND inputs IS NULL
                     AND COALESCE(input_count,0)<>0)
                """).fetchone()
                for key, value in zip((
                    "presegwit_map_canonical_ne_raw_hash",
                    "presegwit_noncoinbase_null_inputs",
                    "presegwit_bad_coinbase_cardinality_blocks",
                    "presegwit_coinbase_null_inputs_nonzero_count",
                ), vals):
                    report[key] = int(value or 0)
                    if report[key]:
                        failed.append(f"{key}:{report[key]}")
                report["reconstructed_rows"] = 0
                report["canonical_identity_audit_mode"] = "presegwit_raw_hash_exact_identity"
            else:
                con.execute("CREATE OR REPLACE TEMP TABLE reconstructed_txid_audit(raw_hash VARCHAR,canonical_txid VARCHAR,block_number BIGINT,block_hash VARCHAR)")
                report["reconstructed_rows"]=_tx_index_map_populate_reconstructed(con,"raw_tx_index_audit","reconstructed_txid_audit",max(100,_env_int("UTXO_TX_INDEX_MAP_RECON_BATCH_ROWS",2000)))
                vals=con.execute("""SELECT
                  (SELECT count(*) FROM reconstructed_txid_audit r JOIN map_tx_index_audit m USING(block_number,block_hash,raw_hash) WHERE r.canonical_txid<>m.canonical_txid),
                  (SELECT count(*) FROM reconstructed_txid_audit r LEFT JOIN map_tx_index_audit m USING(block_number,block_hash,raw_hash,canonical_txid) WHERE m.raw_hash IS NULL),
                  (SELECT count(*) FROM map_tx_index_audit m LEFT JOIN reconstructed_txid_audit r USING(block_number,block_hash,raw_hash,canonical_txid) WHERE r.raw_hash IS NULL),
                  (SELECT count(*) FROM (SELECT block_number,block_hash,canonical_txid FROM map_tx_index_audit GROUP BY 1,2,3 HAVING count(*)>1))""").fetchone()
                for key,value in zip(("canonical_txid_mismatch_rows","reconstructed_missing_in_map","map_extra_vs_reconstructed","duplicate_block_canonical_txid_keys"),vals):
                    report[key]=int(value or 0)
                    if report[key]: failed.append(f"{key}:{report[key]}")
                report["canonical_identity_audit_mode"] = "serialized_nonwitness_reconstruction"
            expected_order=str(manifest.get("canonical_order_sha256") or ""); observed_order=_tx_index_map_order_digest_parquet(path)
            report["canonical_order_sha256_expected"]=expected_order or None; report["canonical_order_sha256_observed"]=observed_order
            if manifest.get("canonical_order_digest_version")!=TX_INDEX_MAP_ORDER_DIGEST_VERSION: failed.append("canonical_order_digest_version_invalid")
            if not re.fullmatch(r"[0-9a-f]{64}",expected_order): failed.append("canonical_order_sha256_missing_or_invalid")
            elif expected_order!=observed_order: failed.append(f"canonical_order_sha256_mismatch:{observed_order}!={expected_order}")
            expected_sha=str(manifest.get("final_map_parquet_sha256") or ""); observed_sha=_file_sha256_streaming(path)
            if not re.fullmatch(r"[0-9a-f]{64}",expected_sha): failed.append("final_map_parquet_sha256_missing_or_invalid")
            elif expected_sha!=observed_sha: failed.append(f"final_map_parquet_sha256_mismatch:{observed_sha}!={expected_sha}")
    except Exception as exc:
        failed.append(f"map_audit_query_failed:{type(exc).__name__}:{exc}")
    finally:
        con.close()
    if require_manifest_ok and manifest_override is None and path.resolve(strict=False)==_tx_index_map_path(day).resolve(strict=False):
        publication_marker_path = _tx_index_map_publication_marker_path(day)
        report["publication_marker_path"] = str(publication_marker_path)
        report["publication_marker_present"] = publication_marker_path.exists()
        if publication_marker_path.exists() and not allow_publication_marker:
            failed.append("publication_marker_present_recovery_required")
        ledger=_tx_index_map_validate_generation_ledger(day,manifest,manifest_path,path); report["generation_ledger"]=ledger
        failed.extend(f"generation_ledger:{x}" for x in ledger.get("failed_checks",[]))
    report["artifact_binding"]=_tx_index_map_artifact_binding(path,manifest_path)
    report["status"]="ok" if not failed else "fail"
    identity_prefixes=("canonical_txid_mismatch_rows","reconstructed_missing_in_map","map_extra_vs_reconstructed","canonical_order_sha256_mismatch","duplicate_block_canonical_txid_keys")
    identity_failed=any(str(x).startswith(identity_prefixes) for x in failed); provenance_failed=any(not str(x).startswith(identity_prefixes) for x in failed)
    if not failed:
        if emit_success_event:
            _emit_event("S12921", f"TX_INDEX_MAP_DUAL_ID_ACCEPTED day={day}")
        elif emit_neutral_success_event:
            _emit_event("S12920", f"TX_INDEX_MAP_CANDIDATE_VALIDATED day={day}")
    else:
        if identity_failed: _emit_event("E12927",f"TX_INDEX_MAP_IDENTITY_MISMATCH day={day} checks={sorted(set(failed))}")
        if provenance_failed: _emit_event("E12926",f"TX_INDEX_MAP_CONTRACT_MISMATCH day={day} checks={sorted(set(failed))}")
    return report



def _tx_index_map_build_command(day: str, raw_base: Optional[str] = None) -> str:
    raw = raw_base or (_env_str("UTXO_RAW_BASE", RAW_BASE_DEFAULT) or RAW_BASE_DEFAULT)
    map_dir = str(_tx_index_map_root_path_no_create())
    return (
        "cd /root/mybot || exit 1; source .venv/bin/activate; "
        f"UTXO_MODE=TX_INDEX_MAP_ONLY UTXO_RAW_BASE={shlex.quote(str(raw))} "
        f"UTXO_START_DATE={shlex.quote(str(day))} UTXO_END_DATE={shlex.quote(str(day))} "
        f"UTXO_TX_INDEX_MAP_DIR={shlex.quote(map_dir)} UTXO_LOCK_ROOT=/root/mybot/lock "
        "LOG_LEVEL=INFO /root/mybot/.venv/bin/python -u /root/mybot/utxo_pipeline_v30.py"
    )


def _tx_index_map_audit_command(day: str, raw_base: Optional[str] = None) -> str:
    raw = raw_base or (_env_str("UTXO_RAW_BASE", RAW_BASE_DEFAULT) or RAW_BASE_DEFAULT)
    map_dir = str(_tx_index_map_root_path_no_create())
    return (
        "cd /root/mybot || exit 1; source .venv/bin/activate; "
        f"UTXO_MODE=TX_INDEX_MAP_AUDIT_ONLY UTXO_RAW_BASE={shlex.quote(str(raw))} "
        f"UTXO_START_DATE={shlex.quote(str(day))} UTXO_END_DATE={shlex.quote(str(day))} "
        f"UTXO_TX_INDEX_MAP_DIR={shlex.quote(map_dir)} UTXO_LOCK_ROOT=/root/mybot/lock "
        "LOG_LEVEL=INFO /root/mybot/.venv/bin/python -u /root/mybot/utxo_pipeline_v30.py"
    )


def _tx_index_map_required_stop(day: str, reason: str, *, report: Optional[Dict[str, Any]] = None) -> None:
    source_valid_until = _tx_index_map_previous_day(day)
    mode = _CURRENT_MODE or "<unknown>"
    rebuild_context = mode in {MODE_REBUILD_FULL, MODE_REBUILD_RESUME}
    payload = {
        "status": "controlled_stop",
        "reason": reason,
        "failed_day": day,
        "blocked_day": day,
        "source_valid_until": source_valid_until,
        "db_valid_until": None if rebuild_context else "unknown",
        "utxo_valid_until": source_valid_until,  # legacy key; do not treat as DB-valid for REBUILD_FULL pre-apply stops
        "next_manual_start_date": day,
        "utxo_db_modified": False,
        "apply_started": False,
        "append_allowed": False if rebuild_context else None,
        "resume_supported": False,
        "restart_policy": "clean_rebuild_from_zero",
        "partial_reusable": False,
        "next_action": {
            "build_tx_index_map": _tx_index_map_build_command(day),
            "audit_tx_index_map": _tx_index_map_audit_command(day),
            "after_success": "rerun the same REBUILD_FULL command" if rebuild_context else "rerun the blocked command",
        },
        "report": report or {},
    }
    if rebuild_context:
        _log_red(f"REBUILD_FULL Phase-0/stage tx_index_map stop before apply: {reason}")
        _log_red(f"Blocked day: {day}")
        _log_red("DB valid until: NONE (apply was not started by this failure).")
        _log_red("APPEND_TAIL is NOT valid for this state; build/audit map, delete/quarantine empty DB if created, rerun REBUILD_FULL.")
        _log_green(f"SOURCE/PREFLIGHT valid until: {source_valid_until}")
    else:
        _log_red(f"REPLAY_SUFFIX/TX_INDEX_MAP stopped before cleanup/apply: {reason}")
        _log_red(f"Blocked day: {day}")
        _log_red("UTXO DB was NOT modified by this map/preflight failure.")
        _log_green(f"SOURCE/PREFLIGHT valid until: {source_valid_until}")
        _log_green(f"Next manual start date: {day}")
    _log_red(f"Next action build: {_tx_index_map_build_command(day)}")
    _log_red(f"Next action audit: {_tx_index_map_audit_command(day)}")
    raise ControlledStopExit(f"controlled stop day={day} reason={reason}", exit_code=76, payload=payload)


def _assert_tx_index_map_usable(raw_base: str, day: str) -> Dict[str, Any]:
    path = _tx_index_map_path(day)
    manifest = _read_json_file(_tx_index_map_manifest_path(day)) or {}
    if not path.exists() or manifest.get("status") != "ok":
        _tx_index_map_required_stop(
            day,
            "missing_or_incomplete_canonical_tx_index_map",
            report={"path": str(path), "manifest_status": manifest.get("status")},
        )
    report = _audit_tx_index_map_day(raw_base, day)
    if report.get("status") != "ok":
        _tx_index_map_required_stop(day, "tx_index_map_audit_failed", report=report)
    return report


def _tx_index_map_day_requirement(raw_base: str, day: str, con: duckdb.DuckDBPyConnection) -> Dict[str, Any]:
    """Return strict day-wide canonical tx_index_map requirement."""
    files=_day_parquet_files(raw_base,day)
    report=_tx_index_map_raw_ordering_contract(con,files,day=day)
    report["day"]=str(day); report["files"]=len(files)
    # Preserve the historical Phase-0 status vocabulary.
    if report.get("status")!="ok": report["status"]="fail"
    return report



def _v11_tx_index_map_preflight_report_path(start_day: str, end_day: str) -> Path:
    logs_dir = Path(_env_str("UTXO_LOG_DIR", "/root/mybot/logs") or "/root/mybot/logs")
    logs_dir.mkdir(parents=True, exist_ok=True)
    ts = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    explicit = _env_str("UTXO_TX_INDEX_MAP_PREFLIGHT_JSON", None)
    if explicit:
        return Path(explicit)
    return logs_dir / f"tx_index_map_preflight_{start_day}_{end_day}_{ts}.json"


def _save_tx_index_map_preflight_report(report: Dict[str, Any]) -> Optional[Path]:
    try:
        path = _v11_tx_index_map_preflight_report_path(str(report.get("start_day")), str(report.get("end_day")))
        path.parent.mkdir(parents=True, exist_ok=True)
        latest = path.parent / "tx_index_map_preflight_latest.json"
        # r10: persist self-references inside the JSON itself.  R9 added these
        # fields only after saving, so the operator-visible report on disk did
        # not contain its own path/latest path.
        report["report_path"] = str(path)
        report["latest_path"] = str(latest)
        _save_json_atomic(path, report)
        _save_json_atomic(latest, report)
        return path
    except Exception as e:
        _warn(f"TX_INDEX_MAP_PREFLIGHT report write failed: {type(e).__name__}: {e}")
        return None


def _v11_tx_index_map_preflight(raw_base: str, days: Sequence[str], *, context: str) -> Dict[str, Any]:
    """Phase-0 tx_index_map readiness scanner.

    This function is read/preflight only: it does not create/open the UTXO DB,
    does not create stage day artifacts, and does not apply cleanup/apply SQL.
    It intentionally checks only the canonical tx_index maps needed by the
    day-level stage rule.
    """
    day_list = [str(d) for d in days]
    report: Dict[str, Any] = {
        "mode": MODE_TX_INDEX_MAP_PREFLIGHT_ONLY,
        "context": str(context),
        "pipeline_version": _pipeline_version(),
        "raw_base": str(raw_base),
        "tx_index_map_dir": str(_tx_index_map_root_path_no_create()),
        "days": len(day_list),
        "start_day": day_list[0] if day_list else None,
        "end_day": day_list[-1] if day_list else None,
        "checked_days": 0,
        "required_days": 0,
        "ok_required_days": 0,
        "missing_days": [],
        "incomplete_days": [],
        "audit_failed_days": [],
        "raw_missing_days": [],
        "warnings": [],
        "required_day_reports": [],
        "status": "ok",
        "safe_to_start_rebuild": True,
        "first_blocked_day": None,
        "created_at": _now_iso(),
    }
    if not day_list:
        _save_tx_index_map_preflight_report(report)
        return report

    _log(
        f"TX_INDEX_MAP_PREFLIGHT begin context={context} days={len(day_list)} "
        f"range={day_list[0]}..{day_list[-1]} map_dir={_tx_index_map_root_path_no_create()}"
    )
    con = duckdb.connect()
    try:
        _apply_duckdb_pragmas(con, phase="stage")
        for idx, day in enumerate(day_list, start=1):
            day_req = _tx_index_map_day_requirement(raw_base, day, con)
            report["checked_days"] = int(report["checked_days"]) + 1
            if day_req.get("status") == "fail":
                report["raw_missing_days"].append(day_req)
                continue
            if not day_req.get("required"):
                continue
            report["required_days"] = int(report["required_days"]) + 1
            map_path = _tx_index_map_path_no_create(day)
            manifest_path = _tx_index_map_manifest_path_no_create(day)
            manifest = _read_json_file(manifest_path) or {}
            required_report = {
                "day": day,
                "requirement": day_req,
                "map_path": str(map_path),
                "manifest_path": str(manifest_path),
                "manifest_status": manifest.get("status"),
                "map_exists": bool(map_path.exists()),
                "audit": None,
                "status": "fail",
                "failed_checks": [],
            }
            failed_checks: List[str] = required_report["failed_checks"]
            if not map_path.exists():
                failed_checks.append("tx_index_map_missing")
                report["missing_days"].append(required_report)
            elif manifest.get("status") != "ok":
                failed_checks.append(f"manifest_status_not_ok:{manifest.get('status')}")
                report["incomplete_days"].append(required_report)
            else:
                try:
                    audit = _audit_tx_index_map_day(raw_base, day)
                    required_report["audit"] = audit
                    if audit.get("status") == "ok":
                        required_report["status"] = "ok"
                        report["ok_required_days"] = int(report["ok_required_days"]) + 1
                    else:
                        failed_checks.extend(list(audit.get("failed_checks") or ["tx_index_map_audit_failed"]))
                        report["audit_failed_days"].append(required_report)
                except Exception as e:
                    failed_checks.append(f"tx_index_map_audit_exception:{type(e).__name__}: {e}")
                    report["audit_failed_days"].append(required_report)
            if required_report["status"] != "ok":
                required_report["next_action"] = {
                    "build_tx_index_map": _tx_index_map_build_command(day, raw_base),
                    "audit_tx_index_map": _tx_index_map_audit_command(day, raw_base),
                    "after_success": "rerun the same REBUILD_FULL command" if context == MODE_REBUILD_FULL else "rerun the blocked command",
                }
            report["required_day_reports"].append(required_report)
            if idx == 1 or idx % 50 == 0 or required_report["status"] != "ok":
                _log(
                    f"TX_INDEX_MAP_PREFLIGHT progress day={day} checked={idx}/{len(day_list)} "
                    f"required={report['required_days']} failures={len(report['missing_days']) + len(report['incomplete_days']) + len(report['audit_failed_days'])}"
                )
    finally:
        con.close()

    failures = len(report["missing_days"]) + len(report["incomplete_days"]) + len(report["audit_failed_days"]) + len(report["raw_missing_days"])
    if failures:
        blocked_days: List[str] = []
        for key in ["missing_days", "incomplete_days", "audit_failed_days", "raw_missing_days"]:
            for item in report.get(key, []):
                d = item.get("day") or item.get("requirement", {}).get("day")
                if d:
                    blocked_days.append(str(d))
        first = sorted(blocked_days)[0] if blocked_days else None
        report.update({
            "status": "blocked",
            "safe_to_start_rebuild": False,
            "first_blocked_day": first,
            "append_allowed": False,
            "db_valid_until": None,
            "source_valid_until": _tx_index_map_previous_day(first) if first else None,
        })
    _save_tx_index_map_preflight_report(report)
    _log(
        f"TX_INDEX_MAP_PREFLIGHT complete status={report['status']} "
        f"checked={report['checked_days']} required={report['required_days']} "
        f"ok_required={report['ok_required_days']} first_blocked_day={report.get('first_blocked_day')}"
    )
    return report


def _v11_rebuild_tx_index_map_phase0_guard(raw_base: str, days: Sequence[str]) -> Optional[Dict[str, Any]]:
    if not _env_bool("UTXO_REBUILD_TX_INDEX_MAP_PREFLIGHT", True):
        _warn("REBUILD_FULL Phase-0 tx_index_map preflight disabled by UTXO_REBUILD_TX_INDEX_MAP_PREFLIGHT=0")
        return None
    report = _v11_tx_index_map_preflight(raw_base, days, context=MODE_REBUILD_FULL)
    if report.get("status") == "ok":
        _log("REBUILD_FULL Phase-0 tx_index_map preflight green; DB/stage/apply may start")
        return report
    blocked_day = str(report.get("first_blocked_day") or "<unknown>")
    reason = "missing_or_incomplete_canonical_tx_index_map"
    if report.get("audit_failed_days"):
        reason = "tx_index_map_audit_failed"
    if report.get("raw_missing_days"):
        reason = "raw_files_missing"
    payload = {
        "status": "rebuild_phase0_blocked",
        "reason": reason,
        "blocked_day": blocked_day,
        "range_start": report.get("start_day"),
        "range_end": report.get("end_day"),
        "db_created": False,
        "stage_built": False,
        "apply_started": False,
        "append_allowed": False,
        "db_valid_until": None,
        "source_valid_until": report.get("source_valid_until"),
        "next_action": None,
        "preflight_report": report,
    }
    # Pull the detailed command from the first matching required-day report when available.
    for item in report.get("required_day_reports", []):
        if str(item.get("day")) == blocked_day and item.get("next_action"):
            payload["next_action"] = item.get("next_action")
            break
    if payload["next_action"] is None and blocked_day != "<unknown>":
        payload["next_action"] = {
            "build_tx_index_map": _tx_index_map_build_command(blocked_day, raw_base),
            "audit_tx_index_map": _tx_index_map_audit_command(blocked_day, raw_base),
            "after_success": "rerun the same REBUILD_FULL command",
        }
    _log_red("REBUILD_FULL blocked by Phase-0 tx_index_map preflight before DB/stage/apply")
    _log_red(f"Reason: {reason}")
    _log_red(f"Blocked day: {blocked_day}")
    _log_red("DB was NOT created/opened by REBUILD_FULL Phase-0 guard.")
    _log_red("Stage was NOT built by REBUILD_FULL Phase-0 guard.")
    _log_red("Apply was NOT started by REBUILD_FULL Phase-0 guard.")
    _log_red("APPEND_TAIL allowed: false. Do not append; build/audit map and rerun REBUILD_FULL.")
    if payload.get("source_valid_until"):
        _log_green(f"SOURCE/PREFLIGHT valid until: {payload.get('source_valid_until')}")
    if payload.get("next_action"):
        _log_red(f"Next action build: {payload['next_action'].get('build_tx_index_map')}")
        _log_red(f"Next action audit: {payload['next_action'].get('audit_tx_index_map')}")
        _log_red(f"After success: {payload['next_action'].get('after_success')}")
    raise ControlledStopExit(f"REBUILD_FULL Phase-0 blocked day={blocked_day} reason={reason}", exit_code=76, payload=payload)


def _tx_index_map_preflight_only(raw_base: str, days: Sequence[str]) -> int:
    report = _v11_tx_index_map_preflight(raw_base, days, context=MODE_TX_INDEX_MAP_PREFLIGHT_ONLY)
    if report.get("status") == "ok":
        return 0
    blocked_day = str(report.get("first_blocked_day") or "<unknown>")
    _log_red(f"TX_INDEX_MAP_PREFLIGHT_ONLY blocked first_day={blocked_day}; see report_path={report.get('report_path')}")
    return 76


def _build_tx_index_map_day(raw_base: str, day: str) -> Dict[str, Any]:
    """Build a fresh dual-ID canonical-order map without mutating the UTXO DB.

    R32 recovery-ledger hardening policy:
      - dual-ID partial resume is disabled; every build starts from raw block zero;
      - stale/incomplete artifacts are quarantined even when no partial exists;
      - an existing good generation is copied as parquet+manifest+progress;
      - any unsuccessful rebuild restores that complete previous generation;
      - failed-generation evidence is retained separately;
      - periodic full partial-parquet rewrites are disabled by default because
        partial files are not reusable. Progress JSON remains lightweight.
    """
    lock_dir: Optional[Path] = None
    previous_generation_backup: Optional[Path] = None
    failed_generation_dir: Optional[Path] = None
    build_success = False
    new_final_promoted = False
    candidate_path: Optional[Path] = None
    previous_generation_restorable = False
    preexisting_generation_invalid = False
    build_dir: Optional[Path] = None
    map_build_con: Optional[duckdb.DuckDBPyConnection] = None
    rows_written = 0
    generation_id = uuid.uuid4().hex
    publication_marker: Optional[Path] = None
    rollback_ledger_error: Optional[BaseException] = None

    def _generation_stamp(prefix: str, day_dir: Path) -> Path:
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
        return day_dir / (
            f"{prefix}.{stamp}.{time.time_ns()}.{os.getpid()}.{uuid.uuid4().hex}"
        )

    def _copy_if_exists(src: Path, dst_dir: Path) -> None:
        if src.exists():
            shutil.copy2(src, dst_dir / src.name)

    def _atomic_replace_from_copy(src: Path, dst: Path) -> None:
        """Restore one artifact through durable temp+replace publication."""
        _atomic_publish_copy(src, dst)

    def _snapshot_previous_generation(
        *,
        day_dir: Path,
        final_path: Path,
        manifest_path: Path,
        progress_path: Path,
        restorable: bool,
        prebuild_audit: Optional[Dict[str, Any]],
    ) -> Optional[Path]:
        """Create a complete snapshot; only a green audited generation is restorable."""
        originals = {
            final_path.name: final_path.exists(),
            manifest_path.name: manifest_path.exists(),
            progress_path.name: progress_path.exists(),
        }
        if not any(originals.values()):
            return None
        backup_dir = _generation_stamp("quarantine.prebuild_generation", day_dir)
        backup_dir.mkdir(parents=True, exist_ok=False)
        inventory_path = backup_dir / "inventory.json"
        previous_manifest_payload = _read_json_file(manifest_path) if manifest_path.is_file() else None
        previous_progress_payload = _read_json_file(progress_path) if progress_path.is_file() else None
        previous_generation_id = str((previous_manifest_payload or {}).get("generation_id") or "") or None
        inventory = {
            "backup_complete": False,
            "day": day,
            "pipeline_version": _pipeline_version(),
            "candidate_generation_id": generation_id,
            "snapshot_generation_id": previous_generation_id,
            "snapshot_progress_generation_id": str((previous_progress_payload or {}).get("generation_id") or "") or None,
            "original_files": originals,
            "created_at": _now_iso(),
            "restorable": bool(restorable),
            "prebuild_audit_status": (prebuild_audit or {}).get("status"),
            "prebuild_audit_failed_checks": (prebuild_audit or {}).get("failed_checks"),
            "manifest_status": ((_read_json_file(manifest_path) or {}).get("status") if manifest_path.exists() else None),
            "map_contract": (prebuild_audit or {}).get("map_contract"),
        }
        _save_json_atomic(inventory_path, inventory)
        try:
            for artifact in (final_path, manifest_path, progress_path):
                if originals[artifact.name]:
                    backup_artifact = backup_dir / artifact.name
                    shutil.copy2(artifact, backup_artifact)
                    with backup_artifact.open("rb") as backup_fh:
                        os.fsync(backup_fh.fileno())
            _fsync_directory(backup_dir)
            inventory["sha256"] = {
                name: _file_sha256_streaming(backup_dir / name)
                for name, present in originals.items() if present
            }
            inventory["backup_complete"] = True
            inventory["completed_at"] = _now_iso()
            _save_json_atomic(inventory_path, inventory)
            return backup_dir
        except Exception:
            inventory["backup_error_at"] = _now_iso()
            try:
                _save_json_atomic(inventory_path, inventory)
            except Exception:
                pass
            raise

    def _preserve_failed_generation(
        *,
        day_dir: Path,
        final_path: Path,
        manifest_path: Path,
        progress_path: Path,
        partial_path: Path,
        candidate: Optional[Path],
        error: BaseException,
    ) -> Path:
        nonlocal failed_generation_dir
        if failed_generation_dir is None:
            failed_generation_dir = _generation_stamp("quarantine.failed_generation", day_dir)
            failed_generation_dir.mkdir(parents=True, exist_ok=False)
        # Copy the active promoted map; rollback/removal happens independently.
        if new_final_promoted and final_path.exists():
            _copy_if_exists(final_path, failed_generation_dir)
        for artifact in (manifest_path, progress_path, partial_path):
            _copy_if_exists(artifact, failed_generation_dir)
        # Candidate is failed-generation state: move it out of the active day dir.
        if candidate is not None and candidate.exists():
            os.replace(candidate, failed_generation_dir / candidate.name)
            _fsync_directory(failed_generation_dir)
            _fsync_directory(candidate.parent)
        failure_report = {
            "status": "failed_generation_preserved",
            "day": day,
            "pipeline_version": _pipeline_version(),
            "generation_id": generation_id,
            "error_type": type(error).__name__,
            "error": str(error),
            "new_final_promoted": bool(new_final_promoted),
            "previous_generation_backup": str(previous_generation_backup) if previous_generation_backup else None,
            "resume_supported": False,
            "restart_policy": "clean_rebuild_from_zero",
            "partial_reusable": False,
            "created_at": _now_iso(),
        }
        _save_json_atomic(failed_generation_dir / "failure_report.json", failure_report)
        return failed_generation_dir

    def _restore_previous_generation(
        *,
        final_path: Path,
        manifest_path: Path,
        progress_path: Path,
        expected_previous_generation_id: Optional[str] = None,
    ) -> bool:
        if previous_generation_backup is None:
            return False
        inventory_path = previous_generation_backup / "inventory.json"
        inventory = _read_json_file(inventory_path) or {}
        if inventory.get("backup_complete") is not True:
            raise RuntimeError(f"previous generation backup is incomplete: {previous_generation_backup}")
        if inventory.get("restorable") is not True:
            return False
        if str(inventory.get("day") or "") != str(day):
            raise RuntimeError(f"previous generation backup day mismatch: {inventory.get('day')!r}!={day}")
        originals = inventory.get("original_files") if isinstance(inventory.get("original_files"), dict) else {}
        expected_sha = inventory.get("sha256") if isinstance(inventory.get("sha256"), dict) else {}
        # Validate every declared backup before touching active artifacts.
        for active in (final_path, manifest_path, progress_path):
            if originals.get(active.name) is True:
                backup = previous_generation_backup / active.name
                if not backup.is_file():
                    raise RuntimeError(f"previous generation backup file missing: {backup}")
                if expected_sha.get(active.name) != _file_sha256_streaming(backup):
                    raise RuntimeError(f"previous generation backup sha256 mismatch: {backup}")
        backup_manifest_payload = _read_json_file(previous_generation_backup / manifest_path.name) if originals.get(manifest_path.name) is True else None
        backup_progress_payload = _read_json_file(previous_generation_backup / progress_path.name) if originals.get(progress_path.name) is True else None
        backup_generation_id = str((backup_manifest_payload or {}).get("generation_id") or "") or None
        backup_progress_generation_id = str((backup_progress_payload or {}).get("generation_id") or "") or None
        inventory_generation_id = str(inventory.get("snapshot_generation_id") or "") or None
        # R30/R31 inventories did not carry snapshot_generation_id; derive it from
        # the backed-up manifest for backward-compatible recovery.
        if inventory_generation_id and inventory_generation_id != backup_generation_id:
            raise RuntimeError(
                f"previous generation backup inventory identity mismatch: "
                f"{inventory_generation_id!r}!={backup_generation_id!r}"
            )
        if expected_previous_generation_id and backup_generation_id != str(expected_previous_generation_id):
            raise RuntimeError(
                f"previous generation backup does not match publication marker: "
                f"{backup_generation_id!r}!={expected_previous_generation_id!r}"
            )
        if backup_progress_generation_id and backup_generation_id and backup_progress_generation_id != backup_generation_id:
            raise RuntimeError(
                f"previous generation backup manifest/progress identity mismatch: "
                f"{backup_generation_id!r}!={backup_progress_generation_id!r}"
            )
        # Publish data first and manifest last as the generation commit marker.
        for active in (final_path, progress_path):
            if originals.get(active.name) is True:
                _atomic_replace_from_copy(previous_generation_backup / active.name, active)
            else:
                active.unlink(missing_ok=True)
        if originals.get(manifest_path.name) is True:
            _atomic_replace_from_copy(previous_generation_backup / manifest_path.name, manifest_path)
        else:
            manifest_path.unlink(missing_ok=True)
        _fsync_directory(final_path.parent)
        return True

    def _remove_failed_published_generation(
        *, final_path: Path, manifest_path: Path, progress_path: Path
    ) -> None:
        """Fail closed when no previous generation exists to restore."""
        for active in (final_path, progress_path, manifest_path):
            active.unlink(missing_ok=True)
        _fsync_directory(final_path.parent)

    try:
        lock_dir = _tx_index_map_acquire_day_lock(day)

        files = _day_parquet_files(raw_base, day)
        if not files:
            raise FileNotFoundError(f"No parquet files found for TX_INDEX_MAP_ONLY day={day}")
        source = _tx_index_map_source()
        day_dir = _tx_index_map_day_dir(day)
        final_path = _tx_index_map_path(day)
        partial_path = _tx_index_map_partial_path(day)
        manifest_path = _tx_index_map_manifest_path(day)
        progress_path = _tx_index_map_progress_path(day)
        valid_until = _tx_index_map_previous_day(day)
        flush_every = _tx_index_map_flush_every_blocks()
        write_partial_evidence = _env_bool("UTXO_TX_INDEX_MAP_WRITE_PARTIAL_EVIDENCE", False)

        # Recover an interrupted publication transaction before inspecting/reusing
        # the active generation. Invalid or ambiguous markers are fail-closed and
        # never authorize deletion/restoration. A fully committed active generation
        # is re-audited and finalized instead of being destructively rolled back.
        publication_marker = _tx_index_map_publication_marker_path(day)
        if publication_marker.exists():
            try:
                pending = _read_json_file(publication_marker)
            except Exception as marker_exc:
                raise ControlledStopExit(
                    f"unreadable tx_index_map publication marker day={day}: {type(marker_exc).__name__}: {marker_exc}",
                    exit_code=76,
                    payload={"day": day, "reason": "publication_marker_unreadable", "marker": str(publication_marker)},
                ) from marker_exc
            marker_failed = _tx_index_map_validate_publication_marker(
                day, pending, day_dir=day_dir, final_path=final_path,
                manifest_path=manifest_path, progress_path=progress_path,
            )
            if marker_failed:
                raise ControlledStopExit(
                    f"invalid tx_index_map publication marker day={day}: {marker_failed}",
                    exit_code=76,
                    payload={"day": day, "reason": "publication_marker_invalid", "failed_checks": marker_failed, "marker": str(publication_marker)},
                )
            pending = dict(pending or {})
            phase = str(pending.get("phase"))
            marker_generation = str(pending.get("generation_id"))
            backup_raw = pending.get("previous_generation_backup")
            active_report: Optional[Dict[str, Any]] = None
            active_manifest = _read_json_file(manifest_path) if manifest_path.is_file() else None
            active_progress = _read_json_file(progress_path) if progress_path.is_file() else None
            active_generation = str((active_manifest or {}).get("generation_id") or "")
            active_progress_generation = str((active_progress or {}).get("generation_id") or "")
            if final_path.is_file() and isinstance(active_manifest, dict) and isinstance(active_progress, dict):
                try:
                    active_report = _audit_tx_index_map_day(
                        raw_base,
                        day,
                        emit_success_event=False,
                        emit_neutral_success_event=False,
                        allow_publication_marker=True,
                    )
                except Exception as active_audit_exc:
                    _warn(
                        f"TX_INDEX_MAP_ONLY recovery active audit failed day={day}: "
                        f"{type(active_audit_exc).__name__}: {active_audit_exc}"
                    )
            committed = bool(
                active_report and active_report.get("status") == "ok"
                and active_generation == marker_generation
                and active_progress_generation == marker_generation
            )
            marker_ledger_sha = str(pending.get("ledger_record_sha256") or "")
            if committed and marker_ledger_sha:
                ledger_record = ((active_report.get("generation_ledger") or {}).get("record") or {})
                committed = str(ledger_record.get("record_sha256") or "") == marker_ledger_sha
            if committed:
                _tx_index_map_clear_publication_marker(day, expected_generation_id=marker_generation)
                publication_marker = None
                if backup_raw:
                    try:
                        backup_path = Path(str(backup_raw))
                        if backup_path.is_dir():
                            shutil.rmtree(backup_path)
                            _fsync_directory(day_dir)
                    except Exception as cleanup_exc:
                        _warn(
                            f"TX_INDEX_MAP_ONLY committed-recovery backup cleanup failed day={day}: "
                            f"{type(cleanup_exc).__name__}: {cleanup_exc}"
                        )
                previous_generation_backup = None
                _warn(f"TX_INDEX_MAP_ONLY finalized committed publication day={day} phase={phase}")
            else:
                # PREPARED can legitimately leave the previous active generation untouched.
                if active_report and active_report.get("status") == "ok" and active_generation != marker_generation:
                    if phase == "PREPARED":
                        # Clear the transaction marker first. A crash after this point
                        # can only leave an inert quarantine backup, never a marker
                        # that references an already-removed recovery source.
                        _tx_index_map_clear_publication_marker(day, expected_generation_id=marker_generation)
                        publication_marker = None
                        if backup_raw:
                            try:
                                abandoned_backup = Path(str(backup_raw))
                                if abandoned_backup.is_dir():
                                    shutil.rmtree(abandoned_backup)
                                    _fsync_directory(day_dir)
                                elif abandoned_backup.exists():
                                    _warn(
                                        f"TX_INDEX_MAP_ONLY abandoned PREPARED backup is not a directory "
                                        f"day={day} path={abandoned_backup}"
                                    )
                            except Exception as cleanup_exc:
                                _warn(
                                    f"TX_INDEX_MAP_ONLY abandoned PREPARED backup cleanup failed "
                                    f"day={day} path={backup_raw}: "
                                    f"{type(cleanup_exc).__name__}: {cleanup_exc}"
                                )
                        previous_generation_backup = None
                        _warn(f"TX_INDEX_MAP_ONLY aborted unpromoted PREPARED generation day={day}; previous active generation retained")
                    elif not backup_raw:
                        raise ControlledStopExit(
                            f"ambiguous publication recovery without backup day={day} phase={phase}",
                            exit_code=76,
                            payload={"day": day, "reason": "publication_recovery_ambiguous", "phase": phase},
                        )
                if publication_marker is not None:
                    recovered = False
                    if backup_raw:
                        previous_generation_backup = Path(str(backup_raw))
                        recovered = _restore_previous_generation(
                            final_path=final_path,
                            manifest_path=manifest_path,
                            progress_path=progress_path,
                            expected_previous_generation_id=(
                                str(pending.get("previous_generation_id"))
                                if pending.get("previous_generation_id") not in {None, ""}
                                else None
                            ),
                        )
                    ledger_state = _tx_index_map_read_generation_ledger() if _tx_index_map_generation_ledger_path().exists() else {
                        "status": "ok", "effective_by_day": {}, "published_by_day": {}, "failed_checks": []
                    }
                    if ledger_state.get("status") != "ok":
                        raise ControlledStopExit(
                            f"cannot recover publication with invalid generation ledger day={day}",
                            exit_code=76,
                            payload={"day": day, "reason": "generation_ledger_invalid_during_recovery", "failed_checks": ledger_state.get("failed_checks")},
                        )
                    current = (ledger_state.get("effective_by_day") or {}).get(str(day))
                    current_generation = str((current or {}).get("generation_id") or "") or None
                    if recovered:
                        restored_manifest = _read_json_file(manifest_path) or {}
                        restored_generation = str(restored_manifest.get("generation_id") or "")
                        if current_generation and current_generation != restored_generation:
                            _tx_index_map_append_generation_ledger(
                                day, manifest_path, final_path, action=TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK,
                                reason=f"startup_recovery_from_phase_{phase}",
                                from_generation_id=current_generation,
                            )
                    else:
                        _remove_failed_published_generation(
                            final_path=final_path, manifest_path=manifest_path, progress_path=progress_path
                        )
                        if current_generation:
                            _tx_index_map_append_generation_ledger(
                                day, manifest_path, final_path, action=TX_INDEX_MAP_LEDGER_ACTION_REVOKE,
                                reason=f"startup_recovery_from_phase_{phase}",
                                revoked_generation_id=current_generation,
                            )
                        elif phase in {"LEDGER_COMMITTED", "FINAL_AUDIT_OK"}:
                            raise ControlledStopExit(
                                f"publication marker claims committed ledger state but no active generation exists day={day} phase={phase}",
                                exit_code=76,
                                payload={"day": day, "reason": "publication_ledger_state_missing", "phase": phase},
                            )
                    _tx_index_map_clear_publication_marker(day, expected_generation_id=marker_generation)
                    publication_marker = None
                    previous_generation_backup = None
                    _warn(f"TX_INDEX_MAP_ONLY recovered interrupted publication day={day} phase={phase} restored={int(recovered)}")

        force_rebuild = _env_bool("UTXO_TX_INDEX_MAP_FORCE_REBUILD", False)
        existing_report: Optional[Dict[str, Any]] = None
        active_parts = (final_path.exists(), manifest_path.exists(), progress_path.exists())
        if any(active_parts) and not all(active_parts):
            preexisting_generation_invalid = True
            _warn(f"TX_INDEX_MAP_ONLY incomplete active generation day={day} final/manifest/progress={active_parts}")
        if final_path.exists():
            existing_report = _audit_tx_index_map_day(
                raw_base,
                day,
                emit_success_event=not force_rebuild,
                emit_neutral_success_event=False,
            )
            previous_generation_restorable = existing_report.get("status") == "ok"
            preexisting_generation_invalid = preexisting_generation_invalid or (not previous_generation_restorable)
            if previous_generation_restorable and not force_rebuild:
                _log(f"TX_INDEX_MAP_ONLY reuse existing ok day={day} path={final_path}")
                build_success = True
                return existing_report
            if preexisting_generation_invalid:
                _warn(f"TX_INDEX_MAP_ONLY existing generation is NOT restorable day={day}: {existing_report.get('failed_checks')}")

        # Snapshot active artifacts for evidence. Restore is allowed only when the
        # existing published generation independently audited green.
        if final_path.exists() or manifest_path.exists() or progress_path.exists():
            previous_generation_backup = _snapshot_previous_generation(
                day_dir=day_dir,
                final_path=final_path,
                manifest_path=manifest_path,
                progress_path=progress_path,
                restorable=previous_generation_restorable,
                prebuild_audit=existing_report,
            )

        # Active publication remains untouched during the long build. New state
        # is isolated in a private build directory under the day lock.
        build_dir = _generation_stamp("build", day_dir)
        build_dir.mkdir(parents=True, exist_ok=False)
        _fsync_directory(day_dir)
        active_manifest_path = manifest_path
        active_progress_path = progress_path
        active_partial_path = partial_path
        manifest_path = build_dir / "manifest.json"
        progress_path = build_dir / "progress.json"
        partial_path = build_dir / "tx_index_map.partial.parquet"

        # Quarantine stale candidate files and abandoned build directories only;
        # never move the currently published manifest/progress during rebuild.
        stale_candidates = sorted(day_dir.glob("tx_index_map.candidate.*.parquet"))
        stale_build_dirs = sorted(p for p in day_dir.glob("build.*") if p != build_dir)
        stale_root_partials = [active_partial_path] if active_partial_path.exists() else []
        if stale_candidates or stale_build_dirs or stale_root_partials:
            quarantine_dir = _generation_stamp("quarantine.noresume", day_dir)
            quarantine_dir.mkdir(parents=True, exist_ok=False)
            moved = []
            for stale_src in (*stale_candidates, *stale_build_dirs, *stale_root_partials):
                if stale_src.exists():
                    dst = quarantine_dir / stale_src.name
                    os.replace(stale_src, dst)
                    moved.append(str(dst))
            _fsync_directory(day_dir)
            _fsync_directory(quarantine_dir)
            _emit_event("W12924", f"STALE_PROGRESS_QUARANTINED day={day} files={len(moved)}")

        con = duckdb.connect()
        try:
            _apply_duckdb_pragmas(con, phase="txid_map")
            raw_ordering_contract = _tx_index_map_raw_ordering_contract(con, files, day=day)
            if raw_ordering_contract.get("status") != "ok":
                raise RuntimeError(f"raw transaction ordering/source contract failed day={day}: {raw_ordering_contract}")
            blocks = _tx_index_map_raw_blocks(con, files, day=day)
            raw_tx_rows = int(sum(c for _bn, _bh, c in blocks))
        finally:
            con.close()

        block_hashes = [str(bh).lower() for _bn, bh, _cnt in blocks]
        if len(block_hashes) != len(set(block_hashes)):
            dupes = sorted({h for h in block_hashes if block_hashes.count(h) > 1})[:10]
            raise RuntimeError(f"duplicate raw block_hash entries in day={day}: {dupes}")

        raw_fingerprint = _tx_index_map_raw_fingerprint(files, blocks, raw_tx_rows)
        map_build_con = duckdb.connect()
        _apply_duckdb_pragmas(map_build_con, phase="txid_map")
        map_build_con.execute("""CREATE TEMP TABLE tx_index_map_build_rows(
          block_number BIGINT, block_hash VARCHAR, raw_hash VARCHAR, canonical_txid VARCHAR,
          canonical_tx_index BIGINT, source VARCHAR, raw_date DATE)""")
        completed_hashes = set()

        base_manifest = {
            "status": "building",
            "mode": MODE_TX_INDEX_MAP_ONLY,
            "pipeline_version": _pipeline_version(),
            "generation_id": generation_id,
            "created_at": _now_iso(),
            "day": day,
            "source": source,
            "map_semantics": "canonical_block_tx_order",
            "key": "block_hash,raw_hash",
            "map_contract_version": TX_INDEX_MAP_CONTRACT_VERSION_V2,
            "contract_locked": True,
            "join_key": "raw_hash",
            "canonical_identity": "canonical_txid",
            "tx_index_base": 0,
            "output_value_unit": _get_output_value_unit(),
            "canonical_txid_reconstruction_contract": _tx_index_map_identity_contract_for_day(day),
            "explicit_index_order_policy": raw_ordering_contract.get("explicit_index_order_policy"),
            "explicit_index_order_trust_status": raw_ordering_contract.get("explicit_index_order_trust_status"),
            "resume_supported": False,
            "restart_policy": "clean_rebuild_from_zero",
            "partial_reusable": False,
            "raw_base": raw_base,
            "raw_fingerprint": raw_fingerprint,
            "path": str(final_path),
            "partial_path": str(partial_path),
            "flush_every_blocks": int(flush_every),
            "write_partial_evidence": bool(write_partial_evidence),
            "utxo_db_modified": False,
            "apply_started": False,
            "utxo_valid_until": valid_until,
            "next_manual_start_date": day,
        }
        _save_json_atomic(manifest_path, base_manifest)

        total_blocks = len(blocks)
        last_flushed_completed = 0

        def flush_progress(
            status: str,
            *,
            last_ok_block_number: Optional[int] = None,
            last_ok_block_hash: Optional[str] = None,
            force_parquet: bool = False,
        ) -> None:
            if rows_written and (force_parquet or write_partial_evidence):
                _export_temp_table_to_parquet(map_build_con, "tx_index_map_build_rows", "block_number, canonical_tx_index", partial_path)
            progress = {
                "status": status,
                "day": day,
                "generation_id": generation_id,
                "source": source,
                "map_contract_version": TX_INDEX_MAP_CONTRACT_VERSION_V2,
                "explicit_index_order_policy": raw_ordering_contract.get("explicit_index_order_policy"),
                "explicit_index_order_trust_status": raw_ordering_contract.get("explicit_index_order_trust_status"),
                "completed_blocks": len(completed_hashes),
                "total_blocks": total_blocks,
                "completed_tx_rows": int(rows_written),
                "map_rows": int(rows_written),
                "raw_tx_rows": int(raw_tx_rows),
                "completed_block_hashes": sorted(completed_hashes),
                "last_ok_block_number": last_ok_block_number,
                "last_ok_block_hash": last_ok_block_hash,
                "raw_fingerprint": raw_fingerprint,
                "flush_every_blocks": int(flush_every),
                "resume_supported": False,
                "restart_policy": "clean_rebuild_from_zero",
                "partial_reusable": False,
                "updated_at": _now_iso(),
            }
            _save_json_atomic(progress_path, progress)

        for block_number, block_hash, raw_count in blocks:
            block_hash = str(block_hash).lower()
            if block_hash in completed_hashes:
                raise RuntimeError(f"duplicate block_hash encountered during build day={day} block={block_number} hash={block_hash}")
            try:
                txids = _fetch_tx_index_map_block_txids(block_hash)
                if len(txids) != int(raw_count):
                    failed_payload = dict(base_manifest)
                    failed_payload.update({
                        "status": "failed",
                        "reason": "canonical_block_tx_count_mismatch",
                        "failed_day": day,
                        "failed_block_number": block_number,
                        "failed_block_hash": block_hash,
                        "raw_block_tx_count": int(raw_count),
                        "canonical_block_tx_count": len(txids),
                        "completed_blocks": len(completed_hashes),
                        "total_blocks": total_blocks,
                        "resume_supported": False,
                        "restart_policy": "clean_rebuild_from_zero",
                        "partial_reusable": False,
                    })
                    _save_json_atomic(manifest_path, failed_payload)
                    flush_progress("failed")
                    raise ControlledStopExit(
                        f"tx_index_map canonical count mismatch day={day} block={block_number}",
                        exit_code=76,
                        payload=failed_payload,
                    )
                local_pairs = _tx_index_map_raw_identities_for_block(
                    files, block_number, block_hash, day=day
                )
                canonical_to_raw: Dict[str, str] = {}
                for raw_hash, canonical_txid in local_pairs:
                    if canonical_txid in canonical_to_raw:
                        raise RuntimeError(f"duplicate reconstructed canonical_txid block={block_number} txid={canonical_txid}")
                    canonical_to_raw[canonical_txid] = raw_hash
                external_order = [str(x).lower() for x in txids]
                external_set = set(external_order)
                local_set = set(canonical_to_raw)
                if len(external_order) != len(external_set):
                    raise RuntimeError(f"duplicate canonical txid returned by source block={block_number}")
                if local_set != external_set:
                    missing = sorted(external_set - local_set)[:10]
                    extra = sorted(local_set - external_set)[:10]
                    _emit_event("E12927", f"TX_INDEX_MAP_IDENTITY_MISMATCH day={day} block={block_number} missing={len(external_set-local_set)} extra={len(local_set-external_set)}")
                    raise RuntimeError(f"canonical identity mismatch block={block_number} missing_sample={missing} extra_sample={extra}")
                block_rows=[(int(block_number),block_hash,canonical_to_raw[canonical_txid],canonical_txid,int(idx),source,day) for idx,canonical_txid in enumerate(external_order)]
                if block_rows:
                    map_build_con.executemany("INSERT INTO tx_index_map_build_rows VALUES (?,?,?,?,?,?,?::DATE)",block_rows)
                    rows_written += len(block_rows)
                completed_hashes.add(block_hash)

                should_flush = (
                    flush_every <= 1
                    or (len(completed_hashes) - last_flushed_completed) >= flush_every
                    or len(completed_hashes) >= total_blocks
                )
                if should_flush:
                    status = "complete_pending_audit" if len(completed_hashes) >= total_blocks else "incomplete"
                    flush_progress(status, last_ok_block_number=block_number, last_ok_block_hash=block_hash)
                    last_flushed_completed = len(completed_hashes)
                    _log(
                        f"TX_INDEX_MAP_ONLY progress checkpoint day={day} completed_blocks={len(completed_hashes)}/{total_blocks} "
                        f"rows={rows_written}/{raw_tx_rows} partial_parquet_written={bool(write_partial_evidence)}"
                    )
                _log(f"TX_INDEX_MAP_ONLY progress day={day} block={block_number} {len(completed_hashes)}/{total_blocks} rows={rows_written}/{raw_tx_rows}")
            except ControlledStopExit:
                raise
            except Exception as e:
                incomplete = dict(base_manifest)
                incomplete.update({
                    "status": "incomplete",
                    "reason": ("controlled_stop" if "CONTROLLED_STOP" in str(e) else ("esplora_unavailable" if source == "esplora" else "canonical_source_unavailable")),
                    "error_type": type(e).__name__,
                    "error": str(e),
                    "failed_day": day,
                    "failed_block_number": block_number,
                    "failed_block_hash": block_hash,
                    "completed_blocks": len(completed_hashes),
                    "total_blocks": total_blocks,
                    "completed_tx_rows": rows_written,
                    "raw_tx_rows": raw_tx_rows,
                    "resume_supported": False,
                    "restart_policy": "clean_rebuild_from_zero",
                    "partial_reusable": False,
                    "updated_at": _now_iso(),
                })
                _save_json_atomic(manifest_path, incomplete)
                flush_progress("incomplete", last_ok_block_number=block_number if block_hash in completed_hashes else None, last_ok_block_hash=block_hash if block_hash in completed_hashes else None)
                raise ControlledStopExit(
                    f"TX_INDEX_MAP_ONLY controlled stop day={day} block={block_number}: {type(e).__name__}: {e}",
                    exit_code=75,
                    payload=incomplete,
                )

        # Write one complete candidate only after all external lookups succeeded.
        flush_progress("complete_pending_audit", last_ok_block_number=blocks[-1][0] if blocks else None, last_ok_block_hash=blocks[-1][1] if blocks else None, force_parquet=True)
        canonical_order_sha256 = _tx_index_map_order_digest_table(map_build_con,"tx_index_map_build_rows")
        audit_pre = {
            **base_manifest,
            "status": "audit_pending",
            "canonical_order_digest_version": TX_INDEX_MAP_ORDER_DIGEST_VERSION,
            "canonical_order_sha256": canonical_order_sha256,
            "completed_blocks": len(completed_hashes),
            "total_blocks": total_blocks,
            "map_rows": rows_written,
            "raw_tx_rows": raw_tx_rows,
            "completed_tx_rows": rows_written,
            "updated_at": _now_iso(),
        }
        _save_json_atomic(manifest_path, audit_pre)
        candidate_path = build_dir / f"tx_index_map.candidate.{generation_id}.parquet"
        candidate_path.unlink(missing_ok=True)
        os.replace(partial_path, candidate_path)
        audit_pre["final_map_parquet_sha256"] = _file_sha256_streaming(candidate_path)
        _save_json_atomic(manifest_path, audit_pre)
        report = _audit_tx_index_map_day(raw_base, day, require_manifest_ok=False, map_path=candidate_path, manifest_override=audit_pre, emit_success_event=False)
        if report.get("status") != "ok":
            failed = dict(base_manifest)
            failed.update({
                "status": "failed",
                "reason": "tx_index_map_audit_failed_after_build",
                "audit_report": report,
                "completed_blocks": len(completed_hashes),
                "total_blocks": total_blocks,
                "map_rows": rows_written,
                "raw_tx_rows": raw_tx_rows,
                "failed_candidate_path": str(candidate_path),
                "resume_supported": False,
                "restart_policy": "clean_rebuild_from_zero",
                "partial_reusable": False,
                "updated_at": _now_iso(),
            })
            _save_json_atomic(manifest_path, failed)
            raise ControlledStopExit(f"tx_index_map audit failed day={day}", exit_code=76, payload=failed)

        ok_manifest = dict(base_manifest)
        ok_manifest.update({
            "status": "ok",
            "completed_blocks": len(completed_hashes),
            "total_blocks": total_blocks,
            "map_rows": rows_written,
            "raw_tx_rows": raw_tx_rows,
            "completed_tx_rows": rows_written,
            "audit_report": report,
            "canonical_order_digest_version": TX_INDEX_MAP_ORDER_DIGEST_VERSION,
            "canonical_order_sha256": canonical_order_sha256,
            "final_map_parquet_sha256": audit_pre["final_map_parquet_sha256"],
            "updated_at": _now_iso(),
        })
        complete_progress = {
            "status": "complete",
            "day": day,
            "generation_id": generation_id,
            "source": source,
            "map_contract_version": TX_INDEX_MAP_CONTRACT_VERSION_V2,
            "explicit_index_order_policy": raw_ordering_contract.get("explicit_index_order_policy"),
            "explicit_index_order_trust_status": raw_ordering_contract.get("explicit_index_order_trust_status"),
            "completed_blocks": len(completed_hashes),
            "total_blocks": total_blocks,
            "completed_tx_rows": int(rows_written),
            "map_rows": int(rows_written),
            "raw_tx_rows": int(raw_tx_rows),
            "raw_fingerprint": raw_fingerprint,
            "flush_every_blocks": int(flush_every),
            "resume_supported": False,
            "restart_policy": "clean_rebuild_from_zero",
            "partial_reusable": False,
            "updated_at": _now_iso(),
        }
        _save_json_atomic(manifest_path, ok_manifest)
        _save_json_atomic(progress_path, complete_progress)
        # Durable publication transaction. A crash leaves an actionable marker
        # that the next run resolves before any reuse/build decision.
        previous_manifest_for_marker = _read_json_file(active_manifest_path) if active_manifest_path.is_file() else None
        publication_marker = _tx_index_map_save_publication_marker(day, {
            "phase": "PREPARED",
            "generation_id": generation_id,
            "previous_generation_id": (previous_manifest_for_marker or {}).get("generation_id"),
            "previous_generation_backup": str(previous_generation_backup) if previous_generation_backup else None,
            "previous_generation_restorable": bool(previous_generation_restorable),
            "final_path": str(final_path.expanduser().resolve(strict=False)),
            "manifest_path": str(active_manifest_path.expanduser().resolve(strict=False)),
            "progress_path": str(active_progress_path.expanduser().resolve(strict=False)),
            "candidate_parquet_sha256": audit_pre["final_map_parquet_sha256"],
        })
        # Publish data, then progress, then manifest as the commit marker. Each
        # replace is directory-fsynced for crash durability.
        _atomic_publish_copy(candidate_path, final_path)
        new_final_promoted = True
        _atomic_publish_copy(progress_path, active_progress_path)
        _atomic_publish_copy(manifest_path, active_manifest_path)
        _tx_index_map_save_publication_marker(day, {
            "phase": "FILES_PUBLISHED", "generation_id": generation_id,
            "previous_generation_backup": str(previous_generation_backup) if previous_generation_backup else None,
        })
        ledger_record = _tx_index_map_append_generation_ledger(
            day, active_manifest_path, final_path, action=TX_INDEX_MAP_LEDGER_ACTION_PUBLISH
        )
        _tx_index_map_save_publication_marker(day, {
            "phase": "LEDGER_COMMITTED", "generation_id": generation_id,
            "previous_generation_backup": str(previous_generation_backup) if previous_generation_backup else None,
            "ledger_record_sha256": ledger_record.get("record_sha256"),
        })
        _log(f"TX_INDEX_MAP_ONLY generation ledger committed day={day} record_sha256={ledger_record.get('record_sha256')}")
        final_report = _audit_tx_index_map_day(
            raw_base,
            day,
            emit_success_event=False,
            emit_neutral_success_event=False,
            allow_publication_marker=True,
        )
        if final_report.get("status") != "ok":
            raise ControlledStopExit(
                f"tx_index_map final audit failed day={day}",
                exit_code=76,
                payload={"day": day, "status": "failed", "reason": "tx_index_map_final_audit_failed_after_promotion", "audit_report": final_report},
            )

        _tx_index_map_save_publication_marker(day, {
            "phase": "FINAL_AUDIT_OK", "generation_id": generation_id,
            "previous_generation_backup": str(previous_generation_backup) if previous_generation_backup else None,
            "ledger_record_sha256": ledger_record.get("record_sha256"),
        })
        _tx_index_map_clear_publication_marker(day, expected_generation_id=generation_id)
        publication_marker = None
        _emit_event("S12921", f"TX_INDEX_MAP_DUAL_ID_ACCEPTED day={day}")
        build_success = True
        if build_dir is not None and build_dir.exists():
            try:
                shutil.rmtree(build_dir)
                _fsync_directory(day_dir)
                build_dir = None
            except Exception as cleanup_exc:
                _warn(f"TX_INDEX_MAP_ONLY build-dir cleanup failed day={day} path={build_dir}: {type(cleanup_exc).__name__}: {cleanup_exc}")
        if previous_generation_backup is not None:
            try:
                shutil.rmtree(previous_generation_backup)
                previous_generation_backup = None
            except Exception as cleanup_exc:
                _warn(f"TX_INDEX_MAP_ONLY previous-generation backup cleanup failed day={day} path={previous_generation_backup}: {type(cleanup_exc).__name__}: {cleanup_exc}")
        _log(f"TX_INDEX_MAP_ONLY complete day={day} path={final_path} rows={rows_written} blocks={len(completed_hashes)}")
        return final_report

    except BaseException as exc:
        # Evidence preservation and rollback are independent. A full disk or
        # quarantine failure must never prevent restoration/fail-closed removal.
        evidence: Optional[Path] = None
        evidence_error: Optional[BaseException] = None
        restore_error: Optional[BaseException] = None
        restored = False
        try:
            if 'day_dir' in locals():
                evidence = _preserve_failed_generation(
                    day_dir=day_dir,
                    final_path=final_path,
                    manifest_path=manifest_path,
                    progress_path=progress_path,
                    partial_path=partial_path,
                    candidate=candidate_path,
                    error=exc,
                )
        except BaseException as preserve_exc:
            evidence_error = preserve_exc
            _warn(f"TX_INDEX_MAP_ONLY failed-generation evidence error day={day}: {type(preserve_exc).__name__}: {preserve_exc}")
        try:
            if 'day_dir' in locals():
                restored = _restore_previous_generation(
                    final_path=final_path,
                    manifest_path=active_manifest_path if 'active_manifest_path' in locals() else manifest_path,
                    progress_path=active_progress_path if 'active_progress_path' in locals() else progress_path,
                )
                if not restored and (new_final_promoted or preexisting_generation_invalid):
                    _remove_failed_published_generation(
                        final_path=final_path,
                        manifest_path=active_manifest_path if 'active_manifest_path' in locals() else manifest_path,
                        progress_path=active_progress_path if 'active_progress_path' in locals() else progress_path,
                    )
                    _fsync_directory(final_path.parent)
        except BaseException as restore_exc:
            restore_error = restore_exc
            _warn(f"TX_INDEX_MAP_ONLY generation rollback failure day={day}: {type(restore_exc).__name__}: {restore_exc}")
        # Best-effort update after restore/removal; never masks the original error.
        if evidence is not None:
            try:
                failure_report_path = evidence / "failure_report.json"
                failure_report = _read_json_file(failure_report_path) or {}
                failure_report.update({
                    "previous_generation_restored": bool(restored),
                    "failed_publish_removed": bool((new_final_promoted or preexisting_generation_invalid) and not restored and restore_error is None),
                    "evidence_error": str(evidence_error) if evidence_error else None,
                    "restore_error": str(restore_error) if restore_error else None,
                    "updated_at": _now_iso(),
                })
                _save_json_atomic(failure_report_path, failure_report)
            except Exception as report_exc:
                _warn(f"TX_INDEX_MAP_ONLY failure report update failed day={day}: {type(report_exc).__name__}: {report_exc}")
        if restored:
            _warn(f"TX_INDEX_MAP_ONLY restored previous complete generation day={day} after failure; evidence={evidence}")
        if restore_error is None and 'active_manifest_path' in locals() and 'final_path' in locals():
            try:
                ledger_updated = False
                state = _tx_index_map_read_generation_ledger() if _tx_index_map_generation_ledger_path().exists() else {
                    "status": "ok", "effective_by_day": {}, "published_by_day": {}, "failed_checks": []
                }
                if state.get("status") != "ok":
                    raise RuntimeError(f"generation ledger invalid during rollback: {state.get('failed_checks')}")
                current = (state.get("effective_by_day") or {}).get(str(day))
                current_generation = str((current or {}).get("generation_id") or "") or None
                if restored:
                    restored_manifest = _read_json_file(active_manifest_path) or {}
                    restored_generation = str(restored_manifest.get("generation_id") or "")
                    if current_generation and current_generation != restored_generation:
                        _tx_index_map_append_generation_ledger(
                            day, active_manifest_path, final_path,
                            action=TX_INDEX_MAP_LEDGER_ACTION_ROLLBACK,
                            reason=f"automatic_rollback_after_{type(exc).__name__}",
                            from_generation_id=current_generation,
                        )
                        ledger_updated = True
                elif (new_final_promoted or preexisting_generation_invalid) and current_generation:
                    _tx_index_map_append_generation_ledger(
                        day, active_manifest_path, final_path,
                        action=TX_INDEX_MAP_LEDGER_ACTION_REVOKE,
                        reason=f"automatic_revoke_after_{type(exc).__name__}",
                        revoked_generation_id=current_generation,
                    )
                    ledger_updated = True
                if publication_marker is not None and publication_marker.exists():
                    _tx_index_map_clear_publication_marker(day, expected_generation_id=generation_id)
                    publication_marker = None
            except BaseException as ledger_exc:
                rollback_ledger_error = ledger_exc
                _warn(f"TX_INDEX_MAP_ONLY rollback ledger update failed day={day}: {type(ledger_exc).__name__}: {ledger_exc}")
        if restore_error is not None:
            raise RuntimeError(
                f"TX_INDEX_MAP_ONLY original failure plus rollback failure day={day}: "
                f"original={type(exc).__name__}:{exc}; rollback={type(restore_error).__name__}:{restore_error}"
            ) from exc
        if rollback_ledger_error is not None:
            raise RuntimeError(
                f"TX_INDEX_MAP_ONLY original failure plus rollback-ledger failure day={day}: "
                f"original={type(exc).__name__}:{exc}; ledger={type(rollback_ledger_error).__name__}:{rollback_ledger_error}"
            ) from exc
        raise

    finally:
        if build_success and previous_generation_backup is not None:
            try:
                shutil.rmtree(previous_generation_backup)
            except Exception as cleanup_exc:
                _warn(f"TX_INDEX_MAP_ONLY previous-generation backup cleanup failed day={day} path={previous_generation_backup}: {type(cleanup_exc).__name__}: {cleanup_exc}")
        if map_build_con is not None:
            try:
                map_build_con.close()
            except Exception as close_exc:
                _warn(f"TX_INDEX_MAP_ONLY map-build DuckDB close failed day={day}: {type(close_exc).__name__}: {close_exc}")
        active_exc = sys.exc_info()[1]
        try:
            _tx_index_map_release_day_lock(lock_dir)
        except BaseException as release_exc:
            if active_exc is not None:
                raise RuntimeError(
                    f"TX_INDEX_MAP_ONLY original failure plus day-lock release failure day={day}: "
                    f"original={type(active_exc).__name__}:{active_exc}; "
                    f"release={type(release_exc).__name__}:{release_exc}"
                ) from active_exc
            raise

def _created_stage_raw_filter_sql(alias: str = "t") -> str:
    """Return the raw-output filter used by created stage and semantic sampling."""
    a = alias
    return (
        f"{a}.block_number::BIGINT <> 0 "
        "AND lower(" + a + ".hash::VARCHAR) <> '4a5e1e4baab89f3a32518a88c31bc87f618f76673e2cc77ab2127b7afdeda33b'"
    )


def _sample_raw_created_rows(con: duckdb.DuckDBPyConnection, parquet_path: str, limit_rows: int, day: Optional[str] = None) -> List[Tuple[str, int, float, str]]:
    # Keep semantic-unit sampling aligned with the canonical-clean created stage.
    # R11: when the validated block filter plan is present, exclude exactly the
    # discarded (height, hash) pairs so the fatal value-unit audit does not turn
    # a correctly filtered competing branch into a false failure.
    raw_filter = _created_stage_raw_filter_sql("t")
    plan_exists = bool(con.execute(
        "SELECT COUNT(*) FROM duckdb_tables() WHERE table_name='dup_guard_block_filter_plan'"
    ).fetchone()[0])
    plan_join = (
        "LEFT JOIN dup_guard_block_filter_plan p "
        "ON p.block_number=TRY_CAST(t.block_number AS BIGINT) "
        "AND p.discarded_block_hash=lower(t.block_hash::VARCHAR)"
        if plan_exists else ""
    )
    plan_filter = " AND p.block_number IS NULL" if plan_exists else ""
    if day and _canonical_enabled_for_day(day):
        _assert_txid_map_exists(day)
        rows = con.execute(
            f"""
            SELECT
              m.canonical_txid AS txid,
              out.index::BIGINT AS vout,
              CAST(out.value AS DOUBLE) AS raw_value,
              typeof(out.value) AS raw_type
            FROM read_parquet(?) t
            JOIN read_parquet({_quote_sql_string(str(_txid_map_path(day)))}) AS m
              ON m.raw_hash = lower(t.hash::VARCHAR)
            {plan_join}
            CROSS JOIN UNNEST(t.outputs) AS o(out)
            WHERE {raw_filter}{plan_filter}
            LIMIT ?;
            """,
            [parquet_path, limit_rows],
        ).fetchall()
    else:
        rows = con.execute(
            f"""
            SELECT
              lower(t.hash::VARCHAR) AS txid,
              out.index::BIGINT AS vout,
              CAST(out.value AS DOUBLE) AS raw_value,
              typeof(out.value) AS raw_type
            FROM read_parquet(?) t
            {plan_join}
            CROSS JOIN UNNEST(t.outputs) AS o(out)
            WHERE {raw_filter}{plan_filter}
            LIMIT ?;
            """,
            [parquet_path, limit_rows],
        ).fetchall()
    out_rows: List[Tuple[str, int, float, str]] = []
    for txid, vout, v, t in rows:
        out_rows.append((str(txid), int(vout), float(v) if v is not None else float("nan"), str(t)))
    return out_rows



def _semantic_discarded_only_empty_sample_proof(
    con: duckdb.DuckDBPyConnection,
    files: Sequence[str],
) -> Dict[str, Any]:
    """Prove an empty semantic sample is caused only by validated block discards."""
    report: Dict[str, Any] = {
        "proven": False,
        "plan_rows": 0,
        "raw_eligible_outputs_before_filter": 0,
        "raw_eligible_outputs_after_filter": 0,
        "created_stage_rows": 0,
        "remaining_discarded_block_meta_rows": 0,
        "errors": [],
    }
    try:
        plan_exists = bool(con.execute(
            "SELECT COUNT(*) FROM duckdb_tables() WHERE table_name='dup_guard_block_filter_plan'"
        ).fetchone()[0])
        if not plan_exists:
            report["errors"].append("validated_block_filter_plan_missing")
            return report
        plan_rows = int(con.execute("SELECT COUNT(*) FROM dup_guard_block_filter_plan").fetchone()[0] or 0)
        report["plan_rows"] = plan_rows
        if plan_rows <= 0:
            report["errors"].append("validated_block_filter_plan_empty")
            return report

        raw_filter = _created_stage_raw_filter_sql("t")
        before = 0
        after = 0
        for fp in files:
            cols = {str(r[0]) for r in con.execute(
                "SELECT column_name FROM (DESCRIBE SELECT * FROM read_parquet(?))",
                [str(fp)],
            ).fetchall()}
            if "outputs" not in cols:
                continue
            row = con.execute(
                f"""
                SELECT
                  COUNT(*) AS eligible_before,
                  COUNT(*) FILTER (WHERE p.block_number IS NULL) AS eligible_after
                FROM read_parquet(?) AS t
                CROSS JOIN UNNEST(t.outputs) AS o(out)
                LEFT JOIN dup_guard_block_filter_plan p
                  ON p.block_number = TRY_CAST(t.block_number AS BIGINT)
                 AND p.discarded_block_hash = lower(t.block_hash::VARCHAR)
                WHERE {raw_filter}
                """,
                [str(fp)],
            ).fetchone()
            before += int(row[0] or 0)
            after += int(row[1] or 0)
        created_stage_rows = int(con.execute("SELECT COUNT(*) FROM created_stage").fetchone()[0] or 0)
        remaining_block_meta = int(con.execute(
            """
            SELECT COUNT(*)
            FROM block_meta_stage_raw m
            JOIN dup_guard_block_filter_plan p
              ON m.block_number = p.block_number
             AND lower(m.block_hash) = p.discarded_block_hash
            """
        ).fetchone()[0] or 0)
        report.update({
            "raw_eligible_outputs_before_filter": before,
            "raw_eligible_outputs_after_filter": after,
            "created_stage_rows": created_stage_rows,
            "remaining_discarded_block_meta_rows": remaining_block_meta,
        })
        if before <= 0:
            report["errors"].append("no_eligible_raw_outputs_before_filter")
        if after != 0:
            report["errors"].append(f"eligible_outputs_survived_filter:{after}")
        if created_stage_rows != 0:
            report["errors"].append(f"canonical_clean_created_stage_not_empty:{created_stage_rows}")
        if remaining_block_meta != 0:
            report["errors"].append(f"discarded_block_meta_rows_remain:{remaining_block_meta}")
        report["proven"] = not report["errors"]
        return report
    except Exception as exc:
        report["errors"].append(f"proof_error:{type(exc).__name__}:{exc}")
        return report

def _semantic_unit_audit_day(con: duckdb.DuckDBPyConnection, day: str, files: Sequence[str]) -> Dict[str, Any]:
    sample_limit = _semantic_sample_limit()
    output_value_unit = _get_output_value_unit()
    address_mode = _get_address_mode()
    sample_rows: List[Tuple[str, int, float, str]] = []
    raw_types: List[str] = []
    nonfinite_count = 0
    fractional_count = 0
    negative_count = 0
    raw_min: Optional[float] = None
    raw_max: Optional[float] = None

    for fp in files:
        remaining = sample_limit - len(sample_rows)
        if remaining <= 0:
            break
        rows = _sample_raw_created_rows(con, fp, remaining, day)
        for txid, vout, raw_value, raw_type in rows:
            sample_rows.append((txid, vout, raw_value, raw_type))
            raw_types.append(raw_type)
            if not (raw_value == raw_value) or raw_value in {float('inf'), float('-inf')}:
                nonfinite_count += 1
                continue
            if raw_value < 0:
                negative_count += 1
            if raw_min is None or raw_value < raw_min:
                raw_min = raw_value
            if raw_max is None or raw_value > raw_max:
                raw_max = raw_value
            if abs(raw_value - round(raw_value)) > 1e-9:
                fractional_count += 1

    unique_raw_types = sorted(set(raw_types))
    if not sample_rows and str(day) == "2009-01-03":
        return {
            "status": "ok",
            "failed_checks": [],
            "sample_size": 0,
            "output_value_unit": output_value_unit,
            "address_mode": address_mode,
            "expected_ratio_raw_over_value_btc": _unit_expected_ratio(output_value_unit),
            "expected_bucket": "same_unit" if output_value_unit == "btc" else "scaled_1e8",
            "raw_types": unique_raw_types,
            "fractional_raw_values": fractional_count,
            "negative_raw_values": negative_count,
            "nonfinite_raw_values": nonfinite_count,
            "raw_value_min": raw_min,
            "raw_value_max": raw_max,
            "missing_stage_rows": 0,
            "ratio_buckets": {"same_unit": 0, "scaled_1e8": 0, "other": 0, "missing": 0, "zero": 0},
            "skipped_reason": "GENESIS_UNSPENDABLE_ONLY",
        }

    discarded_only_proof: Optional[Dict[str, Any]] = None
    if not sample_rows:
        discarded_only_proof = _semantic_discarded_only_empty_sample_proof(con, files)
        if discarded_only_proof.get("proven"):
            return {
                "status": "ok",
                "failed_checks": [],
                "sample_size": 0,
                "output_value_unit": output_value_unit,
                "address_mode": address_mode,
                "expected_ratio_raw_over_value_btc": _unit_expected_ratio(output_value_unit),
                "expected_bucket": "same_unit" if output_value_unit == "btc" else "scaled_1e8",
                "raw_types": unique_raw_types,
                "fractional_raw_values": fractional_count,
                "negative_raw_values": negative_count,
                "nonfinite_raw_values": nonfinite_count,
                "raw_value_min": raw_min,
                "raw_value_max": raw_max,
                "missing_stage_rows": 0,
                "ratio_buckets": {"same_unit": 0, "scaled_1e8": 0, "other": 0, "missing": 0, "zero": 0},
                "skipped_reason": "VALIDATED_DISCARDED_BLOCKS_ONLY",
                "discarded_only_proof": discarded_only_proof,
            }

    failed_checks: List[str] = []
    if not sample_rows:
        failed_checks.append("semantic_sample_empty")
    if nonfinite_count > 0:
        failed_checks.append("semantic_nonfinite_raw_values")
    if negative_count > 0:
        failed_checks.append("semantic_negative_raw_values")
    if len(unique_raw_types) > 1:
        failed_checks.append("semantic_mixed_raw_types")
    if output_value_unit == "sats" and fractional_count > 0:
        failed_checks.append("semantic_fractional_raw_values_in_sats_mode")

    con.execute("DROP TABLE IF EXISTS semantic_unit_sample")
    con.execute(
        """
        CREATE TEMP TABLE semantic_unit_sample(
          txid VARCHAR,
          vout BIGINT,
          raw_value DOUBLE,
          raw_type VARCHAR
        );
        """
    )
    if sample_rows:
        con.executemany(
            "INSERT INTO semantic_unit_sample(txid, vout, raw_value, raw_type) VALUES (?, ?, ?, ?)",
            sample_rows,
        )

    joined = con.execute(
        """
        SELECT
          s.raw_value,
          s.raw_type,
          c.value_btc
        FROM semantic_unit_sample s
        LEFT JOIN created_stage c
          ON c.txid = s.txid AND c.vout = s.vout
        """
    ).fetchall()

    ratio_buckets = {
        "same_unit": 0,
        "scaled_1e8": 0,
        "other": 0,
        "missing": 0,
        "zero": 0,
    }
    missing_stage_rows = 0
    for raw_value, raw_type, value_btc in joined:
        bucket = _bucketize_raw_over_value_btc(float(raw_value), None if value_btc is None else float(value_btc))
        ratio_buckets[bucket] = ratio_buckets.get(bucket, 0) + 1
        if bucket == "missing":
            missing_stage_rows += 1

    if missing_stage_rows > 0:
        failed_checks.append("semantic_missing_created_stage_rows")

    expected_bucket = "same_unit" if output_value_unit == "btc" else "scaled_1e8"
    wrong_bucket_count = 0
    for bucket_name, bucket_count in ratio_buckets.items():
        if bucket_name in {expected_bucket, "zero"}:
            continue
        wrong_bucket_count += int(bucket_count)
    if ratio_buckets.get(expected_bucket, 0) == 0 and sample_rows:
        failed_checks.append("semantic_expected_ratio_bucket_missing")
    if wrong_bucket_count > 0:
        failed_checks.append("semantic_ratio_bucket_mismatch")

    status = "ok" if not failed_checks else "fail"
    expected_ratio = _unit_expected_ratio(output_value_unit)
    return {
        "status": status,
        "failed_checks": failed_checks,
        "sample_size": len(sample_rows),
        "output_value_unit": output_value_unit,
        "address_mode": address_mode,
        "expected_ratio_raw_over_value_btc": expected_ratio,
        "expected_bucket": expected_bucket,
        "raw_types": unique_raw_types,
        "fractional_raw_values": fractional_count,
        "negative_raw_values": negative_count,
        "nonfinite_raw_values": nonfinite_count,
        "raw_value_min": raw_min,
        "raw_value_max": raw_max,
        "missing_stage_rows": missing_stage_rows,
        "ratio_buckets": ratio_buckets,
    }


def _validate_stage_tables(con: duckdb.DuckDBPyConnection, day: str) -> Dict[str, Any]:
    day_sql=f"{_quote_sql_string(day)}::DATE"; failed_checks=[]
    created_rows=int(con.execute("SELECT COUNT(*) FROM created_stage").fetchone()[0]); spends_rows=int(con.execute("SELECT COUNT(*) FROM spends_stage").fetchone()[0])
    created_dup=int(con.execute(_dup_count_sql("created_stage","txid","vout")).fetchone()[0]); spends_dup=int(con.execute(_dup_count_sql("spends_stage","prev_txid","prev_vout")).fetchone()[0])
    created_null_keys=int(con.execute("SELECT COUNT(*) FROM created_stage WHERE txid IS NULL OR vout IS NULL").fetchone()[0]); spends_null_keys=int(con.execute("SELECT COUNT(*) FROM spends_stage WHERE prev_txid IS NULL OR prev_vout IS NULL").fetchone()[0])
    created_date_mismatch=int(con.execute(f"SELECT COUNT(*) FROM created_stage WHERE created_date <> {day_sql}").fetchone()[0]); spends_date_mismatch=int(con.execute(f"SELECT COUNT(*) FROM spends_stage WHERE spent_date <> {day_sql}").fetchone()[0])
    created_raw_partition_mismatch=int(con.execute(f"SELECT COUNT(*) FROM created_stage WHERE raw_partition_date <> {day_sql}").fetchone()[0]); spends_raw_partition_mismatch=int(con.execute(f"SELECT COUNT(*) FROM spends_stage WHERE raw_partition_date <> {day_sql}").fetchone()[0])
    created_missing_causal=int(con.execute("SELECT COUNT(*) FROM created_stage WHERE block_number IS NULL OR block_hash IS NULL OR tx_index IS NULL").fetchone()[0]); spends_missing_causal=int(con.execute("SELECT COUNT(*) FROM spends_stage WHERE block_number IS NULL OR block_hash IS NULL OR tx_index IS NULL").fetchone()[0])
    created_negative_values=int(con.execute("SELECT COUNT(*) FROM created_stage WHERE value_btc < 0").fetchone()[0]); created_sum_sats=int(con.execute("SELECT COALESCE(CAST(ROUND(SUM(value_btc)*100000000.0) AS BIGINT),0) FROM created_stage").fetchone()[0])
    causal=con.execute("""WITH tx AS (SELECT DISTINCT block_number,lower(block_hash) block_hash,tx_index,txid FROM created_stage)
      SELECT
       (SELECT COUNT(*) FROM tx WHERE block_number<0 OR tx_index<0),
       (SELECT COUNT(*) FROM (SELECT block_number,block_hash,tx_index FROM tx GROUP BY 1,2,3 HAVING COUNT(DISTINCT txid)>1) q),
       (SELECT COUNT(*) FROM (SELECT block_number,block_hash,txid FROM tx GROUP BY 1,2,3 HAVING COUNT(DISTINCT tx_index)>1) q),
       (SELECT COUNT(*) FROM (SELECT block_number,block_hash FROM tx GROUP BY 1,2 HAVING MIN(tx_index)<>0 OR MAX(tx_index)+1<>COUNT(*) OR COUNT(DISTINCT tx_index)<>COUNT(*)) q),
       (SELECT COUNT(*) FROM (SELECT block_hash FROM tx GROUP BY 1 HAVING COUNT(DISTINCT block_number)>1) q)""").fetchone()
    causal_keys=("created_negative_causal_rows","created_tx_index_conflict_positions","created_txid_multi_index_rows","created_dense_bad_blocks","created_block_hash_multi_height")
    causal_stats={k:int(v or 0) for k,v in zip(causal_keys,causal)}
    checks=((created_dup,"created_stage_duplicates"),(spends_dup,"spends_stage_duplicates"),(created_null_keys,"created_stage_null_keys"),(spends_null_keys,"spends_stage_null_keys"),(created_missing_causal,"created_stage_missing_causal_fields"),(spends_missing_causal,"spends_stage_missing_causal_fields"),(created_negative_values,"created_stage_negative_value"))
    for value,name in checks:
        if value>0: failed_checks.append(name)
    for key,value in causal_stats.items():
        if value>0: failed_checks.append(key)
    return {"status":"fail" if failed_checks else "ok","failed_checks":failed_checks,"created_rows":created_rows,"spends_rows":spends_rows,"created_dup_after":created_dup,"spends_dup_after":spends_dup,"created_null_keys":created_null_keys,"spends_null_keys":spends_null_keys,"created_date_mismatch":created_date_mismatch,"spends_date_mismatch":spends_date_mismatch,"created_raw_partition_mismatch":created_raw_partition_mismatch,"spends_raw_partition_mismatch":spends_raw_partition_mismatch,"created_missing_causal":created_missing_causal,"spends_missing_causal":spends_missing_causal,"created_negative_values":created_negative_values,"created_sum_sats":created_sum_sats,**causal_stats}




def _build_day_stage(raw_base: str, day: str, mode: str, semantic_stop_on_fail: bool) -> Dict[str, Any]:
    t0 = _tic()
    files = _day_parquet_files(raw_base, day)
    if not files:
        raise FileNotFoundError(f"No parquet files found for day={day}")
    txid_map_preflight = None
    if _canonical_enabled_for_day(day):
        txid_map_preflight = _assert_txid_map_usable(raw_base, day)

    tx_index_map_stage_lock: Optional[Path] = None
    con = duckdb.connect()
    try:
        _apply_duckdb_pragmas(con, phase="stage")
        _create_stage_tables(con)

        raw_file_infos: List[Dict[str, Any]] = []
        total_tx_rows = 0
        created_dup_before = 0
        spends_dup_before = 0

        inspected_files: List[Tuple[str, ParquetFeatures, int, int, bool, str, Dict[str, Any], Optional[Path]]] = []
        pre_inspected_files: List[Tuple[str, ParquetFeatures, int, int, Dict[str, Any]]] = []
        for fp in files:
            feats = _inspect_parquet_features(fp)
            tx_rows = _count_tx_rows(con, fp)
            tx_index_null_rows = _tx_index_null_rows(con, fp) if feats.has_tx_index else int(tx_rows)
            tx_index_quality = _tx_index_quality_from_counts(
                path=fp, has_tx_index=feats.has_tx_index, tx_rows=tx_rows, null_rows=tx_index_null_rows
            )
            pre_inspected_files.append((fp, feats, tx_rows, tx_index_null_rows, tx_index_quality))

        day_has_partial_index = any(q.get("mode") == "partial_index_null" for _fp, _feats, _tx_rows, _null_rows, q in pre_inspected_files)

        # fix16-r4/r9: scan-order fallback is allowed only for narrow smoke-safe
        # cases.  Any partial NULL index, all-NULL multi-transaction block, missing
        # top-level index multi-transaction block, or missing-index multi-file
        # fallback risk requires the canonical tx_index_map for the whole day.
        day_all_null_multi_tx_files: List[Dict[str, Any]] = []
        day_all_null_multi_file_files: List[Dict[str, Any]] = []
        day_missing_index_multi_tx_files: List[Dict[str, Any]] = []
        day_missing_index_multi_file_files: List[Dict[str, Any]] = []
        for fp0, _feats0, _tx_rows0, _null_rows0, q0 in pre_inspected_files:
            if q0.get("mode") not in {"all_index_null", "missing_top_level_index"}:
                continue
            max_txs_per_block = int(con.execute(
                """
                SELECT COALESCE(MAX(cnt), 0)
                FROM (
                  SELECT block_number, lower(block_hash::VARCHAR) AS block_hash, COUNT(*) AS cnt
                  FROM read_parquet(?)
                  WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
                  GROUP BY 1, 2
                ) g
                """,
                [fp0],
            ).fetchone()[0] or 0)
            q0["max_txs_per_block"] = int(max_txs_per_block)
            if q0.get("mode") == "all_index_null" and max_txs_per_block > 1:
                day_all_null_multi_tx_files.append({"path": fp0, "max_txs_per_block": int(max_txs_per_block)})
            if q0.get("mode") == "all_index_null" and len(files) > 1:
                day_all_null_multi_file_files.append({"path": fp0, "files_in_day": len(files), "max_txs_per_block": int(max_txs_per_block)})
            if q0.get("mode") == "missing_top_level_index" and max_txs_per_block > 1:
                day_missing_index_multi_tx_files.append({"path": fp0, "max_txs_per_block": int(max_txs_per_block)})
            if q0.get("mode") == "missing_top_level_index" and len(files) > 1:
                day_missing_index_multi_file_files.append({"path": fp0, "files_in_day": len(files), "max_txs_per_block": int(max_txs_per_block)})

        day_ordering_contract = _tx_index_map_raw_ordering_contract(con, files, day=day)
        if day_ordering_contract.get("status") != "ok":
            raise RuntimeError(f"raw transaction ordering/source contract failed day={day}: {day_ordering_contract}")
        day_needs_canonical_tx_index_map = bool(day_ordering_contract.get("required"))
        day_tx_index_map_path: Optional[Path] = None
        day_tx_index_map_report: Optional[Dict[str, Any]] = None
        if day_needs_canonical_tx_index_map:
            # fix16-r3/r4 day-level rule: a day with any partial NULL tx index, or
            # any all-NULL multi-tx block, must use the canonical map for every file
            # in that day. This avoids mixing raw top-level indexes, scan-order
            # fallback, and canonical-map indexes across files in one day.
            try:
                tx_index_map_stage_lock = _tx_index_map_acquire_day_lock(day)
            except RuntimeError as e:
                _tx_index_map_required_stop(
                    day,
                    "tx_index_map_locked_or_being_built",
                    report={"error_type": type(e).__name__, "error": str(e)},
                )
            day_tx_index_map_report = _assert_tx_index_map_usable(raw_base, day)
            day_tx_index_map_path = _tx_index_map_path(day)
            _log(
                f"TX_INDEX_MAP_STAGE day={day} day_requires_canonical_map=1 "
                f"partial_index={int(day_has_partial_index)} all_null_multi_tx_files={len(day_all_null_multi_tx_files)} "
                f"all_null_multi_file_files={len(day_all_null_multi_file_files)} "
                f"missing_index_multi_tx_files={len(day_missing_index_multi_tx_files)} "
                f"missing_index_multi_file_files={len(day_missing_index_multi_file_files)} "
                f"ordering_reasons={day_ordering_contract.get('reasons')} "
                f"uses canonical map for ALL files files={len(files)} path={day_tx_index_map_path}"
            )

        for fp, feats, tx_rows, tx_index_null_rows, tx_index_quality in pre_inspected_files:
            tx_index_map_path: Optional[Path] = day_tx_index_map_path if day_needs_canonical_tx_index_map else None
            if tx_index_map_path is not None:
                tx_index_quality["tx_index_map_report"] = {
                    "status": (day_tx_index_map_report or {}).get("status"),
                    "path": (day_tx_index_map_report or {}).get("path"),
                    "raw_rows": (day_tx_index_map_report or {}).get("raw_rows"),
                    "map_rows": (day_tx_index_map_report or {}).get("map_rows"),
                    "map_contract": (day_tx_index_map_report or {}).get("map_contract"),
                    "artifact_binding": (day_tx_index_map_report or {}).get("artifact_binding"),
                }
                tx_index_quality["day_level_canonical_map_forced"] = bool(day_needs_canonical_tx_index_map)
            effective_has_tx_index = bool(tx_index_quality["mode"] == "all_index_not_null" or tx_index_map_path is not None)
            if tx_index_quality["mode"] == "all_index_null" and tx_index_map_path is None:
                if not _env_bool("UTXO_ALLOW_NULL_TX_INDEX_SCAN_FALLBACK", True):
                    raise RuntimeError(
                        f"tx_index guard blocked day={day}: top-level transaction index column exists but is NULL "
                        f"file={fp} null_rows={tx_index_null_rows} tx_rows={tx_rows}. Set "
                        "UTXO_ALLOW_NULL_TX_INDEX_SCAN_FALLBACK=1 to use deterministic single-thread parquet scan-order fallback."
                    )
                _warn(
                    "YELLOW_TX_INDEX_NULL_FALLBACK "
                    f"day={day} file={fp} null_rows={tx_index_null_rows} tx_rows={tx_rows}; "
                    "using deterministic single-thread parquet scan-order tx_index for this file"
                )
            tx_index_source = (
                "canonical_tx_index_map"
                if tx_index_map_path is not None
                else ("top_level_index" if effective_has_tx_index else ("derived_scan_order_null_top_level_index" if feats.has_tx_index else "derived_scan_order_missing_top_level_index"))
            )
            tx_index_quality["tx_index_source"] = tx_index_source
            if tx_index_map_path is not None:
                tx_index_quality["tx_index_map_path"] = str(tx_index_map_path)
            inspected_files.append((fp, feats, tx_rows, tx_index_null_rows, effective_has_tx_index, tx_index_source, tx_index_quality, tx_index_map_path))

        missing_tx_index_files = [fp for fp, feats, _tx_rows, _null_rows, _effective, _source, _q, map_path in inspected_files if (not feats.has_tx_index and map_path is None)]
        fallback_tx_index_files = [fp for fp, _feats, _tx_rows, _null_rows, effective, _source, _q, map_path in inspected_files if (not effective and map_path is None)]
        if missing_tx_index_files:
            # Without explicit raw transaction index the only available ordering source
            # is parquet scan order. Keep this fallback deliberately narrow: if a raw
            # day is split into several files, a per-file fallback could reset tx_index
            # inside the same block. Also block fallback when any affected block has
            # more than one transaction, because ROW_NUMBER() OVER () cannot be treated
            # as canonical transaction order for production.
            ambiguous_fallback_blocks: List[Dict[str, Any]] = []
            for missing_fp in missing_tx_index_files:
                max_txs_per_block = int(con.execute(
                    """
                    SELECT COALESCE(MAX(cnt), 0)
                    FROM (
                      SELECT block_number, lower(block_hash::VARCHAR) AS block_hash, COUNT(*) AS cnt
                      FROM read_parquet(?)
                      WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
                      GROUP BY 1, 2
                    ) g
                    """,
                    [missing_fp],
                ).fetchone()[0] or 0)
                if max_txs_per_block > 1:
                    ambiguous_fallback_blocks.append({"path": missing_fp, "max_txs_per_block": max_txs_per_block})
            if ambiguous_fallback_blocks and not _env_bool("UTXO_ALLOW_DERIVED_TX_INDEX_MULTI_TX_BLOCK", False):
                raise RuntimeError(
                    f"tx_index fallback blocked day={day}: missing top-level transaction index and at least one block has "
                    f"multiple transactions: {ambiguous_fallback_blocks[:10]}. Explicit tx index is required for production causal order. "
                    "Set UTXO_ALLOW_DERIVED_TX_INDEX_MULTI_TX_BLOCK=1 only for deliberate lab experiments."
                )
            if len(files) > 1 and not _env_bool("UTXO_ALLOW_MULTI_FILE_TX_INDEX_FALLBACK", False):
                raise RuntimeError(
                    f"tx_index fallback blocked day={day}: {len(missing_tx_index_files)} file(s) lack top-level transaction index "
                    f"and the day has {len(files)} parquet file(s). This could reset tx_index per file. "
                    "Use a day with explicit top-level index, run a one-file early smoke, or set "
                    "UTXO_ALLOW_MULTI_FILE_TX_INDEX_FALLBACK=1 only for a deliberate lab experiment."
                )
        if fallback_tx_index_files:
            if _v11_phase_threads("stage") != 1:
                _warn(
                    f"tx_index fallback day={day}: forcing DuckDB stage threads=1 for deterministic single-file scan order; "
                    f"requested UTXO_STAGE_THREADS={_v11_phase_threads('stage')} fallback_files={len(fallback_tx_index_files)}"
                )
                con.execute("PRAGMA threads=1")
            try:
                con.execute("PRAGMA preserve_insertion_order=true")
            except Exception as e:
                _warn(f"tx_index fallback day={day}: PRAGMA preserve_insertion_order=true failed: {e}")

        for fp, feats, tx_rows, tx_index_null_rows, effective_has_tx_index, tx_index_source, tx_index_quality, tx_index_map_path in inspected_files:
            total_tx_rows += tx_rows
            if feats.has_outputs and not feats.output_has_index:
                raise RuntimeError(
                    f"output index missing in raw parquet day={day} file={fp}. "
                    "Cannot derive vout safely because outputs[].index is required."
                )
            if feats.has_inputs and feats.input_has_prevout and not feats.input_has_index:
                raise RuntimeError(
                    f"input index missing in raw parquet day={day} file={fp}. "
                    "Cannot derive spent_vin safely because inputs[].index is required."
                )
            raw_file_infos.append(
                {
                    "path": fp,
                    "tx_rows": tx_rows,
                    "top_level": list(feats.top_level),
                    "output_fields": list(feats.output_fields),
                    "input_fields": list(feats.input_fields),
                    "has_outputs": feats.has_outputs,
                    "has_inputs": feats.has_inputs,
                    "output_has_index": feats.output_has_index,
                    "output_has_address": feats.output_has_address,
                    "input_has_prevout": feats.input_has_prevout,
                    "input_has_index": feats.input_has_index,
                    "has_tx_index": feats.has_tx_index,
                    "tx_index_null_rows": int(tx_index_null_rows),
                    "effective_has_tx_index": bool(effective_has_tx_index),
                    "tx_index_source": tx_index_source,
                    "tx_index_map_path": str(tx_index_map_path) if tx_index_map_path is not None else None,
                    "tx_index_quality": tx_index_quality,
                }
            )
            _dbg(
                "file features: %s top=%s outputs=%s inputs=%s tx_index=%s tx_rows=%d"
                % (
                    os.path.basename(fp),
                    ",".join(feats.top_level),
                    ",".join(feats.output_fields) or "<none>",
                    ",".join(feats.input_fields) or "<none>",
                    tx_index_source,
                    tx_rows,
                )
            )
            con.execute(
                """
                INSERT INTO block_meta_stage_raw(block_number, block_hash, block_timestamp, block_date, raw_partition_min, raw_partition_max)
                SELECT
                  block_number::BIGINT AS block_number,
                  lower(block_hash::VARCHAR) AS block_hash,
                  block_timestamp::TIMESTAMP AS block_timestamp,
                  CAST(block_timestamp AS DATE) AS block_date,
                  MIN(CAST(date AS DATE)) AS raw_partition_min,
                  MAX(CAST(date AS DATE)) AS raw_partition_max
                FROM read_parquet(?)
                WHERE block_number IS NOT NULL AND block_hash IS NOT NULL AND block_timestamp IS NOT NULL
                GROUP BY block_number, lower(block_hash::VARCHAR), block_timestamp
                """,
                [fp],
            )
            if feats.has_outputs:
                t1 = _tic()
                con.execute(_created_insert_sql(feats.output_has_address, day, effective_has_tx_index, tx_index_map_path), [fp])
                _dbg(f"created raw insert parquet={os.path.basename(fp)} in {_fmt_s(_toc(t1))}")
            if feats.has_inputs and feats.input_has_prevout:
                t2 = _tic()
                con.execute(_spends_insert_sql(day, effective_has_tx_index, tx_index_map_path), [fp])
                _dbg(f"spends raw insert parquet={os.path.basename(fp)} in {_fmt_s(_toc(t2))}")

        stage_max_warn = _env_int("UTXO_STAGE_MAX_TX_ROWS_WARN", 0)
        stage_max_hard = _env_int("UTXO_STAGE_MAX_TX_ROWS_HARD", 0)
        if stage_max_warn > 0 and total_tx_rows > stage_max_warn:
            _warn(f"stage day={day} tx_rows={total_tx_rows} exceeds UTXO_STAGE_MAX_TX_ROWS_WARN={stage_max_warn}")
        if stage_max_hard > 0 and total_tx_rows > stage_max_hard:
            raise RuntimeError(f"stage day={day} tx_rows={total_tx_rows} exceeds UTXO_STAGE_MAX_TX_ROWS_HARD={stage_max_hard}")

        created_dup_before = int(con.execute(_dup_count_sql("created_stage_raw", "txid", "vout")).fetchone()[0])
        spends_dup_before = int(con.execute(_dup_count_sql("spends_stage_raw", "prev_txid", "prev_vout")).fetchone()[0])
        _warn_duplicates("stage_raw", day, created_dup_before, spends_dup_before)

        duplicate_guard = _run_preapply_duplicate_guard_on_stage_raw(con, raw_base, day, files)
        created_dup_after_guard = int(con.execute(_dup_count_sql("created_stage_raw", "txid", "vout")).fetchone()[0])
        spends_dup_after_guard = int(con.execute(_dup_count_sql("spends_stage_raw", "prev_txid", "prev_vout")).fetchone()[0])
        if spends_dup_after_guard > 0 and not _env_bool("UTXO_V11_ALLOW_DUPLICATE_SPENDS_STAGE_RAW_DANGEROUS", False):
            raise RuntimeError(
                f"v11 duplicate raw spends blocked day={day}: spends_dup_after_guard={spends_dup_after_guard}. "
                "A prevout may be spent only once in canonical chain data. This usually means duplicate/noncanonical source rows or schema/source corruption. "
                "Set UTXO_V11_ALLOW_DUPLICATE_SPENDS_STAGE_RAW_DANGEROUS=1 only for deliberate lab diagnosis."
            )
        if duplicate_guard.get("enabled") and not bool(duplicate_guard.get("apply_allowed", True)):
            manifest = _manifest_base(day, mode)
            manifest["status"] = STATUS_BLOCKED_BEFORE_APPLY
            manifest["raw"] = {
                "files": raw_file_infos,
                "files_count": len(files),
                "tx_rows": total_tx_rows,
                "schema_fingerprint": _schema_fingerprint(raw_file_infos),
                "source_fingerprint": _source_fingerprint(raw_file_infos),
            }
            manifest["stage"] = {
                "status": "blocked_before_apply",
                "created_dup_before": created_dup_before,
                "spends_dup_before": spends_dup_before,
                "elapsed_sec": _toc(t0),
            }
            manifest["duplicate_guard"] = duplicate_guard
            manifest["canonical_proof"] = _v11_build_canonical_proof_contract(
                day, duplicate_guard, stage_payload_fingerprint=None
            )
            manifest["files"].update({
                "duplicate_events_parquet": str(_duplicate_events_path(day)),
                "duplicate_summary_json": str(_duplicate_summary_path(day)),
                "global_duplicate_conflicts_parquet": str(_global_duplicate_conflicts_path(day)),
                "discarded_block_events_parquet": str(_discarded_block_events_path(day)),
            })
            manifest["errors"].append({
                "phase": "duplicate_guard",
                "error": "BLOCKED_BEFORE_APPLY",
                "message": "unresolved duplicate txid/vout before DB mutation",
            })
            _save_json_atomic(_manifest_path(day), manifest)
            if mode == MODE_STAGE_ONLY and _stage_only_allow_blocked():
                _warn(f"stage-only blocked day={day} recorded without DB mutation; UTXO_STAGE_ONLY_ALLOW_BLOCKED=1")
                return manifest
            raise RuntimeError(f"duplicate guard blocked day={day} before DB mutation: {duplicate_guard}")

        con.execute(_created_dedup_sql("created_stage_raw", "created_stage"))
        con.execute(_spends_dedup_sql("spends_stage_raw", "spends_stage"))

        stage_validation = _validate_stage_tables(con, day)
        if stage_validation["status"] != "ok" and _env_bool("UTXO_STAGE_STRICT", True):
            raise RuntimeError(f"stage validation failed day={day}: {', '.join(stage_validation['failed_checks'])}")

        semantic_validation = _semantic_unit_audit_day(con, day, files)
        semantic_validation["stop_on_fail"] = bool(semantic_stop_on_fail)
        semantic_validation["warning_only"] = bool(semantic_validation["status"] != "ok" and not semantic_stop_on_fail)
        if semantic_validation["status"] != "ok":
            semantic_msg = f"semantic unit audit failed day={day}: {', '.join(semantic_validation['failed_checks'])}"
            if semantic_stop_on_fail:
                _warn_red(semantic_msg + "; stopping because UTXO_SEMANTIC_AUDIT_STOP_ON_FAIL=1")
                raise RuntimeError(semantic_msg)
            _warn_red(semantic_msg + "; continuing because UTXO_SEMANTIC_AUDIT_STOP_ON_FAIL=0")

        con.execute(
            """
            CREATE OR REPLACE TEMP TABLE block_meta_stage AS
            SELECT
              block_number,
              lower(block_hash)::VARCHAR AS block_hash,
              block_timestamp::TIMESTAMP AS block_timestamp,
              CAST(block_timestamp AS DATE) AS block_date,
              MIN(raw_partition_min)::DATE AS raw_partition_min,
              MAX(raw_partition_max)::DATE AS raw_partition_max
            FROM block_meta_stage_raw
            WHERE block_number IS NOT NULL AND block_hash IS NOT NULL AND block_timestamp IS NOT NULL
            GROUP BY block_number, lower(block_hash), block_timestamp
            """
        )

        created_path = _created_stage_path(day)
        spends_path = _spends_stage_path(day)
        block_meta_path = _block_meta_stage_path(day)
        _export_temp_table_to_parquet(con, "created_stage", "block_number, tx_index, txid, vout", created_path)
        _export_temp_table_to_parquet(con, "spends_stage", "block_number, tx_index, prev_txid, prev_vout", spends_path)
        _export_temp_table_to_parquet(con, "block_meta_stage", "block_number", block_meta_path)

        created_bytes = created_path.stat().st_size if created_path.exists() else 0
        spends_bytes = spends_path.stat().st_size if spends_path.exists() else 0
        block_meta_bytes = block_meta_path.stat().st_size if block_meta_path.exists() else 0
        block_meta_rows = int(con.execute("SELECT COUNT(*) FROM block_meta_stage").fetchone()[0] or 0)

        manifest = _manifest_base(day, mode)
        manifest["status"] = STATUS_READY
        txid_map_audit = txid_map_preflight
        if txid_map_audit is None and _canonical_enabled_for_day(day) and _env_bool("UTXO_TXID_MAP_AUDIT_ON_STAGE", True):
            txid_map_audit = _audit_txid_map_day(raw_base, day)
            if txid_map_audit.get("status") != "ok" and _env_bool("UTXO_TXID_MAP_STRICT", True):
                raise RuntimeError(f"txid map audit failed day={day}: {txid_map_audit}")
        manifest["raw"] = {
            "files": raw_file_infos,
            "files_count": len(files),
            "tx_rows": total_tx_rows,
            "schema_fingerprint": _schema_fingerprint(raw_file_infos),
            "source_fingerprint": _source_fingerprint(raw_file_infos),
        }
        manifest["tx_index_quality"] = {
            "files": [info.get("tx_index_quality", {}) for info in raw_file_infos],
            "by_mode": {},
            "by_severity": {},
        }
        for _q in manifest["tx_index_quality"]["files"]:
            _m = str(_q.get("mode", "unknown"))
            _sev = str(_q.get("severity", "unknown"))
            manifest["tx_index_quality"]["by_mode"][_m] = int(manifest["tx_index_quality"]["by_mode"].get(_m, 0)) + 1
            manifest["tx_index_quality"]["by_severity"][_sev] = int(manifest["tx_index_quality"]["by_severity"].get(_sev, 0)) + 1
        genesis_skipped = 1 if str(day) == "2009-01-03" else 0
        manifest["stage"] = {
            **stage_validation,
            "stage_semantics": "block_ordered",
            "causal_order": "block_number,tx_index",
            "date_semantics": "block_timestamp_utc_date",
            "raw_partition_date_semantics": "storage_only",
            "genesis_unspendable_skipped": genesis_skipped,
            "block_meta_rows": block_meta_rows,
            "created_dup_before": created_dup_before,
            "spends_dup_before": spends_dup_before,
            "created_dup_after_guard": created_dup_after_guard,
            "spends_dup_after_guard": spends_dup_after_guard,
            "elapsed_sec": _toc(t0),
        }
        manifest["duplicate_guard"] = duplicate_guard
        manifest["source_units"] = {
            "output_value_unit": _get_output_value_unit(),
            "address_mode": _get_address_mode(),
        }
        manifest["txid_mode"] = {
            "mode": _get_txid_mode(),
            "canonical_replace_from": _canonical_replace_from(),
            "canonical_enabled_for_day": _canonical_enabled_for_day(day),
            "txid_map_path": str(_txid_map_path(day)) if _canonical_enabled_for_day(day) else None,
            "txid_map_audit": txid_map_audit,
        }
        manifest["semantic_audit"] = semantic_validation
        if day_tx_index_map_path is not None:
            manifest["tx_index_map_binding"] = _tx_index_map_artifact_binding(day_tx_index_map_path)
        else:
            manifest["tx_index_map_binding"] = None
        manifest["files"].update(
            {
                "created_parquet": str(created_path),
                "spends_parquet": str(spends_path),
                "block_meta_parquet": str(block_meta_path),
                "duplicate_events_parquet": str(_duplicate_events_path(day)),
                "duplicate_summary_json": str(_duplicate_summary_path(day)),
                "global_duplicate_conflicts_parquet": str(_global_duplicate_conflicts_path(day)),
                "discarded_block_events_parquet": str(_discarded_block_events_path(day)),
                "created_parquet_bytes": created_bytes,
                "spends_parquet_bytes": spends_bytes,
                "block_meta_parquet_bytes": block_meta_bytes,
                "block_meta_rows": block_meta_rows,
            }
        )
        stage_payload_fingerprint = _v11_stage_payload_fingerprint(day, manifest)
        manifest["canonical_proof"] = _v11_build_canonical_proof_contract(
            day, duplicate_guard, stage_payload_fingerprint=stage_payload_fingerprint
        )
        if manifest["canonical_proof"].get("complete") is not True:
            manifest["status"] = STATUS_BLOCKED_BEFORE_APPLY
            manifest["purge"]["eligible"] = False
            manifest.setdefault("errors", []).append(
                "canonical_proof_contract_incomplete:"
                + ";".join(str(x) for x in manifest["canonical_proof"].get("failures", []))
            )
            _save_json_atomic(_manifest_path(day), manifest)
            if mode == MODE_STAGE_ONLY and _stage_only_allow_blocked():
                _warn(
                    f"STAGE_ONLY canonical proof incomplete day={day}; diagnostic manifest saved "
                    "with BLOCKED_BEFORE_APPLY and is not reusable by write modes"
                )
                return manifest
            raise RuntimeError(
                f"canonical proof contract incomplete day={day}: {manifest['canonical_proof']}"
            )
        manifest["purge"]["eligible"] = True
        manifest["telemetry"]["stage_bytes_total"] = created_bytes + spends_bytes + block_meta_bytes
        _save_json_atomic(_manifest_path(day), manifest)
        _log(
            f"stage day={day} files={len(files)} tx_rows={total_tx_rows} created_stage={stage_validation['created_rows']} "
            f"spends_stage={stage_validation['spends_rows']} created_dup_before={created_dup_before} "
            f"spends_dup_before={spends_dup_before} semantic_status={semantic_validation['status']} in {_fmt_s(manifest['stage']['elapsed_sec'])}"
        )
        return manifest
    finally:
        _tx_index_map_release_day_lock(tx_index_map_stage_lock)
        con.close()



# -----------------------------
# v10_5 stage-key cleanup / post-apply assertions
# -----------------------------

def _v10_5_enabled_for_day(day: str) -> bool:
    """
    v10_6-targeted-created-cleanup-r1

    The extra cleanup is only meaningful for canonical_map SegWit-era writes.
    In canonical_map mode it is mandatory by default: disabling it can preserve
    poisoned/old rows with the same canonical (txid, vout).
    """
    if not _canonical_enabled_for_day(day):
        return False
    enabled = _env_bool("UTXO_V10_5_STAGE_KEY_CLEANUP", True)
    if not enabled and not _env_bool("UTXO_ALLOW_DISABLE_CANONICAL_STAGE_KEY_CLEANUP", False):
        raise RuntimeError(
            "UTXO_V10_5_STAGE_KEY_CLEANUP=0 is blocked for canonical_map days. "
            "Set UTXO_ALLOW_DISABLE_CANONICAL_STAGE_KEY_CLEANUP=1 only for a deliberate lab experiment."
        )
    return enabled


def _v10_5_created_cleanup_rows() -> int:
    return max(1, _env_int("UTXO_V10_5_CREATED_CLEANUP_KEY_ROWS", _env_int("UTXO_APPLY_CREATED_ROWS", 25000)))


def _v10_5_spent_cleanup_rows() -> int:
    return max(1, _env_int("UTXO_V10_5_SPENT_CLEANUP_KEY_ROWS", _env_int("UTXO_APPLY_SPENT_ROWS", 10000)))


def _v10_5_post_assert_rows() -> int:
    return max(1, _env_int("UTXO_V10_5_POST_ASSERT_KEY_ROWS", _env_int("UTXO_APPLY_CREATED_ROWS", 25000)))


def _v10_5_sum_eps() -> float:
    return max(0.0, _env_float("UTXO_V10_5_SUM_EPS", 0.00000001))


def _v10_5_value_eps() -> float:
    return max(0.0, _env_float("UTXO_V10_5_VALUE_EPS", 0.000000000001))


def _v10_5_artifact_path(day: str, name: str, suffix: str = ".json") -> Path:
    d = _audit_dir() / f"date={day}"
    d.mkdir(parents=True, exist_ok=True)
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    return d / f"{_pipeline_version()}_{name}_{ts}{suffix}"


def _v10_5_save_artifact(day: str, name: str, payload: Dict[str, Any]) -> Path:
    payload = dict(payload)
    payload.setdefault("pipeline_version", _pipeline_version())
    payload.setdefault("day", day)
    payload.setdefault("artifact", name)
    payload.setdefault("created_at", _now_iso())
    p = _v10_5_artifact_path(day, name, ".json")
    _save_json_atomic(p, payload)
    return p


def _v10_5_make_created_cleanup_chunk(con: duckdb.DuckDBPyConnection, start_seq: int, end_seq: int) -> int:
    con.execute("DROP TABLE IF EXISTS v10_5_created_cleanup_chunk")
    con.execute(
        """
        CREATE TEMP TABLE v10_5_created_cleanup_chunk AS
        SELECT txid, vout
        FROM created_apply_ready
        WHERE seq BETWEEN ? AND ?;
        """,
        [start_seq, end_seq],
    )
    return int(con.execute("SELECT COUNT(*) FROM v10_5_created_cleanup_chunk").fetchone()[0])


def _v10_5_make_spent_cleanup_chunk(con: duckdb.DuckDBPyConnection, start_seq: int, end_seq: int) -> int:
    con.execute("DROP TABLE IF EXISTS v10_5_spent_cleanup_chunk")
    con.execute(
        """
        CREATE TEMP TABLE v10_5_spent_cleanup_chunk AS
        SELECT prev_txid AS txid, prev_vout AS vout
        FROM spends_apply_ready
        WHERE seq BETWEEN ? AND ?;
        """,
        [start_seq, end_seq],
    )
    return int(con.execute("SELECT COUNT(*) FROM v10_5_spent_cleanup_chunk").fetchone()[0])


def _v10_5_count_created_key_conflicts(con: duckdb.DuckDBPyConnection, created_stage_rows: int) -> int:
    chunk_rows = _v10_5_created_cleanup_rows()
    conflicts = 0
    start = 1
    while start <= created_stage_rows:
        end = min(start + chunk_rows - 1, created_stage_rows)
        chunk_count = _v10_5_make_created_cleanup_chunk(con, start, end)
        if chunk_count <= 0:
            break
        conflicts += int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM utxo u
                JOIN v10_5_created_cleanup_chunk k
                  ON u.txid = k.txid AND u.vout = k.vout;
                """
            ).fetchone()[0]
        )
        start = end + 1
    return conflicts


def _v10_5_count_created_poison_like_conflicts(con: duckdb.DuckDBPyConnection, created_stage_rows: int) -> int:
    """
    v10_6-targeted-created-cleanup-r1

    Count already-existing rows that look like the previously observed poison:
      - same canonical (txid, vout) as the stage row;
      - address is NULL in DB;
      - DB value is approximately stage value / 1e8.

    This is diagnostic only; actual cleanup deletes all same-key rows.
    """
    if created_stage_rows <= 0:
        return 0
    chunk_rows = _v10_5_created_cleanup_rows()
    eps = max(0.0, _env_float("UTXO_V10_5_POISON_VALUE_EPS", 0.000000000000000001))
    poison_like = 0
    start = 1
    while start <= created_stage_rows:
        end = min(start + chunk_rows - 1, created_stage_rows)
        chunk_count = _v10_5_make_created_cleanup_chunk(con, start, end)
        if chunk_count <= 0:
            break
        poison_like += int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM utxo u
                JOIN created_apply_ready s
                  ON u.txid = s.txid AND u.vout = s.vout
                WHERE s.seq BETWEEN ? AND ?
                  AND u.address IS NULL
                  AND ABS(COALESCE(u.value_btc, 0.0) - (COALESCE(s.value_btc, 0.0) / 100000000.0)) <= ?;
                """,
                [start, end, eps],
            ).fetchone()[0]
        )
        start = end + 1
    return poison_like



def _v10_6_created_cleanup_mode() -> str:
    """
    v10_6-targeted-created-cleanup-r1

    created cleanup modes:
      - targeted_poison (default): fast path. Delete only rows that match the
        observed canonical poison pattern: same stage key, DB address NULL, and
        DB value approximately stage_value / 1e8.
      - full_stage_keys: old v10_5/v10_5_4 behavior. Delete every existing DB row
        with the same (txid, vout) as created_stage before apply. Slow but safest.

    Post-apply created assert remains mandatory and catches missed conflicts.
    """
    mode = _env_str("UTXO_V10_6_CREATED_CLEANUP_MODE", "targeted_poison").strip().lower()
    aliases = {
        "targeted": "targeted_poison",
        "poison": "targeted_poison",
        "targeted-poison": "targeted_poison",
        "full": "full_stage_keys",
        "full-stage-keys": "full_stage_keys",
        "full_stage": "full_stage_keys",
        "v10_5": "full_stage_keys",
        "v10_5_4": "full_stage_keys",
    }
    mode = aliases.get(mode, mode)
    if mode not in {"targeted_poison", "full_stage_keys"}:
        raise RuntimeError(
            "Invalid UTXO_V10_6_CREATED_CLEANUP_MODE=%r. Use targeted_poison or full_stage_keys." % mode
        )
    return mode


def _v10_6_poison_value_eps() -> float:
    return max(
        0.0,
        _env_float(
            "UTXO_V10_6_POISON_VALUE_EPS",
            _env_float("UTXO_V10_5_POISON_VALUE_EPS", 0.000000000000000001),
        ),
    )


def _v10_6_make_created_poison_candidates(con: duckdb.DuckDBPyConnection, day: str) -> int:
    """
    Build the small candidate table used by the v10_6 fast cleanup path.

    The important optimisation: filter the huge DB by created_date and address IS NULL
    first, then join those much fewer rows to created_apply_ready. On the 2018-10-07
    and 2018-10-08 lab days this should find the known 25/29 poisoned rows without
    scanning every stage key in 25k chunks.
    """
    eps = _v10_6_poison_value_eps()
    con.execute("DROP TABLE IF EXISTS v10_6_created_poison_candidates")
    con.execute(
        """
        CREATE TEMP TABLE v10_6_created_poison_candidates AS
        SELECT DISTINCT s.txid, s.vout
        FROM (
            SELECT txid, vout, value_btc
            FROM utxo
            WHERE created_date = CAST(? AS DATE)
              AND address IS NULL
        ) AS u
        JOIN created_apply_ready AS s
          ON u.txid = s.txid
         AND u.vout = s.vout
        WHERE ABS(COALESCE(u.value_btc, 0.0) - (COALESCE(s.value_btc, 0.0) / 100000000.0)) <= ?;
        """,
        [day, eps],
    )
    return int(con.execute("SELECT COUNT(*) FROM v10_6_created_poison_candidates").fetchone()[0])


def _v10_6_count_created_poison_candidates_remaining(con: duckdb.DuckDBPyConnection, day: str) -> int:
    eps = _v10_6_poison_value_eps()
    return int(
        con.execute(
            """
            SELECT COUNT(*)
            FROM utxo u
            JOIN created_apply_ready s
              ON u.txid = s.txid
             AND u.vout = s.vout
            WHERE u.created_date = CAST(? AS DATE)
              AND u.address IS NULL
              AND ABS(COALESCE(u.value_btc, 0.0) - (COALESCE(s.value_btc, 0.0) / 100000000.0)) <= ?;
            """,
            [day, eps],
        ).fetchone()[0]
    )


def _v10_6_cleanup_created_targeted_poison(
    con: duckdb.DuckDBPyConnection,
    day: str,
    created_stage_rows: int,
) -> Dict[str, Any]:
    """
    v10_6 fast cleanup.

    Delete only confirmed poison-like canonical conflicts. This is intentionally
    narrower than the old full stage-key cleanup. Correctness is still protected
    by mandatory _v10_5_post_apply_assert_created after apply.
    """
    t0 = _tic()
    candidates = _v10_6_make_created_poison_candidates(con, day)

    con.execute("BEGIN")
    try:
        con.execute(
            """
            DELETE FROM utxo
            USING v10_6_created_poison_candidates k
            WHERE utxo.txid = k.txid
              AND utxo.vout = k.vout;
            """
        )
        con.execute("COMMIT")
    except Exception:
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        raise

    remaining = _v10_6_count_created_poison_candidates_remaining(con, day)
    _log(
        f"v10_10 cleanup created targeted poison day={day} "
        f"stage_rows={created_stage_rows} candidates={candidates} remaining={remaining} "
        f"in {_fmt_s(_toc(t0))}"
    )
    return {
        "created_cleanup_enabled": True,
        "created_cleanup_mode": "targeted_poison",
        "created_cleanup_chunk_rows": 0,
        "created_cleanup_chunks": 1,
        "created_cleanup_stage_keys": int(created_stage_rows or 0),
        "created_pre_existing_deleted_candidates": candidates,
        "created_targeted_poison_candidates": candidates,
        "created_targeted_poison_remaining_after_cleanup": remaining,
        "created_cleanup_elapsed_sec": _toc(t0),
        "created_cleanup_correctness_gate": "post_apply_created_assert",
    }

def _v10_5_cleanup_created_stage_keys(
    con: duckdb.DuckDBPyConnection,
    day: str,
    created_stage_rows: int,
) -> Dict[str, Any]:
    chunk_rows = _v10_5_created_cleanup_rows()
    total_pre_existing = 0
    chunks = 0
    start = 1
    t0 = _tic()

    while start <= created_stage_rows:
        end = min(start + chunk_rows - 1, created_stage_rows)
        chunk_count = _v10_5_make_created_cleanup_chunk(con, start, end)
        if chunk_count <= 0:
            break

        pre_existing = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM utxo u
                JOIN v10_5_created_cleanup_chunk k
                  ON u.txid = k.txid AND u.vout = k.vout;
                """
            ).fetchone()[0]
        )
        total_pre_existing += pre_existing

        con.execute("BEGIN")
        try:
            con.execute(
                """
                DELETE FROM utxo
                USING v10_5_created_cleanup_chunk k
                WHERE utxo.txid = k.txid
                  AND utxo.vout = k.vout;
                """
            )
            con.execute("COMMIT")
        except Exception:
            try:
                con.execute("ROLLBACK")
            except Exception:
                pass
            raise

        chunks += 1
        if chunks == 1 or end == created_stage_rows or chunks % 10 == 0:
            _log(
                f"v10_5 cleanup created stage keys day={day} "
                f"seq={start}-{end} chunk_rows={chunk_count} pre_existing={pre_existing}"
            )

        start = end + 1

    return {
        "created_cleanup_enabled": True,
        "created_cleanup_chunk_rows": chunk_rows,
        "created_cleanup_chunks": chunks,
        "created_cleanup_stage_keys": created_stage_rows,
        "created_pre_existing_deleted_candidates": total_pre_existing,
        "created_cleanup_elapsed_sec": _toc(t0),
    }


def _v10_5_cleanup_spent_stage_prevouts(
    con: duckdb.DuckDBPyConnection,
    day: str,
    spends_stage_rows: int,
) -> Dict[str, Any]:
    chunk_rows = _v10_5_spent_cleanup_rows()
    total_pre_marked = 0
    chunks = 0
    start = 1
    t0 = _tic()

    while start <= spends_stage_rows:
        end = min(start + chunk_rows - 1, spends_stage_rows)
        chunk_count = _v10_5_make_spent_cleanup_chunk(con, start, end)
        if chunk_count <= 0:
            break

        pre_marked = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM utxo u
                JOIN v10_5_spent_cleanup_chunk k
                  ON u.txid = k.txid AND u.vout = k.vout
                WHERE u.spent_ts IS NOT NULL
                   OR u.spent_date IS NOT NULL
                   OR u.spent_txid IS NOT NULL
                   OR u.spent_vin IS NOT NULL;
                """
            ).fetchone()[0]
        )
        total_pre_marked += pre_marked

        con.execute("BEGIN")
        try:
            con.execute(
                """
                UPDATE utxo
                SET
                  spent_ts = NULL,
                  spent_date = NULL,
                  spent_txid = NULL,
                  spent_vin = NULL
                FROM v10_5_spent_cleanup_chunk k
                WHERE utxo.txid = k.txid
                  AND utxo.vout = k.vout;
                """
            )
            con.execute("COMMIT")
        except Exception:
            try:
                con.execute("ROLLBACK")
            except Exception:
                pass
            raise

        chunks += 1
        if chunks == 1 or end == spends_stage_rows or chunks % 10 == 0:
            _log(
                f"v10_5 cleanup spent stage prevouts day={day} "
                f"seq={start}-{end} chunk_rows={chunk_count} pre_marked={pre_marked}"
            )

        start = end + 1

    return {
        "spent_cleanup_enabled": True,
        "spent_cleanup_chunk_rows": chunk_rows,
        "spent_cleanup_chunks": chunks,
        "spent_cleanup_stage_prevout_rows": spends_stage_rows,
        "spent_pre_marked_update_candidates": total_pre_marked,
        "spent_cleanup_elapsed_sec": _toc(t0),
    }


def _v10_5_pre_apply_stage_key_cleanup(
    con: duckdb.DuckDBPyConnection,
    day: str,
    created_stage_rows: int,
    spends_stage_rows: int,
) -> Dict[str, Any]:
    """
    v10_6-targeted-created-cleanup-r1

    Critical fix retained from v10_5:
      ON CONFLICT DO NOTHING must not preserve poisoned/old rows with the same
      canonical (txid, vout).

    v10_6 speed change:
      Default cleanup mode is targeted_poison. It deletes only confirmed
      poison-like rows and relies on mandatory post-apply created assert for the
      final correctness gate. Use UTXO_V10_6_CREATED_CLEANUP_MODE=full_stage_keys
      to force the old slow but exhaustive v10_5/v10_5_4 cleanup.
    """
    if not _v10_5_enabled_for_day(day):
        return {
            "enabled": False,
            "reason": "not canonical_map for day or disabled by UTXO_V10_5_STAGE_KEY_CLEANUP=0",
        }

    t0 = _tic()
    created_cleanup_mode = _v10_6_created_cleanup_mode()

    # In targeted mode the old conflict audit is intentionally disabled by default;
    # it was one of the expensive full stage-key passes. Operators can re-enable it
    # for lab comparison with UTXO_V10_5_PRE_CLEANUP_CONFLICT_AUDIT=1.
    conflict_audit_default = created_cleanup_mode == "full_stage_keys"
    conflict_audit_enabled = _env_bool("UTXO_V10_5_PRE_CLEANUP_CONFLICT_AUDIT", conflict_audit_default)

    conflicts_before = 0
    poison_like_before = 0
    if conflict_audit_enabled:
        conflicts_before = _v10_5_count_created_key_conflicts(con, created_stage_rows)
        poison_like_before = _v10_5_count_created_poison_like_conflicts(con, created_stage_rows)

    _log(
        f"v10_10 pre-apply cleanup begin day={day} "
        f"created_cleanup_mode={created_cleanup_mode} "
        f"created_stage_rows={created_stage_rows} spends_stage_rows={spends_stage_rows} "
        f"pre_cleanup_conflict_audit={conflict_audit_enabled} "
        f"created_key_conflicts_before_cleanup={conflicts_before} "
        f"poison_like_conflicts_before_cleanup={poison_like_before}"
    )

    cleanup_spent_prevouts_enabled = _env_bool("UTXO_V10_5_CLEANUP_SPENT_STAGE_PREVOUTS", False)
    if cleanup_spent_prevouts_enabled:
        spent_report = _v10_5_cleanup_spent_stage_prevouts(con, day, spends_stage_rows)
    else:
        spent_report = {
            "spent_cleanup_enabled": False,
            "spent_cleanup_skipped_reason": "disabled_by_UTXO_V10_5_CLEANUP_SPENT_STAGE_PREVOUTS",
            "spent_cleanup_chunk_rows": 0,
            "spent_cleanup_chunks": 0,
            "spent_cleanup_stage_prevout_rows": int(spends_stage_rows or 0),
            "spent_pre_marked_update_candidates": 0,
            "spent_cleanup_elapsed_sec": 0.0,
        }
        _log(
            f"v10_10 skip spent stage prevout cleanup day={day} "
            f"stage_rows={spends_stage_rows} "
            "reason=UTXO_V10_5_CLEANUP_SPENT_STAGE_PREVOUTS=0"
        )

    if created_cleanup_mode == "targeted_poison":
        created_report = _v10_6_cleanup_created_targeted_poison(con, day, created_stage_rows)
        verify_full_after = _env_bool("UTXO_V10_6_VERIFY_CONFLICTS_AFTER_TARGETED", False)
        if verify_full_after:
            conflicts_after = _v10_5_count_created_key_conflicts(con, created_stage_rows)
            conflicts_after_kind = "full_stage_key_scan"
        else:
            conflicts_after = int(created_report.get("created_targeted_poison_remaining_after_cleanup", 0) or 0)
            conflicts_after_kind = "targeted_poison_remaining"
    else:
        created_report = _v10_5_cleanup_created_stage_keys(con, day, created_stage_rows)
        conflicts_after = _v10_5_count_created_key_conflicts(con, created_stage_rows)
        conflicts_after_kind = "full_stage_key_scan"

    report = {
        "enabled": True,
        "status": "ok" if conflicts_after == 0 else "fail",
        "pre_cleanup_conflict_audit_enabled": conflict_audit_enabled,
        "created_cleanup_mode": created_cleanup_mode,
        "created_key_conflicts_before_cleanup": conflicts_before,
        "created_poison_like_conflicts_before_cleanup": poison_like_before,
        "conflicts_after_cleanup": conflicts_after,
        "conflicts_after_cleanup_kind": conflicts_after_kind,
        "elapsed_sec": _toc(t0),
        **spent_report,
        **created_report,
    }

    artifact = _v10_5_save_artifact(day, "pre_apply_stage_key_cleanup", report)
    report["artifact"] = str(artifact)
    _update_manifest(day, {"acceptance": {"v10_10_pre_apply_stage_key_cleanup": report}})

    if conflicts_after != 0 and _env_bool("UTXO_V10_5_ABORT_ON_CREATED_CONFLICT", True):
        raise RuntimeError(f"v10_10 created key conflicts remain after cleanup day={day}: {conflicts_after}; see {artifact}")

    if _env_bool("UTXO_V10_5_CHECKPOINT_AFTER_STAGE_KEY_CLEANUP", False):
        ck_t0 = _tic()
        con.execute("CHECKPOINT")
        report["checkpoint_after_cleanup_elapsed_sec"] = _toc(ck_t0)
        _update_manifest(day, {"acceptance": {"v10_10_pre_apply_stage_key_cleanup": report}})
        _log(f"v10_10 checkpoint after stage-key cleanup day={day} ok in {_fmt_s(report['checkpoint_after_cleanup_elapsed_sec'])}")

    _log(
        f"v10_10 pre-apply cleanup ok day={day} "
        f"mode={created_cleanup_mode} "
        f"created_pre_existing={created_report['created_pre_existing_deleted_candidates']} "
        f"spent_pre_marked={spent_report['spent_pre_marked_update_candidates']} "
        f"conflicts_after={conflicts_after} kind={conflicts_after_kind} in {_fmt_s(report['elapsed_sec'])}"
    )
    return report


def _v10_10_created_assert_mode() -> str:
    """
    v10_10-apply-spends-tuning-r1

    Created post-apply assert strategy:
      - full: original v10_7 key-by-key coverage/value/address/date assert.
      - summary: fast count + integer-satoshi sum assert.

    summary intentionally does not prove key-level equality. It is a speed mode
    for lab replay after the v10_7 full assert has proven the path on earlier
    days. The deep day audit still runs later when mode is
    STAGE_APPLY_AND_AUDIT_DAY / REPLAY_DAY.
    """
    mode = (_env_str("UTXO_CREATED_ASSERT_MODE", "full") or "full").strip().lower()
    aliases = {
        "key": "full",
        "keys": "full",
        "keyset": "full",
        "full_keys": "full",
        "full-key": "full",
        "full-keyset": "full",
        "sum": "summary",
        "sums": "summary",
        "fast": "summary",
        "count_sum": "summary",
        "count-sum": "summary",
        "summary_sum": "summary",
        "summary-sum": "summary",
    }
    mode = aliases.get(mode, mode)
    if mode not in {"full", "summary"}:
        raise RuntimeError(
            "Invalid UTXO_CREATED_ASSERT_MODE=%r. Use full or summary." % mode
        )
    return mode


def _v10_10_post_apply_summary_assert_created(
    con: duckdb.DuckDBPyConnection,
    day: str,
    created_stage_rows: int,
) -> Dict[str, Any]:
    """
    v10_10-apply-spends-tuning-r1

    Fast replacement for the expensive v10_7 full key-by-key created assert.

    Checks:
      - created_apply_ready count equals DB created_date=day count;
      - integer satoshi sum equals DB created_date=day integer satoshi sum;
      - stage manifest row count agrees with created_apply_ready count.

    It deliberately does NOT check every key/address/value pair. For a stronger
    check, use UTXO_CREATED_ASSERT_MODE=full.
    """
    if not _v10_5_enabled_for_day(day):
        return {
            "enabled": False,
            "mode": "summary",
            "reason": "not canonical_map for day or explicitly disabled with dangerous override",
        }

    t0 = _tic()

    stage_count, stage_sum, stage_sum_sats = con.execute(
        """
        SELECT
          COUNT(*),
          COALESCE(SUM(value_btc), 0.0),
          COALESCE(SUM(CAST(round(COALESCE(value_btc, 0.0) * 100000000) AS BIGINT)), 0)
        FROM created_apply_ready;
        """
    ).fetchone()

    db_count, db_sum, db_sum_sats = con.execute(
        """
        SELECT
          COUNT(*),
          COALESCE(SUM(value_btc), 0.0),
          COALESCE(SUM(CAST(round(COALESCE(value_btc, 0.0) * 100000000) AS BIGINT)), 0)
        FROM utxo
        WHERE created_date = ?::DATE;
        """,
        [day],
    ).fetchone()

    stage_count = int(stage_count or 0)
    db_count = int(db_count or 0)
    stage_sum = float(stage_sum or 0.0)
    db_sum = float(db_sum or 0.0)
    stage_sum_sats = int(stage_sum_sats or 0)
    db_sum_sats = int(db_sum_sats or 0)

    rows_diff = db_count - stage_count
    manifest_rows_diff = stage_count - int(created_stage_rows or 0)
    sum_diff_abs = abs(stage_sum - db_sum)
    sum_sats_diff = db_sum_sats - stage_sum_sats
    sum_sats_diff_abs = abs(sum_sats_diff)

    failed_checks: List[str] = []
    if manifest_rows_diff != 0:
        failed_checks.append("created_stage_manifest_count_mismatch")
    if rows_diff != 0:
        failed_checks.append("created_count_mismatch")
    if sum_sats_diff_abs != 0:
        failed_checks.append("created_sum_sats_mismatch")

    report = {
        "enabled": True,
        "mode": "summary",
        "status": "ok" if not failed_checks else "fail",
        "failed_checks": failed_checks,
        "correctness_scope": "count_and_integer_satoshi_sum_only",
        "full_key_level_assert_skipped": True,
        "full_key_level_assert_hint": "Set UTXO_CREATED_ASSERT_MODE=full for key-by-key coverage/address/value/date assert.",
        "stage_created_count": stage_count,
        "created_stage_rows_arg": int(created_stage_rows or 0),
        "stage_vs_arg_rows_diff": manifest_rows_diff,
        "db_created_day_count": db_count,
        "rows_diff": rows_diff,
        "sum_check_mode": "integer_sats",
        "stage_created_sum_btc": stage_sum,
        "db_created_day_sum_btc": db_sum,
        "sum_diff_abs": sum_diff_abs,
        "sum_diff_abs_double": sum_diff_abs,
        "stage_created_sum_sats": stage_sum_sats,
        "db_created_day_sum_sats": db_sum_sats,
        "sum_sats_diff": sum_sats_diff,
        "sum_sats_diff_abs": sum_sats_diff_abs,
        "sum_btc_diff_by_sats": sum_sats_diff / 100000000.0,
        "missing_stage_keys_in_db": None,
        "mismatched_stage_keys_in_db": None,
        "elapsed_sec": _toc(t0),
    }

    artifact = _v10_5_save_artifact(day, "post_apply_created_assert_summary", report)
    report["artifact"] = str(artifact)

    _update_manifest(
        day,
        {
            "acceptance": {
                "v10_10_post_apply_created_assert_summary": report,
                # Compatibility: existing apply_report readers look for this key.
                "v10_5_post_apply_created_assert": report,
            }
        },
    )

    if failed_checks and _env_bool("UTXO_V10_5_ABORT_ON_POST_ASSERT_FAIL", True):
        raise RuntimeError(
            f"v10_10 summary post-apply created assert failed day={day}: {failed_checks}; see {artifact}"
        )

    _log(
        f"v10_10 post-apply created summary assert {report['status']} day={day} "
        f"stage_count={stage_count} db_count={db_count} rows_diff={rows_diff} "
        f"sum_diff_double={sum_diff_abs} sum_sats_diff={sum_sats_diff} "
        f"in {_fmt_s(report['elapsed_sec'])}"
    )
    return report


def _v10_5_post_apply_assert_created(
    con: duckdb.DuckDBPyConnection,
    day: str,
    created_stage_rows: int,
) -> Dict[str, Any]:
    """
    v10_5-canonical-stage-key-cleanup-r1

    Assert that created rows in DB match created_apply_ready after apply.

    It checks:
      - count(created_date=day) == stage rows;
      - integer satoshi sum matches stage sum; DOUBLE sum is informational only;
      - every stage key exists in DB for this day;
      - existing stage keys do not have poisoned address/value/date.
    """
    if not _v10_5_enabled_for_day(day):
        return {
            "enabled": False,
            "reason": "not canonical_map for day or explicitly disabled with dangerous override",
        }
    if not _env_bool("UTXO_V10_5_POST_ASSERT_CREATED", True):
        if not _env_bool("UTXO_ALLOW_DISABLE_CANONICAL_CREATED_ASSERT", False):
            raise RuntimeError(
                "UTXO_V10_5_POST_ASSERT_CREATED=0 is blocked for canonical_map days. "
                "Set UTXO_ALLOW_DISABLE_CANONICAL_CREATED_ASSERT=1 only for a deliberate lab experiment."
            )
        return {"enabled": False, "reason": "UTXO_V10_5_POST_ASSERT_CREATED=0 with explicit dangerous override"}

    created_assert_mode = _v10_10_created_assert_mode()
    if created_assert_mode == "summary":
        return _v10_10_post_apply_summary_assert_created(con, day, created_stage_rows)

    t0 = _tic()
    chunk_rows = _v10_5_post_assert_rows()
    value_eps = _v10_5_value_eps()
    sum_eps = _v10_5_sum_eps()
    sample_limit = max(0, _env_int("UTXO_V10_5_ASSERT_SAMPLE_LIMIT", 100))

    stage_count, stage_sum, stage_sum_sats = con.execute(
        """
        SELECT
          COUNT(*),
          COALESCE(SUM(value_btc), 0.0),
          COALESCE(SUM(CAST(round(COALESCE(value_btc, 0.0) * 100000000) AS BIGINT)), 0)
        FROM created_apply_ready;
        """
    ).fetchone()
    db_count, db_sum, db_sum_sats = con.execute(
        """
        SELECT
          COUNT(*),
          COALESCE(SUM(value_btc), 0.0),
          COALESCE(SUM(CAST(round(COALESCE(value_btc, 0.0) * 100000000) AS BIGINT)), 0)
        FROM utxo
        WHERE created_date = ?::DATE;
        """,
        [day],
    ).fetchone()

    stage_count = int(stage_count or 0)
    db_count = int(db_count or 0)
    stage_sum = float(stage_sum or 0.0)
    db_sum = float(db_sum or 0.0)
    stage_sum_sats = int(stage_sum_sats or 0)
    db_sum_sats = int(db_sum_sats or 0)

    missing_count = 0
    mismatch_count = 0
    missing_sample: List[Dict[str, Any]] = []
    mismatch_sample: List[Dict[str, Any]] = []

    start = 1
    while start <= created_stage_rows:
        end = min(start + chunk_rows - 1, created_stage_rows)
        con.execute("DROP TABLE IF EXISTS v10_5_created_assert_chunk")
        con.execute(
            """
            CREATE TEMP TABLE v10_5_created_assert_chunk AS
            SELECT txid, vout, address, value_btc, created_date
            FROM created_apply_ready
            WHERE seq BETWEEN ? AND ?;
            """,
            [start, end],
        )

        miss = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM v10_5_created_assert_chunk s
                LEFT JOIN utxo u
                  ON u.txid = s.txid
                 AND u.vout = s.vout
                 AND u.created_date = s.created_date
                WHERE u.txid IS NULL;
                """
            ).fetchone()[0]
        )
        missing_count += miss

        if miss and len(missing_sample) < sample_limit:
            rows = con.execute(
                """
                SELECT s.txid, s.vout, s.address, s.value_btc, s.created_date
                FROM v10_5_created_assert_chunk s
                LEFT JOIN utxo u
                  ON u.txid = s.txid
                 AND u.vout = s.vout
                 AND u.created_date = s.created_date
                WHERE u.txid IS NULL
                ORDER BY s.txid, s.vout
                LIMIT ?;
                """,
                [sample_limit - len(missing_sample)],
            ).fetchall()
            for txid, vout, address, value_btc, created_date in rows:
                missing_sample.append(
                    {
                        "txid": txid,
                        "vout": int(vout),
                        "address": address,
                        "value_btc": None if value_btc is None else float(value_btc),
                        "created_date": str(created_date),
                    }
                )

        mismatch = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM v10_5_created_assert_chunk s
                JOIN utxo u
                  ON u.txid = s.txid
                 AND u.vout = s.vout
                WHERE
                  u.created_date <> s.created_date
                  OR ABS(COALESCE(u.value_btc, 0.0) - COALESCE(s.value_btc, 0.0)) > ?
                  OR (
                    (u.address IS NULL AND s.address IS NOT NULL)
                    OR (u.address IS NOT NULL AND s.address IS NULL)
                    OR (u.address IS NOT NULL AND s.address IS NOT NULL AND u.address <> s.address)
                  );
                """,
                [value_eps],
            ).fetchone()[0]
        )
        mismatch_count += mismatch

        if mismatch and len(mismatch_sample) < sample_limit:
            rows = con.execute(
                """
                SELECT
                  s.txid,
                  s.vout,
                  s.address AS stage_address,
                  s.value_btc AS stage_value_btc,
                  s.created_date AS stage_created_date,
                  u.address AS db_address,
                  u.value_btc AS db_value_btc,
                  u.created_date AS db_created_date,
                  u.spent_date AS db_spent_date,
                  u.spent_txid AS db_spent_txid
                FROM v10_5_created_assert_chunk s
                JOIN utxo u
                  ON u.txid = s.txid
                 AND u.vout = s.vout
                WHERE
                  u.created_date <> s.created_date
                  OR ABS(COALESCE(u.value_btc, 0.0) - COALESCE(s.value_btc, 0.0)) > ?
                  OR (
                    (u.address IS NULL AND s.address IS NOT NULL)
                    OR (u.address IS NOT NULL AND s.address IS NULL)
                    OR (u.address IS NOT NULL AND s.address IS NOT NULL AND u.address <> s.address)
                  )
                ORDER BY s.txid, s.vout
                LIMIT ?;
                """,
                [value_eps, sample_limit - len(mismatch_sample)],
            ).fetchall()
            for row in rows:
                (
                    txid,
                    vout,
                    stage_address,
                    stage_value_btc,
                    stage_created_date,
                    db_address,
                    db_value_btc,
                    db_created_date,
                    db_spent_date,
                    db_spent_txid,
                ) = row
                mismatch_sample.append(
                    {
                        "txid": txid,
                        "vout": int(vout),
                        "stage_address": stage_address,
                        "stage_value_btc": None if stage_value_btc is None else float(stage_value_btc),
                        "stage_created_date": str(stage_created_date),
                        "db_address": db_address,
                        "db_value_btc": None if db_value_btc is None else float(db_value_btc),
                        "db_created_date": str(db_created_date),
                        "db_spent_date": None if db_spent_date is None else str(db_spent_date),
                        "db_spent_txid": db_spent_txid,
                    }
                )

        if start == 1 or end == created_stage_rows or ((start - 1) // chunk_rows + 1) % 10 == 0:
            _log(
                f"v10_5 post-assert created day={day} seq={start}-{end} "
                f"missing_chunk={miss} mismatch_chunk={mismatch}"
            )

        start = end + 1

    sum_diff_abs = abs(stage_sum - db_sum)
    sum_sats_diff = db_sum_sats - stage_sum_sats
    sum_sats_diff_abs = abs(sum_sats_diff)
    failed_checks: List[str] = []
    if stage_count != db_count:
        failed_checks.append("created_count_mismatch")
    if sum_sats_diff_abs != 0:
        failed_checks.append("created_sum_sats_mismatch")
    if missing_count > 0:
        failed_checks.append("created_stage_keys_missing_in_db")
    if mismatch_count > 0:
        failed_checks.append("created_stage_keys_poisoned_or_mismatched_in_db")

    report = {
        "enabled": True,
        "status": "ok" if not failed_checks else "fail",
        "failed_checks": failed_checks,
        "chunk_rows": chunk_rows,
        "value_eps": value_eps,
        "sum_eps": sum_eps,
        "stage_created_count": stage_count,
        "db_created_day_count": db_count,
        "sum_check_mode": "integer_sats",
        "stage_created_sum_btc": stage_sum,
        "db_created_day_sum_btc": db_sum,
        "sum_diff_abs": sum_diff_abs,
        "sum_diff_abs_double": sum_diff_abs,
        "sum_eps_double_informational_only": sum_eps,
        "stage_created_sum_sats": stage_sum_sats,
        "db_created_day_sum_sats": db_sum_sats,
        "sum_sats_diff": sum_sats_diff,
        "sum_sats_diff_abs": sum_sats_diff_abs,
        "sum_btc_diff_by_sats": sum_sats_diff / 100000000.0,
        "missing_stage_keys_in_db": missing_count,
        "mismatched_stage_keys_in_db": mismatch_count,
        "missing_sample": missing_sample,
        "mismatch_sample": mismatch_sample,
        "elapsed_sec": _toc(t0),
    }

    artifact = _v10_5_save_artifact(day, "post_apply_created_assert", report)
    report["artifact"] = str(artifact)
    _update_manifest(day, {"acceptance": {"v10_5_post_apply_created_assert": report}})

    if failed_checks and _env_bool("UTXO_V10_5_ABORT_ON_POST_ASSERT_FAIL", True):
        raise RuntimeError(f"v10_5 post-apply created assert failed day={day}: {failed_checks}; see {artifact}")

    _log(
        f"v10_5 post-apply created assert {report['status']} day={day} "
        f"stage_count={stage_count} db_count={db_count} "
        f"sum_diff_double={sum_diff_abs} sum_sats_diff={sum_sats_diff} "
        f"missing={missing_count} mismatch={mismatch_count} "
        f"in {_fmt_s(report['elapsed_sec'])}"
    )
    return report



def _v10_5_post_apply_warn_spends(
    con: duckdb.DuckDBPyConnection,
    day: str,
    spends_stage_rows: int,
) -> Dict[str, Any]:
    """
    v10_6-targeted-created-cleanup-r1

    Warning-only spends coverage report after apply.

    Disabled by default in v10_6 because this diagnostic can be expensive on
    large DuckDB files. Enable with UTXO_V10_5_POST_WARN_SPENDS=1 when needed.

    In an isolated single-day canonical replay this may report orphan prevouts
    because previous days can still be in old wtxid/raw_hash semantics. During a
    full replay from UTXO_CANONICAL_REPLACE_FROM to DB tail, these numbers should
    converge toward healthy values and can be made fatal with
    UTXO_V10_5_ABORT_ON_SPENDS_POST_ASSERT_FAIL=1.
    """
    if not _canonical_enabled_for_day(day):
        return {"enabled": False, "reason": "not canonical_map for day"}
    if not _env_bool("UTXO_V10_5_POST_WARN_SPENDS", False):
        return {"enabled": False, "reason": "UTXO_V10_5_POST_WARN_SPENDS=0"}

    t0 = _tic()
    chunk_rows = max(1, _env_int("UTXO_V10_5_SPENDS_POST_ASSERT_KEY_ROWS", _v10_5_spent_cleanup_rows()))
    sample_limit = max(0, _env_int("UTXO_V10_5_SPENDS_WARN_SAMPLE_LIMIT", 50))

    join_total = 0
    applied_match = 0
    open_joined = 0
    mismatch_joined = 0
    orphan_spends = 0
    orphan_sample: List[Dict[str, Any]] = []
    mismatch_sample: List[Dict[str, Any]] = []

    start = 1
    chunks = 0
    while start <= spends_stage_rows:
        end = min(start + chunk_rows - 1, spends_stage_rows)
        con.execute("DROP TABLE IF EXISTS v10_5_spends_assert_chunk")
        con.execute(
            """
            CREATE TEMP TABLE v10_5_spends_assert_chunk AS
            SELECT prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date
            FROM spends_apply_ready
            WHERE seq BETWEEN ? AND ?;
            """,
            [start, end],
        )
        chunk_count = int(con.execute("SELECT COUNT(*) FROM v10_5_spends_assert_chunk").fetchone()[0])
        if chunk_count <= 0:
            break

        vals = con.execute(
            """
            SELECT
              COUNT(*) FILTER (WHERE u.txid IS NOT NULL) AS joined,
              COUNT(*) FILTER (
                WHERE u.txid IS NOT NULL
                  AND u.spent_ts IS NOT NULL
                  AND COALESCE(lower(u.spent_txid), '') = COALESCE(lower(s.spent_txid), '')
                  AND COALESCE(u.spent_vin, -1) = COALESCE(s.spent_vin, -1)
                  AND COALESCE(u.spent_date, CAST(u.spent_ts AS DATE)) = s.spent_date
              ) AS matched,
              COUNT(*) FILTER (WHERE u.txid IS NOT NULL AND u.spent_ts IS NULL) AS open_joined,
              COUNT(*) FILTER (
                WHERE u.txid IS NOT NULL
                  AND u.spent_ts IS NOT NULL
                  AND (
                    COALESCE(lower(u.spent_txid), '') <> COALESCE(lower(s.spent_txid), '')
                    OR COALESCE(u.spent_vin, -1) <> COALESCE(s.spent_vin, -1)
                    OR COALESCE(u.spent_date, CAST(u.spent_ts AS DATE)) <> s.spent_date
                  )
              ) AS mismatch_joined,
              COUNT(*) FILTER (WHERE u.txid IS NULL) AS orphan
            FROM v10_5_spends_assert_chunk s
            LEFT JOIN utxo u
              ON u.txid = s.prev_txid AND u.vout = s.prev_vout;
            """
        ).fetchone()

        join_total += int(vals[0] or 0)
        applied_match += int(vals[1] or 0)
        open_joined += int(vals[2] or 0)
        mismatch_joined += int(vals[3] or 0)
        orphan_spends += int(vals[4] or 0)

        if len(orphan_sample) < sample_limit:
            rows = con.execute(
                """
                SELECT s.prev_txid, s.prev_vout, s.spent_txid, s.spent_vin, s.spent_date
                FROM v10_5_spends_assert_chunk s
                LEFT JOIN utxo u
                  ON u.txid = s.prev_txid AND u.vout = s.prev_vout
                WHERE u.txid IS NULL
                LIMIT ?;
                """,
                [sample_limit - len(orphan_sample)],
            ).fetchall()
            for prev_txid, prev_vout, spent_txid, spent_vin, spent_date in rows:
                orphan_sample.append({
                    "prev_txid": prev_txid,
                    "prev_vout": int(prev_vout),
                    "spent_txid": spent_txid,
                    "spent_vin": None if spent_vin is None else int(spent_vin),
                    "spent_date": None if spent_date is None else str(spent_date),
                })

        if len(mismatch_sample) < sample_limit:
            rows = con.execute(
                """
                SELECT
                  s.prev_txid, s.prev_vout, s.spent_txid, s.spent_vin, s.spent_date,
                  u.spent_txid AS db_spent_txid, u.spent_vin AS db_spent_vin, u.spent_date AS db_spent_date
                FROM v10_5_spends_assert_chunk s
                JOIN utxo u
                  ON u.txid = s.prev_txid AND u.vout = s.prev_vout
                WHERE u.spent_ts IS NOT NULL
                  AND (
                    COALESCE(lower(u.spent_txid), '') <> COALESCE(lower(s.spent_txid), '')
                    OR COALESCE(u.spent_vin, -1) <> COALESCE(s.spent_vin, -1)
                    OR COALESCE(u.spent_date, CAST(u.spent_ts AS DATE)) <> s.spent_date
                  )
                LIMIT ?;
                """,
                [sample_limit - len(mismatch_sample)],
            ).fetchall()
            for prev_txid, prev_vout, spent_txid, spent_vin, spent_date, db_spent_txid, db_spent_vin, db_spent_date in rows:
                mismatch_sample.append({
                    "prev_txid": prev_txid,
                    "prev_vout": int(prev_vout),
                    "stage_spent_txid": spent_txid,
                    "stage_spent_vin": None if spent_vin is None else int(spent_vin),
                    "stage_spent_date": None if spent_date is None else str(spent_date),
                    "db_spent_txid": db_spent_txid,
                    "db_spent_vin": None if db_spent_vin is None else int(db_spent_vin),
                    "db_spent_date": None if db_spent_date is None else str(db_spent_date),
                })

        chunks += 1
        if chunks == 1 or end == spends_stage_rows or chunks % 10 == 0:
            _log(
                f"v10_10 post-warn spends day={day} seq={start}-{end} "
                f"joined_total={join_total} orphan_total={orphan_spends} mismatch_total={mismatch_joined}"
            )

        start = end + 1

    orphan_pct = round((orphan_spends / spends_stage_rows * 100.0), 8) if spends_stage_rows else 0.0
    join_pct = round((join_total / spends_stage_rows * 100.0), 8) if spends_stage_rows else 0.0
    failed_checks: List[str] = []
    if orphan_spends > 0:
        failed_checks.append("orphan_spends_warning")
    if open_joined > 0:
        failed_checks.append("spends_left_open_warning")
    if mismatch_joined > 0:
        failed_checks.append("spends_mismatch_warning")

    report = {
        "enabled": True,
        "status": "ok" if not failed_checks else "warn",
        "failed_checks": failed_checks,
        "warning_only": True,
        "spends_stage_rows": spends_stage_rows,
        "chunk_rows": chunk_rows,
        "chunks": chunks,
        "join_total": join_total,
        "join_pct": join_pct,
        "applied_match": applied_match,
        "open_joined": open_joined,
        "mismatch_joined": mismatch_joined,
        "orphan_spends": orphan_spends,
        "orphan_pct": orphan_pct,
        "orphan_sample": orphan_sample,
        "mismatch_sample": mismatch_sample,
        "elapsed_sec": _toc(t0),
    }
    artifact = _v10_5_save_artifact(day, "post_apply_spends_warn", report)
    report["artifact"] = str(artifact)
    _update_manifest(day, {"acceptance": {"v10_10_post_apply_spends_warn": report}})

    if failed_checks and _env_bool("UTXO_V10_5_ABORT_ON_SPENDS_POST_ASSERT_FAIL", False):
        raise RuntimeError(f"v10_10 post-apply spends assert failed day={day}: {failed_checks}; see {artifact}")

    _log(
        f"v10_10 post-apply spends warn {report['status']} day={day} "
        f"stage={spends_stage_rows} joined={join_total} join_pct={join_pct}% "
        f"orphan={orphan_spends} orphan_pct={orphan_pct}% open={open_joined} mismatch={mismatch_joined} "
        f"in {_fmt_s(report['elapsed_sec'])}"
    )
    return report


# -----------------------------
# apply from stage parquet
# -----------------------------

def _apply_day_from_stage(con: duckdb.DuckDBPyConnection, day: str, manifest: Dict[str, Any], mode: str, run_cleanup_day: bool = False) -> Dict[str, Any]:
    t0 = _tic()
    created_path = Path(manifest["files"]["created_parquet"])
    spends_path = Path(manifest["files"]["spends_parquet"])
    if not created_path.exists() or not spends_path.exists():
        raise FileNotFoundError(f"stage parquet missing for day={day}")

    created_stage_rows_manifest = int(manifest.get("stage", {}).get("created_rows", 0))
    spends_stage_rows_manifest = int(manifest.get("stage", {}).get("spends_rows", 0))
    created_stage_rows = int(con.execute(f"SELECT COUNT(*) FROM read_parquet({_quote_sql_string(str(created_path))})").fetchone()[0])
    spends_stage_rows = int(con.execute(f"SELECT COUNT(*) FROM read_parquet({_quote_sql_string(str(spends_path))})").fetchone()[0])
    if created_stage_rows != created_stage_rows_manifest or spends_stage_rows != spends_stage_rows_manifest:
        _warn(
            f"stage row count mismatch day={day}: manifest created/spends={created_stage_rows_manifest}/{spends_stage_rows_manifest} "
            f"actual={created_stage_rows}/{spends_stage_rows}"
        )

    apply_created_rows = max(1, _env_int("UTXO_APPLY_CREATED_ROWS", _env_int("UTXO_BATCH_TX_ROWS", 100000)))
    apply_spent_rows_default = max(1, _env_int("UTXO_APPLY_SPENT_ROWS", _env_int("UTXO_BATCH_TX_ROWS", 100000)))
    apply_spent_rows = _v10_10_apply_spent_rows(apply_spent_rows_default)
    spends_profile = _v10_10_spends_profile()
    checkpoint_every_chunks = max(0, _env_int("UTXO_APPLY_CHECKPOINT_EVERY_CHUNKS", 0))
    _log(
        f"v10_10 apply profile day={day} spends_profile={spends_profile} "
        f"apply_created_rows={apply_created_rows} apply_spent_rows={apply_spent_rows} "
        f"env_apply_spent_rows_default={apply_spent_rows_default}"
    )

    _update_manifest(day, {"status": STATUS_PREAPPLY_GUARD})
    cleanup_day = None

    con.execute(
        f"""
        CREATE OR REPLACE TEMP TABLE created_apply_ready AS
        SELECT
          ROW_NUMBER() OVER (ORDER BY txid, vout) AS seq,
          txid, vout, address, value_btc, created_ts, created_date
        FROM read_parquet({_quote_sql_string(str(created_path))});
        """
    )
    con.execute(
        f"""
        CREATE OR REPLACE TEMP TABLE spends_apply_ready AS
        SELECT
          ROW_NUMBER() OVER (ORDER BY prev_txid, prev_vout) AS seq,
          prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date
        FROM read_parquet({_quote_sql_string(str(spends_path))});
        """
    )

    seq_checks = {
        "created": _seq_checks(con, "created_apply_ready"),
        "spends": _seq_checks(con, "spends_apply_ready"),
    }
    if not seq_checks["created"]["ok"]:
        raise RuntimeError(f"created seq checks failed day={day}: {seq_checks['created']}")
    if not seq_checks["spends"]["ok"]:
        raise RuntimeError(f"spends seq checks failed day={day}: {seq_checks['spends']}")
    if int(seq_checks["created"].get("count") or 0) != int(created_stage_rows):
        raise RuntimeError(
            f"created seq count mismatch day={day}: "
            f"seq_count={seq_checks['created'].get('count')} stage_rows={created_stage_rows}"
        )
    if int(seq_checks["spends"].get("count") or 0) != int(spends_stage_rows):
        raise RuntimeError(
            f"spends seq count mismatch day={day}: "
            f"seq_count={seq_checks['spends'].get('count')} stage_rows={spends_stage_rows}"
        )
    _log(
        f"v10_14 seq guard ok day={day} "
        f"created_count={seq_checks['created'].get('count')} spends_count={seq_checks['spends'].get('count')} "
        f"per_chunk_count=disabled"
    )

    # v10_17_2: final guards before any cleanup/apply mutation.
    # This catches cross-day txid:vout conflicts before either day cleanup or
    # stage-key cleanup can delete existing DB rows.
    duplicate_guard_global = _preapply_global_duplicate_guard(con, day, manifest)

    if run_cleanup_day:
        cleanup_day = _cleanup_day_safe(con, day)
        _log(f"cleanup day={day} status={cleanup_day['status']} in {_fmt_s(cleanup_day['elapsed_sec'])}")
        _update_manifest(
            day,
            {
                "cleanup": cleanup_day,
                "replay": {
                    "cleanup_after_preapply_guards": True,
                    "cleanup_status": cleanup_day.get("status"),
                    "cleanup_elapsed_sec": cleanup_day.get("elapsed_sec"),
                },
            },
        )

    _update_manifest(day, {"status": STATUS_APPLYING})

    v10_5_stage_key_cleanup = _v10_5_pre_apply_stage_key_cleanup(
        con,
        day,
        created_stage_rows,
        spends_stage_rows,
    )

    created_chunks = 0
    spends_chunks = 0
    created_apply_elapsed_sec = 0.0
    spends_apply_elapsed_sec = 0.0
    created_chunk_max_sec = 0.0
    spends_chunk_max_sec = 0.0
    created_assert_elapsed_sec = 0.0
    checkpoint_after_created_assert_elapsed_sec = 0.0
    spends_warn_elapsed_sec = 0.0
    _v10_10_log_memory(f"apply start day={day}", force=True)

    if created_stage_rows > 0:
        start = 1
        while start <= created_stage_rows:
            end = min(start + apply_created_rows - 1, created_stage_rows)
            t1 = _tic()
            # v10_12: seq density was verified once before the loops, so avoid
            # per-chunk COUNT(*) scans over created_apply_ready.
            chunk_rows = end - start + 1
            con.execute("BEGIN")
            try:
                con.execute(
                    """
                    INSERT INTO utxo (txid, vout, address, value_btc, created_ts, created_date)
                    SELECT txid, vout, address, value_btc, created_ts, created_date
                    FROM created_apply_ready
                    WHERE seq BETWEEN ? AND ?
                    ON CONFLICT (txid, vout) DO NOTHING;
                    """,
                    [start, end],
                )
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            created_chunks += 1
            chunk_elapsed = _toc(t1)
            created_apply_elapsed_sec += chunk_elapsed
            created_chunk_max_sec = max(created_chunk_max_sec, chunk_elapsed)
            _dbg(f"apply created day={day} seq={start}-{end} chunk_rows={chunk_rows} in {_fmt_s(chunk_elapsed)}")
            _v10_10_log_memory(f"apply created day={day} chunk={created_chunks}", chunk_index=created_chunks)
            if checkpoint_every_chunks > 0 and created_chunks % checkpoint_every_chunks == 0:
                con.execute("CHECKPOINT")
                _dbg(f"checkpoint created day={day} chunk={created_chunks} ok")
            start = end + 1

    if spends_stage_rows > 0:
        start = 1
        while start <= spends_stage_rows:
            end = min(start + apply_spent_rows - 1, spends_stage_rows)
            t2 = _tic()
            # v10_12: seq density was verified once before the loops, so avoid
            # per-chunk COUNT(*) scans over spends_apply_ready.
            chunk_rows = end - start + 1
            update_candidates: Optional[int] = None
            if _env_bool("UTXO_V10_5_LOG_SPENDS_UPDATE_CANDIDATES", False):
                # v10_10: optional diagnostic only. Disabled by default because this join can be expensive.
                update_candidates = int(con.execute(
                    """
                    SELECT COUNT(*)
                    FROM spends_apply_ready AS s
                    JOIN utxo AS u
                      ON u.txid = s.prev_txid
                     AND u.vout = s.prev_vout
                    WHERE s.seq BETWEEN ? AND ?
                      AND u.spent_ts IS NULL;
                    """,
                    [start, end],
                ).fetchone()[0])
            con.execute("BEGIN")
            try:
                con.execute(
                    """
                    UPDATE utxo AS u
                    SET
                      spent_ts   = s.spent_ts,
                      spent_date = s.spent_date,
                      spent_txid = s.spent_txid,
                      spent_vin  = s.spent_vin
                    FROM spends_apply_ready AS s
                    WHERE s.seq BETWEEN ? AND ?
                      AND u.txid = s.prev_txid
                      AND u.vout = s.prev_vout
                      AND u.spent_ts IS NULL;
                    """,
                    [start, end],
                )
                con.execute("COMMIT")
            except Exception:
                try:
                    con.execute("ROLLBACK")
                except Exception:
                    pass
                raise
            spends_chunks += 1
            chunk_elapsed = _toc(t2)
            spends_apply_elapsed_sec += chunk_elapsed
            spends_chunk_max_sec = max(spends_chunk_max_sec, chunk_elapsed)
            dbg_msg = f"apply spends day={day} seq={start}-{end} chunk_rows={chunk_rows}"
            if update_candidates is not None:
                dbg_msg += f" update_candidates={update_candidates}"
            _dbg(f"{dbg_msg} in {_fmt_s(chunk_elapsed)}")
            _v10_10_log_memory(f"apply spends day={day} chunk={spends_chunks}", chunk_index=spends_chunks)
            if checkpoint_every_chunks > 0 and spends_chunks % checkpoint_every_chunks == 0:
                con.execute("CHECKPOINT")
                _dbg(f"checkpoint spends day={day} chunk={spends_chunks} ok")
            start = end + 1

    assert_t0 = _tic()
    v10_5_created_assert = _v10_5_post_apply_assert_created(
        con,
        day,
        created_stage_rows,
    )
    created_assert_elapsed_sec = _toc(assert_t0)
    if _env_bool("UTXO_V10_5_CHECKPOINT_AFTER_CREATED_ASSERT", True):
        ck_t0 = _tic()
        con.execute("CHECKPOINT")
        checkpoint_after_created_assert_elapsed_sec = _toc(ck_t0)
        _log(f"v10_10 checkpoint after created assert day={day} ok in {_fmt_s(checkpoint_after_created_assert_elapsed_sec)}")

    try:
        spends_warn_t0 = _tic()
        v10_5_spends_warn = _v10_5_post_apply_warn_spends(
            con,
            day,
            spends_stage_rows,
        )
        spends_warn_elapsed_sec = _toc(spends_warn_t0)
    except Exception as e:
        spends_warn_elapsed_sec = _toc(spends_warn_t0) if 'spends_warn_t0' in locals() else 0.0
        # v10_10: spends warn is a best-effort diagnostic. It must not erase
        # the successful created/spends apply path unless the operator explicitly
        # requests fatal behavior.
        v10_5_spends_warn = {
            "enabled": True,
            "status": "error",
            "warning_only": True,
            "day": str(day),
            "stage_rows": int(spends_stage_rows or 0),
            "error_type": type(e).__name__,
            "error": str(e),
            "abort_on_fail": _env_bool("UTXO_V10_5_ABORT_ON_SPENDS_POST_ASSERT_FAIL", False),
            "pipeline_version": _pipeline_version(),
        }
        try:
            artifact = _v10_5_save_artifact(day, "post_apply_spends_warn_error", v10_5_spends_warn)
            v10_5_spends_warn["artifact"] = str(artifact)
            _update_manifest(day, {"acceptance": {"v10_10_post_apply_spends_warn": v10_5_spends_warn}})
        except Exception as artifact_exc:
            v10_5_spends_warn["artifact_error_type"] = type(artifact_exc).__name__
            v10_5_spends_warn["artifact_error"] = str(artifact_exc)
        _warn(
            f"v10_10 post-warn spends failed but apply continues day={day}: "
            f"{type(e).__name__}: {e}"
        )
        if _env_bool("UTXO_V10_5_ABORT_ON_SPENDS_POST_ASSERT_FAIL", False):
            raise

    apply_report = {
        "status": "ok",
        "elapsed_sec": _toc(t0),
        "created_stage_bytes": created_path.stat().st_size if created_path.exists() else 0,
        "spends_stage_bytes": spends_path.stat().st_size if spends_path.exists() else 0,
        "created_stage_rows": created_stage_rows,
        "spends_stage_rows": spends_stage_rows,
        "created_stage_rows_manifest": created_stage_rows_manifest,
        "spends_stage_rows_manifest": spends_stage_rows_manifest,
        "apply_created_rows": apply_created_rows,
        "apply_spent_rows": apply_spent_rows,
        "spends_profile": spends_profile,
        "created_assert_mode": _v10_10_created_assert_mode(),
        "created_chunks": created_chunks,
        "spends_chunks": spends_chunks,
        "apply_created_elapsed_sec": created_apply_elapsed_sec,
        "apply_spends_elapsed_sec": spends_apply_elapsed_sec,
        "created_chunk_max_sec": created_chunk_max_sec,
        "spends_chunk_max_sec": spends_chunk_max_sec,
        "created_assert_elapsed_sec": created_assert_elapsed_sec,
        "checkpoint_after_created_assert_elapsed_sec": checkpoint_after_created_assert_elapsed_sec,
        "spends_warn_elapsed_sec": spends_warn_elapsed_sec,
        "memory_after_apply": _v10_10_memory_report(),
        "seq_checks": seq_checks,
        "duplicate_guard_global": duplicate_guard_global,
        "cleanup_day": cleanup_day,
        "v10_5_stage_key_cleanup": v10_5_stage_key_cleanup,
        "v10_5_created_assert": v10_5_created_assert,
        "v10_10_spends_warn": v10_5_spends_warn,
    }
    perf_artifact = _v10_10_save_apply_performance(day, apply_report)
    if perf_artifact:
        apply_report["v10_10_apply_performance_artifact"] = perf_artifact
    _update_manifest(day, {"status": STATUS_APPLIED, "apply": apply_report})
    _log(
        f"apply day={day} created_stage={created_stage_rows} spends_stage={spends_stage_rows} "
        f"created_chunks={created_chunks} spends_chunks={spends_chunks} "
        f"spends_profile={spends_profile} apply_spent_rows={apply_spent_rows} "
        f"apply_created={_fmt_s(created_apply_elapsed_sec)} apply_spends={_fmt_s(spends_apply_elapsed_sec)} "
        f"created_assert={_fmt_s(created_assert_elapsed_sec)} in {_fmt_s(apply_report['elapsed_sec'])}"
    )
    return apply_report



def _seq_checks(con: duckdb.DuckDBPyConnection, table_name: str) -> Dict[str, Any]:
    row = con.execute(
        f"SELECT COUNT(*), MIN(seq), MAX(seq), COUNT(DISTINCT seq) FROM {table_name}"
    ).fetchone()
    count_rows = int(row[0])
    min_seq = int(row[1]) if row[1] is not None else None
    max_seq = int(row[2]) if row[2] is not None else None
    distinct_seq = int(row[3])
    ok = True
    if count_rows == 0:
        return {"ok": True, "count": 0, "min_seq": None, "max_seq": None, "distinct_seq": 0}
    if min_seq != 1:
        ok = False
    if max_seq != count_rows:
        ok = False
    if distinct_seq != count_rows:
        ok = False
    return {
        "ok": ok,
        "count": count_rows,
        "min_seq": min_seq,
        "max_seq": max_seq,
        "distinct_seq": distinct_seq,
    }


# -----------------------------
# raw/db audit (deep audit)
# -----------------------------

def _create_audit_tables(con: duckdb.DuckDBPyConnection) -> None:
    con.execute(
        """
        CREATE OR REPLACE TEMP TABLE audit_created_raw(
          txid VARCHAR,
          vout BIGINT,
          created_date DATE,
          value_raw DOUBLE,
          raw_type VARCHAR
        );
        """
    )
    con.execute(
        """
        CREATE OR REPLACE TEMP TABLE audit_spends_raw(
          prev_txid VARCHAR,
          prev_vout BIGINT,
          spent_txid VARCHAR,
          spent_vin BIGINT,
          spent_ts TIMESTAMP,
          spent_date DATE
        );
        """
    )


def _clear_audit_tables(con: duckdb.DuckDBPyConnection) -> None:
    con.execute("DELETE FROM audit_created_raw;")
    con.execute("DELETE FROM audit_spends_raw;")


def _audit_expected_value_expr() -> str:
    unit = _get_output_value_unit()
    if unit == "btc":
        return "value_raw"
    return "(value_raw / 100000000.0)"


def _audit_created_bip30_exception_report(
    con: duckdb.DuckDBPyConnection,
    day: str,
    expected_value_expr: str,
) -> Dict[str, Any]:
    """Return internal-audit allowance for known BIP30 duplicate coinbase outputs.

    v10_17_4-internal-audit-bip30-exception-r1.

    Main utxo is intentionally state-like with PRIMARY KEY(txid, vout), so the
    second historical BIP30 duplicate coinbase output cannot be represented as a
    separate row with created_date=day. This report is deliberately narrow:
      - only known BIP30 txids;
      - only early historical boundary;
      - DB must already contain the same key on another created_date;
      - integer-satoshi payload must match exactly;
      - no same-day DB row may already exist.

    It does not hide arbitrary missing rows. The caller must still verify that
    db + exception exactly equals raw stage count/sum.
    """
    empty = {
        "enabled": bool(_dup_guard_allow_bip30()),
        "status": "NOT_APPLICABLE",
        "keys": 0,
        "sats": 0,
        "examples": [],
    }
    if not _dup_guard_allow_bip30():
        return empty
    if str(day) > _dup_guard_bip30_max_date():
        return empty

    known = sorted(_dup_guard_known_bip30_txids())
    known_sql = "(" + ",".join(_quote_sql_string(x) for x in known) + ")" if known else "('__NO_KNOWN_BIP30_TXID__')"
    con.execute("DROP TABLE IF EXISTS audit_created_bip30_exception")
    con.execute(
        f"""
        CREATE TEMP TABLE audit_created_bip30_exception AS
        SELECT
          lower(r.txid) AS txid,
          CAST(r.vout AS BIGINT) AS vout,
          CAST(r.created_date AS DATE) AS stage_created_date,
          CAST(u.created_date AS DATE) AS db_created_date,
          CAST(round(COALESCE({expected_value_expr}, 0.0) * 100000000) AS BIGINT) AS stage_sats,
          CAST(round(COALESCE(u.value_btc, 0.0) * 100000000) AS BIGINT) AS db_sats,
          u.address AS db_address,
          u.spent_date AS db_spent_date
        FROM audit_created_stage r
        JOIN utxo u
          ON lower(u.txid) = lower(r.txid)
         AND CAST(u.vout AS BIGINT) = CAST(r.vout AS BIGINT)
        WHERE lower(r.txid) IN {known_sql}
          AND CAST(r.created_date AS DATE) = CAST({_quote_sql_string(day)} AS DATE)
          AND CAST(u.created_date AS DATE) <> CAST({_quote_sql_string(day)} AS DATE)
          AND NOT EXISTS (
              SELECT 1
              FROM utxo usame
              WHERE lower(usame.txid) = lower(r.txid)
                AND CAST(usame.vout AS BIGINT) = CAST(r.vout AS BIGINT)
                AND CAST(usame.created_date AS DATE) = CAST({_quote_sql_string(day)} AS DATE)
          )
          AND CAST(round(COALESCE({expected_value_expr}, 0.0) * 100000000) AS BIGINT)
              = CAST(round(COALESCE(u.value_btc, 0.0) * 100000000) AS BIGINT)
        """
    )
    keys, sats = con.execute(
        """
        SELECT
          COUNT(*) AS keys,
          COALESCE(SUM(stage_sats), 0) AS sats
        FROM audit_created_bip30_exception
        """
    ).fetchone()
    keys_i = int(keys or 0)
    sats_i = int(sats or 0)
    rows = con.execute(
        """
        SELECT txid, vout, stage_created_date, db_created_date, stage_sats, db_sats, db_spent_date
        FROM audit_created_bip30_exception
        ORDER BY txid, vout
        LIMIT 20
        """
    ).fetchall()
    examples = [
        {
            "txid": str(r[0]),
            "vout": int(r[1]),
            "stage_created_date": str(r[2]),
            "db_created_date": str(r[3]),
            "stage_sats": int(r[4] or 0),
            "db_sats": int(r[5] or 0),
            "db_spent_date": None if r[6] is None else str(r[6]),
        }
        for r in rows
    ]
    return {
        "enabled": True,
        "status": STATUS_OK_WITH_BIP30_EXCEPTION if keys_i > 0 else "NOT_APPLICABLE",
        "keys": keys_i,
        "sats": sats_i,
        "known_txids": known,
        "max_date": _dup_guard_bip30_max_date(),
        "examples": examples,
    }


def _audit_insert_created_sql(day: str) -> str:
    txid_expr = _canonical_txid_expr(day, "t")
    map_join = _canonical_map_join_sql(day, "t")
    return f"""
    INSERT INTO audit_created_raw(txid, vout, created_date, value_raw, raw_type)
    SELECT
      {txid_expr} AS txid,
      out.index::BIGINT AS vout,
      CAST(t.date AS DATE) AS created_date,
      CAST(out.value AS DOUBLE) AS value_raw,
      typeof(out.value) AS raw_type
    FROM read_parquet(?) t
    {map_join}
    CROSS JOIN UNNEST(t.outputs) AS o(out);
    """

def _audit_created_dedup_sql(src_table: str, dst_table: str) -> str:
    return f"""
    CREATE OR REPLACE TEMP TABLE {dst_table} AS
    SELECT
      txid,
      vout,
      MIN(created_date) AS created_date,
      MIN(value_raw) AS value_raw,
      MIN(raw_type) AS raw_type
    FROM {src_table}
    GROUP BY 1,2;
    """


def _audit_insert_spends_sql(day: str) -> str:
    spent_txid_expr = _canonical_txid_expr(day, "t")
    map_join = _canonical_map_join_sql(day, "t")
    return f"""
    INSERT INTO audit_spends_raw(prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date)
    SELECT prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date
    FROM (
      SELECT
        lower(inp.spent_transaction_hash::VARCHAR) AS prev_txid,
        inp.spent_output_index::BIGINT AS prev_vout,
        {spent_txid_expr} AS spent_txid,
        inp.index::BIGINT AS spent_vin,
        t.block_timestamp AS spent_ts,
        CAST(t.date AS DATE) AS spent_date,
        ROW_NUMBER() OVER (
          PARTITION BY lower(inp.spent_transaction_hash::VARCHAR), inp.spent_output_index
          ORDER BY t.block_timestamp, {spent_txid_expr}, inp.index
        ) AS rn
      FROM read_parquet(?) t
      {map_join}
      CROSS JOIN UNNEST(t.inputs) AS u(inp)
      WHERE NOT COALESCE(t.is_coinbase, false)
        AND inp.spent_transaction_hash IS NOT NULL
        AND inp.spent_output_index IS NOT NULL
    ) x
    WHERE rn = 1;
    """



def _audit_orphan_spends_max_rate() -> float:
    """Return orphan-spends acceptance rate as a fraction.

    v10_17_6-source-gap-prod-hardening-r1.

    Operators may set either a fraction or a human percent:
      - 0.06 -> 6%
      - 6    -> 6%
      - 1    -> 1% (v10_17_6 change; avoids the old 100% footgun)
    """
    raw = _env_float("UTXO_AUDIT_ORPHAN_SPENDS_MAX_RATE", 0.06)
    if raw < 0.0:
        return 0.0
    if raw >= 1.0:
        return raw / 100.0
    return raw


def _audit_orphan_spends_max_count() -> int:
    return max(0, _env_int("UTXO_AUDIT_ORPHAN_SPENDS_MAX_COUNT", 100000))


def _audit_orphan_gap_acceptance_scope(day: str) -> Dict[str, Any]:
    """Production gate for source coverage gap acceptance.

    Raw/pre-canonical windows can accept small source gaps by default. Anything
    at or after the canonical boundary is stricter because orphan prevouts can
    indicate txid-map/keyspace/canonical-filter problems rather than a simple
    raw source coverage gap.
    """
    base_enabled = _env_bool("UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP", True)
    canonical_boundary_day = str(day) >= _canonical_replace_from()
    canonical_day = bool(_canonical_enabled_for_day(day))
    canonical_enabled = _env_bool("UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP_CANONICAL", False)
    post_canonical_enabled = _env_bool("UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP_POST_CANONICAL", False)
    if canonical_day and not canonical_enabled:
        return {
            "enabled": False,
            "base_enabled": base_enabled,
            "canonical_enabled": canonical_enabled,
            "post_canonical_enabled": post_canonical_enabled,
            "canonical_boundary_day": canonical_boundary_day,
            "canonical_enabled_for_day": canonical_day,
            "scope": "canonical_map_blocked_by_default",
            "disabled_reason": "canonical_map_requires_UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP_CANONICAL_1",
        }
    if canonical_boundary_day and not canonical_day and not post_canonical_enabled:
        return {
            "enabled": False,
            "base_enabled": base_enabled,
            "canonical_enabled": canonical_enabled,
            "post_canonical_enabled": post_canonical_enabled,
            "canonical_boundary_day": canonical_boundary_day,
            "canonical_enabled_for_day": canonical_day,
            "scope": "post_canonical_boundary_blocked_by_default",
            "disabled_reason": "post_canonical_boundary_requires_UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP_POST_CANONICAL_1",
        }
    if canonical_day:
        scope = "canonical_map_explicit"
    elif canonical_boundary_day:
        scope = "raw_hash_post_canonical_explicit"
    else:
        scope = "raw_hash_pre_canonical"
    return {
        "enabled": bool(base_enabled),
        "base_enabled": base_enabled,
        "canonical_enabled": canonical_enabled,
        "post_canonical_enabled": post_canonical_enabled,
        "canonical_boundary_day": canonical_boundary_day,
        "canonical_enabled_for_day": canonical_day,
        "scope": scope,
        "disabled_reason": None if base_enabled else "UTXO_AUDIT_ACCEPT_ORPHAN_SPENDS_GAP_0",
    }


def _audit_created_clean_for_source_gap(
    *,
    enable_count_created: bool,
    enable_integrity: bool,
    raw_created_count: Optional[int],
    created_effective_db_count: Optional[int],
    created_missing_count: Optional[int],
    created_effective_sum_sats_diff: Optional[int],
) -> Dict[str, Any]:
    """Explicit created-state cleanliness gate for orphan source-gap acceptance."""
    require_created_clean = _env_bool("UTXO_AUDIT_SOURCE_GAP_REQUIRE_CREATED_CLEAN", True)
    checks_available = bool((enable_count_created or enable_integrity) and raw_created_count is not None)
    count_ok = checks_available and created_effective_db_count == raw_created_count
    missing_ok = checks_available and created_missing_count == 0
    sum_ok = checks_available and created_effective_sum_sats_diff == 0
    ok = (not require_created_clean) or (checks_available and count_ok and missing_ok and sum_ok)
    failed: List[str] = []
    if require_created_clean and not checks_available:
        failed.append("created_checks_not_available")
    if require_created_clean and checks_available and not count_ok:
        failed.append("created_effective_count_not_clean")
    if require_created_clean and checks_available and not missing_ok:
        failed.append("created_missing_not_clean")
    if require_created_clean and checks_available and not sum_ok:
        failed.append("created_effective_sum_not_clean")
    return {
        "required": bool(require_created_clean),
        "ok": bool(ok),
        "checks_available": bool(checks_available),
        "failed_checks": failed,
        "raw_created_count": raw_created_count,
        "effective_db_created_count": created_effective_db_count,
        "created_missing_count": created_missing_count,
        "effective_created_sum_sats_diff": created_effective_sum_sats_diff,
    }


def _audit_save_orphan_spends_artifacts(
    con: duckdb.DuckDBPyConnection,
    day: str,
    *,
    raw_spends_count: Optional[int],
    orphan_spends_count: Optional[int],
    orphan_spends_rate: Optional[float],
    max_orphan_rate: float,
    max_orphan_count: int,
    scope: str,
) -> Dict[str, Any]:
    """Persist orphan-spends evidence before stage purge.

    The sample is intentionally small and stored under UTXO_AUDIT_DIR, not in
    stage, so it survives purge of created.parquet/spends.parquet after an
    accepted AUDITED_OK day.
    """
    enabled = _env_bool("UTXO_AUDIT_SAVE_ORPHAN_SPENDS_ARTIFACT", True)
    sample_rows = max(0, _env_int("UTXO_AUDIT_ORPHAN_SPENDS_SAMPLE_ROWS", 1000))
    report: Dict[str, Any] = {
        "enabled": bool(enabled),
        "status": "DISABLED" if not enabled else "NOT_APPLICABLE",
        "sample_rows_limit": sample_rows,
        "sample_rows_written": 0,
        "sample_path": None,
        "summary_path": None,
    }
    if not enabled:
        return report
    if not orphan_spends_count or orphan_spends_count <= 0:
        return report

    summary_path = _v10_5_artifact_path(day, "orphan_spends_summary", ".json")
    sample_path = _v10_5_artifact_path(day, "orphan_spends_sample", ".parquet")
    sample_written = 0
    if sample_rows > 0:
        tmp = _tmp_path(sample_path)
        con.execute(
            f"""
            COPY (
              SELECT
                s.prev_txid,
                s.prev_vout,
                s.spent_txid,
                s.spent_vin,
                s.spent_date
              FROM audit_spends_stage s
              WHERE NOT EXISTS (
                SELECT 1
                FROM utxo u
                WHERE u.txid = s.prev_txid
                  AND u.vout = s.prev_vout
              )
              ORDER BY s.prev_txid, s.prev_vout, s.spent_txid, s.spent_vin
              LIMIT {int(sample_rows)}
            ) TO {_quote_sql_string(str(tmp))} (FORMAT PARQUET, COMPRESSION ZSTD)
            """
        )
        os.replace(tmp, sample_path)
        sample_written = min(int(orphan_spends_count), sample_rows)

    payload = {
        "artifact": "orphan_spends_summary",
        "pipeline_version": _pipeline_version(),
        "day": str(day),
        "scope": scope,
        "raw_spends_count": raw_spends_count,
        "orphan_spends_count": orphan_spends_count,
        "orphan_spends_rate": orphan_spends_rate,
        "orphan_spends_rate_pct": round(float(orphan_spends_rate or 0.0) * 100.0, 8),
        "max_orphan_spends_rate": max_orphan_rate,
        "max_orphan_spends_rate_pct": round(float(max_orphan_rate) * 100.0, 8),
        "max_orphan_spends_count": max_orphan_count,
        "sample_rows_limit": sample_rows,
        "sample_rows_written": sample_written,
        "sample_path": str(sample_path) if sample_rows > 0 else None,
        "created_at": _now_iso(),
    }
    _save_json_atomic(summary_path, payload)
    report.update(
        {
            "status": "WRITTEN",
            "sample_rows_written": sample_written,
            "sample_path": str(sample_path) if sample_rows > 0 else None,
            "summary_path": str(summary_path),
        }
    )
    return report


def _audit_day(con: duckdb.DuckDBPyConnection, raw_base: str, day: str, mode: str) -> Dict[str, Any]:
    t0 = _tic()
    failed_checks: List[str] = []
    notes: List[str] = []

    enable_count_created = _audit_enabled(mode, "UTXO_ENABLE_COUNT_CREATED")
    enable_spent_stats = _audit_enabled(mode, "UTXO_ENABLE_SPENT_STATS")
    enable_integrity = _audit_enabled(mode, "UTXO_ENABLE_INTEGRITY_CHECK")
    min_raw_spends = _env_int("UTXO_AUDIT_MIN_RAW_SPENDS", 1000)
    skipped_checks: List[str] = []
    if not (enable_count_created or enable_integrity):
        skipped_checks.append("created_counts")
    if not (enable_spent_stats or enable_integrity):
        skipped_checks.append("spent_stats")

    _create_audit_tables(con)
    _clear_audit_tables(con)

    files = _day_parquet_files(raw_base, day)
    if not files:
        return {
            "status": "fail",
            "failed_checks": ["raw_files_missing"],
            "notes": ["No parquet files found for day"],
            "elapsed_sec": _toc(t0),
        }
    if _canonical_enabled_for_day(day):
        _assert_txid_map_exists(day)
        txid_map_audit = _audit_txid_map_day(raw_base, day)
        if txid_map_audit.get("status") != "ok" and _env_bool("UTXO_TXID_MAP_STRICT", True):
            return {
                "status": "fail",
                "failed_checks": ["txid_map_audit_failed"],
                "notes": [json.dumps(txid_map_audit, ensure_ascii=False, sort_keys=True)],
                "elapsed_sec": _toc(t0),
            }

    for fp in files:
        feats = _inspect_parquet_features(fp)
        if feats.has_outputs:
            con.execute(_audit_insert_created_sql(day), [fp])
        if feats.has_inputs and feats.input_has_prevout:
            con.execute(_audit_insert_spends_sql(day), [fp])

    dup_created_before = int(con.execute(_dup_count_sql("audit_created_raw", "txid", "vout")).fetchone()[0])
    con.execute(_audit_created_dedup_sql("audit_created_raw", "audit_created_stage"))
    dup_spends_before = int(con.execute(_dup_count_sql("audit_spends_raw", "prev_txid", "prev_vout")).fetchone()[0])
    _warn_duplicates("audit_raw", day, dup_created_before, dup_spends_before)
    con.execute(_spends_dedup_sql("audit_spends_raw", "audit_spends_stage"))

    raw_created_count = db_created_count = created_missing_count = None
    raw_spends_count = db_spent_count = spends_join_total = spends_join_open = spends_mismatch_count = orphan_spends_count = None
    orphan_spends_rate = None
    source_coverage_gap: Dict[str, Any] = {"status": "NOT_EVALUATED", "enabled": False}
    raw_created_sum_btc_expected = db_created_sum_btc = None
    raw_created_sum_sats_expected = db_created_sum_sats = None
    created_sum_sats_diff = None
    created_effective_db_count = None
    created_effective_db_sum_sats = None
    created_effective_sum_sats_diff = None
    created_bip30_exception: Dict[str, Any] = {"status": "NOT_EVALUATED", "keys": 0, "sats": 0, "examples": []}
    created_raw_types: List[str] = []

    if enable_count_created or enable_integrity:
        raw_created_count = int(con.execute("SELECT COUNT(*) FROM audit_created_stage").fetchone()[0])
        created_raw_types = sorted(set(r[0] for r in con.execute("SELECT DISTINCT raw_type FROM audit_created_stage").fetchall()))
        expected_value_expr = _audit_expected_value_expr()
        raw_created_sum_btc_expected = float(con.execute(
            f"SELECT COALESCE(SUM({expected_value_expr}), 0.0) FROM audit_created_stage"
        ).fetchone()[0])
        raw_created_sum_sats_expected = int(con.execute(
            f"""
            SELECT COALESCE(SUM(CAST(round(COALESCE({expected_value_expr}, 0.0) * 100000000) AS BIGINT)), 0)
            FROM audit_created_stage
            """
        ).fetchone()[0])
        db_created_count = int(con.execute("SELECT COUNT(*) FROM utxo WHERE created_date = ?::DATE", [day]).fetchone()[0])
        db_created_sum_btc = float(
            con.execute(
                "SELECT COALESCE(SUM(value_btc), 0.0) FROM utxo WHERE created_date = ?::DATE",
                [day],
            ).fetchone()[0]
        )
        db_created_sum_sats = int(
            con.execute(
                """
                SELECT COALESCE(SUM(CAST(round(COALESCE(value_btc, 0.0) * 100000000) AS BIGINT)), 0)
                FROM utxo
                WHERE created_date = ?::DATE
                """,
                [day],
            ).fetchone()[0]
        )
        created_sum_sats_diff = db_created_sum_sats - raw_created_sum_sats_expected
        created_missing_count = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM audit_created_stage r
                WHERE NOT EXISTS (
                  SELECT 1 FROM utxo u WHERE u.txid = r.txid AND u.vout = r.vout
                );
                """
            ).fetchone()[0]
        )
        created_bip30_exception = _audit_created_bip30_exception_report(con, day, expected_value_expr)
        created_effective_db_count = db_created_count + int(created_bip30_exception.get("keys") or 0)
        created_effective_db_sum_sats = db_created_sum_sats + int(created_bip30_exception.get("sats") or 0)
        created_effective_sum_sats_diff = created_effective_db_sum_sats - raw_created_sum_sats_expected
        created_count_ok = db_created_count == raw_created_count
        created_count_ok_with_bip30 = (
            (not created_count_ok)
            and int(created_bip30_exception.get("keys") or 0) > 0
            and created_effective_db_count == raw_created_count
        )
        created_sum_ok = created_sum_sats_diff == 0
        created_sum_ok_with_bip30 = (
            (not created_sum_ok)
            and int(created_bip30_exception.get("sats") or 0) > 0
            and created_effective_sum_sats_diff == 0
        )
        if created_missing_count > 0:
            failed_checks.append("created_missing_after_write")
            notes.append(f"created_missing_count={created_missing_count}")
        if not (created_count_ok or created_count_ok_with_bip30):
            failed_checks.append("created_count_mismatch")
            notes.append(
                f"db_created_count={db_created_count} raw_created_count={raw_created_count} "
                f"effective_db_created_count={created_effective_db_count} "
                f"bip30_exception_keys={int(created_bip30_exception.get('keys') or 0)}"
            )
        elif created_count_ok_with_bip30:
            notes.append(
                f"created_count_mismatch accepted as {STATUS_OK_WITH_BIP30_EXCEPTION}: "
                f"db_created_count={db_created_count} + bip30_exception_keys={int(created_bip30_exception.get('keys') or 0)} "
                f"= raw_created_count={raw_created_count}"
            )
        if not (created_sum_ok or created_sum_ok_with_bip30):
            failed_checks.append("created_sum_sats_mismatch")
            notes.append(
                "db_created_sum_sats="
                f"{db_created_sum_sats} raw_created_sum_sats_expected={raw_created_sum_sats_expected} "
                f"created_sum_sats_diff={created_sum_sats_diff} "
                f"effective_db_created_sum_sats={created_effective_db_sum_sats} "
                f"effective_created_sum_sats_diff={created_effective_sum_sats_diff} "
                f"bip30_exception_sats={int(created_bip30_exception.get('sats') or 0)}"
            )
        elif created_sum_ok_with_bip30:
            notes.append(
                f"created_sum_sats_mismatch accepted as {STATUS_OK_WITH_BIP30_EXCEPTION}: "
                f"db_created_sum_sats={db_created_sum_sats} + bip30_exception_sats={int(created_bip30_exception.get('sats') or 0)} "
                f"= raw_created_sum_sats_expected={raw_created_sum_sats_expected}"
            )

    if enable_spent_stats or enable_integrity:
        raw_spends_count = int(con.execute("SELECT COUNT(*) FROM audit_spends_stage").fetchone()[0])
        db_spent_count = int(con.execute("SELECT COUNT(*) FROM utxo WHERE spent_date = ?::DATE", [day]).fetchone()[0])
        spends_join_total = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM audit_spends_stage s
                JOIN utxo u ON u.txid = s.prev_txid AND u.vout = s.prev_vout;
                """
            ).fetchone()[0]
        )
        spends_join_open = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM audit_spends_stage s
                JOIN utxo u ON u.txid = s.prev_txid AND u.vout = s.prev_vout
                WHERE u.spent_ts IS NULL;
                """
            ).fetchone()[0]
        )
        spends_mismatch_count = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM audit_spends_stage s
                JOIN utxo u ON u.txid = s.prev_txid AND u.vout = s.prev_vout
                WHERE u.spent_ts IS NOT NULL
                  AND (
                    COALESCE(lower(u.spent_txid), '') <> COALESCE(lower(s.spent_txid), '')
                    OR COALESCE(u.spent_vin, -1) <> COALESCE(s.spent_vin, -1)
                    OR COALESCE(u.spent_date, CAST(u.spent_ts AS DATE)) <> s.spent_date
                  );
                """
            ).fetchone()[0]
        )
        orphan_spends_count = int(
            con.execute(
                """
                SELECT COUNT(*)
                FROM audit_spends_stage s
                WHERE NOT EXISTS (
                  SELECT 1 FROM utxo u WHERE u.txid = s.prev_txid AND u.vout = s.prev_vout
                );
                """
            ).fetchone()[0]
        )

        if raw_spends_count >= min_raw_spends and spends_join_total < raw_spends_count:
            failed_checks.append("spends_join_total_too_small")
            notes.append(f"raw_spends={raw_spends_count} spends_join_total={spends_join_total}")
        if spends_join_open > 0:
            failed_checks.append("spends_left_open_after_write")
            notes.append(f"spends_join_open={spends_join_open}")
        if spends_mismatch_count > 0:
            failed_checks.append("spends_mismatch_after_write")
            notes.append(f"spends_mismatch_count={spends_mismatch_count}")
        if orphan_spends_count > 0:
            failed_checks.append("orphan_spends")
            notes.append(f"orphan_spends_count={orphan_spends_count}")
        if db_spent_count != spends_join_total:
            failed_checks.append("db_spent_count_mismatch")
            notes.append(f"db_spent_count={db_spent_count} spends_join_total={spends_join_total}")

        if raw_spends_count and raw_spends_count > 0:
            orphan_spends_rate = float(orphan_spends_count or 0) / float(raw_spends_count)
        else:
            orphan_spends_rate = 0.0

        scope_report = _audit_orphan_gap_acceptance_scope(day)
        accept_source_gap = bool(scope_report.get("enabled"))
        max_orphan_rate = _audit_orphan_spends_max_rate()
        max_orphan_count = _audit_orphan_spends_max_count()
        created_clean_report = _audit_created_clean_for_source_gap(
            enable_count_created=enable_count_created,
            enable_integrity=enable_integrity,
            raw_created_count=raw_created_count,
            created_effective_db_count=created_effective_db_count,
            created_missing_count=created_missing_count,
            created_effective_sum_sats_diff=created_effective_sum_sats_diff,
        )
        allowed_source_gap_failures = {"spends_join_total_too_small", "orphan_spends"}
        failure_set = set(failed_checks)
        source_gap_candidate = (
            accept_source_gap
            and bool(created_clean_report.get("ok"))
            and orphan_spends_count is not None
            and orphan_spends_count > 0
            and raw_spends_count is not None
            and raw_spends_count >= min_raw_spends
            and spends_join_open == 0
            and spends_mismatch_count == 0
            and failure_set
            and failure_set.issubset(allowed_source_gap_failures)
        )
        count_ok = max_orphan_count <= 0 or int(orphan_spends_count or 0) <= max_orphan_count
        rate_ok = orphan_spends_rate is not None and orphan_spends_rate <= max_orphan_rate
        orphan_artifacts = _audit_save_orphan_spends_artifacts(
            con,
            day,
            raw_spends_count=raw_spends_count,
            orphan_spends_count=orphan_spends_count,
            orphan_spends_rate=orphan_spends_rate,
            max_orphan_rate=max_orphan_rate,
            max_orphan_count=max_orphan_count,
            scope=str(scope_report.get("scope") or "unknown"),
        )
        source_coverage_gap = {
            "enabled": accept_source_gap,
            "base_enabled": scope_report.get("base_enabled"),
            "canonical_enabled": scope_report.get("canonical_enabled"),
            "post_canonical_enabled": scope_report.get("post_canonical_enabled"),
            "canonical_boundary_day": scope_report.get("canonical_boundary_day"),
            "canonical_enabled_for_day": scope_report.get("canonical_enabled_for_day"),
            "scope": scope_report.get("scope"),
            "disabled_reason": scope_report.get("disabled_reason"),
            "status": "NOT_APPLICABLE",
            "accepted": False,
            "candidate": bool(source_gap_candidate),
            "orphan_spends_count": orphan_spends_count,
            "raw_spends_count": raw_spends_count,
            "orphan_spends_rate": orphan_spends_rate,
            "orphan_spends_rate_pct": round(float(orphan_spends_rate or 0.0) * 100.0, 8),
            "max_orphan_spends_rate": max_orphan_rate,
            "max_orphan_spends_rate_pct": round(float(max_orphan_rate) * 100.0, 8),
            "max_orphan_spends_count": max_orphan_count,
            "spends_join_open": spends_join_open,
            "spends_mismatch_count": spends_mismatch_count,
            "min_raw_spends": min_raw_spends,
            "rate_ok": bool(rate_ok),
            "count_ok": bool(count_ok),
            "created_clean": created_clean_report,
            "artifacts": orphan_artifacts,
        }
        if source_gap_candidate and count_ok and rate_ok:
            failed_checks = []
            source_coverage_gap["status"] = STATUS_OK_WITH_SOURCE_COVERAGE_GAP
            source_coverage_gap["accepted"] = True
            notes.append(
                f"spends orphan coverage gap accepted as {STATUS_OK_WITH_SOURCE_COVERAGE_GAP}: "
                f"scope={source_coverage_gap['scope']} orphan_spends_count={orphan_spends_count} "
                f"raw_spends_count={raw_spends_count} orphan_rate={orphan_spends_rate:.8f} "
                f"max_rate={max_orphan_rate:.8f} max_rate_pct={max_orphan_rate * 100.0:.4f} "
                f"max_count={max_orphan_count} (0 disables count cap)"
            )
        elif source_gap_candidate:
            source_coverage_gap["status"] = "REJECTED_BY_THRESHOLD"
        elif orphan_spends_count and orphan_spends_count > 0 and set(failed_checks).issubset(allowed_source_gap_failures):
            if not accept_source_gap:
                source_coverage_gap["status"] = "REJECTED_BY_SCOPE_OR_DISABLED"
            elif not bool(created_clean_report.get("ok")):
                source_coverage_gap["status"] = "REJECTED_CREATED_NOT_CLEAN"
            else:
                source_coverage_gap["status"] = "REJECTED_NOT_CANDIDATE"

    status = "ok" if not failed_checks else "fail"
    return {
        "status": status,
        "failed_checks": failed_checks,
        "skipped_checks": skipped_checks,
        "audit_flags": {
            "enable_count_created": enable_count_created,
            "enable_spent_stats": enable_spent_stats,
            "enable_integrity_check": enable_integrity,
        },
        "notes": notes,
        "output_value_unit": _get_output_value_unit(),
        "txid_mode": _get_txid_mode(),
        "canonical_enabled_for_day": _canonical_enabled_for_day(day),
        "created_raw_types": created_raw_types,
        "raw_created_count": raw_created_count,
        "db_created_count": db_created_count,
        "created_missing_count": created_missing_count,
        "created_sum_check_mode": "integer_sats",
        "raw_created_sum_btc_expected": raw_created_sum_btc_expected,
        "db_created_sum_btc": db_created_sum_btc,
        "raw_created_sum_sats_expected": raw_created_sum_sats_expected,
        "db_created_sum_sats": db_created_sum_sats,
        "created_sum_sats_diff": created_sum_sats_diff,
        "effective_db_created_count": created_effective_db_count,
        "effective_db_created_sum_sats": created_effective_db_sum_sats,
        "effective_created_sum_sats_diff": created_effective_sum_sats_diff,
        "created_bip30_exception": created_bip30_exception,
        "raw_spends_count": raw_spends_count,
        "db_spent_count": db_spent_count,
        "spends_join_total": spends_join_total,
        "spends_join_open": spends_join_open,
        "spends_mismatch_count": spends_mismatch_count,
        "orphan_spends_count": orphan_spends_count,
        "orphan_spends_rate": orphan_spends_rate,
        "source_coverage_gap": source_coverage_gap,
        "duplicate_raw_spends_before_dedup": dup_spends_before,
        "elapsed_sec": _toc(t0),
    }


# -----------------------------
# purge stage
# -----------------------------

def _purge_stage(day: str) -> Dict[str, Any]:
    created_path = _created_stage_path(day)
    spends_path = _spends_stage_path(day)
    deleted_created = False
    deleted_spends = False
    if created_path.exists():
        created_path.unlink()
        deleted_created = True
    if spends_path.exists():
        spends_path.unlink()
        deleted_spends = True
    patch = {
        "purge": {
            "eligible": True,
            "purged": deleted_created or deleted_spends,
            "purged_at": _now_iso(),
            "created_parquet_deleted": deleted_created,
            "spends_parquet_deleted": deleted_spends,
        }
    }
    _update_manifest(day, patch)
    return patch["purge"]


# -----------------------------
# engine
# -----------------------------

def _mark_failed(day: str, exc: Exception) -> None:
    if _CURRENT_MODE == MODE_AUDIT_ONLY and not _audit_only_write_manifest_enabled():
        _warn(
            f"AUDIT_ONLY failure manifest write skipped day={day}; "
            f"UTXO_AUDIT_ONLY_WRITE_MANIFEST=0 error={type(exc).__name__}: {exc}"
        )
        return
    try:
        manifest = _load_manifest(day) or _manifest_base(day, _CURRENT_MODE or _resolve_mode(None))
        errors = list(manifest.get("errors", []))
        errors.append(
            {
                "at": _now_iso(),
                "type": type(exc).__name__,
                "class": _classify_exception(exc),
                "message": str(exc),
            }
        )
        _update_manifest(day, {"status": STATUS_FAILED, "errors": errors})
    except Exception:
        pass


def _verify_manifests() -> int:
    failures = 0
    checked = 0
    for p in sorted(_stage_root().rglob("manifest.json")):
        day = p.parent.name.split("=", 1)[-1]
        checked += 1
        result = _verify_manifest_files(day)
        if result["status"] != "ok":
            failures += 1
            _warn(f"manifest verify fail day={day}: {', '.join(result.get('failed_checks', []))}")
    _log(f"verify manifests checked={checked} failures={failures}")
    return 0 if failures == 0 else 4


def _verify_units(raw_base: str, db_path: str, days: Sequence[str]) -> int:
    if not days:
        _log("verify units: no days to check")
        return 0
    con = duckdb.connect(db_path, read_only=True)
    try:
        sample_limit = _semantic_sample_limit()
        failures = 0
        checked = 0
        expected_bucket = "same_unit" if _get_output_value_unit() == "btc" else "scaled_1e8"
        for day in days:
            files = _day_parquet_files(raw_base, day)
            if not files:
                continue
            rows_acc: List[Tuple[str, int, float, str]] = []
            for fp in files:
                remaining = sample_limit - len(rows_acc)
                if remaining <= 0:
                    break
                rows_acc.extend(_sample_raw_created_rows(con, fp, remaining, day))
            if not rows_acc:
                _warn(f"verify units day={day} sample_empty")
                failures += 1
                checked += 1
                continue
            con.execute("DROP TABLE IF EXISTS verify_units_sample")
            con.execute(
                """
                CREATE TEMP TABLE verify_units_sample(
                  txid VARCHAR,
                  vout BIGINT,
                  raw_value DOUBLE,
                  raw_type VARCHAR
                );
                """
            )
            con.executemany(
                "INSERT INTO verify_units_sample(txid, vout, raw_value, raw_type) VALUES (?, ?, ?, ?)",
                rows_acc,
            )
            df = con.execute(
                """
                SELECT
                  s.raw_type,
                  s.raw_value,
                  u.value_btc AS db_value_btc
                FROM verify_units_sample s
                LEFT JOIN utxo u ON u.txid = s.txid AND u.vout = s.vout
                """
            ).fetchall()
            checked += 1
            buckets = {"same_unit": 0, "scaled_1e8": 0, "other": 0, "missing": 0, "zero": 0}
            raw_types = sorted(set(str(raw_type) for raw_type, _, _ in df))
            for raw_type, raw_value, db_value_btc in df:
                bucket = _bucketize_raw_over_value_btc(float(raw_value), None if db_value_btc is None else float(db_value_btc))
                buckets[bucket] = buckets.get(bucket, 0) + 1
            _log(
                f"verify units day={day} sample={len(df)} raw_types={raw_types} "
                f"same_unit={buckets['same_unit']} scaled_1e8={buckets['scaled_1e8']} "
                f"other={buckets['other']} missing={buckets['missing']} zero={buckets['zero']}"
            )
            wrong = sum(v for k, v in buckets.items() if k not in {expected_bucket, "zero"})
            if buckets.get(expected_bucket, 0) == 0 or wrong > 0:
                failures += 1
        _log(f"verify units checked={checked} failures={failures}")
        return 0 if failures == 0 else 5
    finally:
        con.close()



# -----------------------------
# v11 block-order full rebuild helpers
# -----------------------------

def _v11_cleanup_requested(mode: str) -> bool:
    return bool(
        _env_bool("UTXO_CLEAN_WINDOW", False)
        or mode in {MODE_CLEANUP_ONLY, MODE_REPLAY_DAY, MODE_REPAIR_CREATED_RANGE, MODE_REPAIR_SPENT_RANGE}
        or (_env_str("UTXO_CLEANUP_SEMANTICS", "") or "").strip() not in {"", "disabled", "none"}
    )


def _v11_startup_guard(mode: str, *, cleanup_requested: bool) -> None:
    """v11-r1-fix16 startup guard.

    v11-r1 supports only:
      - REBUILD_FULL into a new/empty DB;
      - APPEND_TAIL append-only extension of an existing block-contiguous DB;
      - REPLAY_SUFFIX block-height suffix cleanup + reapply, guarded by dirty marker;
      - STAGE_ONLY / TXID_MAP_ONLY / TXID_MAP_AUDIT_ONLY / AUDIT_ONLY read/prep modes.

    All legacy v10 cleanup/replay/repair/write modes are hard-blocked in r1.
    Do not add dangerous overrides here: legacy date cleanup and middle-range cleanup remain blocked.
    """
    dangerous_envs = [
        "UTXO_ALLOW_V11_CLEANUP_DANGEROUS",
        "UTXO_ALLOW_V11_LEGACY_MUTATING_MODES_DANGEROUS",
        "UTXO_ALLOW_V11_LEGACY_DATE_CLEANUP_DANGEROUS",
        "UTXO_V11_ALLOW_NON_EMPTY_REBUILD_DB_DANGEROUS",
    ]
    enabled_dangerous = [name for name in dangerous_envs if _env_bool(name, False)]
    if enabled_dangerous:
        raise RuntimeError(
            "v11-r1-fix16 blocks dangerous legacy overrides entirely: "
            + ",".join(enabled_dangerous)
            + ". Use a future v11-r2 block_range cleanup implementation instead."
        )

    if cleanup_requested:
        raise RuntimeError(
            "v11-r1-fix16 legacy cleanup blocked: use UTXO_MODE=REPLAY_SUFFIX for the new block-height suffix cleanup. "
            "Do not use UTXO_CLEAN_WINDOW, REPLAY_DAY, CLEANUP_ONLY, repair cleanup, UTXO_CLEANUP_SEMANTICS, or legacy date cleanup."
        )

    disallowed_mutating = {
        MODE_STAGE_AND_APPLY,
        MODE_STAGE_APPLY_AND_AUDIT_DAY,
        MODE_CLEANUP_ONLY,
        MODE_REPLAY_DAY,
        MODE_REPAIR_CREATED_RANGE,
        MODE_REPAIR_SPENT_RANGE,
        MODE_WRITE_ONLY,
        MODE_WRITE_AND_AUDIT_DAY,
    }
    if mode in disallowed_mutating:
        raise RuntimeError(
            f"v11-r1-fix16 blocks legacy mutating mode={mode}. "
            "Use UTXO_MODE=REBUILD_FULL for a new/empty DB, UTXO_MODE=APPEND_TAIL for append-only tail extension, UTXO_MODE=REPLAY_SUFFIX for block-height suffix replay, or STAGE_ONLY/TXID_MAP_ONLY for non-mutating prep."
        )

    cleanup_mode_raw = os.environ.get("UTXO_CLEANUP_MODE")
    if cleanup_mode_raw:
        raise RuntimeError(
            f"v11-r1-fix16 blocks UTXO_CLEANUP_MODE={cleanup_mode_raw!r}. "
            "Old cleanup is date-based; v11 replay cleanup must be block_range and is not implemented in r1."
        )

    partial_null_flag = os.environ.get("UTXO_ALLOW_PARTIAL_NULL_TX_INDEX_SCAN_FALLBACK")
    if partial_null_flag and mode in {MODE_REBUILD_FULL, MODE_REBUILD_RESUME, MODE_APPEND_TAIL, MODE_REPLAY_SUFFIX, MODE_STAGE_ONLY}:
        raise RuntimeError(
            "fix15 disables UTXO_ALLOW_PARTIAL_NULL_TX_INDEX_SCAN_FALLBACK for v11 stage/apply modes. "
            "Partial NULL top-level transaction indexes require a future canonical tx_index resolver/map; "
            "blind scan-order fallback was proven unsafe by causal postcheck."
        )




def _v11_lab_flag_guard(mode: str) -> None:
    lab_flags = [
        "UTXO_V11_ALLOW_PARTIAL_LAB_REBUILD",
        "UTXO_V11_ALLOW_ORPHANS",
        "UTXO_V11_ALLOW_MISSING_BLOCK_HEIGHTS_DANGEROUS",
        "UTXO_V11_ALLOW_VALUE_UNIT_MISMATCH_DANGEROUS",
        "UTXO_V11_ALLOW_OLDER_V11_STAGE",
        "UTXO_V11_ALLOW_NO_EXPECTED_END_HEIGHT",
        "UTXO_ALLOW_DERIVED_TX_INDEX_MULTI_TX_BLOCK",
        "UTXO_ALLOW_MULTI_FILE_TX_INDEX_FALLBACK",
        "UTXO_V11_ALLOW_DUPLICATE_SPENDS_STAGE_RAW_DANGEROUS",
        "UTXO_DISABLE_POST_SEGWIT_TXID_MODE_GUARD",
    ]
    enabled = [name for name in lab_flags if _env_bool(name, False)]
    if enabled and not _env_bool("UTXO_V11_LAB_MODE", False):
        raise RuntimeError(
            "v11-r1-fix16 lab/dangerous flags require UTXO_V11_LAB_MODE=1: "
            + ",".join(enabled)
            + ". Unset these flags for production-like v11 apply mode."
        )
    if mode in {MODE_REBUILD_FULL, MODE_REBUILD_RESUME, MODE_APPEND_TAIL, MODE_REPLAY_SUFFIX} and _env_bool("UTXO_V11_LAB_MODE", False):
        _warn(f"v11 LAB MODE is enabled for {mode}; resulting DB must be treated as lab/not-for-metrics unless the run is intentionally controlled and audited.")


def _v11_global_duckdb_threads_guard(mode: str) -> None:
    if mode not in {MODE_REBUILD_FULL, MODE_REBUILD_RESUME, MODE_APPEND_TAIL, MODE_REPLAY_SUFFIX}:
        return
    if os.environ.get("DUCKDB_THREADS") and not _env_bool("UTXO_V11_ALLOW_GLOBAL_DUCKDB_THREADS", False):
        raise RuntimeError(
            f"v11-r1-fix16 blocks global DUCKDB_THREADS={os.environ.get('DUCKDB_THREADS')!r} for v11 apply-capable mode. "
            "Use phase-specific UTXO_STAGE_THREADS/UTXO_TXID_MAP_THREADS/UTXO_APPLY_THREADS/UTXO_AUDIT_THREADS. "
            "Set UTXO_V11_ALLOW_GLOBAL_DUCKDB_THREADS=1 only for a deliberate lab benchmark."
        )


def _v11_require_external_canonical_proof_for_write(mode: str) -> None:
    """Fail closed before any apply-capable v11 run can create or mutate state.

    UTXO_REPLAY_DUP_BLOCK_FILTER_ALWAYS=1 preserves the original all-block proof.
    UTXO_REPLAY_DUP_BLOCK_FILTER_ALWAYS=0 is an explicit operational compromise:
    the same duplicate guard and block filter remain enabled, but external block
    lookup is triggered only when duplicate transaction evidence exists.
    """
    write_modes = {MODE_REBUILD_FULL, MODE_REBUILD_RESUME, MODE_APPEND_TAIL, MODE_REPLAY_SUFFIX}
    if mode not in write_modes:
        return

    failures: List[str] = []
    source = _dup_guard_canonical_source()
    checks = {
        "UTXO_REPLAY_DUP_GUARD": _dup_guard_enabled(),
        "UTXO_REPLAY_DUP_BLOCK_FILTER": _dup_guard_block_filter(),
        "UTXO_REPLAY_DUP_AUTO_RESOLVE": _dup_guard_auto_resolve(),
        "UTXO_REPLAY_DUP_REQUIRE_CANONICAL_PROOF": _dup_guard_require_canonical_proof(),
        "UTXO_REPLAY_DUP_GUARD_FAIL_ON_UNRESOLVED": _dup_guard_fail_on_unresolved(),
    }
    for name, enabled in checks.items():
        if not enabled:
            failures.append(f"{name}=0")
    if source not in {"bitcoin_cli", "esplora"}:
        failures.append(f"UTXO_REPLAY_DUP_CANONICAL_SOURCE={source!r}")
    if _dup_guard_allow_unproven_modern():
        failures.append("UTXO_REPLAY_DUP_ALLOW_UNPROVEN_MODERN=1")

    if failures:
        raise RuntimeError(
            "BLOCKED_BEFORE_APPLY: external canonical duplicate-resolution configuration is mandatory "
            f"for mode={mode}; unsafe settings={failures}. Required: "
            "UTXO_REPLAY_DUP_GUARD=1, UTXO_REPLAY_DUP_CANONICAL_SOURCE=bitcoin_cli|esplora, "
            "UTXO_REPLAY_DUP_BLOCK_FILTER=1, UTXO_REPLAY_DUP_AUTO_RESOLVE=1, "
            "UTXO_REPLAY_DUP_REQUIRE_CANONICAL_PROOF=1, "
            "UTXO_REPLAY_DUP_GUARD_FAIL_ON_UNRESOLVED=1, "
            "UTXO_REPLAY_DUP_ALLOW_UNPROVEN_MODERN=0. "
            "UTXO_REPLAY_DUP_BLOCK_FILTER_ALWAYS may be 1 (all blocks) or 0 "
            "(duplicate-triggered lookup). No DB, stage, partial/dirty marker, cleanup or apply "
            "mutation has started."
        )

    scope = _dup_guard_canonical_proof_scope()
    if scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED:
        _warn(
            "OPERATIONAL CANONICAL POLICY: UTXO_REPLAY_DUP_BLOCK_FILTER_ALWAYS=0. "
            "Public Esplora is not queried for every historical block because large rebuilds can "
            "require hundreds of thousands of rate-limited requests and dramatically increase "
            "calculation time. Canonical lookup remains mandatory and fail-closed on days where "
            "duplicate transaction evidence is detected; UTXO_REPLAY_DUP_BLOCK_FILTER remains enabled."
        )
    _log(
        "v11 external canonical duplicate-resolution startup guard ok: "
        f"mode={mode} source={source} proof_scope={scope} "
        f"all_block_filter={int(_dup_guard_block_filter_always())} fail_on_unresolved=1"
    )


def _v11_expected_end_height_guard(h_max: int) -> None:
    raw = _env_str("UTXO_V11_EXPECTED_END_HEIGHT", None)
    if raw is None:
        if not _env_bool("UTXO_V11_LAB_MODE", False) and not _env_bool("UTXO_V11_ALLOW_NO_EXPECTED_END_HEIGHT", False):
            raise RuntimeError(
                "v11 production expected-end-height guard blocked run: UTXO_V11_EXPECTED_END_HEIGHT is not set. "
                "For production, set it to the known canonical/local raw-tail height. "
                "For smoke/lab only, set UTXO_V11_LAB_MODE=1."
            )
        _warn("v11 expected end-height guard: UTXO_V11_EXPECTED_END_HEIGHT is not set; tail completeness cannot be proven from local stage alone")
        return
    try:
        expected = int(raw)
    except Exception as e:
        raise RuntimeError(f"invalid UTXO_V11_EXPECTED_END_HEIGHT={raw!r}: {type(e).__name__}: {e}") from e
    if int(h_max) != expected:
        raise RuntimeError(f"v11 expected end-height guard failed: actual_h_max={int(h_max)} expected={expected}")
    _log(f"v11 expected end-height guard ok: h_max={int(h_max)}")


def _v11_partial_marker_path(db_path: str) -> Path:
    identity = str(Path(db_path).resolve())
    return _lock_root(create=True) / f"utxo_v11_partial.{_lock_key(identity)}.json"


def _v11_completed_marker_path(db_path: str) -> Path:
    identity = str(Path(db_path).resolve())
    ts = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    return _lock_root(create=True) / (
        f"utxo_v11_completed.{_lock_key(identity)}.{ts}.{uuid.uuid4().hex}.json"
    )


def _v11_existing_completed_markers(db_path: str) -> List[Dict[str, Any]]:
    identity = str(Path(db_path).resolve())
    key = _lock_key(identity)
    rows: List[Dict[str, Any]] = []
    for path in sorted(_lock_root(create=True).glob(f"utxo_v11_completed.{key}.*.json")):
        payload, sha256, snapshot = _read_json_regular_file_snapshot(path)
        marker_db = str(payload.get("db_path_resolved") or payload.get("db_path") or "")
        try:
            marker_db = str(Path(marker_db).resolve()) if marker_db else ""
        except Exception:
            marker_db = ""
        if marker_db != identity or str(payload.get("status") or "") != "completed":
            continue
        rows.append({
            "path": str(path),
            "sha256": sha256,
            "snapshot": snapshot,
            "payload": payload,
        })
    return rows


def _v11_rebuild_completed_marker_guard(db_path: str) -> None:
    markers = _v11_existing_completed_markers(db_path)
    if markers:
        raise RuntimeError(
            "REBUILD_FULL target path already has completed provenance marker(s). "
            "Move/quarantine the marker(s) together with the old DB before rebuilding "
            f"the same path. markers={[x['path'] for x in markers]}"
        )


def _v11_partial_marker_guard(db_path: str) -> None:
    path = _v11_partial_marker_path(db_path)
    if not path.exists():
        return
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        payload = {"unreadable": True, "path": str(path)}
    if _env_bool("UTXO_V11_ALLOW_PARTIAL_MARKER_OVERRIDE_DANGEROUS", False) and _env_bool("UTXO_V11_LAB_MODE", False):
        _warn(f"DANGEROUS: ignoring existing v11 partial marker by explicit lab override path={path} payload={payload}")
        return
    raise RuntimeError(
        f"v11 partial rebuild marker exists: {path}. DB may be partial/not-resumable. "
        f"Quarantine/delete DB or inspect marker before rerun. payload={payload}"
    )


def _v11_write_partial_marker(db_path: str, payload: Dict[str, Any]) -> Path:
    path = _v11_partial_marker_path(db_path)
    base = {
        "status": "partial_rebuild_not_resumable",
        "db_path": str(db_path),
        "db_path_resolved": str(Path(db_path).resolve()),
        "stage_dir": str(_stage_root_path_no_create()),
        "raw_base": _env_str("UTXO_RAW_BASE", RAW_BASE_DEFAULT),
        "pid": os.getpid(),
        "host": socket.gethostname(),
        "cmdline": " ".join(sys.argv),
        "pipeline_version": _pipeline_version(),
        "updated_at": _now_iso(),
        "lock_root": str(_lock_root(create=False)),
    }
    base.update(payload)
    _save_json_atomic(path, base)
    return path


def _v11_update_partial_marker(db_path: str, payload: Dict[str, Any]) -> Path:
    """Merge an update into the existing partial marker without losing resume evidence."""
    path = _v11_partial_marker_path(db_path)
    current: Dict[str, Any] = {}
    if path.exists():
        try:
            current = _v11_marker_public_payload(_v11_recovery_marker_payload(path))
        except Exception:
            current = {}
    current.update(dict(payload))
    return _v11_write_partial_marker(db_path, current)


def _v11_complete_partial_marker(db_path: str, payload: Dict[str, Any]) -> Optional[Path]:
    src = _v11_partial_marker_path(db_path)
    final_payload = {
        "status": "completed",
        "db_path": str(db_path),
        "db_path_resolved": str(Path(db_path).resolve()),
        "pipeline_version": _pipeline_version(),
        "crash_recovery_contract": V11_CRASH_RECOVERY_CONTRACT_VERSION,
        "completed_at": _now_iso(),
        "db_identity": _v11_db_regular_identity(db_path) if Path(db_path).is_file() else None,
    }
    final_payload.update(payload)
    dst = _v11_completed_marker_path(db_path)
    _save_json_atomic(dst, final_payload)
    if src.exists():
        _v11_durable_unlink(src, label="partial rebuild marker after completed publication")
    if src.exists() or not dst.is_file():
        raise RuntimeError(
            f"rebuild terminal marker transition incomplete src_exists={src.exists()} dst={dst}"
        )
    return dst

def _v11_table_exists(con: duckdb.DuckDBPyConnection, table_name: str) -> bool:
    return bool(con.execute(
        """
        SELECT COUNT(*)
        FROM information_schema.tables
        WHERE lower(table_name) = lower(?)
        """,
        [table_name],
    ).fetchone()[0])


def _v11_required_utxo_columns() -> set:
    return {
        "txid",
        "vout",
        "address",
        "value_btc",
        "created_ts",
        "created_date",
        "created_height",
        "created_tx_index",
        "spent_ts",
        "spent_date",
        "spent_txid",
        "spent_vin",
        "spent_height",
        "spent_tx_index",
    }


def _v11_table_columns(con: duckdb.DuckDBPyConnection, table_name: str) -> set:
    rows = con.execute(
        """
        SELECT lower(column_name)
        FROM information_schema.columns
        WHERE lower(table_name) = lower(?)
        """,
        [table_name],
    ).fetchall()
    return {str(r[0]).lower() for r in rows}


def _v11_assert_schema_compatible(con: duckdb.DuckDBPyConnection, db_path: str) -> None:
    if _v11_table_exists(con, "utxo"):
        cols = _v11_table_columns(con, "utxo")
        missing = sorted(_v11_required_utxo_columns() - cols)
        if missing:
            raise RuntimeError(
                f"v11 schema guard blocked old/incompatible utxo table in db={db_path}: "
                f"missing_columns={missing}. Delete/quarantine this DB or use a fresh UTXO_DB_PATH."
            )
    if _v11_table_exists(con, "block_meta"):
        cols = _v11_table_columns(con, "block_meta")
        required = {"block_number", "block_hash", "block_timestamp", "block_date", "raw_partition_min", "raw_partition_max"}
        missing = sorted(required - cols)
        if missing:
            raise RuntimeError(
                f"v11 schema guard blocked incompatible block_meta table in db={db_path}: "
                f"missing_columns={missing}. Delete/quarantine this DB or use a fresh UTXO_DB_PATH."
            )


def _v11_assert_empty_rebuild_db(con: duckdb.DuckDBPyConnection, db_path: str) -> None:
    _v11_assert_schema_compatible(con, db_path)
    if _v11_table_exists(con, "utxo"):
        rows = int(con.execute("SELECT COUNT(*) FROM utxo").fetchone()[0] or 0)
        if rows > 0:
            raise RuntimeError(
                f"v11 REBUILD_FULL requires a new/empty DB. db={db_path} utxo_rows={rows}. "
                "Move the old DB to quarantine or set a new UTXO_DB_PATH. "
                "Non-empty rebuild is not supported for REBUILD_FULL in v11-r1-fix16; use APPEND_TAIL for strict append-only extension."
            )
    if _v11_table_exists(con, "block_meta"):
        rows = int(con.execute("SELECT COUNT(*) FROM block_meta").fetchone()[0] or 0)
        if rows > 0:
            raise RuntimeError(
                f"v11 REBUILD_FULL requires empty block_meta. db={db_path} block_meta_rows={rows}. "
                "Non-empty rebuild is not supported for REBUILD_FULL in v11-r1-fix16; use APPEND_TAIL for strict append-only extension."
            )


def _v11_stage_manifest_guard(day: str, manifest: Dict[str, Any]) -> None:
    """Reject incompatible or correctness-blocked stage manifests before reuse."""
    failed: List[str] = []
    if not isinstance(manifest, dict):
        raise RuntimeError(f"v11 stage manifest guard failed day={day}: ['manifest_missing_or_not_object']")
    manifest_version = str(manifest.get("pipeline_version", ""))
    if manifest_version != PIPELINE_VERSION:
        if _v11_stage_action() == "reuse":
            if manifest_version in V11_REUSABLE_STAGE_PIPELINE_VERSIONS:
                _warn(
                    "v11 reviewed stage producer accepted for explicit reuse "
                    f"day={day}: manifest={manifest_version} consumer={PIPELINE_VERSION} "
                    f"contract={V11_STAGE_REUSE_CONTRACT_VERSION}"
                )
            else:
                failed.append(
                    "unreviewed_stage_producer_for_reuse:"
                    f"manifest={manifest_version} allowed={sorted(V11_REUSABLE_STAGE_PIPELINE_VERSIONS)}"
                )
        elif _env_bool("UTXO_V11_ALLOW_OLDER_V11_STAGE", False) and manifest_version.startswith("v11-"):
            _warn(
                f"v11 stage manifest version mismatch allowed by UTXO_V11_ALLOW_OLDER_V11_STAGE=1 "
                f"day={day}: manifest={manifest_version} expected={PIPELINE_VERSION}"
            )
        else:
            failed.append(f"pipeline_version_mismatch:manifest={manifest_version} expected={PIPELINE_VERSION}")
    if manifest.get("stage_semantics") != "block_ordered":
        failed.append("stage_semantics_not_block_ordered")
    if manifest.get("causal_order") != "block_number,tx_index":
        failed.append("causal_order_not_block_number_tx_index")
    if str(manifest.get("status") or "") == STATUS_BLOCKED_BEFORE_APPLY:
        failed.append("manifest_status_blocked_before_apply")

    files = manifest.get("files") if isinstance(manifest.get("files"), dict) else None
    if files is None:
        failed.append("manifest_files_missing_or_not_object")
    else:
        for key in ("created_parquet", "spends_parquet", "block_meta_parquet"):
            value = files.get(key)
            if not isinstance(value, str) or not value.strip():
                failed.append(f"manifest_file_path_invalid:{key}:{value!r}")

    stage = manifest.get("stage", {}) if isinstance(manifest.get("stage"), dict) else {}
    if stage.get("status") != "ok":
        failed.append(f"stage_status_not_ok:{stage.get('status')}")
    created_missing_causal = _v11_contract_int(
        stage.get("created_missing_causal"), "stage_created_missing_causal", failed
    )
    spends_missing_causal = _v11_contract_int(
        stage.get("spends_missing_causal"), "stage_spends_missing_causal", failed
    )
    if created_missing_causal > 0:
        failed.append("created_missing_causal")
    if spends_missing_causal > 0:
        failed.append("spends_missing_causal")
    txid_mode = manifest.get("txid_mode", {}) if isinstance(manifest.get("txid_mode"), dict) else {}
    if txid_mode.get("mode") != _get_txid_mode():
        failed.append(f"txid_mode_mismatch:manifest={txid_mode.get('mode')} env={_get_txid_mode()}")

    tx_index_binding=manifest.get("tx_index_map_binding")
    raw_info=manifest.get("raw") if isinstance(manifest.get("raw"),dict) else {}
    raw_files=raw_info.get("files") if isinstance(raw_info.get("files"),list) else []
    map_backed=any(isinstance(x,dict) and x.get("tx_index_source")=="canonical_tx_index_map" for x in raw_files)
    if map_backed and tx_index_binding is None: failed.append("tx_index_map_binding_missing_for_map_backed_stage")
    elif tx_index_binding is not None: failed.extend(_tx_index_map_validate_stage_binding(day,tx_index_binding))
    canonical_proof = manifest.get("canonical_proof")
    failed.extend(_v11_validate_canonical_proof_contract(canonical_proof, day=day))

    duplicate_guard = manifest.get("duplicate_guard") if isinstance(manifest.get("duplicate_guard"), dict) else None
    if not duplicate_guard:
        failed.append("duplicate_guard_missing")
    else:
        allowed_statuses = {
            STATUS_DUPLICATE_GUARD_OK,
            STATUS_RESOLVED_NO_DUPLICATES,
            STATUS_RESOLVED_CANONICAL_SELECTED,
            STATUS_RESOLVED_CANONICAL_BLOCK_FILTER,
            STATUS_RESOLVED_BIP30_EXCEPTION,
        }
        guard_status = str(duplicate_guard.get("status") or "")
        if duplicate_guard.get("enabled") is not True:
            failed.append(f"duplicate_guard_not_enabled:{duplicate_guard.get('enabled')!r}")
        if guard_status not in allowed_statuses:
            failed.append(f"duplicate_guard_status_not_green:{guard_status or '<missing>'}")
        if duplicate_guard.get("apply_allowed") is not True:
            failed.append(f"duplicate_guard_apply_not_allowed:{duplicate_guard.get('apply_allowed')!r}")
        unresolved_groups = _v11_contract_int(
            duplicate_guard.get("unresolved_groups"), "duplicate_guard_unresolved_groups", failed
        )
        if unresolved_groups != 0:
            failed.append(f"duplicate_guard_unresolved_groups:{duplicate_guard.get('unresolved_groups')}")
        lookup_errors = duplicate_guard.get("canonical_lookup_errors")
        if not isinstance(lookup_errors, list):
            failed.append("duplicate_guard_canonical_lookup_errors_not_list")
        elif lookup_errors:
            failed.append(f"duplicate_guard_canonical_lookup_errors:{len(lookup_errors)}")
        if duplicate_guard.get("hard_canonical_failure") is True:
            failed.append("duplicate_guard_hard_canonical_failure")
        hard_errors = duplicate_guard.get("hard_canonical_errors")
        if hard_errors not in (None, []):
            failed.append(f"duplicate_guard_hard_canonical_errors:{hard_errors}")
        if duplicate_guard.get("canonical_source") not in {"bitcoin_cli", "esplora"}:
            failed.append(
                f"duplicate_guard_external_canonical_source_missing:{duplicate_guard.get('canonical_source')!r}"
            )
        if duplicate_guard.get("block_filter_enabled") is not True:
            failed.append("duplicate_guard_block_filter_not_enabled")
        guard_scope = _dup_guard_scope_from_report(duplicate_guard)
        current_scope = _dup_guard_canonical_proof_scope()
        duplicate_txids = _v11_contract_int(
            duplicate_guard.get("duplicate_txids"), "duplicate_guard_duplicate_txids", failed
        )
        if current_scope == CANONICAL_PROOF_SCOPE_ALL_BLOCKS and guard_scope != CANONICAL_PROOF_SCOPE_ALL_BLOCKS:
            failed.append(
                f"duplicate_guard_scope_weaker_than_current_policy:{guard_scope}!={current_scope}"
            )
        if guard_scope == CANONICAL_PROOF_SCOPE_ALL_BLOCKS:
            if duplicate_guard.get("block_filter_requested") is not True:
                failed.append("duplicate_guard_block_filter_not_requested")
            if duplicate_guard.get("block_filter_always") is not True:
                failed.append("duplicate_guard_block_filter_not_always")
        elif guard_scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED:
            if duplicate_guard.get("block_filter_always") is not False:
                failed.append("duplicate_guard_block_filter_always_not_false_for_triggered_scope")
            if duplicate_txids > 0 and duplicate_guard.get("block_filter_requested") is not True:
                failed.append("duplicate_guard_block_filter_not_requested_for_duplicates")
            if duplicate_txids == 0 and duplicate_guard.get("block_filter_requested") is not False:
                failed.append("duplicate_guard_block_filter_requested_without_duplicates")
        else:
            failed.append(f"duplicate_guard_invalid_proof_scope:{guard_scope}")
        if duplicate_guard.get("auto_resolve") is not True:
            failed.append("duplicate_guard_auto_resolve_not_enabled")
        if duplicate_guard.get("require_canonical_proof") is not True:
            failed.append("duplicate_guard_require_canonical_proof_not_enabled")
        if duplicate_guard.get("allow_unproven_modern") is not False:
            failed.append("duplicate_guard_allow_unproven_modern_not_false")
        if duplicate_guard.get("canonical_proof_complete") is not True:
            failed.append(
                "duplicate_guard_canonical_proof_incomplete:"
                f"{duplicate_guard.get('canonical_proof_failures')}"
            )
        proof_failures = duplicate_guard.get("canonical_proof_failures")
        if not isinstance(proof_failures, list):
            failed.append("duplicate_guard_canonical_proof_failures_not_list")
        elif proof_failures:
            failed.append(f"duplicate_guard_canonical_proof_failures:{proof_failures}")
        checked_blocks = _v11_contract_int(
            duplicate_guard.get("checked_blocks"), "duplicate_guard_checked_blocks", failed
        )
        lookup_bad_hash_rows = _v11_contract_int(
            duplicate_guard.get("canonical_lookup_bad_hash_rows"),
            "duplicate_guard_canonical_lookup_bad_hash_rows", failed
        )
        lookup_ok_rows = _v11_contract_int(
            duplicate_guard.get("canonical_lookup_ok_rows"),
            "duplicate_guard_canonical_lookup_ok_rows", failed
        )
        if checked_blocks <= 0 and not (
            guard_scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED and duplicate_txids == 0
        ):
            failed.append("duplicate_guard_no_blocks_checked")
        if (
            guard_scope == CANONICAL_PROOF_SCOPE_DUPLICATE_TRIGGERED
            and duplicate_txids == 0
            and checked_blocks != 0
        ):
            failed.append(f"duplicate_guard_unexpected_blocks_checked:{checked_blocks}")
        if lookup_bad_hash_rows != 0:
            failed.append(
                f"duplicate_guard_invalid_canonical_hash_rows:{duplicate_guard.get('canonical_lookup_bad_hash_rows')}"
            )
        if lookup_ok_rows != checked_blocks:
            failed.append(
                "duplicate_guard_canonical_lookup_coverage_mismatch:"
                f"{duplicate_guard.get('canonical_lookup_ok_rows')}!={duplicate_guard.get('checked_blocks')}"
            )

        replacements = duplicate_guard.get("canonical_replacements")
        if replacements is None:
            replacements = []
        if not isinstance(replacements, list):
            failed.append("canonical_replacements_not_list")
            replacements = []
        noncanonical_blocks = _v11_contract_int(
            duplicate_guard.get("noncanonical_blocks"), "duplicate_guard_noncanonical_blocks", failed
        )
        block_filter = duplicate_guard.get("block_meta_filter") if isinstance(duplicate_guard.get("block_meta_filter"), dict) else None
        if noncanonical_blocks > 0 or replacements:
            if not block_filter:
                failed.append("block_meta_filter_missing_for_replacements")
            else:
                if block_filter.get("status") != "OK":
                    failed.append(f"block_meta_filter_status_not_ok:{block_filter.get('status')}")
                if block_filter.get("apply_allowed") is not True:
                    failed.append(f"block_meta_filter_apply_not_allowed:{block_filter.get('apply_allowed')!r}")
                filter_errors = block_filter.get("errors")
                if not isinstance(filter_errors, list):
                    failed.append("block_meta_filter_errors_not_list")
                elif filter_errors:
                    failed.append(f"block_meta_filter_errors:{filter_errors}")
                planned = _v11_contract_int(
                    block_filter.get("planned_discarded_blocks"),
                    "block_filter_planned_discarded_blocks", failed
                )
                deleted = _v11_contract_int(
                    block_filter.get("block_meta_distinct_blocks_deleted"),
                    "block_filter_distinct_blocks_deleted", failed
                )
                if planned != len(replacements):
                    failed.append(f"canonical_replacements_count_mismatch:{len(replacements)}!={planned}")
                if noncanonical_blocks != planned:
                    failed.append(f"noncanonical_blocks_plan_mismatch:{noncanonical_blocks}!={planned}")
                if deleted != planned:
                    failed.append(f"block_meta_deleted_plan_mismatch:{deleted}!={planned}")
                for key in (
                    "remaining_discarded_created_rows",
                    "remaining_discarded_spends_rows",
                    "remaining_discarded_block_meta_rows",
                    "unexpected_block_meta_keys_deleted",
                    "expected_block_meta_keys_not_deleted",
                ):
                    value = _v11_contract_int(block_filter.get(key), f"block_filter_{key}", failed)
                    if value != 0:
                        failed.append(f"block_meta_filter_nonzero:{key}={block_filter.get(key)}")
        elif block_filter is not None:
            filter_status = str(block_filter.get("status") or "")
            if filter_status not in {"NOT_REQUIRED", "NOT_REQUESTED", "OK"}:
                failed.append(f"block_meta_filter_unexpected_status_without_replacements:{filter_status}")
            if block_filter.get("apply_allowed") is not True:
                failed.append("block_meta_filter_not_apply_allowed_without_replacements")
            planned = _v11_contract_int(
                block_filter.get("planned_discarded_blocks"),
                "block_filter_planned_discarded_blocks", failed
            )
            deleted = _v11_contract_int(
                block_filter.get("block_meta_distinct_blocks_deleted"),
                "block_filter_distinct_blocks_deleted", failed
            )
            if planned != 0:
                failed.append(f"block_meta_filter_unexpected_plan_without_replacements:{planned}")
            if deleted != 0:
                failed.append(f"block_meta_filter_unexpected_deleted_without_replacements:{deleted}")
            for key in (
                "remaining_discarded_created_rows",
                "remaining_discarded_spends_rows",
                "remaining_discarded_block_meta_rows",
                "unexpected_block_meta_keys_deleted",
                "expected_block_meta_keys_not_deleted",
            ):
                value = _v11_contract_int(block_filter.get(key), f"block_filter_{key}", failed)
                if value != 0:
                    failed.append(f"block_meta_filter_nonzero_without_replacements:{key}={block_filter.get(key)}")

    if failed:
        raise RuntimeError(f"v11 stage manifest guard failed day={day}: {failed}")


def _v11_stage_paths(days: Sequence[str]) -> Tuple[List[str], List[str], List[str]]:
    created_paths: List[str] = []
    spends_paths: List[str] = []
    block_meta_paths: List[str] = []
    for day in days:
        manifest = _load_manifest(str(day))
        if not manifest:
            raise RuntimeError(f"v11 stage missing manifest day={day}")
        _v11_stage_manifest_guard(str(day), manifest)
        cp = Path(manifest["files"]["created_parquet"])
        sp = Path(manifest["files"]["spends_parquet"])
        bmp_raw = manifest.get("files", {}).get("block_meta_parquet")
        bp = Path(bmp_raw) if bmp_raw else _block_meta_stage_path(str(day))
        if not cp.exists() or not sp.exists() or not bp.exists():
            raise FileNotFoundError(
                f"v11 stage parquet missing day={day}: "
                f"created={cp.exists()} spends={sp.exists()} block_meta={bp.exists()}"
            )
        created_paths.append(str(cp))
        spends_paths.append(str(sp))
        block_meta_paths.append(str(bp))
    return created_paths, spends_paths, block_meta_paths


def _v11_known_bip30_sql_list() -> str:
    values = sorted(_dup_guard_known_bip30_txids())
    if not values:
        values = ["__NO_KNOWN_BIP30_TXID__"]
    return "(" + ",".join(_quote_sql_string(v) for v in values) + ")"


def _v11_known_bip30_height_pairs() -> Tuple[Tuple[int, int], ...]:
    """Return known BIP30 duplicate height pairs as (later, earlier).

    The env override is intentionally explicit and small.  Accepted forms:
      UTXO_V11_BIP30_KNOWN_HEIGHT_PAIRS=91842:91812,91880:91722
      UTXO_V11_BIP30_KNOWN_HEIGHT_PAIRS=91842<-91812,91880<-91722
    """
    raw = _env_str("UTXO_V11_BIP30_KNOWN_HEIGHT_PAIRS", "")
    if not raw:
        return DEFAULT_BIP30_DUP_HEIGHT_PAIRS
    pairs: List[Tuple[int, int]] = []
    for token in str(raw).split(","):
        item = token.strip()
        if not item:
            continue
        if "<-" in item:
            left, right = item.split("<-", 1)
        elif ":" in item:
            left, right = item.split(":", 1)
        else:
            raise RuntimeError(
                "invalid UTXO_V11_BIP30_KNOWN_HEIGHT_PAIRS token "
                f"{item!r}; expected later:earlier or later<-earlier"
            )
        later = int(left.strip())
        earlier = int(right.strip())
        if later <= earlier:
            raise RuntimeError(
                "invalid BIP30 height pair: later height must be greater than earlier height: "
                f"{later}:{earlier}"
            )
        pairs.append((later, earlier))
    return tuple(sorted(set(pairs)))




def _v11_bip30_window_split_enabled() -> bool:
    """Enable arithmetic-only BIP30 block-window splitting.

    This guard prevents known historical BIP30 earlier/later duplicate pairs from
    being deduplicated inside a single large apply window.  It does not change
    apply SQL or the state-like PRIMARY KEY(txid, vout) policy.
    """
    return _env_bool("UTXO_V11_BIP30_WINDOW_SPLIT", True)


def _v11_bip30_window_split_strict() -> bool:
    return _env_bool("UTXO_V11_BIP30_WINDOW_SPLIT_STRICT", True)


def _v11_bip30_pairs_inside_window(h1: int, h2: int) -> List[Dict[str, int]]:
    """Return known BIP30 pairs fully contained in a candidate window.

    A pair is considered dangerous only when the same apply window contains both
    the earlier original height and the later duplicate height.  This is O(known
    pairs), currently two checks, so it is effectively free even for large runs.
    """
    h1_i = int(h1)
    h2_i = int(h2)
    pairs: List[Dict[str, int]] = []
    for later, earlier in _v11_known_bip30_height_pairs():
        later_i = int(later)
        earlier_i = int(earlier)
        if h1_i <= earlier_i < later_i <= h2_i:
            pairs.append({"later_height": later_i, "earlier_height": earlier_i})
    return sorted(pairs, key=lambda x: (int(x["later_height"]), int(x["earlier_height"])))


def _v11_adjust_block_window_for_bip30(h1: int, raw_h2: int, *, context: str) -> Tuple[int, Dict[str, Any]]:
    """Return an adjusted block-window end plus a small forensic report.

    The split is deliberately arithmetic-only and is applied before any DuckDB
    mutation.  If multiple historical BIP30 pairs are present in one large
    window, split before the earliest later duplicate height; the next loop
    iteration will evaluate the remaining pair.
    """
    h1_i = int(h1)
    raw_h2_i = int(raw_h2)
    if raw_h2_i < h1_i:
        raise RuntimeError(f"{context} invalid raw block window before BIP30 split: h1={h1_i} raw_h2={raw_h2_i}")

    candidates = _v11_bip30_pairs_inside_window(h1_i, raw_h2_i)
    report: Dict[str, Any] = {
        "enabled": bool(_v11_bip30_window_split_enabled()),
        "strict": bool(_v11_bip30_window_split_strict()),
        "applied": False,
        "context": str(context),
        "h1": h1_i,
        "original_h2": raw_h2_i,
        "adjusted_h2": raw_h2_i,
        "candidate_pairs_inside_original_window": candidates,
        "known_height_pairs": [
            {"later_height": int(later), "earlier_height": int(earlier)}
            for later, earlier in _v11_known_bip30_height_pairs()
        ],
        "guard": "PASS",
    }

    if not candidates:
        return raw_h2_i, report

    if not _v11_bip30_window_split_enabled():
        report["guard"] = "FAIL_SPLIT_DISABLED_PAIR_INSIDE_WINDOW"
        msg = f"{context} BIP30 window split disabled but window contains known BIP30 pair(s): {report}"
        if _v11_bip30_window_split_strict():
            raise RuntimeError(msg)
        _warn(msg)
        return raw_h2_i, report

    chosen = candidates[0]
    later = int(chosen["later_height"])
    earlier = int(chosen["earlier_height"])
    adjusted_h2 = later - 1

    # First-level arithmetic guard: catch off-by-one and loop-progress bugs
    # before any apply-window SQL can run.
    if not (h1_i <= earlier < later <= raw_h2_i):
        raise RuntimeError(
            f"{context} invalid BIP30 split candidate h1={h1_i} raw_h2={raw_h2_i} "
            f"later={later} earlier={earlier} candidates={candidates}"
        )
    if adjusted_h2 < h1_i:
        raise RuntimeError(
            f"{context} BIP30 split would create non-progressing window: "
            f"h1={h1_i} adjusted_h2={adjusted_h2} later={later} earlier={earlier} raw_h2={raw_h2_i}"
        )
    if adjusted_h2 != later - 1 or later != adjusted_h2 + 1:
        raise RuntimeError(
            f"{context} BIP30 split off-by-one guard failed: "
            f"h1={h1_i} adjusted_h2={adjusted_h2} later={later} earlier={earlier} raw_h2={raw_h2_i}"
        )

    report.update(
        {
            "applied": True,
            "reason": "BIP30_SPLIT_BEFORE_LATER_HEIGHT",
            "later_height": later,
            "earlier_height": earlier,
            "adjusted_h2": adjusted_h2,
            "remaining_pairs_after_split": _v11_bip30_pairs_inside_window(h1_i, adjusted_h2),
        }
    )
    _warn(
        f"{context} BIP30-aware block-window split applied: "
        f"h1={h1_i} original_h2={raw_h2_i} adjusted_h2={adjusted_h2} "
        f"pair={later}<-{earlier} candidates={candidates}"
    )
    return adjusted_h2, report


def _v11_assert_no_bip30_pair_inside_window(h1: int, h2: int, *, context: str) -> None:
    """Second-level arithmetic guard after any BIP30-aware split."""
    h1_i = int(h1)
    h2_i = int(h2)
    if h2_i < h1_i:
        raise RuntimeError(f"{context} invalid adjusted block window: h1={h1_i} h2={h2_i}")
    pairs = _v11_bip30_pairs_inside_window(h1_i, h2_i)
    if pairs:
        msg = (
            f"{context} BIP30 post-split guard failed: adjusted window still contains full known pair(s) "
            f"h1={h1_i} h2={h2_i} pairs={pairs}. This would let ROW_NUMBER() hide a later duplicate."
        )
        if _v11_bip30_window_split_strict():
            raise RuntimeError(msg)
        _warn(msg + " Continuing only because UTXO_V11_BIP30_WINDOW_SPLIT_STRICT=0.")


def _v11_bip30_window_split_summary(window_reports: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    items: List[Dict[str, Any]] = []
    for report in window_reports:
        split = report.get("bip30_window_split") if isinstance(report, dict) else None
        if not isinstance(split, dict):
            continue
        if bool(split.get("applied")) or split.get("guard") not in {None, "PASS"}:
            items.append(split)
    return {
        "enabled": bool(_v11_bip30_window_split_enabled()),
        "strict": bool(_v11_bip30_window_split_strict()),
        "applied_count": sum(1 for x in items if bool(x.get("applied"))),
        "reported_count": len(items),
        "items": items,
    }

def _v11_bip30_pair_predicate_sql(later_height_expr: str, earlier_height_expr: str) -> str:
    pairs = _v11_known_bip30_height_pairs()
    if not pairs:
        return "false"
    return "(" + " OR ".join(
        f"(CAST({later_height_expr} AS BIGINT) = {int(later)} AND CAST({earlier_height_expr} AS BIGINT) = {int(earlier)})"
        for later, earlier in pairs
    ) + ")"


def _v11_bip30_same_payload_sql(stage_alias: str = "s", db_alias: str = "u") -> str:
    return (
        f"CAST(round(CAST({stage_alias}.value_btc AS DOUBLE) * 100000000) AS BIGINT) "
        f"= CAST(round(CAST({db_alias}.value_btc AS DOUBLE) * 100000000) AS BIGINT) "
        f"AND COALESCE({stage_alias}.address, '') = COALESCE({db_alias}.address, '')"
    )


def _v11_stage_bip30_duplicate_report(
    con: duckdb.DuckDBPyConnection,
    *,
    h1: Optional[int] = None,
    h2: Optional[int] = None,
    stage_table: str = "v11_created_all",
) -> Dict[str, Any]:
    """Classify BIP30 duplicate rows inside a materialized table or parquet-backed source.

    This is an observability/guard layer.  It does not change the stage source
    and does not change the state-like PK behaviour.  A valid case must be one
    of the known height pairs, coinbase tx_index=0 on both rows, and same
    payload.
    """
    known_sql = _v11_known_bip30_sql_list()
    range_a = "1=1"
    range_b = "1=1"
    if h1 is not None and h2 is not None:
        range_a = f"CAST(a.block_number AS BIGINT) BETWEEN {int(h1)} AND {int(h2)}"
        range_b = f"CAST(b.block_number AS BIGINT) BETWEEN {int(h1)} AND {int(h2)}"
    pair_pred = _v11_bip30_pair_predicate_sql("a.block_number", "b.block_number")
    same_payload = (
        "CAST(round(CAST(a.value_btc AS DOUBLE) * 100000000) AS BIGINT) "
        "= CAST(round(CAST(b.value_btc AS DOUBLE) * 100000000) AS BIGINT) "
        "AND COALESCE(a.address, '') = COALESCE(b.address, '')"
    )
    con.execute("DROP TABLE IF EXISTS v11_bip30_stage_pairs")
    con.execute(
        f"""
        CREATE TEMP TABLE v11_bip30_stage_pairs AS
        SELECT
          lower(a.txid) AS txid,
          CAST(a.vout AS BIGINT) AS vout,
          CAST(a.block_number AS BIGINT) AS later_height,
          CAST(b.block_number AS BIGINT) AS earlier_height,
          CAST(a.tx_index AS BIGINT) AS later_tx_index,
          CAST(b.tx_index AS BIGINT) AS earlier_tx_index,
          CAST(round(CAST(a.value_btc AS DOUBLE) * 100000000) AS BIGINT) AS later_value_sats,
          CAST(round(CAST(b.value_btc AS DOUBLE) * 100000000) AS BIGINT) AS earlier_value_sats,
          COALESCE(a.address, '') AS later_address,
          COALESCE(b.address, '') AS earlier_address,
          CASE
            WHEN {pair_pred}
             AND CAST(a.tx_index AS BIGINT) = 0
             AND CAST(b.tx_index AS BIGINT) = 0
             AND {same_payload}
            THEN true ELSE false
          END AS valid_bip30_pair
        FROM {stage_table} a
        JOIN {stage_table} b
          ON lower(a.txid) = lower(b.txid)
         AND CAST(a.vout AS BIGINT) = CAST(b.vout AS BIGINT)
         AND CAST(a.block_number AS BIGINT) > CAST(b.block_number AS BIGINT)
        WHERE lower(a.txid) IN {known_sql}
          AND ({range_a})
          AND ({range_b})
        """
    )
    known_duplicate_rows = int(con.execute(
        f"""
        SELECT COALESCE(SUM(cnt - 1), 0)
        FROM (
          SELECT lower(txid) AS txid, vout, COUNT(*) AS cnt
          FROM {stage_table}
          WHERE lower(txid) IN {known_sql}
            AND ({'CAST(block_number AS BIGINT) BETWEEN ' + str(int(h1)) + ' AND ' + str(int(h2)) if h1 is not None and h2 is not None else '1=1'})
          GROUP BY 1, 2
          HAVING COUNT(*) > 1
        ) d
        """
    ).fetchone()[0] or 0)
    pair_rows, valid_pairs = con.execute(
        """
        SELECT
          COUNT(*) AS pair_rows,
          COUNT(*) FILTER (WHERE valid_bip30_pair) AS valid_pairs
        FROM v11_bip30_stage_pairs
        """
    ).fetchone()
    pair_rows_i = int(pair_rows or 0)
    valid_pairs_i = int(valid_pairs or 0)
    invalid_duplicate_rows = max(0, int(known_duplicate_rows) - valid_pairs_i)
    examples = [
        {
            "txid": str(r[0]),
            "vout": int(r[1]),
            "later_height": int(r[2]) if r[2] is not None else None,
            "earlier_height": int(r[3]) if r[3] is not None else None,
            "later_tx_index": int(r[4]) if r[4] is not None else None,
            "earlier_tx_index": int(r[5]) if r[5] is not None else None,
            "valid_bip30_pair": bool(r[6]),
        }
        for r in con.execute(
            """
            SELECT txid, vout, later_height, earlier_height, later_tx_index, earlier_tx_index, valid_bip30_pair
            FROM v11_bip30_stage_pairs
            WHERE NOT valid_bip30_pair
            ORDER BY later_height, earlier_height, txid, vout
            LIMIT 20
            """
        ).fetchall()
    ]
    return {
        "known_height_pairs": [f"{later}<-{earlier}" for later, earlier in _v11_known_bip30_height_pairs()],
        "known_duplicate_rows": int(known_duplicate_rows),
        "pair_rows": pair_rows_i,
        "valid_pairs": valid_pairs_i,
        "invalid_duplicate_rows": invalid_duplicate_rows,
        "invalid_examples": examples,
    }


def _v11_created_conflict_report(
    con: duckdb.DuckDBPyConnection,
    *,
    stage_table: str,
    stage_height_col: str,
    stage_tx_index_col: str,
    where_sql: str = "1=1",
) -> Dict[str, Any]:
    """Classify stage-created vs DB txid:vout conflicts.

    A conflict is allowed only when it is an exact known BIP30 later->earlier
    height pair with same payload and tx_index=0 on both rows.  This keeps the
    existing state-like PK + ON CONFLICT DO NOTHING logic intact, while avoiding
    accidental allowance of arbitrary conflicts on a known BIP30 txid.
    """
    known_sql = _v11_known_bip30_sql_list()
    pair_pred = _v11_bip30_pair_predicate_sql(stage_height_col, "u.created_height")
    same_payload = _v11_bip30_same_payload_sql("s", "u")
    valid_expr = (
        f"lower(s.txid) IN {known_sql} "
        f"AND {pair_pred} "
        f"AND CAST({stage_tx_index_col} AS BIGINT) = 0 "
        f"AND CAST(u.created_tx_index AS BIGINT) = 0 "
        f"AND {same_payload}"
    )
    con.execute("DROP TABLE IF EXISTS v11_created_conflict_report")
    con.execute(
        f"""
        CREATE TEMP TABLE v11_created_conflict_report AS
        SELECT
          lower(s.txid) AS txid,
          CAST(s.vout AS BIGINT) AS vout,
          CAST({stage_height_col} AS BIGINT) AS stage_height,
          CAST({stage_tx_index_col} AS BIGINT) AS stage_tx_index,
          CAST(u.created_height AS BIGINT) AS db_height,
          CAST(u.created_tx_index AS BIGINT) AS db_tx_index,
          CAST(round(CAST(s.value_btc AS DOUBLE) * 100000000) AS BIGINT) AS stage_value_sats,
          CAST(round(CAST(u.value_btc AS DOUBLE) * 100000000) AS BIGINT) AS db_value_sats,
          COALESCE(s.address, '') AS stage_address,
          COALESCE(u.address, '') AS db_address,
          CASE WHEN lower(s.txid) IN {known_sql} THEN true ELSE false END AS known_bip30_txid,
          CASE WHEN {valid_expr} THEN true ELSE false END AS valid_bip30_conflict
        FROM {stage_table} s
        JOIN utxo u
          ON lower(u.txid) = lower(s.txid)
         AND CAST(u.vout AS BIGINT) = CAST(s.vout AS BIGINT)
        WHERE ({where_sql})
        """
    )
    total, known, valid = con.execute(
        """
        SELECT
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE known_bip30_txid) AS known_bip30_txid,
          COUNT(*) FILTER (WHERE valid_bip30_conflict) AS valid_bip30_conflict
        FROM v11_created_conflict_report
        """
    ).fetchone()
    total_i = int(total or 0)
    known_i = int(known or 0)
    valid_i = int(valid or 0)
    invalid_i = max(0, total_i - valid_i)
    examples = [
        {
            "txid": str(r[0]),
            "vout": int(r[1]),
            "stage_height": int(r[2]) if r[2] is not None else None,
            "db_height": int(r[3]) if r[3] is not None else None,
            "stage_tx_index": int(r[4]) if r[4] is not None else None,
            "db_tx_index": int(r[5]) if r[5] is not None else None,
            "known_bip30_txid": bool(r[6]),
            "valid_bip30_conflict": bool(r[7]),
        }
        for r in con.execute(
            """
            SELECT txid, vout, stage_height, db_height, stage_tx_index, db_tx_index, known_bip30_txid, valid_bip30_conflict
            FROM v11_created_conflict_report
            WHERE NOT valid_bip30_conflict
            ORDER BY stage_height, txid, vout
            LIMIT 20
            """
        ).fetchall()
    ]
    return {
        "total": total_i,
        "known_bip30_txid": known_i,
        "valid_bip30_conflict": valid_i,
        "invalid_total": invalid_i,
        "non_bip30": max(0, total_i - known_i),
        "known_bip30_invalid": max(0, known_i - valid_i),
        "invalid_examples": examples,
    }




def _v11_collect_canonical_replacements(days: Sequence[str]) -> List[Dict[str, Any]]:
    """Load and validate per-day canonical replacement plans from stage manifests."""
    collected: List[Dict[str, Any]] = []
    errors: List[str] = []
    target_by_height: Dict[int, str] = {}
    seen: set = set()
    for day_raw in days:
        day = str(day_raw)
        manifest = _load_manifest(day)
        if not manifest:
            errors.append(f"manifest_missing:{day}")
            continue
        duplicate_guard = manifest.get("duplicate_guard") if isinstance(manifest.get("duplicate_guard"), dict) else {}
        replacements = duplicate_guard.get("canonical_replacements")
        if replacements is None:
            replacements = []
        if not isinstance(replacements, list):
            errors.append(f"canonical_replacements_not_list:{day}")
            continue
        for i, item in enumerate(replacements):
            if not isinstance(item, dict):
                errors.append(f"canonical_replacement_not_object:{day}:{i}")
                continue
            try:
                height = int(item.get("block_number"))
            except Exception:
                errors.append(f"canonical_replacement_bad_height:{day}:{i}:{item.get('block_number')!r}")
                continue
            discarded = str(item.get("discarded_block_hash") or "").strip().lower()
            canonical = str(item.get("canonical_block_hash") or "").strip().lower()
            source = str(item.get("canonical_source") or "").strip().lower()
            if not re.fullmatch(r"[0-9a-f]{64}", discarded):
                errors.append(f"canonical_replacement_bad_discarded_hash:{day}:{height}:{discarded!r}")
            if not re.fullmatch(r"[0-9a-f]{64}", canonical):
                errors.append(f"canonical_replacement_bad_canonical_hash:{day}:{height}:{canonical!r}")
            if discarded == canonical:
                errors.append(f"canonical_replacement_same_hash:{day}:{height}")
            if source not in {"bitcoin_cli", "esplora"}:
                errors.append(f"canonical_replacement_bad_source:{day}:{height}:{source!r}")
            old_target = target_by_height.get(height)
            if old_target is not None and old_target != canonical:
                errors.append(f"canonical_replacement_conflicting_target:{height}:{old_target}!={canonical}")
            target_by_height[height] = canonical
            key = (height, discarded, canonical)
            if key in seen:
                continue
            seen.add(key)
            collected.append({
                "day": day,
                "block_number": height,
                "discarded_block_hash": discarded,
                "canonical_block_hash": canonical,
                "canonical_source": source,
            })
    discarded_keys = {(r["block_number"], r["discarded_block_hash"]) for r in collected}
    for r in collected:
        if (r["block_number"], r["canonical_block_hash"]) in discarded_keys:
            errors.append(
                f"canonical_replacement_target_also_discarded:{r['block_number']}:{r['canonical_block_hash']}"
            )
    if errors:
        raise RuntimeError("BLOCKED_BEFORE_APPLY invalid canonical replacement manifest plan: " + ";".join(errors[:100]))
    return sorted(collected, key=lambda r: (int(r["block_number"]), str(r["discarded_block_hash"]), str(r["day"])))


def _v11_mark_canonical_replacement_preflight(
    days: Sequence[str],
    report: Dict[str, Any],
    *,
    blocked: bool,
) -> None:
    affected = set(str(x) for x in report.get("affected_days") or [])
    if not affected:
        return
    for day_raw in days:
        day = str(day_raw)
        if day not in affected:
            continue
        patch: Dict[str, Any] = {
            "duplicate_guard": {
                "canonical_replacement_preflight": report,
            }
        }
        if blocked:
            patch["status"] = STATUS_BLOCKED_BEFORE_APPLY
            patch["errors"] = [{
                "phase": "canonical_replacement_preflight",
                "error": "BLOCKED_BEFORE_APPLY",
                "message": str(report.get("error") or "canonical replacement preflight failed"),
            }]
        _update_manifest(day, patch)


def _v11_canonical_replacement_preflight(
    con: duckdb.DuckDBPyConnection,
    days: Sequence[str],
    *,
    context: str,
    persist_manifest: bool = True,
) -> Dict[str, Any]:
    """Require each discarded block to be absent and its canonical replacement unique.

    This runs after all requested stage days are materialized, but before any
    partial/dirty marker and before REPLAY_SUFFIX cleanup or the first apply
    window.  It checks v11_block_meta_raw (un-collapsed) as well as the collapsed
    v11_block_meta_all view.
    """
    t0 = _tic()
    replacements = _v11_collect_canonical_replacements(days)
    affected_days = sorted({str(r["day"]) for r in replacements})
    report: Dict[str, Any] = {
        "status": "OK",
        "context": str(context),
        "checked_replacements": len(replacements),
        "affected_days": affected_days,
        "missing_replacements": 0,
        "discarded_blocks_remaining": 0,
        "multiple_hashes_at_replaced_heights": 0,
        "canonical_replacement_duplicated": 0,
        "collapsed_block_meta_mismatch": 0,
        "failures": [],
        "examples": [],
        "elapsed_sec": 0.0,
    }
    con.execute("DROP TABLE IF EXISTS v11_canonical_replacements")
    con.execute(
        """
        CREATE TEMP TABLE v11_canonical_replacements(
          day VARCHAR,
          block_number BIGINT,
          discarded_block_hash VARCHAR,
          canonical_block_hash VARCHAR,
          canonical_source VARCHAR
        )
        """
    )
    if not replacements:
        report["elapsed_sec"] = _toc(t0)
        _log(f"v11 canonical replacement preflight context={context}: no replacements")
        return report
    con.executemany(
        "INSERT INTO v11_canonical_replacements VALUES (?, ?, ?, ?, ?)",
        [
            (
                r["day"], int(r["block_number"]), r["discarded_block_hash"],
                r["canonical_block_hash"], r["canonical_source"],
            )
            for r in replacements
        ],
    )
    rows = con.execute(
        """
        SELECT
          p.day,
          p.block_number,
          p.discarded_block_hash,
          p.canonical_block_hash,
          COUNT(*) FILTER (WHERE r.block_hash = p.canonical_block_hash) AS canonical_rows,
          COUNT(*) FILTER (WHERE r.block_hash = p.discarded_block_hash) AS discarded_rows,
          COUNT(DISTINCT r.block_hash) AS hashes_at_height,
          COUNT(DISTINCT CASE WHEN r.block_hash = p.canonical_block_hash THEN r.block_timestamp END) AS canonical_timestamps,
          COUNT(*) FILTER (
            WHERE a.block_hash IS DISTINCT FROM p.canonical_block_hash
               OR a.block_number IS NULL
          ) AS collapsed_mismatch
        FROM v11_canonical_replacements p
        LEFT JOIN v11_block_meta_raw r
          ON r.block_number = p.block_number
        LEFT JOIN v11_block_meta_all a
          ON a.block_number = p.block_number
        GROUP BY 1,2,3,4
        ORDER BY p.block_number, p.discarded_block_hash
        """
    ).fetchall()
    failures: List[str] = []
    examples: List[Dict[str, Any]] = []
    for row in rows:
        day, height, discarded, canonical = str(row[0]), int(row[1]), str(row[2]), str(row[3])
        canonical_rows = int(row[4] or 0)
        discarded_rows = int(row[5] or 0)
        hashes_at_height = int(row[6] or 0)
        canonical_timestamps = int(row[7] or 0)
        collapsed_mismatch = int(row[8] or 0)
        row_failures: List[str] = []
        if canonical_rows == 0:
            report["missing_replacements"] += 1
            row_failures.append("canonical_missing")
        if canonical_rows != 1 or canonical_timestamps != 1:
            if canonical_rows > 1 or canonical_timestamps > 1:
                report["canonical_replacement_duplicated"] += 1
            row_failures.append(f"canonical_not_unique:rows={canonical_rows}:timestamps={canonical_timestamps}")
        if discarded_rows != 0:
            report["discarded_blocks_remaining"] += 1
            row_failures.append(f"discarded_remaining:{discarded_rows}")
        if hashes_at_height != 1:
            report["multiple_hashes_at_replaced_heights"] += 1
            row_failures.append(f"hashes_at_height:{hashes_at_height}")
        if collapsed_mismatch != 0:
            report["collapsed_block_meta_mismatch"] += 1
            row_failures.append("collapsed_block_meta_mismatch")
        if row_failures:
            failures.append(
                f"height={height}:discarded={discarded}:canonical={canonical}:" + ",".join(row_failures)
            )
            if len(examples) < 50:
                examples.append({
                    "day": day,
                    "block_number": height,
                    "discarded_block_hash": discarded,
                    "canonical_block_hash": canonical,
                    "canonical_rows": canonical_rows,
                    "discarded_rows": discarded_rows,
                    "hashes_at_height": hashes_at_height,
                    "canonical_timestamps": canonical_timestamps,
                    "collapsed_mismatch": collapsed_mismatch,
                    "failures": row_failures,
                })
    report["failures"] = failures[:100]
    report["examples"] = examples
    report["elapsed_sec"] = _toc(t0)
    if failures:
        report["status"] = STATUS_BLOCKED_BEFORE_APPLY
        report["error"] = "canonical replacement preflight failed: " + ";".join(failures[:20])
        if persist_manifest:
            _v11_mark_canonical_replacement_preflight(days, report, blocked=True)
        raise RuntimeError("BLOCKED_BEFORE_APPLY " + str(report["error"]))
    if persist_manifest:
        _v11_mark_canonical_replacement_preflight(days, report, blocked=False)
    _log(
        f"v11 canonical replacement preflight context={context} status=OK "
        f"checked={len(replacements)} in {_fmt_s(report['elapsed_sec'])}"
    )
    return report

def _v11_reused_stage_day_manifest(day: str) -> Dict[str, Any]:
    """Load one immutable existing day stage without deleting or rebuilding it."""
    day = str(day)
    day_dir = (_stage_root_path_no_create() / f"date={day}").resolve(strict=False)
    manifest_path = day_dir / "manifest.json"
    if not manifest_path.is_file() or manifest_path.is_symlink():
        raise RuntimeError(
            f"explicit stage reuse requires regular manifest day={day}: {manifest_path}"
        )
    manifest = _load_manifest(day)
    if not isinstance(manifest, dict):
        raise RuntimeError(f"explicit stage reuse manifest unreadable day={day}: {manifest_path}")
    _v11_stage_manifest_guard(day, manifest)
    files = manifest.get("files") if isinstance(manifest.get("files"), dict) else {}
    expected = {
        "created_parquet": day_dir / "created.parquet",
        "spends_parquet": day_dir / "spends.parquet",
        "block_meta_parquet": day_dir / "block_meta.parquet",
    }
    for key, expected_path in expected.items():
        raw = files.get(key)
        actual = Path(str(raw or "")).resolve(strict=False)
        expected_resolved = expected_path.resolve(strict=False)
        if actual != expected_resolved:
            raise RuntimeError(
                f"explicit stage reuse path mismatch day={day} key={key}: "
                f"actual={actual} expected={expected_resolved}"
            )
        if not actual.is_file() or actual.is_symlink():
            raise RuntimeError(
                f"explicit stage reuse file missing/not-regular day={day} "
                f"key={key} path={actual}"
            )
    return manifest


def _v11_stage_dayset_contract(days: Sequence[str]) -> Dict[str, Any]:
    """Return a stable identity for the exact ordered selected-stage day set.

    Available raw partitions are not guaranteed to exist for every calendar day
    (notably at the start of the Bitcoin chain).  Therefore range length must
    never be inferred from end-start+1.  Bind artifacts to the exact sorted list.
    """
    normalized = [str(x) for x in days]
    if not normalized:
        raise RuntimeError("stage dayset cannot be empty")
    parsed = []
    for item in normalized:
        try:
            parsed.append(_parse_date(item))
        except Exception as exc:
            raise RuntimeError(f"invalid stage day in selected dayset: {item!r}") from exc
    if len(set(normalized)) != len(normalized):
        raise RuntimeError("stage dayset contains duplicate dates")
    if any(parsed[i] >= parsed[i + 1] for i in range(len(parsed) - 1)):
        raise RuntimeError("stage dayset must be strictly increasing")
    h = hashlib.sha256()
    for item in normalized:
        h.update(item.encode("ascii"))
        h.update(b"\n")
    return {
        "contract_version": V11_STAGE_DAYSET_CONTRACT_VERSION,
        "days": len(normalized),
        "start_day": normalized[0],
        "end_day": normalized[-1],
        "days_sha256": h.hexdigest(),
    }


def _v11_prepare_write_stage_days(
    raw_base: str,
    days: Sequence[str],
    mode: str,
    semantic_stop_on_fail: bool,
) -> Dict[str, Any]:
    """Build selected stage days or reuse them under one explicit operator policy."""
    action = _v11_stage_action()
    producer_versions = set()
    completed = 0
    for i, day_raw in enumerate(days, start=1):
        day = str(day_raw)
        next_day = str(days[i]) if i < len(days) else None
        if action == "build":
            _prepare_day_for_replay(day)
            _phase_started(
                f"stage:{day}", "S13910",
                f"STAGE_BUILD_STARTED day={day} mode={mode} action=build",
            )
            manifest = _build_day_stage(raw_base, day, mode, semantic_stop_on_fail)
            _v11_stage_manifest_guard(day, manifest)
            _phase_completed(
                f"stage:{day}", "S13911",
                f"STAGE_BUILD_COMPLETE day={day} mode={mode} action=build",
            )
        else:
            _phase_started(
                f"stage:{day}", "S13910",
                f"STAGE_REUSE_STARTED day={day} mode={mode} action=reuse",
            )
            manifest = _v11_reused_stage_day_manifest(day)
            _phase_completed(
                f"stage:{day}", "S13911",
                f"STAGE_REUSE_COMPLETE day={day} mode={mode} action=reuse "
                f"producer={manifest.get('pipeline_version')}",
            )
        producer_versions.add(str(manifest.get("pipeline_version") or ""))
        completed += 1
        stop_now, stop_reason = _check_controlled_stop_after_completed_day(
            day, completed, next_day
        )
        if stop_now:
            raise ControlledStopExit(
                f"v11 {mode} controlled stop during stage {action} "
                f"after day={day}: {stop_reason}",
                exit_code=75,
                payload={"mode": mode, "day": day, "stage_action": action, "reason": stop_reason},
            )
    reviewed_producers = sorted(x for x in producer_versions if x)
    if action == "reuse":
        unreviewed = sorted(
            x for x in reviewed_producers
            if x not in V11_REUSABLE_STAGE_PIPELINE_VERSIONS
        )
        if unreviewed:
            raise RuntimeError(
                "explicit stage reuse contains unreviewed producer versions: "
                f"{unreviewed}; allowed={sorted(V11_REUSABLE_STAGE_PIPELINE_VERSIONS)}"
            )
    dayset = _v11_stage_dayset_contract(days)
    if int(completed) != int(dayset["days"]):
        raise RuntimeError(
            f"stage input completed-day count mismatch: {completed}!={dayset['days']}"
        )
    report = {
        "contract_version": V11_STAGE_REUSE_CONTRACT_VERSION,
        "action": action,
        "days": int(dayset["days"]),
        "start_day": dayset["start_day"],
        "end_day": dayset["end_day"],
        "dayset_contract_version": dayset["contract_version"],
        "days_sha256": dayset["days_sha256"],
        "producer_versions": reviewed_producers,
    }
    _log(f"v11 stage input ready: {report}")
    return report


def _v11_materialize_apply_stage(
    con: duckdb.DuckDBPyConnection,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> None:
    """Materialize all v11 stage parquet once before block-window apply."""
    created_sql = _quote_sql_list([str(x) for x in created_paths])
    spends_sql = _quote_sql_list([str(x) for x in spends_paths])
    block_meta_sql = _quote_sql_list([str(x) for x in block_meta_paths])
    for table in ["v11_created_all", "v11_spends_all", "v11_block_meta_raw", "v11_block_meta_all"]:
        con.execute(f"DROP TABLE IF EXISTS {table}")

    con.execute(
        f"""
        CREATE TEMP TABLE v11_created_all AS
        SELECT
          txid,
          vout,
          address,
          value_btc,
          created_ts,
          created_date,
          block_number::BIGINT AS block_number,
          block_hash::VARCHAR AS block_hash,
          tx_index::BIGINT AS tx_index,
          raw_partition_date
        FROM read_parquet({created_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL
        """
    )

    con.execute(
        f"""
        CREATE TEMP TABLE v11_spends_all AS
        SELECT
          prev_txid,
          prev_vout,
          spent_txid,
          spent_vin,
          spent_ts,
          spent_date,
          block_number::BIGINT AS block_number,
          block_hash::VARCHAR AS block_hash,
          tx_index::BIGINT AS tx_index,
          raw_partition_date
        FROM read_parquet({spends_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL
        """
    )

    con.execute(
        f"""
        CREATE TEMP TABLE v11_block_meta_raw AS
        SELECT
          block_number::BIGINT AS block_number,
          lower(block_hash)::VARCHAR AS block_hash,
          block_timestamp::TIMESTAMP AS block_timestamp,
          CAST(block_timestamp AS DATE) AS block_date,
          MIN(raw_partition_min)::DATE AS raw_partition_min,
          MAX(raw_partition_max)::DATE AS raw_partition_max
        FROM read_parquet({block_meta_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL AND block_hash IS NOT NULL AND block_timestamp IS NOT NULL
        GROUP BY block_number, lower(block_hash), block_timestamp
        """
    )

    # Keep v11_block_meta_raw for duplicate-hash/timestamp preflight, then
    # collapse to one row per height only after the raw metadata has been checked.
    con.execute(
        """
        CREATE TEMP TABLE v11_block_meta_all AS
        SELECT
          block_number,
          MIN(block_hash)::VARCHAR AS block_hash,
          MIN(block_timestamp)::TIMESTAMP AS block_timestamp,
          CAST(MIN(block_timestamp) AS DATE) AS block_date,
          MIN(raw_partition_min)::DATE AS raw_partition_min,
          MAX(raw_partition_max)::DATE AS raw_partition_max
        FROM v11_block_meta_raw
        GROUP BY block_number
        """
    )

    created_rows = int(con.execute("SELECT COUNT(*) FROM v11_created_all").fetchone()[0] or 0)
    spends_rows = int(con.execute("SELECT COUNT(*) FROM v11_spends_all").fetchone()[0] or 0)
    blocks = int(con.execute("SELECT COUNT(*) FROM v11_block_meta_all").fetchone()[0] or 0)
    _log(f"v11 materialized apply stage: created_rows={created_rows} spends_rows={spends_rows} blocks={blocks}")


def _v11_materialized_stage_counts(con: duckdb.DuckDBPyConnection) -> Dict[str, int]:
    return {
        "created_rows": int(con.execute("SELECT COUNT(*) FROM v11_created_all").fetchone()[0] or 0),
        "spends_rows": int(con.execute("SELECT COUNT(*) FROM v11_spends_all").fetchone()[0] or 0),
        "block_meta_rows": int(con.execute("SELECT COUNT(*) FROM v11_block_meta_all").fetchone()[0] or 0),
    }


def _v11_stage_source_paths_snapshot(
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> Dict[str, List[str]]:
    return {
        "created_paths": [str(Path(x).resolve(strict=False)) for x in created_paths],
        "spends_paths": [str(Path(x).resolve(strict=False)) for x in spends_paths],
        "block_meta_paths": [str(Path(x).resolve(strict=False)) for x in block_meta_paths],
    }


def _v11_write_frozen_stage_contract(
    stage_lock: Path,
    *,
    mode: str,
    days: Sequence[str],
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
    stage_fingerprint: Dict[str, Any],
    stage_counts: Dict[str, int],
    h_min: Optional[int],
    h_max: Optional[int],
    block_preflight: Dict[str, Any],
    global_preflight: Dict[str, Any],
    canonical_replacement_preflight: Dict[str, Any],
    stage_input_report: Optional[Dict[str, Any]] = None,
    window_source_index: Optional[Dict[str, Any]] = None,
    enforce_content_fingerprint: bool = False,
) -> Dict[str, Any]:
    if not stage_lock.exists():
        raise RuntimeError(f"cannot freeze stage without active stage lock: {stage_lock}")
    stat_fingerprint = _v11_stage_manifest_fingerprint(days)
    dayset = _v11_stage_dayset_contract(days)
    stage_input_payload = dict(stage_input_report or {})
    for key, expected in (
        ("days", dayset["days"]),
        ("start_day", dayset["start_day"]),
        ("end_day", dayset["end_day"]),
        ("dayset_contract_version", dayset["contract_version"]),
        ("days_sha256", dayset["days_sha256"]),
    ):
        if stage_input_payload.get(key) != expected:
            raise RuntimeError(
                f"cannot freeze inconsistent stage-input dayset field {key}: "
                f"{stage_input_payload.get(key)!r}!={expected!r}"
            )
    if stat_fingerprint.get("days_sha256") != dayset["days_sha256"]:
        raise RuntimeError("cannot freeze inconsistent stat-fingerprint stage dayset")
    if isinstance(stage_fingerprint, dict) and stage_fingerprint.get("days_sha256") != dayset["days_sha256"]:
        raise RuntimeError("cannot freeze inconsistent content-fingerprint stage dayset")
    contract = {
        "contract_version": FROZEN_STAGE_CONTRACT_VERSION,
        "generation_id": uuid.uuid4().hex,
        "status": "frozen",
        "mode": str(mode),
        "pid": os.getpid(),
        "host": socket.gethostname(),
        "frozen_at": _now_iso(),
        "stage_root": str(_stage_root_path_no_create().resolve()),
        "days": [str(x) for x in days],
        "start_day": str(days[0]) if days else None,
        "end_day": str(days[-1]) if days else None,
        "paths": _v11_stage_source_paths_snapshot(created_paths, spends_paths, block_meta_paths),
        "stage_fingerprint": stage_fingerprint,
        "stat_fingerprint": stat_fingerprint,
        "enforce_content_fingerprint": bool(enforce_content_fingerprint),
        "stage_counts": {str(k): int(v) for k, v in stage_counts.items()},
        "h_min": None if h_min is None else int(h_min),
        "h_max": None if h_max is None else int(h_max),
        "block_preflight": block_preflight,
        "global_preflight": global_preflight,
        "canonical_replacement_preflight": canonical_replacement_preflight,
        "stage_input": stage_input_payload,
        "window_source_index": dict(window_source_index or {}),
    }
    path = stage_lock / "frozen_stage.json"
    _save_json_atomic(path, contract)
    contract["contract_path"] = str(path)
    _emit_event(
        "S15912",
        f"STAGE_FROZEN mode={mode} generation_id={contract['generation_id']} "
        f"range={contract['h_min']}..{contract['h_max']} sha256={stat_fingerprint.get('sha256')}",
    )
    return contract


def _v11_revalidate_frozen_stage(
    contract: Dict[str, Any],
    *,
    days: Sequence[str],
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> Dict[str, Any]:
    if str(contract.get("contract_version") or "") != FROZEN_STAGE_CONTRACT_VERSION:
        raise RuntimeError(
            f"BLOCKED_BEFORE_APPLY frozen-stage contract mismatch: {contract.get('contract_version')!r}"
        )
    expected_days = [str(x) for x in days]
    dayset = _v11_stage_dayset_contract(expected_days)
    if contract.get("days") != expected_days:
        raise RuntimeError("BLOCKED_BEFORE_APPLY frozen-stage selected day list changed")
    stage_input_payload = contract.get("stage_input") if isinstance(contract.get("stage_input"), dict) else {}
    for key, expected in (
        ("days", dayset["days"]),
        ("start_day", dayset["start_day"]),
        ("end_day", dayset["end_day"]),
        ("dayset_contract_version", dayset["contract_version"]),
        ("days_sha256", dayset["days_sha256"]),
    ):
        if stage_input_payload.get(key) != expected:
            raise RuntimeError(
                f"BLOCKED_BEFORE_APPLY frozen-stage dayset field changed {key}: "
                f"{stage_input_payload.get(key)!r}!={expected!r}"
            )
    stage_root = str(_stage_root_path_no_create().resolve())
    if str(contract.get("stage_root") or "") != stage_root:
        raise RuntimeError(
            f"BLOCKED_BEFORE_APPLY frozen-stage root changed: {contract.get('stage_root')!r}!={stage_root!r}"
        )
    current_paths = _v11_stage_source_paths_snapshot(created_paths, spends_paths, block_meta_paths)
    if contract.get("paths") != current_paths:
        raise RuntimeError("BLOCKED_BEFORE_APPLY frozen-stage parquet path set changed")
    current_stat = _v11_stage_manifest_fingerprint(days)
    expected_stat = contract.get("stat_fingerprint") if isinstance(contract.get("stat_fingerprint"), dict) else {}
    if current_stat.get("sha256") != expected_stat.get("sha256"):
        raise RuntimeError(
            "BLOCKED_BEFORE_APPLY frozen-stage stat fingerprint changed: "
            f"{expected_stat.get('sha256')}!={current_stat.get('sha256')}"
        )
    if current_stat.get("days_sha256") != dayset["days_sha256"]:
        raise RuntimeError("BLOCKED_BEFORE_APPLY frozen-stage stat fingerprint dayset changed")
    source_index = contract.get("window_source_index")
    if not isinstance(source_index, dict):
        raise RuntimeError("BLOCKED_BEFORE_APPLY frozen-stage window source index missing")
    if str(source_index.get("contract_version") or "") != V11_WINDOW_SOURCE_INDEX_CONTRACT_VERSION:
        raise RuntimeError(
            "BLOCKED_BEFORE_APPLY frozen-stage window source index contract mismatch: "
            f"{source_index.get('contract_version')!r}"
        )
    index_entries = source_index.get("entries")
    if not isinstance(index_entries, list) or len(index_entries) != len(created_paths):
        raise RuntimeError(
            "BLOCKED_BEFORE_APPLY frozen-stage window source index cardinality mismatch"
        )
    indexed_paths = {
        "created_paths": [str(x.get("created_path")) for x in index_entries if isinstance(x, dict)],
        "spends_paths": [str(x.get("spends_path")) for x in index_entries if isinstance(x, dict)],
        "block_meta_paths": [str(x.get("block_meta_path")) for x in index_entries if isinstance(x, dict)],
    }
    if indexed_paths != current_paths:
        raise RuntimeError(
            "BLOCKED_BEFORE_APPLY frozen-stage window source index path set changed"
        )

    current_content = None
    if bool(contract.get("enforce_content_fingerprint")):
        current_content = _v11_append_stage_manifest_fingerprint(days)
        expected_content = contract.get("stage_fingerprint") if isinstance(contract.get("stage_fingerprint"), dict) else {}
        if current_content.get("days_sha256") != dayset["days_sha256"]:
            raise RuntimeError("BLOCKED_BEFORE_APPLY frozen-stage content fingerprint dayset changed")
        if current_content.get("sha256") != expected_content.get("sha256"):
            raise RuntimeError(
                "BLOCKED_BEFORE_APPLY frozen-stage content fingerprint changed: "
                f"{expected_content.get('sha256')}!={current_content.get('sha256')}"
            )
    _emit_event(
        "S15913",
        f"FROZEN_STAGE_REVALIDATED generation_id={contract.get('generation_id')} "
        f"stat_sha256={current_stat.get('sha256')}",
    )
    return {"stat_fingerprint": current_stat, "content_fingerprint": current_content}


def _v11_release_proof_memory(context: str) -> None:
    gc.collect()
    trimmed = None
    try:
        libc = ctypes.CDLL(None)
        malloc_trim = getattr(libc, "malloc_trim", None)
        if malloc_trim is not None:
            malloc_trim.argtypes = [ctypes.c_size_t]
            malloc_trim.restype = ctypes.c_int
            trimmed = int(malloc_trim(0))
    except Exception:
        trimmed = None
    _log(f"v11 proof memory release context={context} malloc_trim={trimmed} {_v10_10_memory_text()}")


def _v11_memory_snapshot() -> Dict[str, Any]:
    report: Dict[str, Any] = {
        "available": False,
        "mem_available_gb": None,
        "swap_total_gb": None,
        "swap_free_gb": None,
        "rss_gb": None,
        "hwm_gb": None,
        "vm_swap_gb": None,
    }
    try:
        values: Dict[str, int] = {}
        for line in Path("/proc/meminfo").read_text(errors="replace").splitlines():
            if line.startswith(("MemAvailable:", "SwapTotal:", "SwapFree:")):
                key, rest = line.split(":", 1)
                values[key] = int(rest.strip().split()[0])
        proc_values: Dict[str, int] = {}
        for line in Path("/proc/self/status").read_text(errors="replace").splitlines():
            if line.startswith(("VmRSS:", "VmHWM:", "VmSwap:")):
                key, rest = line.split(":", 1)
                proc_values[key] = int(rest.strip().split()[0])
        scale = 1024.0 * 1024.0
        report.update({
            "available": "MemAvailable" in values,
            "mem_available_gb": round(values.get("MemAvailable", 0) / scale, 3),
            "swap_total_gb": round(values.get("SwapTotal", 0) / scale, 3),
            "swap_free_gb": round(values.get("SwapFree", 0) / scale, 3),
            "rss_gb": round(proc_values.get("VmRSS", 0) / scale, 3),
            "hwm_gb": round(proc_values.get("VmHWM", 0) / scale, 3),
            "vm_swap_gb": round(proc_values.get("VmSwap", 0) / scale, 3),
        })
    except Exception as exc:
        report["error"] = f"{type(exc).__name__}:{exc}"
    return report


def _v11_memory_guard(context: str, *, before_window: bool = False) -> Dict[str, Any]:
    report = _v11_memory_snapshot()
    _log(f"v11 memory guard context={context} report={report}")
    if not _env_bool("UTXO_V11_MEMORY_GUARD", True) or not report.get("available"):
        return report
    env_name = (
        "UTXO_V11_MIN_AVAILABLE_GB_BEFORE_WINDOW"
        if before_window
        else "UTXO_V11_MIN_AVAILABLE_GB_BEFORE_WRITE"
    )
    default = 2.0 if before_window else 4.0
    minimum = max(0.0, _env_float(env_name, default))
    available = float(report.get("mem_available_gb") or 0.0)
    if available < minimum:
        raise ControlledStopExit(
            f"memory guard blocked {context}: MemAvailable={available:.3f}GB < {minimum:.3f}GB ({env_name})",
            exit_code=75,
            payload={"context": context, "memory": report, "minimum_available_gb": minimum},
        )
    return report


def _v11_build_window_source_index(
    con: duckdb.DuckDBPyConnection,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> Dict[str, Any]:
    """Build one compact file-to-height index from block_meta parquet.

    The three path lists are emitted in day order by _v11_stage_paths(), so one
    block_meta file provides the authoritative height bounds for its matching
    created/spends files. Empty fully-discarded partitions remain indexed with
    NULL bounds and are never selected for a writer window.
    """
    if not (
        len(created_paths) == len(spends_paths) == len(block_meta_paths)
    ):
        raise RuntimeError(
            "window source path cardinality mismatch: "
            f"created={len(created_paths)} spends={len(spends_paths)} "
            f"block_meta={len(block_meta_paths)}"
        )
    if not block_meta_paths:
        raise RuntimeError("window source index cannot be built from an empty path set")

    block_meta_sql = _quote_sql_list([str(x) for x in block_meta_paths])
    rows = con.execute(
        f"""
        SELECT
          filename::VARCHAR AS filename,
          MIN(block_number::BIGINT) AS h_min,
          MAX(block_number::BIGINT) AS h_max,
          COUNT(*)::BIGINT AS rows
        FROM read_parquet(
          {block_meta_sql},
          union_by_name=true,
          filename=true
        )
        WHERE block_number IS NOT NULL
        GROUP BY filename
        """
    ).fetchall()
    bounds: Dict[str, Tuple[int, int, int]] = {}
    for filename, h_min, h_max, row_count in rows:
        key = str(Path(str(filename)).resolve(strict=False))
        if key in bounds:
            raise RuntimeError(f"duplicate block_meta filename in window source index: {key}")
        bounds[key] = (int(h_min), int(h_max), int(row_count))

    expected_block_paths = {
        str(Path(x).resolve(strict=False)) for x in block_meta_paths
    }
    unexpected = sorted(set(bounds) - expected_block_paths)
    if unexpected:
        raise RuntimeError(
            f"window source index returned unexpected block_meta files: {unexpected[:20]}"
        )

    entries: List[Dict[str, Any]] = []
    nonempty = 0
    global_min: Optional[int] = None
    global_max: Optional[int] = None
    for created, spends, block_meta in zip(created_paths, spends_paths, block_meta_paths):
        block_key = str(Path(block_meta).resolve(strict=False))
        bound = bounds.get(block_key)
        h_min = bound[0] if bound else None
        h_max = bound[1] if bound else None
        row_count = bound[2] if bound else 0
        if bound:
            nonempty += 1
            global_min = h_min if global_min is None else min(global_min, h_min)
            global_max = h_max if global_max is None else max(global_max, h_max)
        entries.append({
            "created_path": str(Path(created).resolve(strict=False)),
            "spends_path": str(Path(spends).resolve(strict=False)),
            "block_meta_path": block_key,
            "h_min": h_min,
            "h_max": h_max,
            "block_meta_rows": int(row_count),
        })

    report = {
        "contract_version": V11_WINDOW_SOURCE_INDEX_CONTRACT_VERSION,
        "entries": entries,
        "files_total": len(entries),
        "files_nonempty": int(nonempty),
        "files_empty": int(len(entries) - nonempty),
        "h_min": global_min,
        "h_max": global_max,
    }
    _log(
        "v11 window source index ready: "
        f"files_total={report['files_total']} nonempty={report['files_nonempty']} "
        f"empty={report['files_empty']} range={global_min}..{global_max}"
    )
    return report


def _v11_window_source_index_summary(source_index: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "contract_version": source_index.get("contract_version"),
        "files_total": source_index.get("files_total"),
        "files_nonempty": source_index.get("files_nonempty"),
        "files_empty": source_index.get("files_empty"),
        "h_min": source_index.get("h_min"),
        "h_max": source_index.get("h_max"),
    }


def _v11_select_window_source_paths(
    source_index: Dict[str, Any], h1: int, h2: int
) -> Tuple[List[str], List[str], List[str]]:
    if str(source_index.get("contract_version") or "") != V11_WINDOW_SOURCE_INDEX_CONTRACT_VERSION:
        raise RuntimeError(
            "window source index contract mismatch: "
            f"{source_index.get('contract_version')!r}"
        )
    entries = source_index.get("entries")
    if not isinstance(entries, list):
        raise RuntimeError("window source index entries missing/not-list")
    selected = []
    for item in entries:
        if not isinstance(item, dict):
            raise RuntimeError("window source index entry is not an object")
        lo = item.get("h_min")
        hi = item.get("h_max")
        if lo is None or hi is None:
            continue
        if int(hi) >= int(h1) and int(lo) <= int(h2):
            selected.append(item)
    if not selected:
        raise RuntimeError(
            f"window source index selected no parquet files for block_window={h1}-{h2}"
        )
    return (
        [str(x["created_path"]) for x in selected],
        [str(x["spends_path"]) for x in selected],
        [str(x["block_meta_path"]) for x in selected],
    )


def _v11_bind_windowed_stage_sources(
    con: duckdb.DuckDBPyConnection,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> None:
    if not created_paths or not spends_paths or not block_meta_paths:
        raise RuntimeError(
            "cannot bind windowed stage sources with an empty selected path set"
        )
    created_sql = _quote_sql_list([str(x) for x in created_paths])
    spends_sql = _quote_sql_list([str(x) for x in spends_paths])
    block_meta_sql = _quote_sql_list([str(x) for x in block_meta_paths])
    for name in ("v11_created_source", "v11_spends_source", "v11_block_meta_source"):
        con.execute(f"DROP VIEW IF EXISTS {name}")
    con.execute(f"""
        CREATE TEMP VIEW v11_created_source AS
        SELECT txid, vout, address, value_btc, created_ts, created_date,
               block_number::BIGINT AS block_number, block_hash::VARCHAR AS block_hash,
               tx_index::BIGINT AS tx_index, raw_partition_date
        FROM read_parquet({created_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL
    """)
    con.execute(f"""
        CREATE TEMP VIEW v11_spends_source AS
        SELECT prev_txid, prev_vout, spent_txid, spent_vin, spent_ts, spent_date,
               block_number::BIGINT AS block_number, block_hash::VARCHAR AS block_hash,
               tx_index::BIGINT AS tx_index, raw_partition_date
        FROM read_parquet({spends_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL
    """)
    con.execute(f"""
        CREATE TEMP VIEW v11_block_meta_source AS
        SELECT block_number::BIGINT AS block_number,
               lower(block_hash)::VARCHAR AS block_hash,
               block_timestamp::TIMESTAMP AS block_timestamp,
               raw_partition_min::DATE AS raw_partition_min,
               raw_partition_max::DATE AS raw_partition_max
        FROM read_parquet({block_meta_sql}, union_by_name=true)
        WHERE block_number IS NOT NULL
          AND block_hash IS NOT NULL
          AND block_timestamp IS NOT NULL
    """)


def _v11_prepare_windowed_stage_sources(
    con: duckdb.DuckDBPyConnection,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
) -> Dict[str, Any]:
    """Prepare a compact index; actual parquet views are rebound per window."""
    return _v11_build_window_source_index(
        con, created_paths, spends_paths, block_meta_paths
    )



def _v11_stage_block_range(con: duckdb.DuckDBPyConnection, created_paths: Sequence[str], spends_paths: Sequence[str]) -> Tuple[int, int]:
    row = con.execute(
        """
        SELECT MIN(block_number), MAX(block_number)
        FROM v11_block_meta_all
        WHERE block_number IS NOT NULL
        """
    ).fetchone()
    if row[0] is None or row[1] is None:
        raise RuntimeError("v11 stage block range is empty")
    return int(row[0]), int(row[1])


def _v11_rebuild_physical_days(days: Sequence[str]) -> Tuple[List[str], Dict[str, Any]]:
    """Return the physical REBUILD_FULL slice that will be staged and applied.

    fix9: UTXO_MAX_DAYS_PER_RUN / UTXO_STOP_AFTER_DAY must not stop the run
    after stage build and before apply. They are planning knobs: they shrink the
    physical day list before stage/apply. This is intentionally independent from
    the genesis/block_meta per-block rule from fix8.
    """
    requested_days = [str(d) for d in days]
    physical_days = list(requested_days)
    stop_after_day = _stop_after_day_env()
    max_days = _max_days_per_run_env()

    if stop_after_day:
        physical_days = [d for d in physical_days if d <= stop_after_day]
    if max_days > 0:
        physical_days = physical_days[:max_days]

    if not physical_days:
        raise RuntimeError(
            "v11 REBUILD_FULL physical day slice is empty: "
            f"requested_range={requested_days[0]}..{requested_days[-1]} "
            f"UTXO_MAX_DAYS_PER_RUN={max_days or '<unset>'} "
            f"UTXO_STOP_AFTER_DAY={stop_after_day or '<unset>'}"
        )

    report = {
        "requested_start_day": requested_days[0],
        "requested_end_day": requested_days[-1],
        "requested_days": len(requested_days),
        "physical_start_day": physical_days[0],
        "physical_end_day": physical_days[-1],
        "physical_days": len(physical_days),
        "max_days_per_run": int(max_days),
        "stop_after_day": stop_after_day,
        "sliced": physical_days != requested_days,
        "reason": "physical_slice_before_stage_apply",
    }
    if report["sliced"]:
        _warn(
            "v11 REBUILD_FULL physical slice active: "
            f"requested={requested_days[0]}..{requested_days[-1]} days={len(requested_days)} "
            f"physical={physical_days[0]}..{physical_days[-1]} days={len(physical_days)} "
            f"UTXO_MAX_DAYS_PER_RUN={max_days or '<unset>'} "
            f"UTXO_STOP_AFTER_DAY={stop_after_day or '<unset>'}. "
            "Stage and apply will use only the physical slice; no mid-stage stop will be used."
        )
    return physical_days, report


def _v11_prod_rebuild_scope_guard(
    raw_base: str,
    requested_days: Sequence[str],
    physical_days: Sequence[str],
    physical_slice_report: Dict[str, Any],
) -> None:
    """Production REBUILD_FULL must be a real full rebuild, not a smoke slice."""
    if _env_bool("UTXO_V11_LAB_MODE", False):
        return

    available_days = _list_available_days(raw_base)
    if not available_days:
        raise RuntimeError("v11 production REBUILD_FULL blocked: no raw days available")

    requested_days = [str(d) for d in requested_days]
    physical_days = [str(d) for d in physical_days]
    failed: List[str] = []

    if not requested_days:
        failed.append("requested_days_empty")
    if not physical_days:
        failed.append("physical_days_empty")

    if requested_days and requested_days[0] != available_days[0]:
        failed.append(f"requested_start_not_raw_start:{requested_days[0]}!={available_days[0]}")
    if requested_days and requested_days[-1] != available_days[-1]:
        failed.append(f"requested_end_not_raw_tail:{requested_days[-1]}!={available_days[-1]}")
    if bool(physical_slice_report.get("sliced")):
        failed.append("physical_slice_active")
    if _max_days_per_run_env() > 0:
        failed.append(f"UTXO_MAX_DAYS_PER_RUN_set:{_max_days_per_run_env()}")
    if _stop_after_day_env():
        failed.append(f"UTXO_STOP_AFTER_DAY_set:{_stop_after_day_env()}")
    if _env_bool("UTXO_V11_ALLOW_PARTIAL_LAB_REBUILD", False):
        failed.append("UTXO_V11_ALLOW_PARTIAL_LAB_REBUILD_requires_lab_mode")

    if failed:
        raise RuntimeError(
            "v11 production REBUILD_FULL scope guard blocked partial/smoke rebuild: "
            + ",".join(failed)
            + f". available_raw_range={available_days[0]}..{available_days[-1]} "
            + f"requested_range={(requested_days[0] if requested_days else '<empty>')}..{(requested_days[-1] if requested_days else '<empty>')} "
            + f"physical_range={(physical_days[0] if physical_days else '<empty>')}..{(physical_days[-1] if physical_days else '<empty>')}. "
            + "For smoke/lab runs set UTXO_V11_LAB_MODE=1 and use a lab DB path."
        )

    _log(
        "v11 production REBUILD_FULL scope guard ok: "
        f"raw_range={available_days[0]}..{available_days[-1]} days={len(available_days)} "
        f"requested_days={len(requested_days)} physical_days={len(physical_days)}"
    )


def _v11_block_preflight(con: duckdb.DuckDBPyConnection) -> Dict[str, Any]:
    duplicate_hash_heights = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT block_number
          FROM v11_block_meta_raw
          WHERE block_number IS NOT NULL
          GROUP BY block_number
          HAVING COUNT(DISTINCT block_hash) > 1
        ) d
        """
    ).fetchone()[0] or 0)

    timestamp_inconsistent_blocks = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT block_number
          FROM v11_block_meta_raw
          WHERE block_number IS NOT NULL AND block_timestamp IS NOT NULL
          GROUP BY block_number
          HAVING COUNT(DISTINCT block_timestamp) > 1
        ) d
        """
    ).fetchone()[0] or 0)

    tx_index_conflict_positions = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT block_number, tx_index
          FROM (
            SELECT block_number, tx_index, txid FROM v11_created_all
            UNION ALL
            SELECT block_number, tx_index, spent_txid AS txid FROM v11_spends_all
          ) x
          WHERE block_number IS NOT NULL AND tx_index IS NOT NULL AND txid IS NOT NULL
          GROUP BY block_number, tx_index
          HAVING COUNT(DISTINCT txid) > 1
        ) d
        """
    ).fetchone()[0] or 0)

    txid_multi_index_rows = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT block_number, txid
          FROM (
            SELECT block_number, tx_index, txid FROM v11_created_all
            UNION ALL
            SELECT block_number, tx_index, spent_txid AS txid FROM v11_spends_all
          ) x
          WHERE block_number IS NOT NULL AND tx_index IS NOT NULL AND txid IS NOT NULL
          GROUP BY block_number, txid
          HAVING COUNT(DISTINCT tx_index) > 1
        ) d
        """
    ).fetchone()[0] or 0)

    causal_row = con.execute(
        """WITH tx AS (
             SELECT DISTINCT block_number, lower(block_hash) AS block_hash, tx_index, txid
             FROM v11_created_all
             WHERE block_number IS NOT NULL AND block_hash IS NOT NULL AND tx_index IS NOT NULL AND txid IS NOT NULL
           )
           SELECT
             (SELECT COUNT(*) FROM tx WHERE block_number < 0 OR tx_index < 0),
             (SELECT COUNT(*) FROM (SELECT block_number,block_hash FROM tx GROUP BY 1,2 HAVING MIN(tx_index)<>0 OR MAX(tx_index)+1<>COUNT(*) OR COUNT(DISTINCT tx_index)<>COUNT(*)) q),
             (SELECT COUNT(*) FROM (SELECT block_hash FROM tx GROUP BY 1 HAVING COUNT(DISTINCT block_number)>1) q)
        """
    ).fetchone()
    negative_causal_rows = int(causal_row[0] or 0)
    dense_bad_blocks = int(causal_row[1] or 0)
    block_hash_multi_height = int(causal_row[2] or 0)

    created_blocks_without_meta = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT DISTINCT block_number, lower(block_hash) AS block_hash
          FROM v11_created_all
          WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
        ) c
        LEFT JOIN v11_block_meta_raw m
          ON m.block_number = c.block_number AND lower(m.block_hash) = c.block_hash
        WHERE m.block_number IS NULL
        """
    ).fetchone()[0] or 0)

    spends_blocks_without_meta = int(con.execute(
        """
        SELECT COUNT(*)
        FROM (
          SELECT DISTINCT block_number, lower(block_hash) AS block_hash
          FROM v11_spends_all
          WHERE block_number IS NOT NULL AND block_hash IS NOT NULL
        ) s
        LEFT JOIN v11_block_meta_raw m
          ON m.block_number = s.block_number AND lower(m.block_hash) = s.block_hash
        WHERE m.block_number IS NULL
        """
    ).fetchone()[0] or 0)

    row = con.execute(
        """
        SELECT
          MIN(block_number),
          MAX(block_number),
          COUNT(DISTINCT block_number)
        FROM v11_block_meta_raw
        """
    ).fetchone()
    h_min = int(row[0]) if row[0] is not None else None
    h_max = int(row[1]) if row[1] is not None else None
    distinct_heights = int(row[2] or 0)
    expected_heights = (h_max - h_min + 1) if h_min is not None and h_max is not None else 0
    missing_heights = max(0, expected_heights - distinct_heights)

    examples = []
    if duplicate_hash_heights:
        examples = [
            {"block_number": int(r[0]), "hashes": int(r[1])}
            for r in con.execute(
                """
                SELECT block_number, COUNT(DISTINCT block_hash) AS hashes
                FROM v11_block_meta_raw
                GROUP BY block_number
                HAVING COUNT(DISTINCT block_hash) > 1
                ORDER BY block_number
                LIMIT 20
                """
            ).fetchall()
        ]

    report = {
        "h_min": h_min,
        "h_max": h_max,
        "distinct_heights": distinct_heights,
        "expected_heights": expected_heights,
        "missing_heights": missing_heights,
        "duplicate_hash_heights": duplicate_hash_heights,
        "duplicate_hash_examples": examples,
        "timestamp_inconsistent_blocks": timestamp_inconsistent_blocks,
        "tx_index_conflict_positions": tx_index_conflict_positions,
        "txid_multi_index_rows": txid_multi_index_rows,
        "negative_causal_rows": negative_causal_rows,
        "dense_bad_blocks": dense_bad_blocks,
        "block_hash_multi_height": block_hash_multi_height,
        "created_blocks_without_meta": created_blocks_without_meta,
        "spends_blocks_without_meta": spends_blocks_without_meta,
    }

    if timestamp_inconsistent_blocks > 0:
        raise RuntimeError(f"v11 block preflight failed: multiple timestamps inside same block: {report}")

    if tx_index_conflict_positions > 0:
        raise RuntimeError(f"v11 block preflight failed: same (block_number, tx_index) maps to multiple txids: {report}")

    if txid_multi_index_rows > 0:
        raise RuntimeError(f"v11 block preflight failed: same txid appears with multiple tx_index values inside one block: {report}")

    if negative_causal_rows > 0 or dense_bad_blocks > 0 or block_hash_multi_height > 0:
        raise RuntimeError(f"v11 block preflight failed: invalid causal index/block identity contract: {report}")

    if created_blocks_without_meta > 0 or spends_blocks_without_meta > 0:
        raise RuntimeError(f"v11 block preflight failed: created/spends rows reference blocks missing from block_meta stage: {report}")

    if duplicate_hash_heights > 0:
        raise RuntimeError(f"v11 block preflight failed: multiple block_hash per height: {report}")

    if missing_heights > 0 and not _env_bool("UTXO_V11_ALLOW_MISSING_BLOCK_HEIGHTS_DANGEROUS", False):
        raise RuntimeError(
            f"v11 block preflight failed: missing block heights detected: {report}. "
            "Only for deliberate partial lab windows set UTXO_V11_ALLOW_MISSING_BLOCK_HEIGHTS_DANGEROUS=1."
        )

    if missing_heights > 0:
        _warn(f"DANGEROUS: allowing missing block heights in v11 lab run: {report}")

    _log(f"v11 block preflight ok: {report}")
    return report


def _v11_global_stage_preflight(con: duckdb.DuckDBPyConnection) -> Dict[str, Any]:
    known_bip30_sql = _v11_known_bip30_sql_list()

    created_dup_non_bip30 = int(con.execute(
        f"""
        SELECT COALESCE(SUM(cnt - 1), 0)
        FROM (
          SELECT lower(txid) AS txid, vout, COUNT(*) AS cnt
          FROM v11_created_all
          GROUP BY 1, 2
          HAVING COUNT(*) > 1
             AND lower(txid) NOT IN {known_bip30_sql}
        ) d
        """
    ).fetchone()[0] or 0)

    created_dup_bip30 = int(con.execute(
        f"""
        SELECT COALESCE(SUM(cnt - 1), 0)
        FROM (
          SELECT lower(txid) AS txid, vout, COUNT(*) AS cnt
          FROM v11_created_all
          GROUP BY 1, 2
          HAVING COUNT(*) > 1
             AND lower(txid) IN {known_bip30_sql}
        ) d
        """
    ).fetchone()[0] or 0)
    bip30_stage_report = _v11_stage_bip30_duplicate_report(con)
    created_dup_bip30_valid_pairs = int(bip30_stage_report.get("valid_pairs") or 0)
    created_dup_bip30_invalid = int(bip30_stage_report.get("invalid_duplicate_rows") or 0)

    spends_dup = int(con.execute(
        """
        SELECT COALESCE(SUM(cnt - 1), 0)
        FROM (
          SELECT lower(prev_txid) AS prev_txid, prev_vout, COUNT(*) AS cnt
          FROM v11_spends_all
          GROUP BY 1, 2
          HAVING COUNT(*) > 1
        ) d
        """
    ).fetchone()[0] or 0)

    created_null_causal = int(con.execute(
        """
        SELECT COUNT(*)
        FROM v11_created_all
        WHERE txid IS NULL OR vout IS NULL OR block_number IS NULL OR tx_index IS NULL
        """
    ).fetchone()[0] or 0)

    spends_null_causal = int(con.execute(
        """
        SELECT COUNT(*)
        FROM v11_spends_all
        WHERE prev_txid IS NULL OR prev_vout IS NULL OR block_number IS NULL OR tx_index IS NULL
        """
    ).fetchone()[0] or 0)

    stage_internal_impossible_causal = int(con.execute(
        """
        SELECT COUNT(*)
        FROM v11_spends_all s
        JOIN v11_created_all c
          ON lower(c.txid) = lower(s.prev_txid)
         AND CAST(c.vout AS BIGINT) = CAST(s.prev_vout AS BIGINT)
        WHERE c.block_number = s.block_number
          AND CAST(c.tx_index AS BIGINT) >= CAST(s.tx_index AS BIGINT)
        """
    ).fetchone()[0] or 0)
    stage_internal_impossible_examples: List[Dict[str, Any]] = []
    if stage_internal_impossible_causal:
        stage_internal_impossible_examples = [
            {
                "prev_txid": str(r[0]),
                "prev_vout": int(r[1]),
                "created_height": int(r[2]),
                "created_tx_index": int(r[3]),
                "spent_height": int(r[4]),
                "spent_tx_index": int(r[5]),
                "spent_txid": str(r[6]),
                "spent_vin": int(r[7]) if r[7] is not None else None,
            }
            for r in con.execute(
                """
                SELECT
                  s.prev_txid, s.prev_vout,
                  c.block_number AS created_height, c.tx_index AS created_tx_index,
                  s.block_number AS spent_height, s.tx_index AS spent_tx_index,
                  s.spent_txid, s.spent_vin
                FROM v11_spends_all s
                JOIN v11_created_all c
                  ON lower(c.txid) = lower(s.prev_txid)
                 AND CAST(c.vout AS BIGINT) = CAST(s.prev_vout AS BIGINT)
                WHERE c.block_number = s.block_number
                  AND CAST(c.tx_index AS BIGINT) >= CAST(s.tx_index AS BIGINT)
                ORDER BY s.block_number, s.tx_index, c.tx_index
                LIMIT 20
                """
            ).fetchall()
        ]

    report = {
        "created_dup_non_bip30": created_dup_non_bip30,
        "created_dup_bip30": created_dup_bip30,
        "created_dup_bip30_valid_pairs": created_dup_bip30_valid_pairs,
        "created_dup_bip30_invalid": created_dup_bip30_invalid,
        "bip30_stage_report": bip30_stage_report,
        "spends_dup": spends_dup,
        "created_null_causal": created_null_causal,
        "spends_null_causal": spends_null_causal,
        "stage_internal_impossible_causal": stage_internal_impossible_causal,
        "stage_internal_impossible_examples": stage_internal_impossible_examples,
    }

    failed = []
    if created_dup_non_bip30:
        failed.append("created_duplicate_keys_non_bip30")
    if created_dup_bip30_invalid:
        failed.append("created_duplicate_keys_bip30_invalid")
    if spends_dup:
        failed.append("duplicate_spent_prevouts")
    if created_null_causal:
        failed.append("created_null_key_or_causal")
    if spends_null_causal:
        failed.append("spends_null_key_or_causal")
    if stage_internal_impossible_causal:
        failed.append("stage_internal_impossible_causal")
    if failed:
        report["failed_checks"] = failed
        raise RuntimeError(f"v11 global stage preflight failed: {report}")

    if created_dup_bip30:
        _warn(
            "v11 global stage preflight: known BIP30 duplicate created keys observed "
            f"count={created_dup_bip30} valid_pairs={created_dup_bip30_valid_pairs} "
            f"known_pairs={bip30_stage_report.get('known_height_pairs')}"
        )

    _log(f"v11 global stage preflight ok: {report}")
    return report


def _v11_apply_block_window(
    con: duckdb.DuckDBPyConnection,
    *,
    h1: int,
    h2: int,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Optional[Sequence[str]] = None,
    window_source_index: Optional[Dict[str, Any]] = None,
    bip30_window_split: Optional[Dict[str, Any]] = None,
    post_commit_hook: Optional[Any] = None,
) -> Dict[str, Any]:
    t0 = _tic()

    selected_file_count: Optional[int] = None
    if window_source_index is not None:
        selected_created, selected_spends, selected_block_meta = _v11_select_window_source_paths(
            window_source_index, int(h1), int(h2)
        )
        _v11_bind_windowed_stage_sources(
            con, selected_created, selected_spends, selected_block_meta
        )
        selected_file_count = len(selected_block_meta)
    elif block_meta_paths is not None:
        _v11_bind_windowed_stage_sources(
            con, created_paths, spends_paths, block_meta_paths
        )
        selected_file_count = len(block_meta_paths)

    for table in ["v11_block_meta_ready", "v11_created_window", "v11_spends_window"]:
        con.execute(f"DROP TABLE IF EXISTS {table}")

    con.execute(
        """
        CREATE TEMP TABLE v11_block_meta_ready AS
        SELECT
          block_number,
          MIN(block_hash)::VARCHAR AS block_hash,
          MIN(block_timestamp)::TIMESTAMP AS block_timestamp,
          CAST(MIN(block_timestamp) AS DATE) AS block_date,
          MIN(raw_partition_min)::DATE AS raw_partition_min,
          MAX(raw_partition_max)::DATE AS raw_partition_max
        FROM v11_block_meta_source
        WHERE block_number BETWEEN ? AND ?
        GROUP BY block_number
        ORDER BY block_number
        """,
        [h1, h2],
    )

    con.execute(
        """
        CREATE TEMP TABLE v11_created_window AS
        SELECT * EXCLUDE(rn)
        FROM (
          SELECT
            ROW_NUMBER() OVER (PARTITION BY txid, vout ORDER BY block_number, tx_index, created_ts) AS rn,
            txid,
            vout,
            address,
            value_btc,
            created_ts,
            created_date,
            block_number::BIGINT AS created_height,
            tx_index::INTEGER AS created_tx_index
          FROM v11_created_source
          WHERE block_number BETWEEN ? AND ?
        ) x
        WHERE rn = 1
        """,
        [h1, h2],
    )

    con.execute(
        """
        CREATE TEMP TABLE v11_spends_window AS
        SELECT * EXCLUDE(rn)
        FROM (
          SELECT
            ROW_NUMBER() OVER (PARTITION BY prev_txid, prev_vout ORDER BY block_number, tx_index, spent_vin) AS rn,
            prev_txid,
            prev_vout,
            spent_txid,
            spent_vin,
            spent_ts,
            spent_date,
            block_number::BIGINT AS spent_height,
            tx_index::INTEGER AS spent_tx_index
          FROM v11_spends_source
          WHERE block_number BETWEEN ? AND ?
        ) x
        WHERE rn = 1
        """,
        [h1, h2],
    )

    created_rows = int(con.execute("SELECT COUNT(*) FROM v11_created_window").fetchone()[0] or 0)
    spends_rows = int(con.execute("SELECT COUNT(*) FROM v11_spends_window").fetchone()[0] or 0)
    block_rows = int(con.execute("SELECT COUNT(*) FROM v11_block_meta_ready").fetchone()[0] or 0)

    bip30_window_stage_report = _v11_stage_bip30_duplicate_report(
        con, h1=int(h1), h2=int(h2), stage_table="v11_created_source"
    )
    if int(bip30_window_stage_report.get("invalid_duplicate_rows") or 0) > 0:
        raise RuntimeError(
            f"v11 invalid BIP30 stage duplicate in block_window={h1}-{h2}: "
            f"{bip30_window_stage_report}"
        )
    if int(bip30_window_stage_report.get("known_duplicate_rows") or 0) > 0:
        _warn(
            f"v11 known BIP30 stage duplicate observed block_window={h1}-{h2}: "
            f"{bip30_window_stage_report}"
        )

    created_conflict_report = _v11_created_conflict_report(
        con,
        stage_table="v11_created_window",
        stage_height_col="s.created_height",
        stage_tx_index_col="s.created_tx_index",
    )
    conflicts_total = int(created_conflict_report.get("total") or 0)
    conflicts_bip30 = int(created_conflict_report.get("known_bip30_txid") or 0)
    conflicts_bip30_valid = int(created_conflict_report.get("valid_bip30_conflict") or 0)
    conflicts_bip30_invalid = int(created_conflict_report.get("known_bip30_invalid") or 0)
    conflicts_invalid_total = int(created_conflict_report.get("invalid_total") or 0)
    if conflicts_invalid_total > 0:
        raise RuntimeError(
            f"v11 unexpected created conflicts before insert block_window={h1}-{h2}: "
            f"conflicts_total={conflicts_total} known_bip30_txid={conflicts_bip30} "
            f"valid_bip30={conflicts_bip30_valid} invalid_total={conflicts_invalid_total} "
            f"examples={created_conflict_report.get('invalid_examples')}"
        )
    if conflicts_bip30_valid:
        _warn(
            f"v11 known BIP30 conflicts allowed block_window={h1}-{h2}: "
            f"valid={conflicts_bip30_valid} known_txid={conflicts_bip30} "
            f"known_pairs={_v11_known_bip30_height_pairs()}"
        )

    con.execute("BEGIN")
    try:
        con.execute(
            """
            INSERT INTO block_meta(block_number, block_hash, block_timestamp, block_date, raw_partition_min, raw_partition_max)
            SELECT block_number, block_hash, block_timestamp, block_date, raw_partition_min, raw_partition_max
            FROM v11_block_meta_ready
            ON CONFLICT(block_number) DO NOTHING;
            """
        )

        con.execute(
            """
            INSERT INTO utxo(
              txid, vout, address, value_btc,
              created_ts, created_date, created_height, created_tx_index
            )
            SELECT
              txid, vout, address, value_btc,
              created_ts, created_date, created_height, created_tx_index
            FROM v11_created_window
            ON CONFLICT(txid, vout) DO NOTHING;
            """
        )

        impossible = int(con.execute(
            """
            SELECT COUNT(*)
            FROM v11_spends_window s
            JOIN utxo u
              ON u.txid = s.prev_txid AND u.vout = s.prev_vout
            WHERE NOT (
              u.created_height < s.spent_height
              OR (u.created_height = s.spent_height AND u.created_tx_index < s.spent_tx_index)
            )
            """
        ).fetchone()[0] or 0)
        if impossible > 0:
            raise RuntimeError(f"v11 causal impossible spends in block window {h1}-{h2}: {impossible}")

        orphan = int(con.execute(
            """
            SELECT COUNT(*)
            FROM v11_spends_window s
            LEFT JOIN utxo u
              ON u.txid = s.prev_txid AND u.vout = s.prev_vout
            WHERE u.txid IS NULL
            """
        ).fetchone()[0] or 0)
        if orphan > 0 and not _env_bool("UTXO_V11_ALLOW_ORPHANS", False):
            raise RuntimeError(
                f"v11 orphan spends in block window {h1}-{h2}: {orphan}. "
                "For partial lab windows only, set UTXO_V11_ALLOW_ORPHANS=1."
            )

        already_spent = int(con.execute(
            """
            SELECT COUNT(*)
            FROM v11_spends_window s
            JOIN utxo u
              ON u.txid = s.prev_txid AND u.vout = s.prev_vout
            WHERE u.spent_ts IS NOT NULL
            """
        ).fetchone()[0] or 0)
        if already_spent > 0:
            raise RuntimeError(f"v11 spends would overwrite already-spent UTXO rows in block window {h1}-{h2}: {already_spent}")

        con.execute(
            """
            UPDATE utxo AS u
            SET
              spent_ts       = s.spent_ts,
              spent_date     = s.spent_date,
              spent_txid     = s.spent_txid,
              spent_vin      = s.spent_vin,
              spent_height   = s.spent_height,
              spent_tx_index = s.spent_tx_index
            FROM v11_spends_window AS s
            WHERE u.txid = s.prev_txid
              AND u.vout = s.prev_vout
              AND u.spent_ts IS NULL
              AND (
                u.created_height < s.spent_height
                OR (u.created_height = s.spent_height AND u.created_tx_index < s.spent_tx_index)
              );
            """
        )
        spend_apply_mismatch = int(con.execute(
            """
            SELECT COUNT(*)
            FROM v11_spends_window s
            JOIN utxo u
              ON u.txid = s.prev_txid AND u.vout = s.prev_vout
            WHERE u.spent_ts IS NULL
               OR u.spent_height IS NULL
               OR u.spent_tx_index IS NULL
               OR COALESCE(u.spent_txid, '') <> COALESCE(s.spent_txid, '')
               OR COALESCE(u.spent_vin, -1) <> COALESCE(s.spent_vin, -1)
               OR u.spent_height <> s.spent_height
               OR u.spent_tx_index <> s.spent_tx_index
            """
        ).fetchone()[0] or 0)
        if spend_apply_mismatch > 0 and not _env_bool("UTXO_V11_ALLOW_ORPHANS", False):
            raise RuntimeError(f"v11 spend apply verification failed block_window={h1}-{h2}: mismatches={spend_apply_mismatch}")

        con.execute("COMMIT")
        if post_commit_hook is not None:
            preliminary_report = {
                "h1": int(h1),
                "h2": int(h2),
                "block_rows": int(block_rows),
                "selected_stage_files": selected_file_count,
                "created_rows": int(created_rows),
                "spends_rows": int(spends_rows),
                "conflicts_total": int(conflicts_total),
                "conflicts_bip30": int(conflicts_bip30),
                "conflicts_bip30_valid": int(conflicts_bip30_valid),
                "conflicts_bip30_invalid": int(conflicts_bip30_invalid),
                "created_conflict_report": created_conflict_report,
                "bip30_window_stage_report": bip30_window_stage_report,
                "bip30_window_split": bip30_window_split or {
                    "enabled": bool(_v11_bip30_window_split_enabled()),
                    "applied": False,
                    "h1": int(h1),
                    "original_h2": int(h2),
                    "adjusted_h2": int(h2),
                    "guard": "PASS",
                },
                "already_spent": int(already_spent),
                "spend_apply_mismatch": int(spend_apply_mismatch),
                "commit_confirmed_before_temp_cleanup": True,
            }
            post_commit_hook(con, preliminary_report)
    except Exception:
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        raise

    elapsed = _toc(t0)
    report = {
        "h1": int(h1),
        "h2": int(h2),
        "block_rows": block_rows,
        "selected_stage_files": selected_file_count,
        "created_rows": created_rows,
        "spends_rows": spends_rows,
        "conflicts_total": conflicts_total,
        "conflicts_bip30": conflicts_bip30,
        "conflicts_bip30_valid": conflicts_bip30_valid,
        "conflicts_bip30_invalid": conflicts_bip30_invalid,
        "created_conflict_report": created_conflict_report,
        "bip30_window_stage_report": bip30_window_stage_report,
        "bip30_window_split": bip30_window_split or {"enabled": bool(_v11_bip30_window_split_enabled()), "applied": False, "h1": int(h1), "original_h2": int(h2), "adjusted_h2": int(h2), "guard": "PASS"},
        "already_spent": already_spent,
        "spend_apply_mismatch": spend_apply_mismatch,
        "elapsed_sec": elapsed,
        "memory_after_window": _v10_10_memory_report(),
    }
    _log(
        f"v11 apply block_window={h1}-{h2} blocks={block_rows} "
        f"selected_files={selected_file_count} created={created_rows} spends={spends_rows} conflicts={conflicts_total} "
        f"known_bip30={conflicts_bip30} valid_bip30={conflicts_bip30_valid} "
        f"already_spent={already_spent} "
        f"spend_apply_mismatch={spend_apply_mismatch} in {_fmt_s(elapsed)} "
        f"{_v10_10_memory_text(report['memory_after_window'])}"
    )
    for table in [
        "v11_block_meta_ready", "v11_created_window", "v11_spends_window",
        "v11_created_conflict_report", "v11_bip30_stage_pairs",
    ]:
        con.execute(f"DROP TABLE IF EXISTS {table}")
    for view in ("v11_created_source", "v11_spends_source", "v11_block_meta_source"):
        con.execute(f"DROP VIEW IF EXISTS {view}")
    return report




def _v11_is_duckdb_oom(exc: BaseException) -> bool:
    """Recognize DuckDB OOM without treating arbitrary MemoryError as retryable."""
    oom_cls = getattr(duckdb, "OutOfMemoryException", None)
    if oom_cls is not None and isinstance(exc, oom_cls):
        return True
    message = str(exc).lower()
    return (
        "out of memory error" in message
        or "outofmemoryexception" in type(exc).__name__.lower()
    )


def _v11_adaptive_apply_enabled() -> bool:
    return _env_bool("UTXO_V11_ADAPTIVE_APPLY_ON_OOM", True)


def _v11_adaptive_apply_min_window() -> int:
    return max(1, _env_int("UTXO_V11_MIN_BLOCK_WINDOW_SIZE", 1))


def _v11_adaptive_apply_max_retries() -> int:
    return max(0, _env_int("UTXO_V11_OOM_MAX_RETRIES", 16))


def _v11_adaptive_apply_backoff_divisor() -> int:
    return max(2, _env_int("UTXO_V11_OOM_BACKOFF_DIVISOR", 2))


def _v11_validate_committed_block_prefix_after_oom(
    con: duckdb.DuckDBPyConnection,
    *,
    db_path: str,
    expected_min: int,
    expected_max: int,
    context: str,
) -> Dict[str, Any]:
    """Verify the only cheap authoritative prefix after an aborted apply attempt.

    Every successful apply transaction inserts block_meta in the same transaction
    as created/spent mutation. Therefore an exact contiguous block_meta prefix is
    the durable commit authority used after reopening a writer following OOM.
    """
    _v11_assert_schema_compatible(con, db_path)
    row = con.execute(
        """
        SELECT
          MIN(block_number),
          MAX(block_number),
          COUNT(DISTINCT block_number),
          COUNT(*)
        FROM block_meta
        """
    ).fetchone()
    meta_min, meta_max, meta_distinct, meta_rows = row
    meta_distinct_i = int(meta_distinct or 0)
    meta_rows_i = int(meta_rows or 0)

    if int(expected_max) < int(expected_min):
        ok = (
            meta_min is None
            and meta_max is None
            and meta_distinct_i == 0
            and meta_rows_i == 0
        )
        expected_rows = 0
    else:
        expected_rows = int(expected_max) - int(expected_min) + 1
        ok = (
            meta_min is not None
            and meta_max is not None
            and int(meta_min) == int(expected_min)
            and int(meta_max) == int(expected_max)
            and meta_distinct_i == expected_rows
            and meta_rows_i == expected_rows
        )

    report = {
        "context": str(context),
        "db_path": str(db_path),
        "expected_min": int(expected_min),
        "expected_max": int(expected_max),
        "expected_rows": int(expected_rows),
        "actual_min": int(meta_min) if meta_min is not None else None,
        "actual_max": int(meta_max) if meta_max is not None else None,
        "actual_distinct": meta_distinct_i,
        "actual_rows": meta_rows_i,
        "status": "ok" if ok else "fail",
    }
    if not ok:
        raise RuntimeError(
            "committed block_meta prefix changed across DuckDB OOM; automatic "
            f"retry is unsafe: {report}"
        )
    return report


def _v11_reopen_apply_writer_after_oom(
    con: Optional[duckdb.DuckDBPyConnection],
    *,
    db_path: str,
    expected_prefix_min: int,
    expected_prefix_max: int,
    context: str,
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any]]:
    """Discard the OOM-touched connection and reopen a verified writer."""
    close_error: Optional[str] = None
    if con is not None:
        try:
            con.close()
        except BaseException as exc:
            close_error = f"{type(exc).__name__}:{exc}"
            raise RuntimeError(
                "cannot prove the OOM-touched DuckDB writer was closed; "
                f"automatic reopen is blocked: {close_error}"
            ) from exc

    _v11_release_proof_memory(f"{context} after_oom")

    reopened = duckdb.connect(db_path)
    try:
        _apply_duckdb_pragmas(reopened, phase="apply")
        prefix = _v11_validate_committed_block_prefix_after_oom(
            reopened,
            db_path=db_path,
            expected_min=int(expected_prefix_min),
            expected_max=int(expected_prefix_max),
            context=context,
        )
        report = {
            "status": "ok",
            "close_error": close_error,
            "prefix": prefix,
            "memory_after_reopen": _v11_memory_snapshot(),
        }
        _emit_event(
            "S17913",
            "APPLY_WRITER_REOPENED "
            f"context={context} expected_tail={expected_prefix_max} "
            f"actual_tail={prefix.get('actual_max')}",
        )
        return reopened, report
    except BaseException:
        try:
            reopened.close()
        except BaseException:
            pass
        raise


def _v11_apply_block_window_with_inprocess_oom_backoff(
    con: duckdb.DuckDBPyConnection,
    *,
    db_path: str,
    mode: str,
    h1: int,
    h_max: int,
    requested_window_size: int,
    expected_prefix_min: int,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
    window_source_index: Dict[str, Any],
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any], int, int]:
    """Apply one committed window, shrinking and reopening on DuckDB OOM.

    Returns (possibly reopened connection, report, committed_h2,
    effective_window_size). Only OutOfMemoryException is retryable. Any prefix
    mismatch or non-OOM exception escapes into the existing crash-recovery path.
    """
    configured_size = max(1, int(requested_window_size))
    current_size = configured_size
    min_size = min(configured_size, _v11_adaptive_apply_min_window())
    max_retries = _v11_adaptive_apply_max_retries()
    divisor = _v11_adaptive_apply_backoff_divisor()
    adaptive_enabled = _v11_adaptive_apply_enabled()
    oom_events: List[Dict[str, Any]] = []
    attempt = 0
    reopened_connection_owned = False

    try:
        while True:
            raw_h2 = min(int(h1) + int(current_size) - 1, int(h_max))
            h2, bip30_window_split = _v11_adjust_block_window_for_bip30(
                int(h1), int(raw_h2), context=f"v11 {mode}"
            )
            _v11_assert_no_bip30_pair_inside_window(
                int(h1), int(h2), context=f"v11 {mode}"
            )
            _v11_memory_guard(
                f"{mode} block_window={h1}-{h2} attempt={attempt + 1}",
                before_window=True,
            )
            phase_name = f"apply_window:{h1}:{h2}:attempt:{attempt + 1}"
            _phase_started(
                phase_name,
                "S17910",
                f"APPLY_WINDOW_STARTED h1={h1} h2={h2} "
                f"attempt={attempt + 1} effective_window_size={current_size}",
            )
            try:
                report = _v11_apply_block_window(
                    con,
                    h1=int(h1),
                    h2=int(h2),
                    created_paths=created_paths,
                    spends_paths=spends_paths,
                    block_meta_paths=block_meta_paths,
                    window_source_index=window_source_index,
                    bip30_window_split=bip30_window_split,
                )
            except BaseException as exc:
                if not (_v11_is_duckdb_oom(exc) and adaptive_enabled):
                    raise

                attempt += 1
                attempted_blocks = int(h2) - int(h1) + 1
                can_retry = attempt <= max_retries and current_size > min_size
                next_size = max(min_size, current_size // divisor)
                if next_size >= current_size and current_size > min_size:
                    next_size = current_size - 1
                if next_size < 1:
                    next_size = 1

                event = {
                    "attempt": int(attempt),
                    "h1": int(h1),
                    "h2": int(h2),
                    "attempted_blocks": int(attempted_blocks),
                    "window_size_before": int(current_size),
                    "window_size_after": int(next_size),
                    "min_window_size": int(min_size),
                    "max_retries": int(max_retries),
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                    "memory_at_oom": _v11_memory_snapshot(),
                }
                oom_events.append(event)
                _phase_completed(
                    phase_name,
                    "W17912",
                    "APPLY_WINDOW_OOM_BACKOFF "
                    f"mode={mode} h1={h1} h2={h2} attempt={attempt}/{max_retries} "
                    f"window={current_size}->{next_size} error={type(exc).__name__}:{exc}",
                    stream=sys.stderr,
                )

                try:
                    con, reopen_report = _v11_reopen_apply_writer_after_oom(
                        con,
                        db_path=db_path,
                        expected_prefix_min=int(expected_prefix_min),
                        expected_prefix_max=int(h1) - 1,
                        context=f"{mode} h1={h1} failed_h2={h2}",
                    )
                    reopened_connection_owned = True
                    event["writer_reopen"] = reopen_report
                except BaseException as reopen_exc:
                    _emit_event(
                        "E17914",
                        "APPLY_OOM_RECOVERY_FAILED "
                        f"mode={mode} h1={h1} h2={h2} "
                        f"error={type(reopen_exc).__name__}:{reopen_exc}",
                        stream=sys.stderr,
                    )
                    raise RuntimeError(
                        "DuckDB OOM occurred and writer reopen/prefix validation failed; "
                        f"original={type(exc).__name__}:{exc}; "
                        f"reopen={type(reopen_exc).__name__}:{reopen_exc}"
                    ) from exc

                if not can_retry or next_size >= current_size:
                    raise RuntimeError(
                        "DuckDB OOM adaptive retry budget exhausted: "
                        f"mode={mode} h1={h1} failed_h2={h2} "
                        f"window_size={current_size} min_window_size={min_size} "
                        f"attempts={attempt}/{max_retries}"
                    ) from exc

                current_size = int(next_size)
                continue

            _phase_completed(
                phase_name,
                "S17911",
                f"APPLY_WINDOW_COMPLETE h1={h1} h2={h2} "
                f"attempt={attempt + 1} effective_window_size={current_size}",
            )
            report = dict(report)
            report.update({
                "adaptive_apply_enabled": bool(adaptive_enabled),
                "requested_window_size": int(configured_size),
                "effective_window_size": int(current_size),
                "oom_retry_count": int(attempt),
                "oom_events": oom_events,
            })
            reopened_connection_owned = False
            return con, report, int(h2), int(current_size)

    except BaseException:
        if reopened_connection_owned:
            try:
                con.close()
            except BaseException as close_exc:
                _warn(
                    "v11 adaptive APPLY failed to close function-owned reopened writer "
                    f"before outer crash recovery: {type(close_exc).__name__}: {close_exc}"
                )
        raise



def _v11_apply_process_isolation_enabled() -> bool:
    return _env_bool("UTXO_V11_APPLY_PROCESS_ISOLATION", True)


def _v11_runtime_script_sha256_guard_enabled() -> bool:
    enabled = _env_bool("UTXO_V11_RUNTIME_SCRIPT_SHA256_GUARD", True)
    if bool(enabled) != bool(V11_RUNTIME_SCRIPT_SHA256_GUARD_ENABLED):
        raise RuntimeError(
            "UTXO_V11_RUNTIME_SCRIPT_SHA256_GUARD changed after process import; "
            "restart the pipeline with one stable value"
        )
    return bool(enabled)


def _v11_recovery_test_hooks_preflight() -> Dict[str, Any]:
    """Block deterministic recovery fault-injection hooks outside explicit lab mode."""
    hooks = {
        "UTXO_V11_RECOVERY_TEST_OOM_MIN_BLOCKS": max(
            0, _env_int("UTXO_V11_RECOVERY_TEST_OOM_MIN_BLOCKS", 0)
        ),
        "UTXO_V11_RECOVERY_TEST_CRASH_BEFORE_COMMIT": _env_bool(
            "UTXO_V11_RECOVERY_TEST_CRASH_BEFORE_COMMIT", False
        ),
        "UTXO_V11_RECOVERY_TEST_CRASH_AFTER_COMMIT": _env_bool(
            "UTXO_V11_RECOVERY_TEST_CRASH_AFTER_COMMIT", False
        ),
    }
    enabled = {name: value for name, value in hooks.items() if bool(value)}
    if enabled and not _env_bool("UTXO_V11_LAB_MODE", False):
        raise RuntimeError(
            "recovery fault-injection hooks are blocked outside lab mode: "
            f"enabled={enabled}. Set UTXO_V11_LAB_MODE=1 only for deliberate tests."
        )
    if enabled:
        _warn(
            "DANGEROUS LAB TEST MODE: deterministic recovery fault injection enabled "
            f"hooks={enabled}"
        )
    return {
        "status": "lab_fault_injection_enabled" if enabled else "disabled",
        "enabled_hooks": enabled,
    }


def _v11_apply_process_isolation_preflight(mode: str) -> Dict[str, Any]:
    """Fail before stage/target mutation if the required worker guard is unavailable."""
    recovery_test_hooks = _v11_recovery_test_hooks_preflight()
    if mode not in {MODE_REBUILD_FULL, MODE_REBUILD_RESUME, MODE_APPEND_TAIL, MODE_REPLAY_SUFFIX}:
        return {"required": False, "status": "not_applicable"}
    enabled = _v11_apply_process_isolation_enabled()
    if not enabled:
        if not _v11_inprocess_apply_dangerous_allowed():
            raise RuntimeError(
                "UTXO_V11_APPLY_PROCESS_ISOLATION=0 is blocked before write-mode "
                "mutation. For an explicit lab-only diagnostic, set both "
                "UTXO_V11_LAB_MODE=1 and "
                "UTXO_V11_ALLOW_INPROCESS_APPLY_DANGEROUS=1."
            )
        _warn(
            "DANGEROUS LAB MODE: process-isolated APPLY disabled during startup "
            "preflight; native DuckDB aborts can terminate the parent pipeline."
        )
        return {"required": False, "enabled": False, "status": "lab_inprocess_override"}

    if not sys.platform.startswith("linux"):
        raise RuntimeError(
            "process-isolated APPLY requires Linux PR_SET_PDEATHSIG; "
            f"platform={sys.platform!r}"
        )
    libc = ctypes.CDLL(None, use_errno=True)
    prctl = getattr(libc, "prctl", None)
    if prctl is None:
        raise RuntimeError(
            "libc.prctl is unavailable; process-isolated APPLY cannot guarantee "
            "worker termination when the parent dies"
        )
    prctl.restype = ctypes.c_int
    current_signal = ctypes.c_int(0)
    current_signal_ptr = ctypes.cast(
        ctypes.byref(current_signal),
        ctypes.c_void_p,
    ).value
    rc = int(prctl(
        ctypes.c_int(2),  # PR_GET_PDEATHSIG
        ctypes.c_ulong(int(current_signal_ptr or 0)),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
    ))
    if rc != 0:
        err = ctypes.get_errno()
        raise OSError(err, os.strerror(err))
    set_rc = int(prctl(
        ctypes.c_int(1),  # PR_SET_PDEATHSIG
        ctypes.c_ulong(int(current_signal.value)),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
    ))
    if set_rc != 0:
        err = ctypes.get_errno()
        raise OSError(
            err,
            "PR_SET_PDEATHSIG is unavailable although PR_GET_PDEATHSIG succeeded: "
            + os.strerror(err),
        )
    verify_signal = ctypes.c_int(-1)
    verify_signal_ptr = ctypes.cast(ctypes.byref(verify_signal), ctypes.c_void_p).value
    verify_rc = int(prctl(
        ctypes.c_int(2),  # PR_GET_PDEATHSIG
        ctypes.c_ulong(int(verify_signal_ptr or 0)),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
    ))
    if verify_rc != 0:
        err = ctypes.get_errno()
        raise OSError(err, os.strerror(err))
    if int(verify_signal.value) != int(current_signal.value):
        raise RuntimeError(
            "PR_SET_PDEATHSIG preflight changed the parent-death signal unexpectedly: "
            f"before={current_signal.value} after={verify_signal.value}"
        )
    report = {
        "required": True,
        "enabled": True,
        "status": "ok",
        "platform": sys.platform,
        "prctl_get_pdeathsig": True,
        "prctl_set_pdeathsig": True,
        "current_parent_death_signal": int(verify_signal.value),
        "loaded_script_path": V11_PROCESS_SCRIPT_PATH,
        "runtime_script_sha256_guard_enabled": _v11_runtime_script_sha256_guard_enabled(),
        "loaded_script_sha256": V11_PROCESS_SCRIPT_SHA256,
        "python_executable": V11_PROCESS_PYTHON_EXECUTABLE,
        "python_version": V11_PROCESS_PYTHON_VERSION,
        "duckdb_version": V11_PROCESS_DUCKDB_VERSION,
        "recovery_test_hooks": recovery_test_hooks,
    }
    if not _v11_runtime_script_sha256_guard_enabled():
        _warn(
            "UTXO_V11_RUNTIME_SCRIPT_SHA256_GUARD=0: parent/worker source-file "
            "SHA256 freeze is disabled. Script path, Python/DuckDB runtime, job/result "
            "hashes, stage bindings and target DB identity remain enforced."
        )
    _log(f"R54 APPLY/recovery process-isolation preflight ok: {report}")
    return report


def _v11_inprocess_apply_dangerous_allowed() -> bool:
    return bool(
        _env_bool("UTXO_V11_LAB_MODE", False)
        and _env_bool("UTXO_V11_ALLOW_INPROCESS_APPLY_DANGEROUS", False)
    )


def _v11_apply_worker_checkpoint_enabled() -> bool:
    return _env_bool(
        "UTXO_V11_APPLY_WORKER_CHECKPOINT",
        _env_bool("UTXO_V11_CHECKPOINT_EVERY_WINDOW", True),
    )


def _v11_apply_worker_timeout_seconds() -> int:
    return max(0, _env_int("UTXO_V11_APPLY_WORKER_TIMEOUT_SECONDS", 0))


def _v11_apply_worker_kill_grace_seconds() -> int:
    return max(1, _env_int("UTXO_V11_APPLY_WORKER_KILL_GRACE_SECONDS", 30))


def _v11_apply_worker_keep_success_jobs() -> bool:
    return _env_bool("UTXO_V11_APPLY_WORKER_KEEP_SUCCESS_JOBS", False)


def _v11_apply_worker_keep_failed_jobs() -> bool:
    return _env_bool("UTXO_V11_APPLY_WORKER_KEEP_FAILED_JOBS", True)


def _v11_apply_worker_job_root(db_path: str) -> Path:
    root = (
        _lock_root(create=True)
        / "utxo_v11_apply_worker_jobs"
        / _lock_key(str(Path(db_path).resolve()))
    )
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    if root.is_symlink() or not root.is_dir():
        raise RuntimeError(f"invalid APPLY worker job root: {root}")
    try:
        root.chmod(0o700)
    except Exception:
        pass
    return root


def _v11_apply_worker_job_hash(payload: Dict[str, Any]) -> str:
    return _v11_canonical_json_hash(payload, exclude=("job_sha256",))


def _v11_apply_worker_result_hash(payload: Dict[str, Any]) -> str:
    return _v11_canonical_json_hash(payload, exclude=("result_sha256",))


def _v11_apply_worker_env_contract() -> Dict[str, Any]:
    """Bind the child to the parent semantics that affect APPLY SQL."""
    return {
        "output_value_unit": _get_output_value_unit(),
        "address_mode": _get_address_mode(),
        "txid_mode": _get_txid_mode(),
        "canonical_replace_from": _canonical_replace_from(),
        "allow_orphans": bool(_env_bool("UTXO_V11_ALLOW_ORPHANS", False)),
        "apply_threads": int(_v11_phase_threads("apply")),
        "apply_memory_limit": str(_v11_phase_memory_limit("apply")),
        "duckdb_tmpdir": str(_env_str("DUCKDB_TMPDIR", "") or ""),
        "duckdb_temp_max": str(_env_str("DUCKDB_TEMP_MAX", "") or ""),
        "python_executable": V11_PROCESS_PYTHON_EXECUTABLE,
        "python_version": V11_PROCESS_PYTHON_VERSION,
        "duckdb_version": V11_PROCESS_DUCKDB_VERSION,
        "duckdb_module_path": V11_PROCESS_DUCKDB_MODULE_PATH,
        "runtime_script_sha256_guard_enabled": _v11_runtime_script_sha256_guard_enabled(),
    }


def _v11_apply_worker_regular_file(path: Path, *, label: str, private: bool = False) -> os.stat_result:
    try:
        st = path.lstat()
    except FileNotFoundError as exc:
        raise RuntimeError(f"{label} does not exist: {path}") from exc
    if stat.S_ISLNK(st.st_mode) or not stat.S_ISREG(st.st_mode):
        raise RuntimeError(f"{label} must be a regular non-symlink file: {path}")
    if private:
        if int(st.st_uid) != int(os.geteuid()):
            raise RuntimeError(
                f"{label} owner mismatch path={path} uid={st.st_uid} expected={os.geteuid()}"
            )
        if stat.S_IMODE(st.st_mode) & 0o077:
            raise RuntimeError(
                f"{label} permissions are too broad path={path} mode={oct(stat.S_IMODE(st.st_mode))}"
            )
    return st


def _v11_apply_worker_stage_binding(paths_by_role: Dict[str, Sequence[str]]) -> List[Dict[str, Any]]:
    stage_root = _stage_root_path_no_create().resolve(strict=True)
    rows: List[Dict[str, Any]] = []
    for role in ("created", "spends", "block_meta"):
        paths = paths_by_role.get(role)
        if not isinstance(paths, (list, tuple)) or not paths:
            raise RuntimeError(f"APPLY worker stage path list is empty role={role}")
        for raw in paths:
            path = Path(str(raw))
            st = _v11_apply_worker_regular_file(path, label=f"APPLY worker {role} stage")
            resolved = path.resolve(strict=True)
            try:
                resolved.relative_to(stage_root)
            except ValueError as exc:
                raise RuntimeError(
                    f"APPLY worker stage path escapes stage root role={role}: {resolved} root={stage_root}"
                ) from exc
            rows.append({
                "role": role,
                "path": str(resolved),
                "size_bytes": int(st.st_size),
                "mtime_ns": int(st.st_mtime_ns),
                "inode": int(getattr(st, "st_ino", 0)),
                "device": int(getattr(st, "st_dev", 0)),
            })
    return rows


def _v11_apply_worker_validate_stage_binding(rows: Any) -> Dict[str, List[str]]:
    if not isinstance(rows, list) or not rows:
        raise RuntimeError("APPLY worker stage binding missing/not-list")
    stage_root = _stage_root_path_no_create().resolve(strict=True)
    grouped: Dict[str, List[str]] = {"created": [], "spends": [], "block_meta": []}
    seen = set()
    for item in rows:
        if not isinstance(item, dict):
            raise RuntimeError("APPLY worker stage binding item is not an object")
        role = str(item.get("role") or "")
        if role not in grouped:
            raise RuntimeError(f"APPLY worker stage binding role invalid: {role!r}")
        path = Path(str(item.get("path") or ""))
        st = _v11_apply_worker_regular_file(path, label=f"APPLY worker {role} stage")
        resolved = path.resolve(strict=True)
        try:
            resolved.relative_to(stage_root)
        except ValueError as exc:
            raise RuntimeError(
                f"APPLY worker stage path escapes stage root role={role}: {resolved} root={stage_root}"
            ) from exc
        expected = (
            int(item.get("size_bytes") or -1),
            int(item.get("mtime_ns") or -1),
            int(item.get("inode") or -1),
            int(item.get("device") or -1),
        )
        actual = (
            int(st.st_size),
            int(st.st_mtime_ns),
            int(getattr(st, "st_ino", 0)),
            int(getattr(st, "st_dev", 0)),
        )
        if expected != actual:
            raise RuntimeError(
                f"APPLY worker stage binding changed role={role} path={resolved} expected={expected} actual={actual}"
            )
        key = (role, str(resolved))
        if key in seen:
            raise RuntimeError(f"APPLY worker duplicate stage binding: {key}")
        seen.add(key)
        grouped[role].append(str(resolved))
    if not all(grouped.values()):
        counts = {k: len(v) for k, v in grouped.items()}
        raise RuntimeError(
            "APPLY worker stage binding does not contain every required role: "
            f"counts={counts}"
        )
    return grouped


def _v11_assert_loaded_script_unchanged(*, context: str) -> Dict[str, Any]:
    current_path = str(Path(__file__).resolve(strict=True))
    if current_path != V11_PROCESS_SCRIPT_PATH:
        raise RuntimeError(
            "pipeline script path changed after parent import; worker launch blocked: "
            f"context={context} loaded={V11_PROCESS_SCRIPT_PATH} current={current_path}"
        )
    guard_enabled = _v11_runtime_script_sha256_guard_enabled()
    current_sha256: Optional[str] = None
    if guard_enabled:
        current_sha256 = _file_sha256_streaming(Path(current_path))
        if current_sha256 != V11_PROCESS_SCRIPT_SHA256:
            raise RuntimeError(
                "pipeline script content changed after parent import; worker launch blocked: "
                f"context={context} loaded_sha256={V11_PROCESS_SCRIPT_SHA256} "
                f"current_sha256={current_sha256} path={current_path}"
            )
    return {
        "script_path": current_path,
        "script_sha256_guard_enabled": bool(guard_enabled),
        "script_sha256": current_sha256,
    }


def _v11_apply_worker_create_job(
    *,
    db_path: str,
    mode: str,
    h1: int,
    h2: int,
    expected_prefix_min: int,
    selected_created: Sequence[str],
    selected_spends: Sequence[str],
    selected_block_meta: Sequence[str],
    bip30_window_split: Dict[str, Any],
) -> Tuple[Path, Path, Path, Dict[str, Any]]:
    job_id = uuid.uuid4().hex
    db_resolved = Path(db_path).resolve(strict=True)
    db_stat = _v11_apply_worker_regular_file(db_resolved, label="APPLY worker target DB")
    script_identity = _v11_assert_loaded_script_unchanged(
        context=f"create_job mode={mode} h1={h1} h2={h2}"
    )
    script_resolved = Path(script_identity["script_path"])
    stage_files = _v11_apply_worker_stage_binding({
        "created": list(selected_created),
        "spends": list(selected_spends),
        "block_meta": list(selected_block_meta),
    })
    job_dir = _v11_apply_worker_job_root(db_path) / f"job.{int(h1)}.{int(h2)}.{job_id}"
    job_dir.mkdir(mode=0o700, parents=False, exist_ok=False)
    job_path = job_dir / "job.json"
    result_path = job_dir / "result.json"
    payload: Dict[str, Any] = {
        "contract_version": V11_APPLY_WORKER_CONTRACT_VERSION,
        "pipeline_version": PIPELINE_VERSION,
        "script_path": str(script_resolved),
        "script_sha256_guard_enabled": bool(script_identity["script_sha256_guard_enabled"]),
        "script_sha256": script_identity["script_sha256"],
        "job_id": job_id,
        "created_at": _now_iso(),
        "parent_pid": int(os.getpid()),
        "db_path": str(db_resolved),
        "db_identity": {
            "device": int(getattr(db_stat, "st_dev", 0)),
            "inode": int(getattr(db_stat, "st_ino", 0)),
        },
        "mode": str(mode),
        "h1": int(h1),
        "h2": int(h2),
        "expected_prefix_min": int(expected_prefix_min),
        "expected_prefix_max": int(h1) - 1,
        "checkpoint_requested": bool(_v11_apply_worker_checkpoint_enabled()),
        "bip30_window_split": dict(bip30_window_split or {}),
        "env_contract": _v11_apply_worker_env_contract(),
        "stage_files": stage_files,
        "result_path": str(result_path.resolve(strict=False)),
    }
    payload["job_sha256"] = _v11_apply_worker_job_hash(payload)
    try:
        _save_json_atomic(job_path, payload)
        job_path.chmod(0o600)
        _v11_fsync_regular_file(job_path)
        _fsync_directory(job_dir)
        return job_dir, job_path, result_path, payload
    except BaseException:
        shutil.rmtree(job_dir, ignore_errors=True)
        try:
            _fsync_directory(job_dir.parent)
        except BaseException:
            pass
        raise


def _v11_apply_worker_read_job(job_path: Path) -> Dict[str, Any]:
    _v11_apply_worker_regular_file(job_path, label="APPLY worker job", private=True)
    payload = _read_json_file(job_path)
    if not isinstance(payload, dict):
        raise RuntimeError(f"APPLY worker job is not an object: {job_path}")
    if payload.get("contract_version") != V11_APPLY_WORKER_CONTRACT_VERSION:
        raise RuntimeError(
            f"APPLY worker job contract mismatch: {payload.get('contract_version')!r}"
        )
    if payload.get("pipeline_version") != PIPELINE_VERSION:
        raise RuntimeError(
            f"APPLY worker pipeline mismatch: {payload.get('pipeline_version')!r}!={PIPELINE_VERSION!r}"
        )
    script_path = Path(str(payload.get("script_path") or "")).resolve(strict=True)
    if str(script_path) != V11_PROCESS_SCRIPT_PATH:
        raise RuntimeError(
            f"APPLY worker script path mismatch: {script_path}!={V11_PROCESS_SCRIPT_PATH}"
        )
    guard_enabled = _v11_runtime_script_sha256_guard_enabled()
    job_guard_enabled = payload.get("script_sha256_guard_enabled")
    if not isinstance(job_guard_enabled, bool) or job_guard_enabled != guard_enabled:
        raise RuntimeError(
            "APPLY worker script SHA256 guard mismatch: "
            f"job={job_guard_enabled!r} current={guard_enabled!r}"
        )
    if guard_enabled:
        current_script_sha256 = _file_sha256_streaming(script_path)
        if current_script_sha256 != V11_PROCESS_SCRIPT_SHA256:
            raise RuntimeError(
                "APPLY worker loaded-script identity changed after import: "
                f"loaded_sha256={V11_PROCESS_SCRIPT_SHA256} current_sha256={current_script_sha256}"
            )
        if payload.get("script_sha256") != V11_PROCESS_SCRIPT_SHA256:
            raise RuntimeError("APPLY worker script SHA256 mismatch")
    elif payload.get("script_sha256") not in {None, ""}:
        raise RuntimeError(
            "APPLY worker job unexpectedly carries script SHA256 while the guard is disabled"
        )
    db_path = Path(str(payload.get("db_path") or "")).resolve(strict=True)
    db_stat = _v11_apply_worker_regular_file(db_path, label="APPLY worker target DB")
    current_db_identity = {
        "device": int(getattr(db_stat, "st_dev", 0)),
        "inode": int(getattr(db_stat, "st_ino", 0)),
    }
    if payload.get("db_identity") != current_db_identity:
        raise RuntimeError(
            f"APPLY worker target DB identity changed: job={payload.get('db_identity')} current={current_db_identity}"
        )
    expected_hash = _v11_apply_worker_job_hash(payload)
    if payload.get("job_sha256") != expected_hash:
        raise RuntimeError("APPLY worker job SHA256 mismatch")
    if payload.get("env_contract") != _v11_apply_worker_env_contract():
        raise RuntimeError(
            "APPLY worker environment contract mismatch: "
            f"job={payload.get('env_contract')} current={_v11_apply_worker_env_contract()}"
        )
    result_path = Path(str(payload.get("result_path") or ""))
    if result_path.parent.resolve(strict=False) != job_path.parent.resolve(strict=True):
        raise RuntimeError(
            f"APPLY worker result path escapes job directory: {result_path}"
        )
    return payload


def _v11_apply_worker_write_result(result_path: Path, payload: Dict[str, Any]) -> None:
    output = dict(payload)
    output.setdefault("result_contract_version", V11_APPLY_WORKER_RESULT_CONTRACT_VERSION)
    output.setdefault("pipeline_version", PIPELINE_VERSION)
    output.setdefault("written_at", _now_iso())
    output["result_sha256"] = _v11_apply_worker_result_hash(output)
    _save_json_atomic(result_path, output)
    result_path.chmod(0o600)
    _v11_fsync_regular_file(result_path)
    _fsync_directory(result_path.parent)


def _v11_apply_worker_read_result(
    result_path: Path,
    *,
    job: Dict[str, Any],
    required: bool = False,
) -> Optional[Dict[str, Any]]:
    if not result_path.exists():
        if required:
            raise RuntimeError(f"APPLY worker result missing: {result_path}")
        return None
    _v11_apply_worker_regular_file(result_path, label="APPLY worker result", private=True)
    payload = _read_json_file(result_path)
    if not isinstance(payload, dict):
        raise RuntimeError(f"APPLY worker result is not an object: {result_path}")
    if payload.get("result_contract_version") != V11_APPLY_WORKER_RESULT_CONTRACT_VERSION:
        raise RuntimeError(
            f"APPLY worker result contract mismatch: {payload.get('result_contract_version')!r}"
        )
    if payload.get("pipeline_version") != PIPELINE_VERSION:
        raise RuntimeError("APPLY worker result pipeline version mismatch")
    if payload.get("job_id") != job.get("job_id"):
        raise RuntimeError("APPLY worker result job_id mismatch")
    if payload.get("job_sha256") != job.get("job_sha256"):
        raise RuntimeError("APPLY worker result job_sha256 mismatch")
    if payload.get("result_sha256") != _v11_apply_worker_result_hash(payload):
        raise RuntimeError("APPLY worker result SHA256 mismatch")
    return payload


def _v11_apply_worker_arm_parent_death_guard() -> int:
    """Kill the worker if its direct pipeline parent dies.

    PR_SET_PDEATHSIG is armed before DuckDB is opened. The immediate getppid
    check closes the kernel race where the parent could die before prctl().
    """
    if not sys.platform.startswith("linux"):
        raise RuntimeError(
            "R54 process-isolated APPLY requires Linux PR_SET_PDEATHSIG; "
            f"platform={sys.platform!r}"
        )
    libc = ctypes.CDLL(None, use_errno=True)
    prctl = getattr(libc, "prctl", None)
    if prctl is None:
        raise RuntimeError("libc.prctl is unavailable; parent-death guard cannot be armed")
    prctl.restype = ctypes.c_int
    rc = int(prctl(
        ctypes.c_int(1),  # PR_SET_PDEATHSIG
        ctypes.c_ulong(int(signal.SIGKILL)),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
        ctypes.c_ulong(0),
    ))
    if rc != 0:
        err = ctypes.get_errno()
        raise OSError(err, os.strerror(err))
    parent_pid = int(os.getppid())
    if parent_pid <= 1:
        raise RuntimeError(
            "APPLY worker parent disappeared before parent-death guard validation; "
            f"observed_ppid={parent_pid}"
        )
    return parent_pid


def _v11_apply_worker_main(job_path_raw: str) -> int:
    """Internal child entry point. It must never run the ordinary pipeline main."""
    job_path = Path(str(job_path_raw)).resolve(strict=True)
    result_path: Optional[Path] = None
    job: Optional[Dict[str, Any]] = None
    con: Optional[duckdb.DuckDBPyConnection] = None
    committed = False
    guarded_parent_pid: Optional[int] = None
    try:
        guarded_parent_pid = _v11_apply_worker_arm_parent_death_guard()
        job = _v11_apply_worker_read_job(job_path)
        expected_parent_pid = int(job.get("parent_pid") or 0)
        if guarded_parent_pid != expected_parent_pid or int(os.getppid()) != expected_parent_pid:
            _emit_event(
                "E17921",
                "APPLY_WORKER_PARENT_GUARD_FAILED "
                f"job_id={job.get('job_id')} expected_parent_pid={expected_parent_pid} "
                f"guarded_parent_pid={guarded_parent_pid} current_ppid={os.getppid()}",
                stream=sys.stderr,
            )
            raise RuntimeError(
                "APPLY worker parent identity mismatch after PR_SET_PDEATHSIG: "
                f"expected={expected_parent_pid} guarded={guarded_parent_pid} "
                f"current_ppid={os.getppid()}"
            )
        result_path = Path(str(job["result_path"]))
        stage = _v11_apply_worker_validate_stage_binding(job.get("stage_files"))
        db_path = str(Path(str(job.get("db_path") or "")).resolve(strict=True))
        h1 = int(job["h1"])
        h2 = int(job["h2"])
        expected_min = int(job["expected_prefix_min"])
        expected_max = int(job["expected_prefix_max"])
        if h2 < h1:
            raise RuntimeError(f"APPLY worker invalid range {h1}..{h2}")

        _emit_event(
            "S17915",
            f"APPLY_WORKER_STARTED job_id={job['job_id']} pid={os.getpid()} h1={h1} h2={h2}",
        )
        con = duckdb.connect(db_path)
        _apply_duckdb_pragmas(con, phase="apply")
        _v11_validate_committed_block_prefix_after_oom(
            con,
            db_path=db_path,
            expected_min=expected_min,
            expected_max=expected_max,
            context=f"R54 worker pre-apply job_id={job['job_id']}",
        )
        commit_result: Dict[str, Any] = {}

        def _publish_commit_receipt(
            committed_con: duckdb.DuckDBPyConnection,
            preliminary_report: Dict[str, Any],
        ) -> None:
            nonlocal committed, commit_result
            prefix = _v11_validate_committed_block_prefix_after_oom(
                committed_con,
                db_path=db_path,
                expected_min=expected_min,
                expected_max=h2,
                context=f"R54 worker immediate post-commit job_id={job['job_id']}",
            )
            receipt: Dict[str, Any] = {
                "status": "committed",
                "job_id": job["job_id"],
                "job_sha256": job["job_sha256"],
                "worker_pid": int(os.getpid()),
                "h1": h1,
                "h2": h2,
                "report": dict(preliminary_report),
                "prefix": prefix,
                "checkpoint_requested": bool(job.get("checkpoint_requested")),
                "checkpoint_completed": False,
                "memory_after_commit": _v11_memory_snapshot(),
                "receipt_phase": "IMMEDIATE_POST_COMMIT_BEFORE_TEMP_CLEANUP",
            }
            _v11_apply_worker_write_result(result_path, receipt)
            commit_result = receipt
            committed = True
            _emit_event(
                "S17918",
                f"APPLY_WORKER_COMMIT_CONFIRMED job_id={job['job_id']} h1={h1} h2={h2}",
            )

        report = _v11_apply_block_window(
            con,
            h1=h1,
            h2=h2,
            created_paths=stage["created"],
            spends_paths=stage["spends"],
            block_meta_paths=stage["block_meta"],
            window_source_index=None,
            bip30_window_split=dict(job.get("bip30_window_split") or {}),
            post_commit_hook=_publish_commit_receipt,
        )
        if not committed or not commit_result:
            raise RuntimeError("R54 APPLY worker returned from COMMIT without a durable receipt")
        result = dict(commit_result)
        result["report"] = dict(report)
        result["receipt_phase"] = "POST_TEMP_CLEANUP"
        _v11_apply_worker_write_result(result_path, result)

        if bool(job.get("checkpoint_requested")):
            ck_t0 = _tic()
            con.execute("CHECKPOINT")
            result["checkpoint_completed"] = True
            result["checkpoint_elapsed_sec"] = _toc(ck_t0)
            result["status"] = "ok"
            _v11_apply_worker_write_result(result_path, result)
        return 0
    except BaseException as exc:
        is_oom = _v11_is_duckdb_oom(exc)
        if result_path is not None and job is not None and not committed:
            try:
                _v11_apply_worker_write_result(result_path, {
                    "status": "oom" if is_oom else "error",
                    "job_id": job.get("job_id"),
                    "job_sha256": job.get("job_sha256"),
                    "worker_pid": int(os.getpid()),
                    "h1": job.get("h1"),
                    "h2": job.get("h2"),
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                    "retryable_oom": bool(is_oom),
                    "memory_at_error": _v11_memory_snapshot(),
                })
            except BaseException as result_exc:
                _warn(
                    "APPLY worker failed to publish error result: "
                    f"{type(result_exc).__name__}: {result_exc}"
                )
        _log(
            "R54 APPLY worker failed "
            f"type={type(exc).__name__} oom={is_oom}: {exc}",
            stream=sys.stderr,
        )
        return V11_APPLY_WORKER_EXIT_OOM if is_oom else V11_APPLY_WORKER_EXIT_ERROR
    finally:
        if con is not None:
            try:
                con.close()
            except BaseException as close_exc:
                _warn(
                    "R54 APPLY worker close failed: "
                    f"{type(close_exc).__name__}: {close_exc}"
                )


def _v11_apply_worker_launch(job_path: Path) -> Dict[str, Any]:
    script = Path(__file__).resolve(strict=True)
    command = [
        sys.executable,
        str(script),
        "--v11-apply-worker-job",
        str(job_path),
    ]
    env = dict(os.environ)
    env["UTXO_V11_APPLY_WORKER_ACTIVE"] = "1"
    started = _tic()
    proc = subprocess.Popen(
        command,
        env=env,
        close_fds=True,
        start_new_session=True,
    )
    timed_out = False
    timeout = _v11_apply_worker_timeout_seconds()
    try:
        returncode = proc.wait(timeout=timeout if timeout > 0 else None)
    except subprocess.TimeoutExpired:
        timed_out = True
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        try:
            returncode = proc.wait(timeout=_v11_apply_worker_kill_grace_seconds())
        except subprocess.TimeoutExpired:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            returncode = proc.wait()
    return {
        "pid": int(proc.pid),
        "returncode": int(returncode),
        "signal": int(-returncode) if int(returncode) < 0 else None,
        "timed_out": bool(timed_out),
        "elapsed_sec": _toc(started),
        "command": command,
    }


def _v11_apply_worker_cleanup_job(job_dir: Path, *, success: bool) -> None:
    keep = (
        _v11_apply_worker_keep_success_jobs()
        if success
        else _v11_apply_worker_keep_failed_jobs()
    )
    if keep:
        return
    try:
        shutil.rmtree(job_dir, ignore_errors=False)
        _fsync_directory(job_dir.parent)
    except BaseException as exc:
        _warn(
            "R54 APPLY worker job cleanup warning-only failure "
            f"success={success} dir={job_dir}: {type(exc).__name__}: {exc}"
        )


def _v11_close_parent_writer_for_worker(
    con: Optional[duckdb.DuckDBPyConnection], *, context: str
) -> None:
    if con is None:
        return
    try:
        con.close()
    except BaseException as exc:
        raise RuntimeError(
            "R53 cannot prove the parent DuckDB writer was closed before worker launch; "
            f"context={context} error={type(exc).__name__}:{exc}"
        ) from exc
    _v11_release_proof_memory(f"R53 parent writer closed {context}")


def _v11_reopen_parent_writer_verified(
    *,
    db_path: str,
    expected_prefix_min: int,
    expected_prefix_max: int,
    context: str,
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any]]:
    reopened = duckdb.connect(db_path)
    try:
        _apply_duckdb_pragmas(reopened, phase="apply")
        prefix = _v11_validate_committed_block_prefix_after_oom(
            reopened,
            db_path=db_path,
            expected_min=int(expected_prefix_min),
            expected_max=int(expected_prefix_max),
            context=context,
        )
        return reopened, prefix
    except BaseException:
        try:
            reopened.close()
        except BaseException:
            pass
        raise


def _v11_observe_block_meta_prefix(
    *, db_path: str, expected_prefix_min: int, context: str
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any]]:
    con = duckdb.connect(db_path)
    try:
        _apply_duckdb_pragmas(con, phase="apply")
        _v11_assert_schema_compatible(con, db_path)
        meta_min, meta_max, meta_distinct, meta_rows = con.execute(
            """
            SELECT MIN(block_number), MAX(block_number),
                   COUNT(DISTINCT block_number), COUNT(*)
            FROM block_meta
            """
        ).fetchone()
        report = {
            "context": str(context),
            "actual_min": int(meta_min) if meta_min is not None else None,
            "actual_max": int(meta_max) if meta_max is not None else None,
            "actual_distinct": int(meta_distinct or 0),
            "actual_rows": int(meta_rows or 0),
            "expected_prefix_min": int(expected_prefix_min),
        }
        return con, report
    except BaseException:
        try:
            con.close()
        except BaseException:
            pass
        raise


def _v11_prefix_report_matches(
    report: Dict[str, Any], *, expected_min: int, expected_max: int
) -> bool:
    if int(expected_max) < int(expected_min):
        return (
            report.get("actual_min") is None
            and report.get("actual_max") is None
            and int(report.get("actual_distinct") or 0) == 0
            and int(report.get("actual_rows") or 0) == 0
        )
    expected_rows = int(expected_max) - int(expected_min) + 1
    return (
        report.get("actual_min") is not None
        and report.get("actual_max") is not None
        and int(report["actual_min"]) == int(expected_min)
        and int(report["actual_max"]) == int(expected_max)
        and int(report.get("actual_distinct") or 0) == expected_rows
        and int(report.get("actual_rows") or 0) == expected_rows
    )


def _v11_apply_block_window_with_process_isolation(
    con: duckdb.DuckDBPyConnection,
    *,
    db_path: str,
    mode: str,
    h1: int,
    h_max: int,
    requested_window_size: int,
    expected_prefix_min: int,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
    window_source_index: Dict[str, Any],
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any], int, int]:
    configured_size = max(1, int(requested_window_size))
    current_size = configured_size
    min_size = min(configured_size, _v11_adaptive_apply_min_window())
    max_retries = _v11_adaptive_apply_max_retries()
    divisor = _v11_adaptive_apply_backoff_divisor()
    adaptive_enabled = _v11_adaptive_apply_enabled()
    worker_events: List[Dict[str, Any]] = []
    attempt = 0
    parent_con: Optional[duckdb.DuckDBPyConnection] = con
    parent_connection_owned = False

    while True:
        try:
            raw_h2 = min(int(h1) + int(current_size) - 1, int(h_max))
            h2, bip30_window_split = _v11_adjust_block_window_for_bip30(
                int(h1), int(raw_h2), context=f"v11 {mode} R53 worker"
            )
            _v11_assert_no_bip30_pair_inside_window(
                int(h1), int(h2), context=f"v11 {mode} R53 worker"
            )
            attempted_blocks = int(h2) - int(h1) + 1
            _v11_memory_guard(
                f"{mode} isolated block_window={h1}-{h2} attempt={attempt + 1}",
                before_window=True,
            )
            phase_name = f"apply_window:{h1}:{h2}:attempt:{attempt + 1}"
            _phase_started(
                phase_name,
                "S17910",
                f"APPLY_WINDOW_STARTED h1={h1} h2={h2} attempt={attempt + 1} "
                f"effective_window_size={current_size} isolation=subprocess",
            )

            if parent_con is None:
                raise RuntimeError(
                    f"R53 parent writer missing before worker launch mode={mode} h1={h1} h2={h2}"
                )
            _v11_validate_committed_block_prefix_after_oom(
                parent_con,
                db_path=db_path,
                expected_min=int(expected_prefix_min),
                expected_max=int(h1) - 1,
                context=(
                    f"R53 parent pre-launch mode={mode} h1={h1} h2={h2} "
                    f"attempt={attempt + 1}"
                ),
            )
            _v11_assert_loaded_script_unchanged(
                context=f"pre_launch mode={mode} h1={h1} h2={h2} attempt={attempt + 1}"
            )
            _v11_close_parent_writer_for_worker(
                parent_con,
                context=f"{mode} h1={h1} h2={h2} attempt={attempt + 1}",
            )
            parent_con = None
            parent_connection_owned = False

            selected_created, selected_spends, selected_block_meta = _v11_select_window_source_paths(
                window_source_index, int(h1), int(h2)
            )
            job_dir, job_path, result_path, job = _v11_apply_worker_create_job(
                db_path=db_path,
                mode=mode,
                h1=int(h1),
                h2=int(h2),
                expected_prefix_min=int(expected_prefix_min),
                selected_created=selected_created,
                selected_spends=selected_spends,
                selected_block_meta=selected_block_meta,
                bip30_window_split=bip30_window_split,
            )
        except BaseException:
            if parent_connection_owned and parent_con is not None:
                try:
                    parent_con.close()
                except BaseException as close_exc:
                    _warn(
                        "R53 failed to close function-owned parent writer after preamble failure: "
                        f"{type(close_exc).__name__}: {close_exc}"
                    )
            raise
        launch: Dict[str, Any] = {}
        result: Optional[Dict[str, Any]] = None
        protocol_error: Optional[str] = None
        try:
            launch = _v11_apply_worker_launch(job_path)
            try:
                result = _v11_apply_worker_read_result(
                    result_path, job=job, required=False
                )
            except BaseException as exc:
                protocol_error = f"{type(exc).__name__}:{exc}"

            db_now = Path(db_path).resolve(strict=True)
            db_now_stat = _v11_apply_worker_regular_file(
                db_now, label="R53 parent target DB after worker"
            )
            db_now_identity = {
                "device": int(getattr(db_now_stat, "st_dev", 0)),
                "inode": int(getattr(db_now_stat, "st_ino", 0)),
            }
            if db_now_identity != job.get("db_identity"):
                raise RuntimeError(
                    "R53 target DB identity changed across APPLY worker: "
                    f"before={job.get('db_identity')} after={db_now_identity}"
                )
            parent_con, observed = _v11_observe_block_meta_prefix(
                db_path=db_path,
                expected_prefix_min=int(expected_prefix_min),
                context=f"R53 parent observe mode={mode} h1={h1} h2={h2}",
            )
            parent_connection_owned = True
            prefix_before = _v11_prefix_report_matches(
                observed,
                expected_min=int(expected_prefix_min),
                expected_max=int(h1) - 1,
            )
            prefix_after = _v11_prefix_report_matches(
                observed,
                expected_min=int(expected_prefix_min),
                expected_max=int(h2),
            )
            event: Dict[str, Any] = {
                "attempt": int(attempt + 1),
                "h1": int(h1),
                "h2": int(h2),
                "attempted_blocks": int(attempted_blocks),
                "window_size_before": int(current_size),
                "launch": launch,
                "result_status": result.get("status") if result else None,
                "result_path": str(result_path),
                "job_path": str(job_path),
                "protocol_error": protocol_error,
                "observed_prefix": observed,
            }
            worker_events.append(event)

            committed_receipt = bool(
                result
                and result.get("status") in {"committed", "ok"}
                and int(result.get("h1") or -1) == int(h1)
                and int(result.get("h2") or -1) == int(h2)
            )
            if prefix_after and committed_receipt and protocol_error is None:
                report = dict(result.get("report") or {})
                if int(report.get("h1") or -1) != int(h1) or int(report.get("h2") or -1) != int(h2):
                    raise RuntimeError(
                        f"R53 worker committed receipt contains invalid report range: {report}"
                    )
                report.update({
                    "adaptive_apply_enabled": bool(adaptive_enabled),
                    "process_isolation_enabled": True,
                    "requested_window_size": int(configured_size),
                    "effective_window_size": int(current_size),
                    "attempted_blocks": int(attempted_blocks),
                    "oom_retry_count": int(attempt),
                    "worker_retry_count": int(attempt),
                    "worker_events": worker_events,
                    "worker_returncode": launch.get("returncode"),
                    "worker_signal": launch.get("signal"),
                    "worker_checkpoint_requested": bool(result.get("checkpoint_requested")),
                    "worker_checkpoint_completed": bool(result.get("checkpoint_completed")),
                    "worker_committed_receipt": True,
                    "worker_exit_after_commit": bool(int(launch.get("returncode") or 0) != 0),
                })
                _emit_event(
                    "S17919",
                    "APPLY_PARENT_PREFIX_CONFIRMED "
                    f"job_id={job.get('job_id')} h1={h1} h2={h2} "
                    f"returncode={launch.get('returncode')} signal={launch.get('signal')}",
                )
                _phase_completed(
                    phase_name,
                    "S17911",
                    f"APPLY_WINDOW_COMPLETE h1={h1} h2={h2} attempt={attempt + 1} "
                    f"effective_window_size={current_size} isolation=subprocess",
                )
                _v11_apply_worker_cleanup_job(job_dir, success=True)
                parent_connection_owned = False
                return parent_con, report, int(h2), int(current_size)

            if prefix_after and not committed_receipt:
                # The parent proved the exact h1-1 prefix immediately before launch.
                # block_meta and all UTXO mutations are committed by one DuckDB
                # transaction, so an exact contiguous h2 prefix after reopening is
                # authoritative evidence that COMMIT completed even when native code
                # terminated before Python could publish the worker receipt. Recheck
                # the immutable stage binding and persist a parent recovery receipt.
                if int(launch.get("returncode") or 0) == 0:
                    _emit_event(
                        "E17917",
                        "APPLY_WORKER_PROTOCOL_FAILED exit_zero_without_receipt "
                        f"mode={mode} h1={h1} h2={h2} protocol_error={protocol_error}",
                        stream=sys.stderr,
                    )
                    raise RuntimeError(
                        "R54 APPLY worker exited 0 with committed tail but no valid receipt; "
                        f"protocol cannot be trusted: event={event}"
                    )
                _v11_apply_worker_validate_stage_binding(job.get("stage_files"))
                recovered_report: Dict[str, Any] = {
                    "h1": int(h1),
                    "h2": int(h2),
                    "block_rows": int(attempted_blocks),
                    "selected_stage_files": len(job.get("stage_files") or []),
                    "created_rows": None,
                    "spends_rows": None,
                    "conflicts_total": None,
                    "already_spent": None,
                    "spend_apply_mismatch": None,
                    "bip30_window_split": dict(bip30_window_split or {}),
                    "commit_authority": "exact_contiguous_block_meta_prefix_after_worker",
                    "commit_recovered_without_worker_receipt": True,
                    "adaptive_apply_enabled": bool(adaptive_enabled),
                    "process_isolation_enabled": True,
                    "requested_window_size": int(configured_size),
                    "effective_window_size": int(current_size),
                    "attempted_blocks": int(attempted_blocks),
                    "oom_retry_count": int(attempt),
                    "worker_retry_count": int(attempt),
                    "worker_events": worker_events,
                    "worker_returncode": launch.get("returncode"),
                    "worker_signal": launch.get("signal"),
                    "worker_checkpoint_requested": bool(job.get("checkpoint_requested")),
                    "worker_checkpoint_completed": False,
                    "worker_committed_receipt": False,
                    "worker_exit_after_commit": True,
                }
                recovered_result: Dict[str, Any] = {
                    "status": "parent_recovered_commit",
                    "job_id": job.get("job_id"),
                    "job_sha256": job.get("job_sha256"),
                    "worker_pid": launch.get("pid"),
                    "h1": int(h1),
                    "h2": int(h2),
                    "report": recovered_report,
                    "prefix": observed,
                    "checkpoint_requested": bool(job.get("checkpoint_requested")),
                    "checkpoint_completed": False,
                    "receipt_phase": "PARENT_RECOVERED_FROM_EXACT_PREFIX",
                    "worker_returncode": launch.get("returncode"),
                    "worker_signal": launch.get("signal"),
                    "worker_protocol_error": protocol_error,
                }
                _v11_apply_worker_write_result(result_path, recovered_result)
                _emit_event(
                    "W17920",
                    "APPLY_COMMIT_RECOVERED_FROM_PREFIX "
                    f"job_id={job.get('job_id')} mode={mode} h1={h1} h2={h2} "
                    f"returncode={launch.get('returncode')} signal={launch.get('signal')}",
                    stream=sys.stderr,
                )
                _phase_completed(
                    phase_name,
                    "S17911",
                    f"APPLY_WINDOW_COMPLETE h1={h1} h2={h2} attempt={attempt + 1} "
                    f"effective_window_size={current_size} isolation=subprocess "
                    "commit_recovered_from_prefix=true",
                )
                _v11_apply_worker_cleanup_job(job_dir, success=True)
                parent_connection_owned = False
                return parent_con, recovered_report, int(h2), int(current_size)

            if not prefix_before:
                _emit_event(
                    "E17917",
                    "APPLY_WORKER_PROTOCOL_FAILED ambiguous_or_partial_prefix "
                    f"mode={mode} h1={h1} h2={h2} observed={observed}",
                    stream=sys.stderr,
                )
                raise RuntimeError(
                    "R54 APPLY worker changed the committed prefix to an ambiguous/partial state: "
                    f"event={event}"
                )

            if _controlled_stop_requested_no_create() or _signal_stop_requested():
                raise ControlledStopExit(
                    f"CONTROLLED_STOP observed after isolated APPLY worker h1={h1} h2={h2}; prefix unchanged",
                    exit_code=75,
                    payload={"mode": mode, "phase": "after_apply_worker", "event": event},
                )

            result_status = str(result.get("status") or "") if result else ""
            returncode = int(launch.get("returncode") or 0)
            if result_status == "oom" and returncode not in {V11_APPLY_WORKER_EXIT_OOM} and returncode >= 0:
                raise RuntimeError(
                    "R54 APPLY worker protocol mismatch: OOM result with unexpected "
                    f"returncode={returncode} event={event}"
                )
            if result_status == "error" and returncode not in {V11_APPLY_WORKER_EXIT_ERROR} and returncode >= 0:
                raise RuntimeError(
                    "R54 APPLY worker protocol mismatch: error result with unexpected "
                    f"returncode={returncode} event={event}"
                )
            if returncode == 0 and result_status not in {"committed", "ok"}:
                raise RuntimeError(
                    "R54 APPLY worker protocol mismatch: exit 0 without committed/ok receipt: "
                    f"event={event}"
                )

            result_is_oom = bool(result_status == "oom")
            returncode_is_oom = bool(
                int(launch.get("returncode") or 0) == V11_APPLY_WORKER_EXIT_OOM
            )
            native_signal = int(launch.get("signal") or 0)
            retryable_signal = native_signal in {
                int(getattr(signal, "SIGABRT", 6)),
                int(getattr(signal, "SIGSEGV", 11)),
                int(getattr(signal, "SIGBUS", 7)),
                int(getattr(signal, "SIGKILL", 9)),
            }
            retryable = bool(
                adaptive_enabled
                and protocol_error is None
                and (
                    result_is_oom
                    or returncode_is_oom
                    or retryable_signal
                    or bool(launch.get("timed_out"))
                )
            )
            if not retryable:
                error_text = (
                    result.get("error") if result else
                    protocol_error or f"worker_returncode={launch.get('returncode')}"
                )
                raise RuntimeError(
                    "R54 APPLY worker failed with unchanged prefix but the failure is not "
                    f"retryable: mode={mode} h1={h1} h2={h2} error={error_text} event={event}"
                )

            attempt += 1
            base_size = max(1, min(int(current_size), int(attempted_blocks)))
            next_size = max(int(min_size), int(base_size) // int(divisor))
            if next_size >= int(base_size) and int(base_size) > int(min_size):
                next_size = int(base_size) - 1
            can_retry = attempt <= max_retries and int(base_size) > int(min_size)
            event["window_size_after"] = int(next_size)
            event["retryable_native_signal"] = bool(retryable_signal)
            event["retryable_oom"] = bool(result_is_oom or returncode_is_oom)
            event["worker_exit_code_oom"] = bool(returncode_is_oom)
            event["retryable_timeout"] = bool(launch.get("timed_out"))
            _phase_completed(
                phase_name,
                "W17912",
                "APPLY_WINDOW_OOM_BACKOFF "
                f"mode={mode} h1={h1} h2={h2} attempt={attempt}/{max_retries} "
                f"actual_blocks={attempted_blocks} window={current_size}->{next_size} "
                f"returncode={launch.get('returncode')} signal={native_signal} "
                f"result_status={result.get('status') if result else None}",
                stream=sys.stderr,
            )
            _emit_event(
                "W17916",
                "APPLY_WORKER_RETRY "
                f"mode={mode} h1={h1} failed_h2={h2} actual_blocks={attempted_blocks} "
                f"next_window={next_size} returncode={launch.get('returncode')} signal={native_signal}",
                stream=sys.stderr,
            )
            _v11_apply_worker_cleanup_job(job_dir, success=False)
            if not can_retry or next_size >= base_size:
                raise RuntimeError(
                    "R53 isolated APPLY retry budget/minimum window exhausted: "
                    f"mode={mode} h1={h1} failed_h2={h2} actual_blocks={attempted_blocks} "
                    f"min_window_size={min_size} attempts={attempt}/{max_retries}"
                )
            current_size = int(next_size)
            continue
        except BaseException:
            try:
                if job_dir.exists():
                    _v11_apply_worker_cleanup_job(job_dir, success=False)
            except BaseException as cleanup_exc:
                _warn(
                    "R54 APPLY worker job cleanup failed during exception: "
                    f"{type(cleanup_exc).__name__}: {cleanup_exc}"
                )
            if parent_con is not None:
                try:
                    parent_con.close()
                except BaseException as close_exc:
                    _warn(
                        "R54 failed to close parent writer before outer crash recovery: "
                        f"{type(close_exc).__name__}: {close_exc}"
                    )
            parent_connection_owned = False
            raise


def _v11_apply_block_window_with_oom_backoff(
    con: duckdb.DuckDBPyConnection,
    *,
    db_path: str,
    mode: str,
    h1: int,
    h_max: int,
    requested_window_size: int,
    expected_prefix_min: int,
    created_paths: Sequence[str],
    spends_paths: Sequence[str],
    block_meta_paths: Sequence[str],
    window_source_index: Dict[str, Any],
) -> Tuple[duckdb.DuckDBPyConnection, Dict[str, Any], int, int]:
    if _v11_apply_process_isolation_enabled():
        return _v11_apply_block_window_with_process_isolation(
            con,
            db_path=db_path,
            mode=mode,
            h1=h1,
            h_max=h_max,
            requested_window_size=requested_window_size,
            expected_prefix_min=expected_prefix_min,
            created_paths=created_paths,
            spends_paths=spends_paths,
            block_meta_paths=block_meta_paths,
            window_source_index=window_source_index,
        )
    if not _v11_inprocess_apply_dangerous_allowed():
        raise RuntimeError(
            "UTXO_V11_APPLY_PROCESS_ISOLATION=0 is blocked for production. "
            "The in-process path can lose the parent to a native DuckDB abort. "
            "For an explicit lab-only diagnostic, set both UTXO_V11_LAB_MODE=1 "
            "and UTXO_V11_ALLOW_INPROCESS_APPLY_DANGEROUS=1."
        )
    _warn(
        "DANGEROUS LAB MODE: process-isolated APPLY disabled; native DuckDB aborts "
        "can terminate the parent pipeline. Using R52.1 in-process fallback."
    )
    return _v11_apply_block_window_with_inprocess_oom_backoff(
        con,
        db_path=db_path,
        mode=mode,
        h1=h1,
        h_max=h_max,
        requested_window_size=requested_window_size,
        expected_prefix_min=expected_prefix_min,
        created_paths=created_paths,
        spends_paths=spends_paths,
        block_meta_paths=block_meta_paths,
        window_source_index=window_source_index,
    )

