def _core_stage2_base() -> Path:
    return Path(_env_str("UTXO_CORE_STAGE2_BASE", CORE_STAGE2_BASE_DEFAULT) or CORE_STAGE2_BASE_DEFAULT)


def _core_db_path() -> Path:
    return Path(_env_str("UTXO_CORE_DB_PATH", CORE_DB_PATH_DEFAULT) or CORE_DB_PATH_DEFAULT).absolute()


def _core_work_root(create: bool = True) -> Path:
    p = Path(_env_str("UTXO_CORE_WORK_ROOT", CORE_WORK_ROOT_DEFAULT) or CORE_WORK_ROOT_DEFAULT)
    if create:
        p.mkdir(parents=True, exist_ok=True)
    return p


def _core_worker_root(create: bool = True) -> Path:
    p = Path(_env_str("UTXO_CORE_WORKER_ROOT", CORE_WORKER_ROOT_DEFAULT) or CORE_WORKER_ROOT_DEFAULT)
    if create:
        p.mkdir(parents=True, exist_ok=True)
        try:
            p.chmod(0o700)
        except Exception:
            pass
    return p


def _core_marker_path(db_path: Path) -> Path:
    root = _core_work_root(True) / "checkpoints"
    root.mkdir(parents=True, exist_ok=True)
    return root / f"core_stage2_rebuild.{_lock_key(str(db_path.absolute()))}.json"


def _core_audit_dir() -> Path:
    p = _core_work_root(True) / "audit"
    p.mkdir(parents=True, exist_ok=True)
    return p


def _core_save_audit_json(filename: str, payload: Dict[str, Any]) -> Dict[str, str]:
    """Atomically publish a Core audit JSON and a matching SHA256 sidecar."""
    if not filename or Path(filename).name != filename or not filename.endswith(".json"):
        raise RuntimeError(f"invalid CORE audit filename: {filename!r}")
    path = _core_audit_dir() / filename
    _save_json_atomic(path, payload)
    digest = _file_sha256_streaming(path)
    sidecar = Path(str(path) + ".sha256")
    tmp = sidecar.with_name(
        f".{sidecar.name}.tmp.{os.getpid()}.{time.time_ns()}.{uuid.uuid4().hex}"
    )
    try:
        with open(tmp, "x", encoding="ascii") as f:
            f.write(f"{digest}  {path.name}\n")
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, sidecar)
        _fsync_directory(sidecar.parent)
    except BaseException:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        raise
    # Re-read exactly what was published.  This catches accidental path/sidecar
    # mismatches before a caller reports the audit artifact as frozen.
    recorded = _core_read_sha_sidecar(sidecar, path.name)
    actual = _file_sha256_streaming(path)
    if recorded != digest or actual != digest:
        raise RuntimeError(
            f"CORE audit freeze verification failed path={path} "
            f"recorded={recorded} expected={digest} actual={actual}"
        )
    return {"path": str(path), "sha256": digest, "sidecar": str(sidecar)}


def _core_apply_pragmas(con: duckdb.DuckDBPyConnection, phase: str = "apply") -> None:
    if str(V11_PROCESS_DUCKDB_VERSION) != CORE_EXPECTED_DUCKDB_VERSION:
        raise RuntimeError(
            f"CORE backend requires exact DuckDB {CORE_EXPECTED_DUCKDB_VERSION}; "
            f"loaded={V11_PROCESS_DUCKDB_VERSION}"
        )
    _apply_duckdb_pragmas(con, phase=phase)
    con.execute("SET TimeZone='UTC'")


def _core_require_runtime_script_guard(*, context: str) -> Dict[str, Any]:
    """Core write/read-proof modes require the inherited v30 self-hash guard.

    The legacy pipeline allows the guard to be disabled for historical/debug
    use.  The Core backend does not: its worker/ledger/recovery identity relies
    on an exact script SHA, so a disabled guard would weaken the release
    contract and is rejected fail-closed.
    """
    if not V11_RUNTIME_SCRIPT_SHA256_GUARD_ENABLED:
        raise RuntimeError(
            "CORE backend requires UTXO_V11_RUNTIME_SCRIPT_SHA256_GUARD=1; "
            f"guard was disabled at process bootstrap context={context}"
        )
    if not _v11_runtime_script_sha256_guard_enabled():
        raise RuntimeError(
            "CORE backend runtime script SHA guard became disabled after bootstrap; "
            f"context={context}"
        )
    digest = V11_PROCESS_SCRIPT_SHA256
    if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        raise RuntimeError(
            f"CORE backend has invalid loaded script SHA256 context={context}: {digest!r}"
        )
    return _v11_assert_loaded_script_unchanged(context=context)


def _core_verify_parent_v30_reference() -> Dict[str, Any]:
    parent_path = Path(_env_str("UTXO_V40_PARENT_V30_PATH", "/root/mybot/utxo_pipeline_v30.py") or "/root/mybot/utxo_pipeline_v30.py")
    required = _env_bool("UTXO_V40_REQUIRE_PARENT_V30_SHA", True)
    if not parent_path.exists():
        if required:
            raise RuntimeError(f"frozen v30 parent is missing: {parent_path}")
        return {"status": "MISSING_ALLOWED", "path": str(parent_path), "expected_sha256": V40_PARENT_V30_SHA256}
    before = _core_file_identity(parent_path)
    actual = _file_sha256_streaming(parent_path)
    after = _core_file_identity(parent_path)
    if not _core_identity_equal(before, after):
        raise RuntimeError(
            f"frozen v30 parent changed during SHA verification path={parent_path} "
            f"before={before} after={after}"
        )
    if actual != V40_PARENT_V30_SHA256:
        raise RuntimeError(f"frozen v30 parent SHA mismatch path={parent_path} actual={actual} expected={V40_PARENT_V30_SHA256}")
    return {"status": "GREEN", "path": str(parent_path.resolve()), "sha256": actual, "identity": after}


def _core_file_identity(path: Path) -> Dict[str, Any]:
    # Check the user-visible path before resolve(); checking only the resolved
    # path would silently accept a symlink because resolve() dereferences it.
    if path.is_symlink():
        raise RuntimeError(f"CORE source path must not be a symlink: {path}")
    rp = path.resolve(strict=True)
    if not rp.is_file():
        raise RuntimeError(f"CORE source is not a regular file: {path}")
    st = rp.stat()
    return {
        "path": str(rp),
        "device": int(st.st_dev),
        "inode": int(st.st_ino),
        "size": int(st.st_size),
        "mtime_ns": int(st.st_mtime_ns),
        "ctime_ns": int(st.st_ctime_ns),
    }


def _core_identity_equal(expected: Dict[str, Any], actual: Dict[str, Any]) -> bool:
    return all(int(expected[k]) == int(actual[k]) for k in ("device", "inode", "size", "mtime_ns", "ctime_ns"))


def _core_validate_binding(rows: Sequence[Dict[str, Any]]) -> None:
    for row in rows:
        path = Path(str(row["path"]))
        now = _core_file_identity(path)
        if not _core_identity_equal(row, now):
            raise RuntimeError(f"CORE Stage2 source changed after freeze: expected={row} actual={now}")


def _core_read_text_regular_snapshot(path: Path, *, encoding: str = "utf-8") -> Tuple[str, str, Dict[str, Any]]:
    """Read/hash one stable non-symlink regular text file snapshot."""
    if path.is_symlink():
        raise RuntimeError(f"CORE text snapshot source must not be a symlink: {path}")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(str(path), flags)
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode):
            raise RuntimeError(f"CORE text snapshot source is not a regular file: {path}")
        chunks: List[bytes] = []
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    before_id = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns)
    after_id = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns)
    if before_id != after_id:
        raise RuntimeError(f"CORE text snapshot changed during read path={path} before={before_id} after={after_id}")
    data = b"".join(chunks)
    if len(data) != int(after.st_size):
        raise RuntimeError(f"CORE text snapshot size mismatch path={path} read={len(data)} stat={after.st_size}")
    digest = hashlib.sha256(data).hexdigest()
    return data.decode(encoding), digest, {
        "path": str(path.resolve(strict=True)), "device": int(after.st_dev), "inode": int(after.st_ino),
        "size": int(after.st_size), "mtime_ns": int(after.st_mtime_ns), "ctime_ns": int(after.st_ctime_ns),
    }


def _core_read_sha_sidecar(path: Path, expected_name: Optional[str] = None) -> str:
    if not path.is_file() or path.is_symlink():
        raise RuntimeError(f"missing/non-regular SHA256 sidecar: {path}")
    parts = path.read_text(encoding="ascii").strip().split()
    if not parts or len(parts[0]) != 64 or any(c not in "0123456789abcdefABCDEF" for c in parts[0]):
        raise RuntimeError(f"invalid SHA256 sidecar: {path}")
    if expected_name is not None and len(parts) >= 2 and Path(parts[-1]).name != expected_name:
        raise RuntimeError(f"SHA256 sidecar filename mismatch: sidecar={path} value={parts[-1]!r} expected={expected_name!r}")
    return parts[0].lower()


def _core_verify_file_sha(path: Path, sidecar: Path, expected_sha: Optional[str] = None) -> str:
    # Reject links/non-regular sources before reading either content or sidecar.
    _core_file_identity(path)
    _core_file_identity(sidecar)
    recorded = _core_read_sha_sidecar(sidecar, path.name)
    if expected_sha is not None and recorded != str(expected_sha).lower():
        raise RuntimeError(f"CORE Stage2 recorded SHA mismatch path={path}: recorded={recorded} expected={expected_sha}")
    actual = _file_sha256_streaming(path)
    if actual != recorded:
        raise RuntimeError(f"CORE Stage2 file SHA mismatch path={path}: actual={actual} recorded={recorded}")
    return actual


def _core_schema_rows(con: duckdb.DuckDBPyConnection, path: Path) -> Tuple[Tuple[str, str], ...]:
    rows = con.execute(
        f"DESCRIBE SELECT * FROM read_parquet({_quote_sql_string(str(path))})"
    ).fetchall()
    return tuple((str(r[0]), str(r[1]).upper()) for r in rows)


def _core_assert_schema(con: duckdb.DuckDBPyConnection, path: Path, role: str) -> None:
    expected = CORE_EXPECTED_SCHEMAS[role]
    actual = _core_schema_rows(con, path)
    if actual != expected:
        raise RuntimeError(f"CORE Stage2 schema mismatch role={role} path={path}\nexpected={expected}\nactual={actual}")


def _core_preflight_bip30(con: duckdb.DuckDBPyConnection, entries: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    def paths_for_height(height: int) -> Tuple[str, str]:
        for e in entries:
            if int(e["start_height"]) <= int(height) <= int(e["end_height"]):
                return str(e["transactions_path"]), str(e["outputs_path"])
        raise RuntimeError(f"no CORE Stage2 window contains BIP30 height={height}")

    pair_reports: List[Dict[str, Any]] = []
    for later, earlier in CORE_BIP30_HEIGHT_PAIRS:
        tx_paths = sorted(set(paths_for_height(earlier)[0:1] + paths_for_height(later)[0:1]))
        tx_sql = _quote_sql_list(tx_paths)
        rows = con.execute(
            f"""
            SELECT height, tx_index, lower(txid) AS txid, is_coinbase
            FROM read_parquet({tx_sql}, union_by_name=true)
            WHERE height IN (?, ?) AND tx_index = 0
            ORDER BY height
            """,
            [int(earlier), int(later)],
        ).fetchall()
        if len(rows) != 2:
            raise RuntimeError(f"CORE BIP30 preflight missing coinbase rows pair={later}:{earlier} rows={rows}")
        by_h = {int(r[0]): r for r in rows}
        a = by_h.get(int(earlier))
        b = by_h.get(int(later))
        if a is None or b is None or not bool(a[3]) or not bool(b[3]) or str(a[2]) != str(b[2]):
            raise RuntimeError(f"CORE BIP30 txid/coinbase proof failed pair={later}:{earlier} rows={rows}")
        txid = str(a[2])
        out_paths = sorted(set([paths_for_height(earlier)[1], paths_for_height(later)[1]]))
        out_sql = _quote_sql_list(out_paths)
        out_rows = con.execute(
            f"""
            SELECT height, count(*) AS n, sum(value_sats) AS sats
            FROM read_parquet({out_sql}, union_by_name=true)
            WHERE height IN (?, ?) AND tx_index = 0 AND lower(txid) = ?
            GROUP BY height ORDER BY height
            """,
            [int(earlier), int(later), txid],
        ).fetchall()
        if len(out_rows) != 2 or int(out_rows[0][1]) != int(out_rows[1][1]) or int(out_rows[0][2]) != int(out_rows[1][2]):
            raise RuntimeError(f"CORE BIP30 duplicate transaction output cardinality/value proof failed pair={later}:{earlier} rows={out_rows}")
        payload_mismatch = int(con.execute(
            f"""
            WITH o AS (
              SELECT height, vout, value_sats, script_pubkey, script_pubkey_size
              FROM read_parquet({out_sql}, union_by_name=true)
              WHERE height IN (?, ?) AND tx_index=0 AND lower(txid)=?
            ), e AS (
              SELECT vout,value_sats,script_pubkey,script_pubkey_size FROM o WHERE height=?
            ), l AS (
              SELECT vout,value_sats,script_pubkey,script_pubkey_size FROM o WHERE height=?
            )
            SELECT count(*)
            FROM e FULL OUTER JOIN l USING (vout)
            WHERE e.vout IS NULL OR l.vout IS NULL
               OR e.value_sats IS DISTINCT FROM l.value_sats
               OR e.script_pubkey_size IS DISTINCT FROM l.script_pubkey_size
               OR e.script_pubkey IS DISTINCT FROM l.script_pubkey
            """,
            [int(earlier), int(later), txid, int(earlier), int(later)],
        ).fetchone()[0] or 0)
        if payload_mismatch:
            raise RuntimeError(
                f"CORE BIP30 duplicate transaction exact output payload proof failed "
                f"pair={later}:{earlier} mismatches={payload_mismatch}"
            )
        pair_reports.append({
            "later_height": int(later), "earlier_height": int(earlier), "txid": txid,
            "outputs": int(out_rows[0][1]), "value_sats": int(out_rows[0][2]),
            "exact_output_payload_match": True,
        })
    observed_txids = {str(x["txid"]).lower() for x in pair_reports}
    if len(observed_txids) != len(pair_reports):
        raise RuntimeError(f"CORE BIP30 known pairs unexpectedly share txid: {pair_reports}")
    if observed_txids != set(CORE_BIP30_KNOWN_TXIDS):
        raise RuntimeError(
            f"CORE BIP30 known txid set mismatch observed={sorted(observed_txids)} "
            f"expected={sorted(CORE_BIP30_KNOWN_TXIDS)}"
        )
    return {"status": "GREEN", "pairs": pair_reports, "known_txids": sorted(observed_txids)}


def _core_stage2_preflight(*, verify_parquet_sha: Optional[bool] = None) -> Dict[str, Any]:
    _core_require_runtime_script_guard(context="CORE_STAGE2 source preflight")
    base_raw = _core_stage2_base()
    if base_raw.is_symlink():
        raise RuntimeError(f"CORE Stage2 root must not be a symlink: {base_raw}")
    base = base_raw.resolve(strict=True)
    if not base.is_dir():
        raise RuntimeError(f"CORE Stage2 root is not a directory: {base}")
    manifests = base / "manifests"
    windows_dir = base / "windows"
    for role, directory in (("manifests", manifests), ("windows", windows_dir)):
        if directory.is_symlink():
            raise RuntimeError(f"CORE Stage2 {role} directory must not be a symlink: {directory}")
        if not directory.is_dir():
            raise RuntimeError(f"CORE Stage2 {role} directory is missing/not-directory: {directory}")
    global_manifest = manifests / "canonical_transactions_0_617698.json"
    global_sidecar = Path(str(global_manifest) + ".sha256")
    windows_tsv = manifests / "canonical_transactions_0_617698.windows.tsv"
    windows_sidecar = Path(str(windows_tsv) + ".sha256")

    if verify_parquet_sha is None:
        verify_parquet_sha = _env_bool("UTXO_CORE_STAGE2_VERIFY_PARQUET_SHA", True)

    parent_reference = _core_verify_parent_v30_reference()
    global_sha = _core_verify_file_sha(global_manifest, global_sidecar, CORE_RELEASE_GLOBAL_MANIFEST_SHA256)
    obj, global_snapshot_sha, _ = _read_json_regular_file_snapshot(global_manifest)
    if global_snapshot_sha != global_sha:
        raise RuntimeError(
            f"CORE global manifest changed between hash verification and parse: "
            f"verified={global_sha} parsed={global_snapshot_sha}"
        )
    expected_header = {
        "schema": "mybot_stage2_canonical_transactions_v1",
        "release_complete": True,
        "start_height": CORE_RELEASE_START_HEIGHT,
        "end_height": CORE_RELEASE_END_HEIGHT,
        "block_rows": CORE_RELEASE_TOTALS["blocks"],
        "window_size": 1000,
        "window_count": CORE_RELEASE_WINDOW_COUNT,
        "extractor_script_sha256": CORE_RELEASE_EXTRACTOR_SHA256,
        "decoder_script_sha256": CORE_RELEASE_DECODER_SHA256,
        "duckdb_version": CORE_EXPECTED_DUCKDB_VERSION,
    }
    for k, v in expected_header.items():
        if obj.get(k) != v:
            raise RuntimeError(f"CORE global manifest mismatch key={k}: actual={obj.get(k)!r} expected={v!r}")
    windows_obj = obj.get("windows_tsv") or {}
    if windows_obj.get("file") != "canonical_transactions_0_617698.windows.tsv":
        raise RuntimeError(
            f"CORE global windows.tsv filename mismatch actual={windows_obj.get('file')!r}"
        )
    global_validation_required = {
        "all_windows_release_complete", "all_window_file_sha256_verified",
        "height_coverage_contiguous", "canonical_block_hash_all",
        "canonical_prevhash_all", "exact_block_boundary_all",
        "context_free_tx_checks_all", "txid_wtxid_all", "merkle_root_all",
        "witness_commitment_all", "parquet_cross_table_counts_all",
    }
    global_validation = obj.get("validation") or {}
    bad_global_validation = sorted(
        key for key in global_validation_required if global_validation.get(key) is not True
    )
    if bad_global_validation:
        raise RuntimeError(
            f"CORE global validation contract missing/false keys={bad_global_validation}"
        )
    totals = obj.get("totals") or {}
    for k, v in CORE_RELEASE_TOTALS.items():
        if int(totals.get(k, -1)) != int(v):
            raise RuntimeError(f"CORE global totals mismatch {k}: actual={totals.get(k)} expected={v}")
    provenance = obj.get("provenance") or {}
    for k, v in CORE_RELEASE_PROVENANCE.items():
        if str(provenance.get(k) or "").lower() != str(v).lower():
            raise RuntimeError(
                f"CORE global provenance mismatch {k}: actual={provenance.get(k)!r} expected={v!r}"
            )

    windows_sha = _core_verify_file_sha(windows_tsv, windows_sidecar, obj.get("windows_tsv", {}).get("sha256"))
    rows: List[Dict[str, str]] = []
    import csv as _core_csv
    import io as _core_io
    windows_text, windows_snapshot_sha, _ = _core_read_text_regular_snapshot(windows_tsv, encoding="ascii")
    if windows_snapshot_sha != windows_sha:
        raise RuntimeError(
            f"CORE windows.tsv changed between hash verification and parse: "
            f"verified={windows_sha} parsed={windows_snapshot_sha}"
        )
    reader = _core_csv.DictReader(_core_io.StringIO(windows_text, newline=""), delimiter="\t")
    expected_windows_columns = [
        "window_start", "window_end", "window_manifest_sha256",
        "blocks_sha256", "transactions_sha256", "inputs_sha256", "outputs_sha256",
        "blocks", "transactions", "inputs", "outputs",
    ]
    if list(reader.fieldnames or []) != expected_windows_columns:
        raise RuntimeError(
            f"CORE windows.tsv schema mismatch actual={reader.fieldnames} expected={expected_windows_columns}"
        )
    rows = list(reader)
    if len(rows) != CORE_RELEASE_WINDOW_COUNT:
        raise RuntimeError(f"CORE windows.tsv row count mismatch actual={len(rows)} expected={CORE_RELEASE_WINDOW_COUNT}")

    con = duckdb.connect(":memory:")
    try:
        _core_apply_pragmas(con, phase="stage")
        entries: List[Dict[str, Any]] = []
        expected_start = CORE_RELEASE_START_HEIGHT
        aggregate = {k: 0 for k in CORE_RELEASE_TOTALS}
        source_bindings: List[Dict[str, Any]] = [
            _core_file_identity(global_manifest), _core_file_identity(global_sidecar),
            _core_file_identity(windows_tsv), _core_file_identity(windows_sidecar),
        ]
        for idx, row in enumerate(rows, 1):
            start = int(row["window_start"])
            end = int(row["window_end"])
            if start != expected_start or end != min(start + 999, CORE_RELEASE_END_HEIGHT):
                raise RuntimeError(f"CORE window continuity/range mismatch index={idx} row={row} expected_start={expected_start}")
            expected_start = end + 1
            d = windows_dir / f"window_{start:06d}_{end:06d}"
            if d.is_symlink():
                raise RuntimeError(f"CORE Stage2 window directory must not be a symlink: {d}")
            if not d.is_dir():
                raise RuntimeError(f"CORE Stage2 window directory is missing/not-directory: {d}")
            m = d / "manifest.json"
            ms = d / "manifest.json.sha256"
            manifest_sha = _core_verify_file_sha(m, ms, row["window_manifest_sha256"])
            wm, manifest_snapshot_sha, _ = _read_json_regular_file_snapshot(m)
            if manifest_snapshot_sha != manifest_sha:
                raise RuntimeError(
                    f"CORE window manifest changed between hash verification and parse dir={d}: "
                    f"verified={manifest_sha} parsed={manifest_snapshot_sha}"
                )
            if wm.get("schema") != "mybot_stage2_window_v1" or wm.get("release_complete") is not True:
                raise RuntimeError(f"CORE window manifest contract mismatch dir={d}")
            if int(wm.get("start_height", -1)) != start or int(wm.get("end_height", -1)) != end:
                raise RuntimeError(f"CORE window manifest range mismatch dir={d}")
            if wm.get("extractor_script_sha256") != CORE_RELEASE_EXTRACTOR_SHA256 or wm.get("decoder_script_sha256") != CORE_RELEASE_DECODER_SHA256:
                raise RuntimeError(f"CORE window producer SHA mismatch dir={d}")
            if str(wm.get("duckdb_version")) != CORE_EXPECTED_DUCKDB_VERSION:
                raise RuntimeError(
                    f"CORE window DuckDB producer version mismatch dir={d} "
                    f"actual={wm.get('duckdb_version')} expected={CORE_EXPECTED_DUCKDB_VERSION}"
                )
            if int(wm.get("block_rows", -1)) != end - start + 1 or int(wm.get("window_size_setting", -1)) != 1000:
                raise RuntimeError(
                    f"CORE window row/window-size contract mismatch dir={d} "
                    f"block_rows={wm.get('block_rows')} window_size_setting={wm.get('window_size_setting')}"
                )
            expected_window_provenance = dict(CORE_RELEASE_PROVENANCE)
            expected_window_provenance["stage2_decoder_script_sha256"] = CORE_RELEASE_DECODER_SHA256
            if (wm.get("provenance") or {}) != expected_window_provenance:
                raise RuntimeError(
                    f"CORE window provenance mismatch dir={d} "
                    f"actual={wm.get('provenance')} expected={expected_window_provenance}"
                )
            window_validation_required = {
                "canonical_block_hash_all", "canonical_prevhash_all",
                "exact_block_boundary_all", "context_free_tx_checks_all",
                "txid_wtxid_all", "merkle_root_all", "witness_commitment_all",
                "parquet_cross_table_counts", "parquet_output_script_blob_lengths",
            }
            window_validation = wm.get("validation") or {}
            bad_window_validation = sorted(
                key for key in window_validation_required if window_validation.get(key) is not True
            )
            if bad_window_validation:
                raise RuntimeError(
                    f"CORE window validation contract missing/false dir={d} keys={bad_window_validation}"
                )
            counts = wm.get("counts") or {}
            validated = wm.get("validated_parquet_counts") or {}
            files_obj = wm.get("files") or {}
            role_to_count = {"blocks.parquet": "blocks", "transactions.parquet": "transactions", "inputs.parquet": "inputs", "outputs.parquet": "outputs"}
            if set(files_obj) != set(role_to_count):
                raise RuntimeError(
                    f"CORE window file-set contract mismatch dir={d} actual={sorted(files_obj)} "
                    f"expected={sorted(role_to_count)}"
                )
            entry: Dict[str, Any] = {
                "start_height": start, "end_height": end, "manifest_path": str(m.resolve()),
                "manifest_sha256": manifest_sha,
            }
            binding_rows: List[Dict[str, Any]] = [_core_file_identity(m), _core_file_identity(ms)]
            for role, count_key in role_to_count.items():
                p = d / role
                s = d / f"{role}.sha256"
                # Capture and validate file identity before any stat/hash/Parquet read.
                p_identity = _core_file_identity(p)
                s_identity = _core_file_identity(s)
                info = files_obj.get(role) or {}
                expected_sha = str(info.get("sha256") or "").lower()
                if expected_sha != str(row[f"{count_key}_sha256"]).lower():
                    raise RuntimeError(f"CORE windows.tsv/file manifest SHA disagreement role={role} dir={d}")
                recorded = _core_read_sha_sidecar(s, role)
                if recorded != expected_sha:
                    raise RuntimeError(f"CORE parquet sidecar/manifest SHA disagreement role={role} dir={d}")
                if int(info.get("size_bytes", -1)) != int(p_identity["size"]):
                    raise RuntimeError(f"CORE parquet size mismatch role={role} dir={d}")
                if int(counts.get(count_key, -1)) != int(validated.get(count_key, -2)) or int(counts.get(count_key, -1)) != int(row[count_key]):
                    raise RuntimeError(f"CORE parquet count contract mismatch role={role} dir={d}")
                if verify_parquet_sha:
                    actual_sha = _file_sha256_streaming(p)
                    if actual_sha != expected_sha:
                        raise RuntimeError(f"CORE parquet SHA mismatch role={role} path={p} actual={actual_sha} expected={expected_sha}")
                _core_assert_schema(con, p, role)
                entry[role.replace(".parquet", "_path")] = str(p.resolve())
                entry[role.replace(".parquet", "_sha256")] = expected_sha
                entry[role.replace(".parquet", "_rows")] = int(counts[count_key])
                binding_rows.extend([p_identity, s_identity])
                aggregate[count_key] += int(counts[count_key])
            entry["bindings"] = binding_rows
            source_bindings.extend(binding_rows)
            entries.append(entry)
            if idx == 1 or idx == len(rows) or idx % 50 == 0:
                _log(f"CORE_STAGE2_PREFLIGHT window={idx}/{len(rows)} range={start}-{end} sha={'full' if verify_parquet_sha else 'sidecar'}")
        if expected_start != CORE_RELEASE_END_HEIGHT + 1:
            raise RuntimeError(f"CORE window coverage incomplete expected_next={CORE_RELEASE_END_HEIGHT + 1} actual={expected_start}")
        if aggregate != CORE_RELEASE_TOTALS:
            raise RuntimeError(f"CORE aggregate counts mismatch actual={aggregate} expected={CORE_RELEASE_TOTALS}")

        # The global SHA already freezes the release, but keep an explicit
        # human-auditable terminal block anchor in the source contract as well.
        end_entry = entries[-1]
        end_row = con.execute(
            f"SELECT lower(block_hash), count(*) FROM read_parquet({_quote_sql_string(end_entry['blocks_path'])}) WHERE height=? GROUP BY 1",
            [CORE_RELEASE_END_HEIGHT],
        ).fetchall()
        if end_row != [(CORE_RELEASE_END_HASH, 1)]:
            raise RuntimeError(
                f"CORE frozen end-anchor mismatch height={CORE_RELEASE_END_HEIGHT} "
                f"actual={end_row} expected_hash={CORE_RELEASE_END_HASH}"
            )
        bip30 = _core_preflight_bip30(con, entries)
        _core_validate_binding(source_bindings)
    finally:
        con.close()

    report = {
        "contract_version": V40_CORE_SOURCE_CONTRACT,
        "status": "GREEN",
        "v40_core_pipeline_version": V40_CORE_PIPELINE_VERSION,
        "parent_v30_sha256": V40_PARENT_V30_SHA256,
        "parent_v30_reference": parent_reference,
        "loaded_v40_script_sha256": V11_PROCESS_SCRIPT_SHA256,
        "stage2_base": str(base),
        "global_manifest_path": str(global_manifest),
        "global_manifest_sha256": global_sha,
        "windows_tsv_path": str(windows_tsv),
        "windows_tsv_sha256": windows_sha,
        "verify_parquet_sha": bool(verify_parquet_sha),
        "window_count": len(entries),
        "start_height": CORE_RELEASE_START_HEIGHT,
        "end_height": CORE_RELEASE_END_HEIGHT,
        "end_hash": CORE_RELEASE_END_HASH,
        "totals": aggregate,
        "provenance": dict(CORE_RELEASE_PROVENANCE),
        "bip30": bip30,
        "entries": entries,
        "source_bindings": source_bindings,
    }
    report["source_fingerprint_sha256"] = _v11_canonical_json_hash({
        "contract_version": V40_CORE_SOURCE_CONTRACT,
        "global_manifest_sha256": global_sha,
        "windows_tsv_sha256": windows_sha,
        "entries": [
            {k: e[k] for k in (
                "start_height", "end_height", "manifest_sha256",
                "blocks_sha256", "transactions_sha256", "inputs_sha256", "outputs_sha256",
            )} for e in entries
        ],
    })
    audit_filename = (
        "core_stage2_source_preflight_full_sha.json"
        if verify_parquet_sha
        else "core_stage2_source_preflight_sidecar_only.json"
    )
    frozen_audit = _core_save_audit_json(
        audit_filename,
        {k: v for k, v in report.items() if k not in {"entries", "source_bindings"}},
    )
    report["audit_path"] = frozen_audit["path"]
    report["audit_sha256"] = frozen_audit["sha256"]
    report["audit_sidecar"] = frozen_audit["sidecar"]
    _log(
        f"CORE STAGE2 SOURCE PREFLIGHT: GREEN windows={len(entries)} "
        f"fingerprint={report['source_fingerprint_sha256']} audit_sha256={frozen_audit['sha256']}"
    )
    return report


def _core_select_entries(source: Dict[str, Any], h1: int, h2: int) -> List[Dict[str, Any]]:
    selected = [e for e in source["entries"] if int(e["end_height"]) >= int(h1) and int(e["start_height"]) <= int(h2)]
    if not selected:
        raise RuntimeError(f"CORE source selection empty h1={h1} h2={h2}")
    return selected


def _core_adjust_window_end_for_bip30(h1: int, raw_h2: int) -> Tuple[int, Dict[str, Any]]:
    later_heights = sorted(int(x[0]) for x in CORE_BIP30_HEIGHT_PAIRS)
    candidates = [h for h in later_heights if int(h1) < h <= int(raw_h2)]
    adjusted = int(raw_h2) if not candidates else int(candidates[0]) - 1
    return adjusted, {
        "h1": int(h1), "raw_h2": int(raw_h2), "adjusted_h2": int(adjusted),
        "split_before_later_bip30_height": int(candidates[0]) if candidates else None,
        "known_later_heights": later_heights,
    }


def _core_ensure_schema(con: duckdb.DuckDBPyConnection) -> None:
    con.execute("""
        CREATE TABLE IF NOT EXISTS utxo(
            txid VARCHAR NOT NULL,
            vout BIGINT NOT NULL,
            address VARCHAR,
            value_sats BIGINT NOT NULL,
            value_btc DOUBLE,
            script_pubkey BLOB NOT NULL,
            script_pubkey_size BIGINT NOT NULL,
            is_coinbase BOOLEAN NOT NULL,
            created_ts TIMESTAMP NOT NULL,
            created_date DATE NOT NULL,
            created_height BIGINT NOT NULL,
            created_tx_index INTEGER NOT NULL,
            spent_ts TIMESTAMP,
            spent_date DATE,
            spent_txid VARCHAR,
            spent_vin BIGINT,
            spent_height BIGINT,
            spent_tx_index INTEGER,
            bip30_overwritten_height BIGINT,
            bip30_overwritten_tx_index INTEGER,
            PRIMARY KEY(txid, vout, created_height, created_tx_index)
        )
    """)
    con.execute("""
        CREATE TABLE IF NOT EXISTS utxo_active(
            txid VARCHAR NOT NULL,
            vout BIGINT NOT NULL,
            created_height BIGINT NOT NULL,
            created_tx_index INTEGER NOT NULL,
            PRIMARY KEY(txid, vout)
        )
    """)
    con.execute("""
        CREATE TABLE IF NOT EXISTS block_meta(
            block_number BIGINT PRIMARY KEY,
            block_hash VARCHAR NOT NULL,
            block_timestamp TIMESTAMP NOT NULL,
            block_date DATE NOT NULL,
            raw_partition_min DATE,
            raw_partition_max DATE
        )
    """)
    con.execute("""
        CREATE TABLE IF NOT EXISTS pipeline_meta(
            key VARCHAR PRIMARY KEY,
            value VARCHAR,
            updated_at TIMESTAMP
        )
    """)
    con.execute("""
        CREATE TABLE IF NOT EXISTS core_apply_ledger(
            h1 BIGINT PRIMARY KEY,
            h2 BIGINT NOT NULL,
            contract_version VARCHAR NOT NULL,
            source_global_sha256 VARCHAR NOT NULL,
            source_fingerprint_sha256 VARCHAR NOT NULL,
            source_window_fingerprint_sha256 VARCHAR NOT NULL,
            script_sha256 VARCHAR NOT NULL,
            created_rows BIGINT NOT NULL,
            spends_rows BIGINT NOT NULL,
            block_rows BIGINT NOT NULL,
            unspendable_outputs_skipped BIGINT NOT NULL,
            committed_at TIMESTAMP NOT NULL
        )
    """)


def _core_schema_signature(con: duckdb.DuckDBPyConnection) -> str:
    tables = {}
    for name in ("utxo", "utxo_active", "block_meta", "pipeline_meta", "core_apply_ledger"):
        rows = con.execute(f"PRAGMA table_info({_quote_sql_string(name)})").fetchall()
        tables[name] = [[str(x) for x in r] for r in rows]
    return _v11_canonical_json_hash({"contract": V40_CORE_SCHEMA_CONTRACT, "tables": tables})


def _core_set_meta(con: duckdb.DuckDBPyConnection, key: str, value: Any) -> None:
    con.execute(
        "INSERT INTO pipeline_meta(key,value,updated_at) VALUES (?, ?, now()) ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at",
        [str(key), str(value)],
    )


def _core_get_meta(con: duckdb.DuckDBPyConnection) -> Dict[str, str]:
    return {str(k): str(v) for k, v in con.execute("SELECT key,value FROM pipeline_meta").fetchall()}


def _core_initialize_meta(con: duckdb.DuckDBPyConnection, source: Dict[str, Any], target_end: int) -> None:
    values = {
        "source_backend": "CORE_STAGE2",
        "v40_core_pipeline_version": V40_CORE_PIPELINE_VERSION,
        "parent_v30_sha256": V40_PARENT_V30_SHA256,
        "script_sha256": V11_PROCESS_SCRIPT_SHA256 or "<disabled>",
        "python_executable": V11_PROCESS_PYTHON_EXECUTABLE,
        "python_version": V11_PROCESS_PYTHON_VERSION,
        "duckdb_version": V11_PROCESS_DUCKDB_VERSION,
        "schema_contract": V40_CORE_SCHEMA_CONTRACT,
        "stage2_global_manifest_sha256": source["global_manifest_sha256"],
        "stage2_windows_tsv_sha256": source["windows_tsv_sha256"],
        "stage2_source_fingerprint_sha256": source["source_fingerprint_sha256"],
        "stage2_parquet_sha_verification": "FULL" if bool(source.get("verify_parquet_sha")) else "SIDECAR_ONLY_LAB",
        "release_start_height": CORE_RELEASE_START_HEIGHT,
        "release_end_height": CORE_RELEASE_END_HEIGHT,
        "release_end_hash": CORE_RELEASE_END_HASH,
        "target_end_height": int(target_end),
        "final_muhash_expected": CORE_FINAL_MUHASH,
        "muhash_implementation_status": "PENDING_SEPARATE_EXACT_AUDITOR",
        "bip30_lifecycle_semantics": "EXACT_HISTORICAL_OVERWRITE_PRESERVED_SEPARATELY_FROM_SPEND",
        "address_materialization": "NOT_AVAILABLE_CORE_STAGE2_V1_SCRIPT_PUBKEY_IS_AUTHORITATIVE",
        "value_authority": "value_sats_BIGINT",
    }
    for k, v in values.items():
        _core_set_meta(con, k, v)
    _core_set_meta(con, "schema_signature_sha256", _core_schema_signature(con))


def _core_validate_meta(con: duckdb.DuckDBPyConnection, source: Dict[str, Any], target_end: int) -> None:
    meta = _core_get_meta(con)
    expected = {
        "source_backend": "CORE_STAGE2",
        "v40_core_pipeline_version": V40_CORE_PIPELINE_VERSION,
        "parent_v30_sha256": V40_PARENT_V30_SHA256,
        "script_sha256": V11_PROCESS_SCRIPT_SHA256 or "<disabled>",
        "python_executable": V11_PROCESS_PYTHON_EXECUTABLE,
        "python_version": V11_PROCESS_PYTHON_VERSION,
        "duckdb_version": V11_PROCESS_DUCKDB_VERSION,
        "schema_contract": V40_CORE_SCHEMA_CONTRACT,
        "stage2_global_manifest_sha256": source["global_manifest_sha256"],
        "stage2_windows_tsv_sha256": source["windows_tsv_sha256"],
        "stage2_source_fingerprint_sha256": source["source_fingerprint_sha256"],
        "stage2_parquet_sha_verification": "FULL" if bool(source.get("verify_parquet_sha")) else "SIDECAR_ONLY_LAB",
        "release_start_height": str(CORE_RELEASE_START_HEIGHT),
        "release_end_height": str(CORE_RELEASE_END_HEIGHT),
        "release_end_hash": CORE_RELEASE_END_HASH,
        "target_end_height": str(int(target_end)),
        "bip30_lifecycle_semantics": "EXACT_HISTORICAL_OVERWRITE_PRESERVED_SEPARATELY_FROM_SPEND",
    }
    bad = {k: {"actual": meta.get(k), "expected": str(v)} for k, v in expected.items() if meta.get(k) != str(v)}
    sig = _core_schema_signature(con)
    if meta.get("schema_signature_sha256") != sig:
        bad["schema_signature_sha256"] = {"actual": meta.get("schema_signature_sha256"), "expected": sig}
    if bad:
        raise RuntimeError(f"CORE DB identity/schema/source contract mismatch: {bad}")


def _core_validate_db_prefix(con: duckdb.DuckDBPyConnection, *, expected_end: Optional[int] = None) -> Dict[str, Any]:
    row = con.execute("SELECT min(block_number), max(block_number), count(*), count(DISTINCT block_number) FROM block_meta").fetchone()
    mn, mx, rows, distinct = row
    rows_i = int(rows or 0)
    if rows_i == 0:
        actual_end = -1
        ok = mn is None and mx is None and int(distinct or 0) == 0
    else:
        actual_end = int(mx)
        ok = int(mn) == 0 and rows_i == actual_end + 1 and int(distinct or 0) == rows_i
    ledger = con.execute("SELECT h1,h2,contract_version,source_global_sha256,script_sha256 FROM core_apply_ledger ORDER BY h1").fetchall()
    next_h = 0
    for h1, h2, contract, source_sha, script_sha in ledger:
        if int(h1) != next_h or int(h2) < int(h1):
            ok = False
            break
        if str(contract) != V40_CORE_LEDGER_CONTRACT or str(source_sha) != CORE_RELEASE_GLOBAL_MANIFEST_SHA256 or str(script_sha) != str(V11_PROCESS_SCRIPT_SHA256 or "<disabled>"):
            ok = False
            break
        next_h = int(h2) + 1
    if ledger and next_h - 1 != actual_end:
        ok = False
    if not ledger and actual_end != -1:
        ok = False
    if expected_end is not None and actual_end != int(expected_end):
        ok = False
    report = {"status": "GREEN" if ok else "FAIL", "actual_end": actual_end, "block_rows": rows_i, "ledger_rows": len(ledger), "ledger_next_height": next_h}
    if not ok:
        raise RuntimeError(f"CORE DB contiguous-prefix/ledger proof failed: {report}")
    return report


def _core_validate_ledger_source_bindings(
    con: duckdb.DuckDBPyConnection,
    source: Dict[str, Any],
) -> Dict[str, Any]:
    """Bind every committed range to the exact frozen Stage2 window hashes.

    The DB prefix proves contiguous commit boundaries.  This second proof makes
    resume fail closed if a ledger row was edited or came from a different
    selection of Stage2 windows even when the terminal height still looks sane.
    """
    rows = con.execute(
        """
        SELECT h1,h2,source_global_sha256,source_fingerprint_sha256,
               source_window_fingerprint_sha256,script_sha256,contract_version
        FROM core_apply_ledger ORDER BY h1
        """
    ).fetchall()
    checked = 0
    for h1, h2, global_sha, source_fp, window_fp, script_sha, contract in rows:
        h1_i, h2_i = int(h1), int(h2)
        selected = _core_select_entries(source, h1_i, h2_i)
        expected_window_fp = _core_source_window_fingerprint(selected, h1_i, h2_i)
        bad = (
            str(global_sha) != str(source["global_manifest_sha256"])
            or str(source_fp) != str(source["source_fingerprint_sha256"])
            or str(window_fp) != expected_window_fp
            or str(script_sha) != str(V11_PROCESS_SCRIPT_SHA256 or "<disabled>")
            or str(contract) != V40_CORE_LEDGER_CONTRACT
        )
        if bad:
            raise RuntimeError(
                f"CORE ledger/source binding mismatch range={h1_i}-{h2_i} "
                f"stored_window_fp={window_fp} expected_window_fp={expected_window_fp}"
            )
        checked += 1
    return {"status": "GREEN", "ledger_rows_checked": checked}


def _core_source_window_fingerprint(selected: Sequence[Dict[str, Any]], h1: int, h2: int) -> str:
    return _v11_canonical_json_hash({
        "h1": int(h1), "h2": int(h2),
        "windows": [
            {k: e[k] for k in ("start_height", "end_height", "manifest_sha256", "blocks_sha256", "transactions_sha256", "inputs_sha256", "outputs_sha256")}
            for e in selected
        ],
    })


def _core_bind_selected_views(con: duckdb.DuckDBPyConnection, selected: Sequence[Dict[str, Any]]) -> None:
    roles = {
        "core_blocks_source": "blocks_path",
        "core_transactions_source": "transactions_path",
        "core_inputs_source": "inputs_path",
        "core_outputs_source": "outputs_path",
    }
    for view, key in roles.items():
        paths = [str(e[key]) for e in selected]
        con.execute(f"DROP VIEW IF EXISTS {view}")
        con.execute(f"CREATE TEMP VIEW {view} AS SELECT * FROM read_parquet({_quote_sql_list(paths)}, union_by_name=true)")


def _core_prepare_apply_window(con: duckdb.DuckDBPyConnection, h1: int, h2: int) -> Dict[str, int]:
    """Materialize one causal apply range from the frozen Stage2 tables.

    This is an adapter boundary, not a trust boundary: before any DB mutation we
    re-prove the cross-table cardinalities that matter to UTXO semantics.  A row
    disappearing because of a bad join must never be misclassified as an
    unspendable output or an absent spend.
    """
    for name in ("core_block_meta_ready", "core_created_window", "core_spends_window", "core_spend_targets"):
        con.execute(f"DROP TABLE IF EXISTS {name}")

    raw_block_rows = int(con.execute(
        "SELECT count(*) FROM core_blocks_source WHERE height BETWEEN ? AND ?",
        [int(h1), int(h2)],
    ).fetchone()[0] or 0)
    raw_tx_rows = int(con.execute(
        "SELECT count(*) FROM core_transactions_source WHERE height BETWEEN ? AND ?",
        [int(h1), int(h2)],
    ).fetchone()[0] or 0)
    raw_input_rows = int(con.execute(
        "SELECT count(*) FROM core_inputs_source WHERE height BETWEEN ? AND ?",
        [int(h1), int(h2)],
    ).fetchone()[0] or 0)
    raw_output_rows = int(con.execute(
        "SELECT count(*) FROM core_outputs_source WHERE height BETWEEN ? AND ?",
        [int(h1), int(h2)],
    ).fetchone()[0] or 0)

    expected_blocks = int(h2) - int(h1) + 1
    if raw_block_rows != expected_blocks:
        raise RuntimeError(
            f"CORE apply source missing/duplicate block rows h1={h1} h2={h2} "
            f"actual={raw_block_rows} expected={expected_blocks}"
        )

    bad_blocks = int(con.execute("""
        SELECT count(*) FROM core_blocks_source
        WHERE height BETWEEN ? AND ? AND (
          height IS NULL OR block_hash IS NULL
          OR NOT regexp_full_match(block_hash, '[0-9a-f]{64}', 'c')
          OR block_time IS NULL OR tx_count IS NULL OR tx_count<1
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    bad_transactions = int(con.execute("""
        SELECT count(*) FROM core_transactions_source
        WHERE height BETWEEN ? AND ? AND (
          height IS NULL OR tx_index IS NULL OR tx_index<0
          OR txid IS NULL OR NOT regexp_full_match(txid, '[0-9a-f]{64}', 'c')
          OR is_coinbase IS NULL OR vin_count IS NULL OR vin_count<1
          OR vout_count IS NULL OR vout_count<1
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    bad_inputs_raw = int(con.execute("""
        SELECT count(*) FROM core_inputs_source
        WHERE height BETWEEN ? AND ? AND (
          height IS NULL OR tx_index IS NULL OR tx_index<0
          OR txid IS NULL OR NOT regexp_full_match(txid, '[0-9a-f]{64}', 'c')
          OR vin_index IS NULL OR vin_index<0
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    bad_outputs_raw = int(con.execute("""
        SELECT count(*) FROM core_outputs_source
        WHERE height BETWEEN ? AND ? AND (
          height IS NULL OR tx_index IS NULL OR tx_index<0
          OR txid IS NULL OR NOT regexp_full_match(txid, '[0-9a-f]{64}', 'c')
          OR vout IS NULL OR vout<0 OR value_sats IS NULL OR value_sats<0 OR value_sats>?
          OR script_pubkey IS NULL OR script_pubkey_size IS NULL OR script_pubkey_size<0
          OR octet_length(script_pubkey)<>script_pubkey_size
        )
    """, [int(h1), int(h2), CORE_MAX_MONEY_SATS]).fetchone()[0] or 0)
    if bad_blocks or bad_transactions or bad_inputs_raw or bad_outputs_raw:
        raise RuntimeError(
            f"CORE raw Stage2 domain guard failed h1={h1} h2={h2} "
            f"bad_blocks={bad_blocks} bad_transactions={bad_transactions} "
            f"bad_inputs={bad_inputs_raw} bad_outputs={bad_outputs_raw}"
        )

    tx_declared, vin_declared, vout_declared = con.execute("""
        SELECT coalesce(sum(tx_count),0),
               (SELECT coalesce(sum(vin_count),0) FROM core_transactions_source WHERE height BETWEEN ? AND ?),
               (SELECT coalesce(sum(vout_count),0) FROM core_transactions_source WHERE height BETWEEN ? AND ?)
        FROM core_blocks_source WHERE height BETWEEN ? AND ?
    """, [int(h1), int(h2), int(h1), int(h2), int(h1), int(h2)]).fetchone()
    if int(tx_declared or 0) != raw_tx_rows or int(vin_declared or 0) != raw_input_rows or int(vout_declared or 0) != raw_output_rows:
        raise RuntimeError(
            f"CORE Stage2 cross-table declared-count mismatch h1={h1} h2={h2} "
            f"blocks_tx={int(tx_declared or 0)} tx_rows={raw_tx_rows} "
            f"tx_vin={int(vin_declared or 0)} input_rows={raw_input_rows} "
            f"tx_vout={int(vout_declared or 0)} output_rows={raw_output_rows}"
        )

    tx_block_join_rows = int(con.execute("""
        SELECT count(*)
        FROM core_transactions_source t
        JOIN core_blocks_source b ON b.height=t.height
        WHERE t.height BETWEEN ? AND ?
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    output_join_rows = int(con.execute("""
        SELECT count(*)
        FROM core_outputs_source o
        JOIN core_transactions_source t
          ON t.height=o.height AND t.tx_index=o.tx_index AND t.txid=o.txid
        JOIN core_blocks_source b ON b.height=o.height
        WHERE o.height BETWEEN ? AND ?
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    input_join_rows = int(con.execute("""
        SELECT count(*)
        FROM core_inputs_source i
        JOIN core_transactions_source t
          ON t.height=i.height AND t.tx_index=i.tx_index AND t.txid=i.txid
        JOIN core_blocks_source b ON b.height=i.height
        WHERE i.height BETWEEN ? AND ?
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    if tx_block_join_rows != raw_tx_rows or output_join_rows != raw_output_rows or input_join_rows != raw_input_rows:
        raise RuntimeError(
            f"CORE Stage2 relational join loss/duplication h1={h1} h2={h2} "
            f"tx={raw_tx_rows}/{tx_block_join_rows} outputs={raw_output_rows}/{output_join_rows} "
            f"inputs={raw_input_rows}/{input_join_rows}"
        )

    bad_coinbase_blocks = int(con.execute("""
        SELECT count(*) FROM (
          SELECT b.height,
                 count(*) FILTER (WHERE t.is_coinbase) AS coinbases,
                 count(*) FILTER (WHERE t.is_coinbase AND t.tx_index=0) AS coinbase_at_zero
          FROM core_blocks_source b
          JOIN core_transactions_source t ON t.height=b.height
          WHERE b.height BETWEEN ? AND ?
          GROUP BY b.height
          HAVING coinbases<>1 OR coinbase_at_zero<>1
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    if bad_coinbase_blocks:
        raise RuntimeError(
            f"CORE Stage2 coinbase positional invariant failed h1={h1} h2={h2} blocks={bad_coinbase_blocks}"
        )

    bad_tx_index_density = int(con.execute("""
        SELECT count(*) FROM (
          SELECT b.height,b.tx_count,count(t.tx_index) AS n,
                 count(DISTINCT t.tx_index) AS nd,
                 min(t.tx_index) AS mn,max(t.tx_index) AS mx
          FROM core_blocks_source b
          JOIN core_transactions_source t ON t.height=b.height
          WHERE b.height BETWEEN ? AND ?
          GROUP BY b.height,b.tx_count
          HAVING count(t.tx_index)<>b.tx_count
              OR count(DISTINCT t.tx_index)<>b.tx_count
              OR min(t.tx_index)<>0 OR max(t.tx_index)<>b.tx_count-1
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    bad_vin_density = int(con.execute("""
        SELECT count(*) FROM (
          SELECT t.height,t.tx_index,t.txid,t.vin_count,
                 count(i.vin_index) AS n,count(DISTINCT i.vin_index) AS nd,
                 min(i.vin_index) AS mn,max(i.vin_index) AS mx
          FROM core_transactions_source t
          JOIN core_inputs_source i
            ON i.height=t.height AND i.tx_index=t.tx_index AND i.txid=t.txid
          WHERE t.height BETWEEN ? AND ?
          GROUP BY t.height,t.tx_index,t.txid,t.vin_count
          HAVING count(i.vin_index)<>t.vin_count
              OR count(DISTINCT i.vin_index)<>t.vin_count
              OR min(i.vin_index)<>0 OR max(i.vin_index)<>t.vin_count-1
        )
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    bad_vout_density = int(con.execute("""
        SELECT count(*) FROM (
          SELECT t.height,t.tx_index,t.txid,t.vout_count,
                 count(o.vout) AS n,count(DISTINCT o.vout) AS nd,
                 min(o.vout) AS mn,max(o.vout) AS mx,
                 sum(o.value_sats) AS total_sats
          FROM core_transactions_source t
          JOIN core_outputs_source o
            ON o.height=t.height AND o.tx_index=t.tx_index AND o.txid=t.txid
          WHERE t.height BETWEEN ? AND ?
          GROUP BY t.height,t.tx_index,t.txid,t.vout_count
          HAVING count(o.vout)<>t.vout_count
              OR count(DISTINCT o.vout)<>t.vout_count
              OR min(o.vout)<>0 OR max(o.vout)<>t.vout_count-1 OR sum(o.value_sats)>?
        )
    """, [int(h1), int(h2), CORE_MAX_MONEY_SATS]).fetchone()[0] or 0)
    if bad_tx_index_density or bad_vin_density or bad_vout_density:
        raise RuntimeError(
            f"CORE Stage2 positional-density/value invariant failed h1={h1} h2={h2} "
            f"bad_tx_index_blocks={bad_tx_index_density} bad_vin_txs={bad_vin_density} "
            f"bad_vout_txs={bad_vout_density}"
        )

    con.execute("""
        CREATE TEMP TABLE core_block_meta_ready AS
        SELECT height::BIGINT AS block_number, block_hash::VARCHAR AS block_hash,
               CAST(to_timestamp(block_time) AS TIMESTAMP) AS block_timestamp,
               CAST(to_timestamp(block_time) AS DATE) AS block_date
        FROM core_blocks_source WHERE height BETWEEN ? AND ? ORDER BY height
    """, [int(h1), int(h2)])

    con.execute("""
        CREATE TEMP TABLE core_created_window AS
        SELECT o.txid::VARCHAR AS txid, o.vout::BIGINT AS vout,
               o.value_sats::BIGINT AS value_sats, o.script_pubkey::BLOB AS script_pubkey,
               o.script_pubkey_size::BIGINT AS script_pubkey_size,
               t.is_coinbase::BOOLEAN AS is_coinbase,
               o.height::BIGINT AS created_height, o.tx_index::INTEGER AS created_tx_index,
               CAST(to_timestamp(b.block_time) AS TIMESTAMP) AS created_ts,
               CAST(to_timestamp(b.block_time) AS DATE) AS created_date
        FROM core_outputs_source o
        JOIN core_transactions_source t
          ON t.height=o.height AND t.tx_index=o.tx_index AND t.txid=o.txid
        JOIN core_blocks_source b ON b.height=o.height
        WHERE o.height BETWEEN ? AND ?
          AND o.height <> 0
          AND NOT (
              o.script_pubkey_size > ? OR
              CASE WHEN o.script_pubkey_size > 0 THEN substr(hex(o.script_pubkey), 1, 2) = '6A' ELSE FALSE END
          )
        ORDER BY o.height, o.tx_index, o.vout
    """, [int(h1), int(h2), CORE_MAX_SCRIPT_SIZE])

    con.execute("""
        CREATE TEMP TABLE core_spends_window AS
        SELECT i.prev_txid::VARCHAR AS prev_txid, i.prev_vout::BIGINT AS prev_vout,
               i.txid::VARCHAR AS spent_txid, i.vin_index::BIGINT AS spent_vin,
               i.height::BIGINT AS spent_height, i.tx_index::INTEGER AS spent_tx_index,
               CAST(to_timestamp(b.block_time) AS TIMESTAMP) AS spent_ts,
               CAST(to_timestamp(b.block_time) AS DATE) AS spent_date
        FROM core_inputs_source i
        JOIN core_transactions_source t
          ON t.height=i.height AND t.tx_index=i.tx_index AND t.txid=i.txid
        JOIN core_blocks_source b ON b.height=i.height
        WHERE i.height BETWEEN ? AND ? AND NOT t.is_coinbase
        ORDER BY i.height, i.tx_index, i.vin_index
    """, [int(h1), int(h2)])

    block_rows = int(con.execute("SELECT count(*) FROM core_block_meta_ready").fetchone()[0] or 0)
    br = con.execute(
        "SELECT min(block_number),max(block_number),count(DISTINCT block_number),count(DISTINCT block_hash) FROM core_block_meta_ready"
    ).fetchone()
    if block_rows != expected_blocks or tuple(int(x) for x in br) != (int(h1), int(h2), block_rows, block_rows):
        raise RuntimeError(f"CORE apply block metadata identity failure h1={h1} h2={h2} rows={block_rows} summary={br}")

    coinbase_input_rows = int(con.execute("""
        SELECT count(*)
        FROM core_inputs_source i
        JOIN core_transactions_source t
          ON t.height=i.height AND t.tx_index=i.tx_index AND t.txid=i.txid
        WHERE i.height BETWEEN ? AND ? AND t.is_coinbase
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    if coinbase_input_rows != block_rows:
        raise RuntimeError(
            f"CORE coinbase input cardinality failure h1={h1} h2={h2} "
            f"coinbase_inputs={coinbase_input_rows} blocks={block_rows}"
        )

    expected_spends = raw_input_rows - coinbase_input_rows
    spend_rows = int(con.execute("SELECT count(*) FROM core_spends_window").fetchone()[0] or 0)
    if spend_rows != expected_spends:
        raise RuntimeError(
            f"CORE spend materialization cardinality failure h1={h1} h2={h2} "
            f"spends={spend_rows} expected={expected_spends}"
        )

    genesis_outputs = int(con.execute("""
        SELECT count(*) FROM core_outputs_source
        WHERE height BETWEEN ? AND ? AND height=0
    """, [int(h1), int(h2)]).fetchone()[0] or 0)
    if int(h1) <= 0 <= int(h2) and genesis_outputs != 1:
        raise RuntimeError(f"CORE genesis output cardinality failure rows={genesis_outputs}")
    unspendable_outputs = int(con.execute("""
        SELECT count(*) FROM core_outputs_source
        WHERE height BETWEEN ? AND ? AND height<>0 AND (
          script_pubkey_size>? OR
          CASE WHEN script_pubkey_size>0 THEN substr(hex(script_pubkey),1,2)='6A' ELSE FALSE END
        )
    """, [int(h1), int(h2), CORE_MAX_SCRIPT_SIZE]).fetchone()[0] or 0)
    eligible_outputs = int(con.execute("SELECT count(*) FROM core_created_window").fetchone()[0] or 0)
    expected_eligible = raw_output_rows - genesis_outputs - unspendable_outputs
    if eligible_outputs != expected_eligible:
        raise RuntimeError(
            f"CORE eligible-output materialization mismatch h1={h1} h2={h2} "
            f"raw={raw_output_rows} genesis={genesis_outputs} unspendable={unspendable_outputs} "
            f"eligible={eligible_outputs} expected={expected_eligible}"
        )

    bad_created = int(con.execute("""
        SELECT count(*) FROM core_created_window
        WHERE txid IS NULL OR NOT regexp_full_match(txid, '[0-9a-f]{64}', 'c')
           OR vout<0 OR value_sats<0 OR value_sats>? OR script_pubkey IS NULL
           OR script_pubkey_size<0 OR octet_length(script_pubkey)<>script_pubkey_size
           OR created_height IS NULL OR created_tx_index IS NULL OR created_tx_index<0
    """, [CORE_MAX_MONEY_SATS]).fetchone()[0] or 0)
    bad_spends = int(con.execute("""
        SELECT count(*) FROM core_spends_window
        WHERE prev_txid IS NULL OR NOT regexp_full_match(prev_txid, '[0-9a-f]{64}', 'c')
           OR prev_vout<0 OR spent_txid IS NULL OR NOT regexp_full_match(spent_txid, '[0-9a-f]{64}', 'c')
           OR spent_vin<0 OR spent_height IS NULL OR spent_tx_index IS NULL OR spent_tx_index<0
    """).fetchone()[0] or 0)
    created_dup_pos = int(con.execute("""
        SELECT count(*) FROM (
          SELECT created_height,created_tx_index,vout,count(*) c
          FROM core_created_window GROUP BY 1,2,3 HAVING c<>1
        )
    """).fetchone()[0] or 0)
    created_dup_outpoint = int(con.execute("""
        SELECT count(*) FROM (
          SELECT txid,vout,count(*) c
          FROM core_created_window GROUP BY 1,2 HAVING c>1
        )
    """).fetchone()[0] or 0)
    spend_dup_pos = int(con.execute("""
        SELECT count(*) FROM (
          SELECT spent_height,spent_tx_index,spent_vin,count(*) c
          FROM core_spends_window GROUP BY 1,2,3 HAVING c<>1
        )
    """).fetchone()[0] or 0)
    spend_dup_prevout = int(con.execute("""
        SELECT count(*) FROM (
          SELECT prev_txid,prev_vout,count(*) c
          FROM core_spends_window GROUP BY 1,2 HAVING c>1
        )
    """).fetchone()[0] or 0)
    if bad_created or bad_spends or created_dup_pos or created_dup_outpoint or spend_dup_pos or spend_dup_prevout:
        raise RuntimeError(
            f"CORE apply source semantic guard failed h1={h1} h2={h2} "
            f"bad_created={bad_created} bad_spends={bad_spends} created_dup_pos={created_dup_pos} "
            f"created_dup_outpoint={created_dup_outpoint} spend_dup_pos={spend_dup_pos} "
            f"duplicate_prevout_spends={spend_dup_prevout}"
        )

    return {
        "block_rows": block_rows,
        "transactions_rows": raw_tx_rows,
        "raw_inputs": raw_input_rows,
        "raw_outputs": raw_output_rows,
        "created_rows": eligible_outputs,
        "spends_rows": spend_rows,
        "genesis_outputs_skipped": genesis_outputs,
        "unspendable_outputs_skipped": unspendable_outputs,
    }

def _core_apply_block_window(con: duckdb.DuckDBPyConnection, *, h1: int, h2: int, selected: Sequence[Dict[str, Any]], source_fingerprint_sha256: str) -> Dict[str, Any]:
    t0 = _tic()
    _core_bind_selected_views(con, selected)
    prep = _core_prepare_apply_window(con, h1, h2)
    window_fp = _core_source_window_fingerprint(selected, h1, h2)
    try:
        con.execute("BEGIN TRANSACTION")
        existing_exact = int(con.execute("""
            SELECT count(*) FROM core_created_window s JOIN utxo u
              ON u.txid=s.txid AND u.vout=s.vout
             AND u.created_height=s.created_height AND u.created_tx_index=s.created_tx_index
        """).fetchone()[0] or 0)
        if existing_exact:
            raise RuntimeError(f"CORE exact creation generation already exists h1={h1} h2={h2} rows={existing_exact}")

        # Historical outpoint reuse is legal in this frozen mainnet range only
        # for the two pre-BIP30 duplicate coinbase transactions.  Bitcoin Core
        # overwrites the *active coin* at the repeated outpoint; that is not a
        # normal spend.  Preserve both generations in history, but record this
        # lifecycle transition separately from spent_* so analytical spend
        # semantics are not falsified.
        history_conflicts = int(con.execute("""
            SELECT count(*)
            FROM core_created_window s
            JOIN utxo u ON u.txid=s.txid AND u.vout=s.vout
        """).fetchone()[0] or 0)
        allowed_history_conflicts = 0
        bip30_overwritten_active = 0
        for later, earlier in CORE_BIP30_HEIGHT_PAIRS:
            if not (int(h1) <= int(later) <= int(h2)):
                continue

            current_rows = int(con.execute("""
                SELECT count(*)
                FROM core_created_window
                WHERE created_height=? AND created_tx_index=0 AND is_coinbase
            """, [int(later)]).fetchone()[0] or 0)
            if current_rows <= 0:
                raise RuntimeError(
                    f"CORE BIP30 replacement has no eligible coinbase outputs pair={later}:{earlier}"
                )

            # Exact prior generation and payload equality are mandatory.  The
            # repeated transaction has the same txid/output serialization, but
            # prove it from the frozen Stage2 payload before mutating state.
            matched_prior = int(con.execute("""
                SELECT count(*)
                FROM core_created_window s
                JOIN utxo u ON u.txid=s.txid AND u.vout=s.vout
                WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                  AND u.created_height=? AND u.created_tx_index=0 AND u.is_coinbase
                  AND u.value_sats=s.value_sats
                  AND u.script_pubkey_size=s.script_pubkey_size
                  AND u.script_pubkey=s.script_pubkey
            """, [int(later), int(earlier)]).fetchone()[0] or 0)
            if matched_prior != current_rows:
                raise RuntimeError(
                    f"CORE exact BIP30 prior-generation/payload proof failed pair={later}:{earlier} "
                    f"current_outputs={current_rows} matched_prior={matched_prior}"
                )
            allowed_history_conflicts += current_rows

            # If the earlier generation is still active, Core replaces it when
            # the later duplicate coinbase is connected.  Mark that old history
            # row as BIP30-overwritten and remove only its exact active-map row.
            # If it was already spent, it is not active and remains a normal
            # spent history row; the later duplicate still recreates the outpoint.
            # Before mutating the old generation, prove that every exact
            # prior output is in one and only one legitimate lifecycle state:
            # either still open+active, or already spent strictly before the
            # repeated coinbase block.  Missing active-map rows, pre-existing
            # overwrite markers, spent/overwrite collisions, or any other
            # ambiguous state are fatal.  This makes BIP30 recovery fail closed
            # instead of "repairing" a corrupt history table during overwrite.
            lifecycle = con.execute("""
                SELECT
                  count(*) AS prior_rows,
                  count(*) FILTER (
                    WHERE u.spent_height IS NULL
                      AND u.bip30_overwritten_height IS NULL
                  ) AS open_prior,
                  count(*) FILTER (
                    WHERE u.spent_height IS NOT NULL
                      AND u.spent_height < ?
                      AND u.bip30_overwritten_height IS NULL
                  ) AS spent_before_prior,
                  count(*) FILTER (
                    WHERE u.bip30_overwritten_height IS NOT NULL
                  ) AS already_overwritten_prior,
                  count(*) FILTER (
                    WHERE u.spent_height IS NOT NULL
                      AND u.bip30_overwritten_height IS NOT NULL
                  ) AS collision_prior
                FROM core_created_window s
                JOIN utxo u ON u.txid=s.txid AND u.vout=s.vout
                WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                  AND u.created_height=? AND u.created_tx_index=0
            """, [int(later), int(later), int(earlier)]).fetchone()
            prior_rows, open_prior, spent_prior, already_overwritten_prior, collision_prior = (
                int(x or 0) for x in lifecycle
            )
            if prior_rows != current_rows:
                raise RuntimeError(
                    f"CORE BIP30 prior lifecycle cardinality mismatch pair={later}:{earlier} "
                    f"prior_rows={prior_rows} current_outputs={current_rows}"
                )
            if already_overwritten_prior or collision_prior:
                raise RuntimeError(
                    f"CORE BIP30 prior generation has invalid pre-existing lifecycle markers "
                    f"pair={later}:{earlier} overwritten={already_overwritten_prior} "
                    f"collision={collision_prior}"
                )
            if open_prior + spent_prior != current_rows:
                raise RuntimeError(
                    f"CORE BIP30 prior lifecycle is incomplete/ambiguous pair={later}:{earlier} "
                    f"open={open_prior} spent_before={spent_prior} total={current_rows}"
                )

            active_prior = int(con.execute("""
                SELECT count(*)
                FROM core_created_window s
                JOIN utxo_active a ON a.txid=s.txid AND a.vout=s.vout
                JOIN utxo u ON u.txid=a.txid AND u.vout=a.vout
                  AND u.created_height=a.created_height AND u.created_tx_index=a.created_tx_index
                WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                  AND u.created_height=? AND u.created_tx_index=0
                  AND u.spent_height IS NULL AND u.bip30_overwritten_height IS NULL
            """, [int(later), int(earlier)]).fetchone()[0] or 0)
            if active_prior != open_prior:
                raise RuntimeError(
                    f"CORE BIP30 open-history/active-map mismatch before overwrite pair={later}:{earlier} "
                    f"open_history={open_prior} active_map={active_prior}"
                )

            if active_prior:
                con.execute("""
                    UPDATE utxo u SET
                      bip30_overwritten_height=?,
                      bip30_overwritten_tx_index=0
                    FROM core_created_window s
                    WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                      AND u.txid=s.txid AND u.vout=s.vout
                      AND u.created_height=? AND u.created_tx_index=0
                      AND u.spent_height IS NULL AND u.bip30_overwritten_height IS NULL
                      AND EXISTS (
                        SELECT 1 FROM utxo_active a
                        WHERE a.txid=u.txid AND a.vout=u.vout
                          AND a.created_height=u.created_height
                          AND a.created_tx_index=u.created_tx_index
                      )
                """, [int(later), int(later), int(earlier)])
                con.execute("""
                    DELETE FROM utxo_active
                    WHERE EXISTS (
                      SELECT 1
                      FROM core_created_window s
                      WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                        AND utxo_active.txid=s.txid AND utxo_active.vout=s.vout
                        AND utxo_active.created_height=? AND utxo_active.created_tx_index=0
                    )
                """, [int(later), int(earlier)])

            # Postcondition: every previously-active exact prior generation was
            # retired as overwrite, and no old generation remains active.
            stale_prior_active = int(con.execute("""
                SELECT count(*)
                FROM core_created_window s
                JOIN utxo_active a ON a.txid=s.txid AND a.vout=s.vout
                WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                  AND a.created_height=? AND a.created_tx_index=0
            """, [int(later), int(earlier)]).fetchone()[0] or 0)
            if stale_prior_active:
                raise RuntimeError(
                    f"CORE BIP30 prior active-map retirement failed pair={later}:{earlier} "
                    f"rows={stale_prior_active}"
                )

            marked_overwrite = int(con.execute("""
                SELECT count(*)
                FROM core_created_window s
                JOIN utxo u ON u.txid=s.txid AND u.vout=s.vout
                WHERE s.created_height=? AND s.created_tx_index=0 AND s.is_coinbase
                  AND u.created_height=? AND u.created_tx_index=0
                  AND u.bip30_overwritten_height=? AND u.bip30_overwritten_tx_index=0
            """, [int(later), int(earlier), int(later)]).fetchone()[0] or 0)
            if marked_overwrite != active_prior:
                raise RuntimeError(
                    f"CORE BIP30 overwrite marker cardinality mismatch pair={later}:{earlier} "
                    f"active_prior={active_prior} marked={marked_overwrite}"
                )
            bip30_overwritten_active += active_prior

        if history_conflicts != allowed_history_conflicts:
            sample = con.execute("""
                SELECT s.created_height,s.created_tx_index,s.txid,s.vout,
                       u.created_height AS prior_created_height,u.created_tx_index AS prior_created_tx_index,
                       u.spent_height AS prior_spent_height,
                       u.bip30_overwritten_height AS prior_overwritten_height
                FROM core_created_window s
                JOIN utxo u ON u.txid=s.txid AND u.vout=s.vout
                ORDER BY s.created_height,s.created_tx_index,s.vout,u.created_height
                LIMIT 20
            """).fetchall()
            raise RuntimeError(
                f"CORE unexpected historical outpoint reuse h1={h1} h2={h2} "
                f"conflicts={history_conflicts} allowed_bip30={allowed_history_conflicts} sample={sample}"
            )

        # After exact BIP30 retirement above, every newly-created outpoint must
        # be absent from the current active map.
        active_conflicts = int(con.execute("""
            SELECT count(*)
            FROM core_created_window s
            JOIN utxo_active a ON a.txid=s.txid AND a.vout=s.vout
        """).fetchone()[0] or 0)
        if active_conflicts:
            sample = con.execute("""
                SELECT s.created_height,s.created_tx_index,s.txid,s.vout,
                       a.created_height AS open_created_height,a.created_tx_index AS open_created_tx_index
                FROM core_created_window s
                JOIN utxo_active a ON a.txid=s.txid AND a.vout=s.vout
                ORDER BY s.created_height,s.created_tx_index,s.vout LIMIT 20
            """).fetchall()
            raise RuntimeError(
                f"CORE attempted unexpected overwrite of an active outpoint h1={h1} h2={h2} "
                f"rows={active_conflicts} sample={sample}"
            )

        con.execute("""
            INSERT INTO utxo(
                txid,vout,address,value_sats,value_btc,script_pubkey,script_pubkey_size,is_coinbase,
                created_ts,created_date,created_height,created_tx_index,
                spent_ts,spent_date,spent_txid,spent_vin,spent_height,spent_tx_index,
                bip30_overwritten_height,bip30_overwritten_tx_index
            )
            SELECT txid,vout,NULL,value_sats,CAST(value_sats AS DOUBLE)/100000000.0,script_pubkey,script_pubkey_size,is_coinbase,
                   created_ts,created_date,created_height,created_tx_index,
                   NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
            FROM core_created_window
        """)
        con.execute("""
            INSERT INTO utxo_active(txid,vout,created_height,created_tx_index)
            SELECT txid,vout,created_height,created_tx_index FROM core_created_window
        """)

        con.execute("""
            CREATE TEMP TABLE core_spend_targets AS
            SELECT s.prev_txid,s.prev_vout,s.spent_txid,s.spent_vin,s.spent_ts,s.spent_date,s.spent_height,s.spent_tx_index,
                   u.created_height AS target_created_height,u.created_tx_index AS target_created_tx_index
            FROM core_spends_window s
            JOIN utxo_active a ON a.txid=s.prev_txid AND a.vout=s.prev_vout
            JOIN utxo u ON u.txid=a.txid AND u.vout=a.vout
             AND u.created_height=a.created_height AND u.created_tx_index=a.created_tx_index
             AND u.spent_height IS NULL
             AND u.bip30_overwritten_height IS NULL
             AND (u.created_height < s.spent_height OR (u.created_height=s.spent_height AND u.created_tx_index < s.spent_tx_index))
        """)
        target_rows = int(con.execute("SELECT count(*) FROM core_spend_targets").fetchone()[0] or 0)
        spend_rows = int(prep["spends_rows"])
        cardinality_bad = int(con.execute("""
            SELECT count(*) FROM (
              SELECT s.spent_height,s.spent_tx_index,s.spent_vin,count(t.target_created_height) c
              FROM core_spends_window s LEFT JOIN core_spend_targets t
                ON t.spent_height=s.spent_height AND t.spent_tx_index=s.spent_tx_index AND t.spent_vin=s.spent_vin
              GROUP BY 1,2,3 HAVING c<>1
            )
        """).fetchone()[0] or 0)
        if target_rows != spend_rows or cardinality_bad:
            orphan_sample = con.execute("""
                SELECT s.prev_txid,s.prev_vout,s.spent_txid,s.spent_vin,s.spent_height,s.spent_tx_index
                FROM core_spends_window s LEFT JOIN core_spend_targets t
                  ON t.spent_height=s.spent_height AND t.spent_tx_index=s.spent_tx_index AND t.spent_vin=s.spent_vin
                GROUP BY 1,2,3,4,5,6 HAVING count(t.target_created_height)<>1 LIMIT 20
            """).fetchall()
            raise RuntimeError(f"CORE spend target cardinality failure h1={h1} h2={h2} spends={spend_rows} targets={target_rows} bad={cardinality_bad} sample={orphan_sample}")

        con.execute("""
            UPDATE utxo u SET
              spent_ts=t.spent_ts, spent_date=t.spent_date, spent_txid=t.spent_txid, spent_vin=t.spent_vin,
              spent_height=t.spent_height, spent_tx_index=t.spent_tx_index
            FROM core_spend_targets t
            WHERE u.txid=t.prev_txid AND u.vout=t.prev_vout
              AND u.created_height=t.target_created_height AND u.created_tx_index=t.target_created_tx_index
              AND u.spent_height IS NULL AND u.bip30_overwritten_height IS NULL
        """)
        con.execute("""
            DELETE FROM utxo_active
            WHERE EXISTS (
              SELECT 1
              FROM core_spend_targets t
              WHERE utxo_active.txid=t.prev_txid AND utxo_active.vout=t.prev_vout
                AND utxo_active.created_height=t.target_created_height AND utxo_active.created_tx_index=t.target_created_tx_index
            )
        """)
        mismatch = int(con.execute("""
            SELECT count(*) FROM core_spend_targets t JOIN utxo u
              ON u.txid=t.prev_txid AND u.vout=t.prev_vout
             AND u.created_height=t.target_created_height AND u.created_tx_index=t.target_created_tx_index
            WHERE u.spent_height IS DISTINCT FROM t.spent_height OR u.spent_tx_index IS DISTINCT FROM t.spent_tx_index
               OR u.spent_txid IS DISTINCT FROM t.spent_txid OR u.spent_vin IS DISTINCT FROM t.spent_vin
        """).fetchone()[0] or 0)
        if mismatch:
            raise RuntimeError(f"CORE spend post-apply verification mismatch h1={h1} h2={h2} rows={mismatch}")

        spent_still_active = int(con.execute("""
            SELECT count(*)
            FROM core_spend_targets t
            JOIN utxo_active a
              ON a.txid=t.prev_txid AND a.vout=t.prev_vout
             AND a.created_height=t.target_created_height AND a.created_tx_index=t.target_created_tx_index
        """).fetchone()[0] or 0)
        if spent_still_active:
            raise RuntimeError(
                f"CORE active-map delete postcondition failed h1={h1} h2={h2} "
                f"spent_targets_still_active={spent_still_active}"
            )

        active_creation_mismatch = int(con.execute("""
            SELECT count(*) FROM core_created_window s
            JOIN utxo_active a ON a.txid=s.txid AND a.vout=s.vout
            JOIN utxo u ON u.txid=a.txid AND u.vout=a.vout
              AND u.created_height=a.created_height AND u.created_tx_index=a.created_tx_index
            WHERE u.spent_height IS NOT NULL OR u.bip30_overwritten_height IS NOT NULL
        """).fetchone()[0] or 0)
        if active_creation_mismatch:
            raise RuntimeError(f"CORE active-map points at spent creation after h1={h1} h2={h2}: {active_creation_mismatch}")

        con.execute("""
            INSERT INTO block_meta(block_number,block_hash,block_timestamp,block_date,raw_partition_min,raw_partition_max)
            SELECT block_number,block_hash,block_timestamp,block_date,block_date,block_date FROM core_block_meta_ready ORDER BY block_number
        """)
        con.execute("""
            INSERT INTO core_apply_ledger(
              h1,h2,contract_version,source_global_sha256,source_fingerprint_sha256,source_window_fingerprint_sha256,
              script_sha256,created_rows,spends_rows,block_rows,unspendable_outputs_skipped,committed_at
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,now())
        """, [
            int(h1), int(h2), V40_CORE_LEDGER_CONTRACT, CORE_RELEASE_GLOBAL_MANIFEST_SHA256,
            str(source_fingerprint_sha256), window_fp, str(V11_PROCESS_SCRIPT_SHA256 or "<disabled>"),
            int(prep["created_rows"]), int(prep["spends_rows"]), int(prep["block_rows"]), int(prep["unspendable_outputs_skipped"]),
        ])
        con.execute("COMMIT")
    except BaseException:
        try:
            con.execute("ROLLBACK")
        except BaseException:
            pass
        raise
    finally:
        for name in ("core_spend_targets", "core_block_meta_ready", "core_created_window", "core_spends_window"):
            try:
                con.execute(f"DROP TABLE IF EXISTS {name}")
            except BaseException:
                pass
        for name in ("core_blocks_source", "core_transactions_source", "core_inputs_source", "core_outputs_source"):
            try:
                con.execute(f"DROP VIEW IF EXISTS {name}")
            except BaseException:
                pass
    report = dict(prep)
    report.update({
        "h1": int(h1), "h2": int(h2),
        "source_window_fingerprint_sha256": window_fp,
        "bip30_overwritten_active_rows": int(bip30_overwritten_active),
        "elapsed_sec": _toc(t0),
    })
    return report


def _core_worker_job_hash(payload: Dict[str, Any]) -> str:
    return _v11_canonical_json_hash(payload, exclude=("job_sha256",))


def _core_worker_result_hash(payload: Dict[str, Any]) -> str:
    return _v11_canonical_json_hash(payload, exclude=("result_sha256",))


def _core_create_worker_job(*, db_path: Path, h1: int, h2: int, source: Dict[str, Any], selected: Sequence[Dict[str, Any]], checkpoint_requested: bool) -> Tuple[Path, Path, Path, Dict[str, Any]]:
    root = _core_worker_root(True)
    job_dir = root / f"job_{h1:06d}_{h2:06d}_{uuid.uuid4().hex}"
    job_dir.mkdir(mode=0o700)
    job_path = job_dir / "job.json"
    result_path = job_dir / "result.json"
    db_id = _core_file_identity(db_path)
    bindings: List[Dict[str, Any]] = []
    for e in selected:
        for key in ("blocks_path", "transactions_path", "inputs_path", "outputs_path", "manifest_path"):
            bindings.append(_core_file_identity(Path(str(e[key]))))
    payload: Dict[str, Any] = {
        "contract_version": V40_CORE_APPLY_WORKER_CONTRACT,
        "job_id": uuid.uuid4().hex,
        "parent_pid": int(os.getpid()),
        "script_path": V11_PROCESS_SCRIPT_PATH,
        "script_sha256": V11_PROCESS_SCRIPT_SHA256,
        "python_executable": V11_PROCESS_PYTHON_EXECUTABLE,
        "python_version": V11_PROCESS_PYTHON_VERSION,
        "duckdb_version": V11_PROCESS_DUCKDB_VERSION,
        "parent_v30_sha256": V40_PARENT_V30_SHA256,
        "db_path": str(db_path.resolve(strict=True)),
        "db_identity": db_id,
        "h1": int(h1), "h2": int(h2),
        "source_global_manifest_sha256": source["global_manifest_sha256"],
        "source_windows_tsv_sha256": source["windows_tsv_sha256"],
        "source_fingerprint_sha256": source["source_fingerprint_sha256"],
        "source_verify_parquet_sha": bool(source.get("verify_parquet_sha")),
        "target_end_height": int(_env_int("UTXO_CORE_END_HEIGHT", CORE_RELEASE_END_HEIGHT)),
        "selected_entries": [
            {k: e[k] for k in ("start_height","end_height","manifest_path","manifest_sha256","blocks_path","blocks_sha256","transactions_path","transactions_sha256","inputs_path","inputs_sha256","outputs_path","outputs_sha256")}
            for e in selected
        ],
        "source_bindings": bindings,
        "checkpoint_requested": bool(checkpoint_requested),
        "result_path": str(result_path),
        "created_at": _now_iso(),
    }
    payload["job_sha256"] = _core_worker_job_hash(payload)
    _save_json_atomic(job_path, payload)
    return job_dir, job_path, result_path, payload


def _core_read_worker_job(path: Path) -> Dict[str, Any]:
    obj, _, _ = _read_json_regular_file_snapshot(path)
    if obj.get("contract_version") != V40_CORE_APPLY_WORKER_CONTRACT:
        raise RuntimeError("CORE worker job contract mismatch")
    if obj.get("job_sha256") != _core_worker_job_hash(obj):
        raise RuntimeError("CORE worker job SHA mismatch")
    if obj.get("script_sha256") != V11_PROCESS_SCRIPT_SHA256:
        raise RuntimeError("CORE worker script SHA mismatch")
    if obj.get("python_executable") != V11_PROCESS_PYTHON_EXECUTABLE or obj.get("python_version") != V11_PROCESS_PYTHON_VERSION:
        raise RuntimeError("CORE worker Python runtime mismatch")
    if obj.get("duckdb_version") != V11_PROCESS_DUCKDB_VERSION or V11_PROCESS_DUCKDB_VERSION != CORE_EXPECTED_DUCKDB_VERSION:
        raise RuntimeError("CORE worker DuckDB runtime mismatch")
    if obj.get("parent_v30_sha256") != V40_PARENT_V30_SHA256:
        raise RuntimeError("CORE worker parent-v30 SHA contract mismatch")
    if obj.get("source_global_manifest_sha256") != CORE_RELEASE_GLOBAL_MANIFEST_SHA256:
        raise RuntimeError("CORE worker source global SHA mismatch")
    for key in ("source_windows_tsv_sha256", "source_fingerprint_sha256"):
        value = obj.get(key)
        if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None:
            raise RuntimeError(f"CORE worker invalid {key}: {value!r}")
    if not isinstance(obj.get("source_verify_parquet_sha"), bool):
        raise RuntimeError("CORE worker source_verify_parquet_sha must be boolean")
    h1 = int(obj.get("h1", -1))
    h2 = int(obj.get("h2", -1))
    target_end = int(obj.get("target_end_height", -1))
    if h1 < 0 or h2 < h1 or h2 > target_end or target_end > CORE_RELEASE_END_HEIGHT:
        raise RuntimeError(
            f"CORE worker invalid height contract h1={h1} h2={h2} target_end={target_end}"
        )
    selected = obj.get("selected_entries")
    bindings = obj.get("source_bindings")
    if not isinstance(selected, list) or not selected or not isinstance(bindings, list) or not bindings:
        raise RuntimeError("CORE worker selected_entries/source_bindings missing or empty")
    binding_paths = {str(x.get("path") or "") for x in bindings if isinstance(x, dict)}
    previous_end: Optional[int] = None
    for idx, entry in enumerate(selected):
        if not isinstance(entry, dict):
            raise RuntimeError(f"CORE worker selected entry is not an object index={idx}")
        start = int(entry.get("start_height", -1))
        end = int(entry.get("end_height", -1))
        if start < 0 or end < start:
            raise RuntimeError(f"CORE worker invalid selected range index={idx} start={start} end={end}")
        if previous_end is not None and start != previous_end + 1:
            raise RuntimeError(
                f"CORE worker selected windows are not contiguous index={idx} "
                f"previous_end={previous_end} start={start}"
            )
        previous_end = end
        for role in ("manifest", "blocks", "transactions", "inputs", "outputs"):
            path_key = f"{role}_path"
            sha_key = f"{role}_sha256"
            path_value = str(entry.get(path_key) or "")
            sha_value = entry.get(sha_key)
            if not Path(path_value).is_absolute() or path_value not in binding_paths:
                raise RuntimeError(
                    f"CORE worker selected path is not absolute/bound index={idx} role={role} path={path_value!r}"
                )
            if not isinstance(sha_value, str) or re.fullmatch(r"[0-9a-f]{64}", sha_value) is None:
                raise RuntimeError(
                    f"CORE worker selected SHA invalid index={idx} role={role} sha={sha_value!r}"
                )
    if int(selected[0]["start_height"]) > h1 or int(selected[0]["end_height"]) < h1:
        raise RuntimeError(f"CORE worker selected windows do not contain h1={h1}")
    if int(selected[-1]["start_height"]) > h2 or int(selected[-1]["end_height"]) < h2:
        raise RuntimeError(f"CORE worker selected windows do not contain h2={h2}")
    expected_result = Path(str(obj.get("result_path") or ""))
    if not expected_result.is_absolute() or expected_result.name != "result.json":
        raise RuntimeError(f"CORE worker invalid result_path: {expected_result}")
    return obj


def _core_write_worker_result(path: Path, payload: Dict[str, Any]) -> None:
    out = dict(payload)
    out["contract_version"] = V40_CORE_APPLY_RESULT_CONTRACT
    out["result_sha256"] = _core_worker_result_hash(out)
    _save_json_atomic(path, out)


def _core_read_worker_result(path: Path, job: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not path.exists():
        return None
    obj, _, _ = _read_json_regular_file_snapshot(path)
    if obj.get("contract_version") != V40_CORE_APPLY_RESULT_CONTRACT or obj.get("result_sha256") != _core_worker_result_hash(obj):
        raise RuntimeError(f"CORE worker result contract/SHA mismatch path={path}")
    if obj.get("job_id") != job.get("job_id") or obj.get("job_sha256") != job.get("job_sha256"):
        raise RuntimeError("CORE worker result does not bind to expected job")
    return obj


def _core_worker_main(job_path_raw: str) -> int:
    con: Optional[duckdb.DuckDBPyConnection] = None
    job: Optional[Dict[str, Any]] = None
    result_path: Optional[Path] = None
    committed = False
    try:
        parent_pid = _v11_apply_worker_arm_parent_death_guard()
        _core_require_runtime_script_guard(context="CORE_STAGE2 worker startup")
        job = _core_read_worker_job(Path(job_path_raw).resolve(strict=True))
        if int(job.get("parent_pid") or 0) != parent_pid or int(os.getppid()) != parent_pid:
            raise RuntimeError(f"CORE worker parent identity mismatch expected={job.get('parent_pid')} guarded={parent_pid} current={os.getppid()}")
        result_path = Path(str(job["result_path"]))
        _core_validate_binding(job.get("source_bindings") or [])
        db_path = Path(str(job["db_path"]))
        now_db = _core_file_identity(db_path)
        if not _core_identity_equal(job["db_identity"], now_db):
            raise RuntimeError(f"CORE worker DB inode identity mismatch expected={job['db_identity']} actual={now_db}")
        selected = list(job.get("selected_entries") or [])
        con = duckdb.connect(str(db_path))
        _core_apply_pragmas(con, phase="apply")
        source_stub = {
            "global_manifest_sha256": job["source_global_manifest_sha256"],
            "windows_tsv_sha256": job["source_windows_tsv_sha256"],
            "source_fingerprint_sha256": job["source_fingerprint_sha256"],
            "verify_parquet_sha": bool(job["source_verify_parquet_sha"]),
        }
        # Never create/alter schema in a worker.  The parent has already
        # created a fresh Core DB or proved an existing one read-only; the
        # child must fail closed if that exact contract is no longer present.
        _core_validate_meta(con, source_stub, int(job["target_end_height"]))
        prefix = _core_validate_db_prefix(con, expected_end=int(job["h1"]) - 1)
        report = _core_apply_block_window(
            con, h1=int(job["h1"]), h2=int(job["h2"]), selected=selected,
            source_fingerprint_sha256=str(job["source_fingerprint_sha256"]),
        )
        committed = True
        post = _core_validate_db_prefix(con, expected_end=int(job["h2"]))
        _core_write_worker_result(result_path, {
            "status": "committed", "job_id": job["job_id"], "job_sha256": job["job_sha256"],
            "worker_pid": os.getpid(), "h1": int(job["h1"]), "h2": int(job["h2"]),
            "report": report, "prefix_before": prefix, "prefix_after": post,
            "checkpoint_requested": bool(job.get("checkpoint_requested")), "checkpoint_completed": False,
        })
        if bool(job.get("checkpoint_requested")):
            con.execute("CHECKPOINT")
            _core_write_worker_result(result_path, {
                "status": "ok", "job_id": job["job_id"], "job_sha256": job["job_sha256"],
                "worker_pid": os.getpid(), "h1": int(job["h1"]), "h2": int(job["h2"]),
                "report": report, "prefix_before": prefix, "prefix_after": post,
                "checkpoint_requested": True, "checkpoint_completed": True,
            })
        return 0
    except BaseException as exc:
        is_oom = _v11_is_duckdb_oom(exc)
        if result_path is not None and job is not None and not committed:
            try:
                _core_write_worker_result(result_path, {
                    "status": "oom" if is_oom else "error", "job_id": job.get("job_id"), "job_sha256": job.get("job_sha256"),
                    "worker_pid": os.getpid(), "h1": job.get("h1"), "h2": job.get("h2"),
                    "error_type": type(exc).__name__, "error": str(exc), "retryable_oom": bool(is_oom),
                })
            except BaseException:
                pass
        _log(f"CORE_STAGE2 worker failed committed={committed} oom={is_oom} type={type(exc).__name__}: {exc}", stream=sys.stderr)
        return V40_CORE_WORKER_EXIT_OOM if is_oom else V40_CORE_WORKER_EXIT_ERROR
    finally:
        if con is not None:
            try: con.close()
            except BaseException: pass


def _core_launch_worker(job_path: Path) -> Dict[str, Any]:
    command = [sys.executable, V11_PROCESS_SCRIPT_PATH, "--v40-core-apply-worker-job", str(job_path)]
    env = dict(os.environ)
    env["UTXO_V40_CORE_APPLY_WORKER_ACTIVE"] = "1"
    started = _tic()
    proc = subprocess.Popen(command, env=env, close_fds=True, start_new_session=True)
    timeout = max(0, _env_int("UTXO_CORE_WORKER_TIMEOUT_SECONDS", 0))
    timed_out = False
    try:
        rc = proc.wait(timeout=timeout if timeout else None)
    except subprocess.TimeoutExpired:
        timed_out = True
        try: os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError: pass
        try: rc = proc.wait(timeout=max(1, _env_int("UTXO_CORE_WORKER_KILL_GRACE_SECONDS", 30)))
        except subprocess.TimeoutExpired:
            try: os.killpg(proc.pid, signal.SIGKILL)
            except ProcessLookupError: pass
            rc = proc.wait()
    return {"pid": proc.pid, "returncode": int(rc), "signal": -int(rc) if int(rc) < 0 else None, "timed_out": timed_out, "elapsed_sec": _toc(started), "command": command}


def _core_active_workers() -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    proc = Path("/proc")
    if not proc.is_dir():
        return out
    for p in proc.iterdir():
        if not p.name.isdigit() or int(p.name) == os.getpid():
            continue
        try: args = [x.decode("utf-8", "replace") for x in (p / "cmdline").read_bytes().split(b"\0") if x]
        except (FileNotFoundError, ProcessLookupError, PermissionError, OSError):
            continue
        if "--v40-core-apply-worker-job" in args:
            out.append({"pid": int(p.name), "cmdline": " ".join(args)[:2000]})
    return out


def _core_acquire_writer_lock(db_path: Path, source: Dict[str, Any]) -> Path:
    identity = f"{db_path.absolute()}|{source['global_manifest_sha256']}"
    lock = _lock_root(create=True) / f"utxo_v40_core_writer.{_lock_key(identity)}.lock"
    payload = {"contract": "utxo-v40-core-writer-lock-v1", "pid": os.getpid(), "host": socket.gethostname(), "db_path": str(db_path), "source_global_sha256": source["global_manifest_sha256"], "script_sha256": V11_PROCESS_SCRIPT_SHA256, "created_at": _now_iso()}
    while True:
        try:
            lock.mkdir(mode=0o700)
            _save_json_atomic(lock / "owner.json", payload)
            _fsync_directory(lock.parent)
            return lock
        except FileExistsError:
            owner = None
            try: owner = json.loads((lock / "owner.json").read_text(encoding="utf-8"))
            except Exception: pass
            alive = bool(owner and str(owner.get("host")) == socket.gethostname() and _pid_alive(int(owner.get("pid") or 0)))
            if alive:
                raise RuntimeError(f"CORE writer lock held by live process: {owner}")
            if not _env_bool("UTXO_CORE_RECLAIM_STALE_LOCK", False):
                raise RuntimeError(f"stale/unknown CORE writer lock exists; set UTXO_CORE_RECLAIM_STALE_LOCK=1 only after inspection: {lock} owner={owner}")
            workers = _core_active_workers()
            if workers:
                raise RuntimeError(f"refuse stale CORE lock reclaim while CORE worker exists: {workers}")
            shutil.rmtree(lock)
            _fsync_directory(lock.parent)


def _core_release_writer_lock(lock: Optional[Path]) -> None:
    if lock is None: return
    try:
        shutil.rmtree(lock)
        _fsync_directory(lock.parent)
    except FileNotFoundError:
        return


def _core_write_marker(db_path: Path, source: Dict[str, Any], *, target_end: int, last_committed: int, status: str) -> Path:
    p = _core_marker_path(db_path)
    payload = {
        "contract_version": V40_CORE_MARKER_CONTRACT, "status": str(status),
        "db_path": str(db_path), "source_global_manifest_sha256": source["global_manifest_sha256"],
        "source_fingerprint_sha256": source["source_fingerprint_sha256"], "script_sha256": V11_PROCESS_SCRIPT_SHA256,
        "parent_v30_sha256": V40_PARENT_V30_SHA256, "target_end_height": int(target_end),
        "last_committed_height": int(last_committed), "next_height": int(last_committed) + 1,
        "updated_at": _now_iso(),
    }
    payload["marker_sha256"] = _v11_canonical_json_hash(payload, exclude=("marker_sha256",))
    _save_json_atomic(p, payload)
    return p


def _core_read_marker(db_path: Path, source: Dict[str, Any], target_end: int) -> Optional[Dict[str, Any]]:
    p = _core_marker_path(db_path)
    if not p.exists(): return None
    obj, _, _ = _read_json_regular_file_snapshot(p)
    if obj.get("contract_version") != V40_CORE_MARKER_CONTRACT or obj.get("marker_sha256") != _v11_canonical_json_hash(obj, exclude=("marker_sha256",)):
        raise RuntimeError(f"CORE rebuild marker invalid: {p}")
    expected = {"db_path": str(db_path), "source_global_manifest_sha256": source["global_manifest_sha256"], "source_fingerprint_sha256": source["source_fingerprint_sha256"], "script_sha256": V11_PROCESS_SCRIPT_SHA256, "parent_v30_sha256": V40_PARENT_V30_SHA256, "target_end_height": int(target_end)}
    bad = {k: (obj.get(k), v) for k, v in expected.items() if obj.get(k) != v}
    if bad: raise RuntimeError(f"CORE rebuild marker identity mismatch: {bad}")
    return obj


def _core_disk_preflight(db_path: Path, target_end: int) -> None:
    db_path.parent.mkdir(parents=True, exist_ok=True)
    usage = shutil.disk_usage(db_path.parent)
    free_gib = usage.free / (1024**3)
    default_min = 500 if int(target_end) == CORE_RELEASE_END_HEIGHT else 20
    min_gib = max(1, _env_int("UTXO_CORE_MIN_FREE_GIB", default_min))
    if free_gib < min_gib:
        raise RuntimeError(f"CORE output filesystem free-space guard failed free_gib={free_gib:.1f} required_gib={min_gib}")
    _log(f"CORE disk preflight free_gib={free_gib:.1f} required_gib={min_gib} path={db_path.parent}")


def _core_runtime_disk_guard(db_path: Path, target_end: int) -> Dict[str, Any]:
    """Cheap per-window free-space guard for DB and DuckDB spill files."""
    default_db_reserve = 100 if int(target_end) == CORE_RELEASE_END_HEIGHT else 5
    db_reserve = max(1, _env_int("UTXO_CORE_RUNTIME_MIN_FREE_GIB", default_db_reserve))
    db_free = shutil.disk_usage(db_path.parent).free / (1024**3)
    if db_free < db_reserve:
        raise RuntimeError(
            f"CORE runtime DB free-space guard failed free_gib={db_free:.1f} "
            f"required_gib={db_reserve} path={db_path.parent}"
        )
    result: Dict[str, Any] = {"db_free_gib": round(db_free, 1), "db_required_gib": db_reserve}
    tmp_raw = _env_str("DUCKDB_TMPDIR", "") or ""
    if tmp_raw:
        tmp = Path(tmp_raw)
        tmp.mkdir(parents=True, exist_ok=True)
        default_tmp_reserve = 50 if int(target_end) == CORE_RELEASE_END_HEIGHT else 5
        tmp_reserve = max(1, _env_int("UTXO_CORE_RUNTIME_TMP_MIN_FREE_GIB", default_tmp_reserve))
        tmp_free = shutil.disk_usage(tmp).free / (1024**3)
        if tmp_free < tmp_reserve:
            raise RuntimeError(
                f"CORE runtime DuckDB-temp free-space guard failed free_gib={tmp_free:.1f} "
                f"required_gib={tmp_reserve} path={tmp}"
            )
        result.update({"tmp_path": str(tmp), "tmp_free_gib": round(tmp_free, 1), "tmp_required_gib": tmp_reserve})
    return result


def _core_final_bip30_audit(con: duckdb.DuckDBPyConnection, target_end: int) -> Dict[str, Any]:
    """Prove exact lifecycle semantics for the two historical BIP30 repeats.

    The earlier generation may either have been spent before the later repeat,
    or may have been removed from the active UTXO set by the historical
    duplicate-coinbase overwrite itself.  Overwrite is deliberately not
    represented as a spend.
    """
    reports: List[Dict[str, Any]] = []
    for later, earlier in CORE_BIP30_HEIGHT_PAIRS:
        if int(target_end) < int(later):
            continue
        coinbases = con.execute(
            """
            SELECT created_height, lower(txid) AS txid, count(*) AS outputs
            FROM utxo
            WHERE created_height IN (?, ?) AND created_tx_index=0 AND is_coinbase
            GROUP BY 1,2 ORDER BY 1
            """,
            [int(earlier), int(later)],
        ).fetchall()
        if len(coinbases) != 2 or str(coinbases[0][1]) != str(coinbases[1][1]):
            raise RuntimeError(
                f"CORE final BIP30 coinbase generation proof failed pair={later}:{earlier} rows={coinbases}"
            )
        txid = str(coinbases[0][1]).lower()
        if txid not in CORE_BIP30_KNOWN_TXIDS:
            raise RuntimeError(
                f"CORE final BIP30 txid is not in frozen known set pair={later}:{earlier} txid={txid}"
            )
        earlier_outputs = int(coinbases[0][2])
        later_outputs = int(coinbases[1][2])
        if earlier_outputs != later_outputs:
            raise RuntimeError(
                f"CORE final BIP30 output cardinality mismatch pair={later}:{earlier} "
                f"earlier={earlier_outputs} later={later_outputs}"
            )

        payload_mismatch = int(con.execute(
            """
            SELECT count(*)
            FROM utxo e
            JOIN utxo l ON l.txid=e.txid AND l.vout=e.vout
            WHERE lower(e.txid)=?
              AND e.created_height=? AND e.created_tx_index=0
              AND l.created_height=? AND l.created_tx_index=0
              AND (
                e.value_sats IS DISTINCT FROM l.value_sats
                OR e.script_pubkey_size IS DISTINCT FROM l.script_pubkey_size
                OR e.script_pubkey IS DISTINCT FROM l.script_pubkey
                OR NOT e.is_coinbase OR NOT l.is_coinbase
              )
            """,
            [txid, int(earlier), int(later)],
        ).fetchone()[0] or 0)
        if payload_mismatch:
            raise RuntimeError(
                f"CORE final BIP30 payload mismatch pair={later}:{earlier} txid={txid} rows={payload_mismatch}"
            )

        lifecycle = con.execute(
            """
            SELECT
              count(*) AS rows,
              count(*) FILTER (
                WHERE e.spent_height IS NOT NULL AND e.spent_height < ?
                  AND e.bip30_overwritten_height IS NULL
              ) AS spent_before,
              count(*) FILTER (
                WHERE e.spent_height IS NULL
                  AND e.bip30_overwritten_height=?
                  AND e.bip30_overwritten_tx_index=0
              ) AS overwritten_at_repeat,
              count(*) FILTER (
                WHERE NOT (
                  (e.spent_height IS NOT NULL AND e.spent_height < ?
                    AND e.bip30_overwritten_height IS NULL)
                  OR
                  (e.spent_height IS NULL AND e.bip30_overwritten_height=?
                    AND e.bip30_overwritten_tx_index=0)
                )
              ) AS invalid_lifecycle
            FROM utxo e
            JOIN utxo l ON l.txid=e.txid AND l.vout=e.vout
            WHERE lower(e.txid)=?
              AND e.created_height=? AND e.created_tx_index=0
              AND l.created_height=? AND l.created_tx_index=0
            """,
            [int(later), int(later), int(later), int(later), txid, int(earlier), int(later)],
        ).fetchone()
        rows_i, spent_before, overwritten_at_repeat, invalid = (int(x or 0) for x in lifecycle)
        if rows_i != earlier_outputs or invalid:
            raise RuntimeError(
                f"CORE final BIP30 lifecycle proof failed pair={later}:{earlier} txid={txid} "
                f"rows={rows_i}/{earlier_outputs} spent_before={spent_before} "
                f"overwritten={overwritten_at_repeat} invalid={invalid}"
            )

        prior_active = int(con.execute(
            """
            SELECT count(*)
            FROM utxo_active a
            JOIN utxo e ON e.txid=a.txid AND e.vout=a.vout
              AND e.created_height=a.created_height AND e.created_tx_index=a.created_tx_index
            WHERE lower(e.txid)=? AND e.created_height=? AND e.created_tx_index=0
            """,
            [txid, int(earlier)],
        ).fetchone()[0] or 0)
        if prior_active:
            raise RuntimeError(
                f"CORE final BIP30 earlier generation remains active pair={later}:{earlier} txid={txid} rows={prior_active}"
            )

        reports.append({
            "later_height": int(later), "earlier_height": int(earlier),
            "txid": txid, "earlier_outputs": earlier_outputs,
            "later_outputs": later_outputs, "spent_before_repeat": spent_before,
            "overwritten_at_repeat": overwritten_at_repeat, "status": "GREEN",
        })
    return {"status": "GREEN", "pairs": reports}


def _core_final_audit(con: duckdb.DuckDBPyConnection, *, target_end: int) -> Dict[str, Any]:
    prefix = _core_validate_db_prefix(con, expected_end=int(target_end))
    end_hash = str(con.execute("SELECT block_hash FROM block_meta WHERE block_number=?", [int(target_end)]).fetchone()[0]).lower()
    active_count, active_sats = con.execute("""
        SELECT count(*), coalesce(sum(u.value_sats),0)
        FROM utxo_active a JOIN utxo u
          ON u.txid=a.txid AND u.vout=a.vout
         AND u.created_height=a.created_height AND u.created_tx_index=a.created_tx_index
        WHERE u.spent_height IS NULL AND u.bip30_overwritten_height IS NULL
    """).fetchone()
    history_open_count = int(con.execute(
        "SELECT count(*) FROM utxo WHERE spent_height IS NULL AND bip30_overwritten_height IS NULL"
    ).fetchone()[0] or 0)
    active_map_count = int(con.execute("SELECT count(*) FROM utxo_active").fetchone()[0] or 0)
    active_join_count = int(active_count or 0)
    open_count_mismatch = 0 if history_open_count == active_map_count == active_join_count else (
        abs(history_open_count - active_map_count) + abs(active_map_count - active_join_count)
    )
    open_duplicate_outpoints = int(con.execute("""
        SELECT count(*) FROM (
          SELECT lower(txid) AS txid, vout, count(*) AS c
          FROM utxo WHERE spent_height IS NULL AND bip30_overwritten_height IS NULL
          GROUP BY 1,2 HAVING c<>1
        )
    """).fetchone()[0] or 0)
    active_dangling_or_spent = int(con.execute("""
        SELECT count(*)
        FROM utxo_active a
        LEFT JOIN utxo u
          ON u.txid=a.txid AND u.vout=a.vout
         AND u.created_height=a.created_height AND u.created_tx_index=a.created_tx_index
        WHERE u.txid IS NULL OR u.spent_height IS NOT NULL OR u.bip30_overwritten_height IS NOT NULL
    """).fetchone()[0] or 0)
    open_missing_active = int(con.execute("""
        SELECT count(*)
        FROM utxo u
        LEFT JOIN utxo_active a
          ON a.txid=u.txid AND a.vout=u.vout
         AND a.created_height=u.created_height AND a.created_tx_index=u.created_tx_index
        WHERE u.spent_height IS NULL AND u.bip30_overwritten_height IS NULL AND a.txid IS NULL
    """).fetchone()[0] or 0)
    impossible = int(con.execute("""
        SELECT count(*) FROM utxo WHERE spent_height IS NOT NULL AND NOT (
          created_height < spent_height OR (created_height=spent_height AND created_tx_index < spent_tx_index)
        )
    """).fetchone()[0] or 0)
    lifecycle_collision = int(con.execute("""
        SELECT count(*) FROM utxo
        WHERE spent_height IS NOT NULL AND bip30_overwritten_height IS NOT NULL
    """).fetchone()[0] or 0)
    bip30_overwritten_rows = int(con.execute("""
        SELECT count(*) FROM utxo WHERE bip30_overwritten_height IS NOT NULL
    """).fetchone()[0] or 0)
    history_rows = int(con.execute("SELECT count(*) FROM utxo").fetchone()[0] or 0)
    spent_history_rows = int(con.execute(
        "SELECT count(*) FROM utxo WHERE spent_height IS NOT NULL"
    ).fetchone()[0] or 0)
    ledger_created_rows, ledger_spends_rows, ledger_block_rows = con.execute("""
        SELECT coalesce(sum(created_rows),0),
               coalesce(sum(spends_rows),0),
               coalesce(sum(block_rows),0)
        FROM core_apply_ledger
    """).fetchone()
    ledger_created_rows = int(ledger_created_rows or 0)
    ledger_spends_rows = int(ledger_spends_rows or 0)
    ledger_block_rows = int(ledger_block_rows or 0)
    lifecycle_partition_delta = history_rows - (history_open_count + spent_history_rows + bip30_overwritten_rows)
    history_created_delta = history_rows - ledger_created_rows
    history_spent_delta = spent_history_rows - ledger_spends_rows
    ledger_block_delta = ledger_block_rows - (int(target_end) + 1)
    invalid_overwrite_rows = int(con.execute("""
        SELECT count(*)
        FROM utxo
        WHERE bip30_overwritten_height IS NOT NULL AND NOT (
          (created_height=91812 AND created_tx_index=0 AND is_coinbase
             AND bip30_overwritten_height=91842 AND bip30_overwritten_tx_index=0)
          OR
          (created_height=91722 AND created_tx_index=0 AND is_coinbase
             AND bip30_overwritten_height=91880 AND bip30_overwritten_tx_index=0)
        )
    """).fetchone()[0] or 0)
    bad_unspendable = int(con.execute("""
        SELECT count(*) FROM utxo WHERE script_pubkey_size > ? OR CASE WHEN script_pubkey_size > 0 THEN substr(hex(script_pubkey), 1, 2) = '6A' ELSE FALSE END
    """, [CORE_MAX_SCRIPT_SIZE]).fetchone()[0] or 0)
    genesis_rows = int(con.execute("SELECT count(*) FROM utxo WHERE created_height=0").fetchone()[0] or 0)
    report: Dict[str, Any] = {
        "status": "GREEN_STRUCTURAL", "target_end_height": int(target_end), "end_hash": end_hash,
        "prefix": prefix, "active_txouts": int(active_count or 0), "active_total_sats": int(active_sats or 0),
        "active_total_btc": f"{Decimal(int(active_sats or 0)) / Decimal(100000000):.8f}",
        "active_history_rows": history_open_count, "active_map_rows": active_map_count,
        "active_join_rows": active_join_count, "active_count_mismatch": open_count_mismatch,
        "open_duplicate_outpoints": open_duplicate_outpoints,
        "active_dangling_or_spent": active_dangling_or_spent,
        "open_missing_active": open_missing_active,
        "impossible_causal_rows": impossible,
        "lifecycle_collision_rows": lifecycle_collision,
        "bip30_overwritten_rows": bip30_overwritten_rows,
        "history_rows": history_rows,
        "spent_history_rows": spent_history_rows,
        "ledger_created_rows": ledger_created_rows,
        "ledger_spends_rows": ledger_spends_rows,
        "ledger_block_rows": ledger_block_rows,
        "lifecycle_partition_delta": lifecycle_partition_delta,
        "history_created_delta": history_created_delta,
        "history_spent_delta": history_spent_delta,
        "ledger_block_delta": ledger_block_delta,
        "invalid_bip30_overwrite_rows": invalid_overwrite_rows,
        "unspendable_rows_present": bad_unspendable, "genesis_rows_present": genesis_rows,
        "muhash_expected": CORE_FINAL_MUHASH,
        "muhash_status": "PENDING_SEPARATE_EXACT_AUDITOR",
    }
    bip30 = _core_final_bip30_audit(con, int(target_end))
    report["bip30"] = bip30
    if (
        end_hash != (CORE_RELEASE_END_HASH if int(target_end) == CORE_RELEASE_END_HEIGHT else end_hash)
        or open_count_mismatch or open_duplicate_outpoints or active_dangling_or_spent or open_missing_active
        or impossible or lifecycle_collision or invalid_overwrite_rows or bad_unspendable or genesis_rows
        or lifecycle_partition_delta or history_created_delta or history_spent_delta or ledger_block_delta
    ):
        report["status"] = "FAIL"
        raise RuntimeError(f"CORE final structural audit failed: {report}")
    if int(target_end) == CORE_RELEASE_END_HEIGHT:
        report["expected_active_txouts"] = CORE_FINAL_TXOUTS
        report["expected_active_total_sats"] = CORE_FINAL_TOTAL_SATS
        if int(active_count or 0) != CORE_FINAL_TXOUTS or int(active_sats or 0) != CORE_FINAL_TOTAL_SATS:
            report["status"] = "FAIL_CORE_STATE_ANCHOR"
            raise RuntimeError(f"CORE final state count/amount mismatch: {report}")
        report["status"] = "GREEN_CORE_COUNT_AMOUNT_MUHASH_PENDING"
    return report


def _core_stage2_rebuild() -> int:
    _core_require_runtime_script_guard(context="CORE_STAGE2_REBUILD startup")
    target_end = _env_int("UTXO_CORE_END_HEIGHT", CORE_RELEASE_END_HEIGHT)
    if target_end < 0 or target_end > CORE_RELEASE_END_HEIGHT:
        raise RuntimeError(f"UTXO_CORE_END_HEIGHT out of frozen release range: {target_end}")
    lab_fast_source_verify = _env_bool("UTXO_CORE_LAB_FAST_SOURCE_VERIFY", False)
    if lab_fast_source_verify and target_end == CORE_RELEASE_END_HEIGHT:
        raise RuntimeError(
            "UTXO_CORE_LAB_FAST_SOURCE_VERIFY=1 is forbidden for the full frozen release; "
            "full CORE_STAGE2_REBUILD requires streaming SHA256 verification of every Stage2 parquet"
        )
    source = _core_stage2_preflight(verify_parquet_sha=not lab_fast_source_verify)
    if not bool(source.get("verify_parquet_sha")):
        _warn(
            f"CORE LAB ONLY: Parquet content SHA streaming disabled for partial target_end={target_end}; "
            "do not classify this DB as a production canonical release"
        )
    db_path = _core_db_path()
    if db_path.is_symlink():
        raise RuntimeError(f"CORE output DB path must not be a symlink: {db_path}")
    _core_disk_preflight(db_path, target_end)
    lock: Optional[Path] = None
    con: Optional[duckdb.DuckDBPyConnection] = None
    resume = _env_bool("UTXO_CORE_REBUILD_RESUME", False)
    try:
        _v11_raise_if_controlled_stop(
            "CORE_STAGE2_REBUILD controlled stop before DB mutation",
            mode=MODE_CORE_STAGE2_REBUILD, phase="pre_write",
            payload={"target_end_height": int(target_end)},
        )
        lock = _core_acquire_writer_lock(db_path, source)
        if db_path.exists() and not resume:
            raise RuntimeError(f"CORE_STAGE2_REBUILD refuses existing DB without UTXO_CORE_REBUILD_RESUME=1: {db_path}")
        if not db_path.exists() and resume:
            raise RuntimeError(f"CORE resume requested but DB does not exist: {db_path}")
        if not db_path.exists():
            con = duckdb.connect(str(db_path))
            _core_apply_pragmas(con, phase="apply")
            _core_ensure_schema(con)
            _core_initialize_meta(con, source, target_end)
            con.execute("CHECKPOINT")
            prefix = _core_validate_db_prefix(con, expected_end=-1)
            next_height = 0
            _core_write_marker(db_path, source, target_end=target_end, last_committed=-1, status="BUILDING")
            _log(f"CORE fresh DB initialized path={db_path} schema_signature={_core_schema_signature(con)}")
        else:
            # Existing DBs are identity-probed read-only first.  This is a hard
            # isolation boundary: a legacy v30 DB or unrelated DuckDB file must
            # fail without v40 creating tables, columns, indexes, or metadata in it.
            probe = duckdb.connect(str(db_path), read_only=True)
            try:
                # Identity proof intentionally avoids the normal apply PRAGMAs:
                # it needs only catalog/meta/prefix reads, and should perform no
                # writable setup before we know this is an exact Core-v40 DB.
                _core_validate_meta(probe, source, target_end)
                prefix = _core_validate_db_prefix(probe)
                ledger_binding = _core_validate_ledger_source_bindings(probe, source)
            finally:
                probe.close()
            marker = _core_read_marker(db_path, source, target_end)
            if marker is None and int(prefix["actual_end"]) >= 0:
                _warn("CORE resume marker missing but exact DB apply-ledger/prefix proof is intact; reconstructing marker from DB authority")
            elif marker is not None and int(marker["last_committed_height"]) > int(prefix["actual_end"]):
                raise RuntimeError(f"CORE marker is ahead of DB prefix: marker={marker} prefix={prefix}")

            # Reopen writable only after the read-only identity/schema/source
            # proof passed, then prove it again before publishing a new marker.
            con = duckdb.connect(str(db_path))
            _core_apply_pragmas(con, phase="apply")
            _core_validate_meta(con, source, target_end)
            prefix_rw = _core_validate_db_prefix(con, expected_end=int(prefix["actual_end"]))
            _core_validate_ledger_source_bindings(con, source)
            next_height = int(prefix_rw["actual_end"]) + 1
            _core_write_marker(db_path, source, target_end=target_end, last_committed=int(prefix_rw["actual_end"]), status="BUILDING")
            _log(f"CORE resume accepted next_height={next_height} prefix={prefix_rw} ledger_binding={ledger_binding}")

        configured = max(1, _env_int("UTXO_CORE_APPLY_BLOCK_WINDOW", 1000))
        min_window = max(1, _env_int("UTXO_CORE_MIN_BLOCK_WINDOW", 1))
        max_retries = max(0, _env_int("UTXO_CORE_OOM_MAX_RETRIES", 16))
        divisor = max(2, _env_int("UTXO_CORE_OOM_BACKOFF_DIVISOR", 2))
        checkpoint_every = max(1, _env_int("UTXO_CORE_CHECKPOINT_EVERY_WINDOWS", 25))
        committed_windows = int(con.execute("SELECT count(*) FROM core_apply_ledger").fetchone()[0] or 0)

        while next_height <= target_end:
            _v11_assert_loaded_script_unchanged(context=f"CORE pre-window next_height={next_height}")
            disk_state = _core_runtime_disk_guard(db_path, target_end)
            _v11_raise_if_controlled_stop(
                "CORE_STAGE2_REBUILD controlled stop at committed window boundary",
                mode=MODE_CORE_STAGE2_REBUILD, phase="apply_window_boundary",
                payload={"next_height": int(next_height), "target_end_height": int(target_end)},
            )
            if committed_windows == 0 or committed_windows % 25 == 0:
                _log(f"CORE runtime disk state next_height={next_height} {disk_state}")
            current_size = configured
            attempt = 0
            while True:
                raw_h2 = min(next_height + current_size - 1, target_end)
                h2, split = _core_adjust_window_end_for_bip30(next_height, raw_h2)
                selected = _core_select_entries(source, next_height, h2)
                _core_validate_binding([b for e in selected for b in e["bindings"]])
                before = _core_validate_db_prefix(con, expected_end=next_height - 1)
                try:
                    con.close(); con = None
                    checkpoint_requested = ((committed_windows + 1) % checkpoint_every == 0) or h2 == target_end
                    job_dir, job_path, result_path, job = _core_create_worker_job(
                        db_path=db_path, h1=next_height, h2=h2, source=source, selected=selected,
                        checkpoint_requested=checkpoint_requested,
                    )
                    _log(f"CORE APPLY worker launch range={next_height}-{h2} raw_h2={raw_h2} size={current_size} attempt={attempt+1} bip30_split={split.get('split_before_later_bip30_height')}")
                    launch = _core_launch_worker(job_path)
                    result_error = None
                    try: result = _core_read_worker_result(result_path, job)
                    except BaseException as exc:
                        result = None; result_error = f"{type(exc).__name__}:{exc}"
                    con = duckdb.connect(str(db_path)); _core_apply_pragmas(con, phase="apply"); _core_validate_meta(con, source, target_end)
                    observed = _core_validate_db_prefix(con)
                    if int(observed["actual_end"]) == int(h2):
                        expected_window_fp = _core_source_window_fingerprint(selected, int(job["h1"]), int(h2))
                        ledger_row = con.execute(
                            """
                            SELECT source_global_sha256,source_fingerprint_sha256,
                                   source_window_fingerprint_sha256,script_sha256,contract_version
                            FROM core_apply_ledger WHERE h1=? AND h2=?
                            """,
                            [int(job["h1"]), int(h2)],
                        ).fetchone()
                        ledger_ok = bool(
                            ledger_row is not None
                            and str(ledger_row[0]) == str(source["global_manifest_sha256"])
                            and str(ledger_row[1]) == str(source["source_fingerprint_sha256"])
                            and str(ledger_row[2]) == expected_window_fp
                            and str(ledger_row[3]) == str(V11_PROCESS_SCRIPT_SHA256 or "<disabled>")
                            and str(ledger_row[4]) == V40_CORE_LEDGER_CONTRACT
                        )
                        if not ledger_ok:
                            raise RuntimeError(
                                f"CORE committed-prefix recovery ledger does not bind to exact source/runtime: "
                                f"job={job['job_id']} ledger={ledger_row} expected_window_fp={expected_window_fp}"
                            )
                        _core_validate_binding([b for e in selected for b in e["bindings"]])
                        committed_windows += 1
                        next_height = h2 + 1
                        _core_write_marker(db_path, source, target_end=target_end, last_committed=h2, status="BUILDING")
                        report = (result or {}).get("report") or {}
                        _log(f"CORE APPLY COMMITTED range={job['h1']}-{h2} worker_rc={launch['returncode']} result={(result or {}).get('status')} created={report.get('created_rows')} spends={report.get('spends_rows')} elapsed={launch['elapsed_sec']:.1f}s")
                        try: shutil.rmtree(job_dir)
                        except Exception: pass
                        break
                    if int(observed["actual_end"]) != int(job["h1"]) - 1:
                        raise RuntimeError(f"CORE worker left ambiguous/partial DB prefix: before={before} observed={observed} launch={launch} result={result} result_error={result_error}")
                    status = str((result or {}).get("status") or "")
                    native_signal = int(launch.get("signal") or 0)
                    retryable_signal = native_signal in {int(getattr(signal,"SIGABRT",6)), int(getattr(signal,"SIGSEGV",11)), int(getattr(signal,"SIGBUS",7)), int(getattr(signal,"SIGKILL",9))}
                    retryable = status == "oom" or int(launch["returncode"]) == V40_CORE_WORKER_EXIT_OOM or retryable_signal or bool(launch.get("timed_out"))
                    if not retryable:
                        raise RuntimeError(f"CORE worker failed with unchanged prefix, non-retryable: launch={launch} result={result} result_error={result_error}")
                    attempt += 1
                    base_size = max(1, h2 - int(job["h1"]) + 1)
                    next_size = max(min_window, base_size // divisor)
                    if attempt > max_retries or base_size <= min_window or next_size >= base_size:
                        raise RuntimeError(f"CORE worker retry budget/min-window exhausted range={job['h1']}-{h2} attempt={attempt}/{max_retries} base_size={base_size} min={min_window}")
                    _warn(f"CORE APPLY OOM/native-failure backoff range={job['h1']}-{h2} size={base_size}->{next_size} rc={launch['returncode']} signal={native_signal} status={status}")
                    current_size = next_size
                    try: shutil.rmtree(job_dir)
                    except Exception: pass
                    continue
                except BaseException:
                    if con is None:
                        try:
                            con = duckdb.connect(str(db_path)); _core_apply_pragmas(con, phase="apply")
                        except BaseException:
                            pass
                    raise

        if con is None:
            con = duckdb.connect(str(db_path)); _core_apply_pragmas(con, phase="apply")
        _core_validate_binding(source["source_bindings"])
        ledger_binding = _core_validate_ledger_source_bindings(con, source)
        audit = _core_final_audit(con, target_end=target_end)
        audit["ledger_source_binding"] = ledger_binding
        _core_set_meta(con, "final_audit_status", audit["status"])
        _core_set_meta(con, "final_active_txouts", audit["active_txouts"])
        _core_set_meta(con, "final_active_total_sats", audit["active_total_sats"])
        con.execute("CHECKPOINT")
        frozen_audit = _core_save_audit_json(f"core_utxo_final_audit_0_{target_end}.json", audit)
        _core_write_marker(db_path, source, target_end=target_end, last_committed=target_end, status="COMPLETE")
        _log(
            f"CORE STAGE2 REBUILD COMPLETE status={audit['status']} db={db_path} "
            f"audit={frozen_audit['path']} audit_sha256={frozen_audit['sha256']}"
        )
        return 0
    finally:
        if con is not None:
            try: con.close()
            except BaseException: pass
        _core_release_writer_lock(lock)


def _core_stage2_preflight_mode() -> int:
    report = _core_stage2_preflight()
    print(json.dumps({k: v for k, v in report.items() if k not in {"entries", "source_bindings"}}, indent=2, sort_keys=True))
    return 0



# Backward-compatible aliases for older wrappers/imports.
update_utxo_v10_14 = update_utxo_v10_5
update_utxo_v10_13 = update_utxo_v10_5
update_utxo_v10_12 = update_utxo_v10_5
update_utxo_v10_11 = update_utxo_v10_5
update_utxo_v10_10 = update_utxo_v10_5
update_utxo_v10_9 = update_utxo_v10_5
update_utxo_v10_7 = update_utxo_v10_5
update_utxo_v10_6 = update_utxo_v10_5
update_utxo_v10_5_1 = update_utxo_v10_5
update_utxo_v10_4 = update_utxo_v10_5
update_utxo_v10_3 = update_utxo_v10_5
update_utxo_v10_2 = update_utxo_v10_5
update_utxo_v10_1 = update_utxo_v10_5
update_utxo_v9 = update_utxo_v10_5
# -----------------------------
# CLI
# -----------------------------

def _build_arg_parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(description="UTXO pipeline v11: block-order causal full rebuild r1")
    ap.add_argument("--dry-run", action="store_true", help="Plan only; never write to DB")
    ap.add_argument(
        "--mode",
        default=None,
        help="CORE_STAGE2_PREFLIGHT|CORE_STAGE2_REBUILD|REBUILD_FULL|REBUILD_RESUME|APPEND_TAIL|REPLAY_SUFFIX|STAGE_ONLY|AUDIT_ONLY|VERIFY_MANIFESTS|VERIFY_UNITS|TX_INDEX_MAP_ONLY|TX_INDEX_MAP_AUDIT_ONLY|TX_INDEX_MAP_PREFLIGHT_ONLY|TXID_MAP_ONLY|TXID_MAP_AUDIT_ONLY (legacy date cleanup/replay modes remain blocked)",
    )
    ap.add_argument(
        "--v11-apply-worker-job",
        default=None,
        help=argparse.SUPPRESS,
    )
    ap.add_argument(
        "--v11-recovery-worker-job",
        default=None,
        help=argparse.SUPPRESS,
    )
    ap.add_argument(
        "--v40-core-apply-worker-job",
        default=None,
        help=argparse.SUPPRESS,
    )
    return ap

def main(argv: Optional[Sequence[str]] = None) -> int:
    ap = _build_arg_parser()
    ns = ap.parse_args(argv)
    if ns.v11_apply_worker_job:
        if not _env_bool("UTXO_V11_APPLY_WORKER_ACTIVE", False):
            _log("R54 APPLY worker invocation rejected: activation env missing", stream=sys.stderr)
            return V11_APPLY_WORKER_EXIT_PROTOCOL
        return int(_v11_apply_worker_main(ns.v11_apply_worker_job))
    if ns.v11_recovery_worker_job:
        if not _env_bool("UTXO_V11_RECOVERY_WORKER_ACTIVE", False):
            _log("R54 recovery worker invocation rejected: activation env missing", stream=sys.stderr)
            return V11_RECOVERY_WORKER_EXIT_PROTOCOL
        return int(_v11_recovery_worker_main(ns.v11_recovery_worker_job))
    if ns.v40_core_apply_worker_job:
        if not _env_bool("UTXO_V40_CORE_APPLY_WORKER_ACTIVE", False):
            _log("v40 CORE APPLY worker invocation rejected: activation env missing", stream=sys.stderr)
            return V40_CORE_WORKER_EXIT_PROTOCOL
        return int(_core_worker_main(ns.v40_core_apply_worker_job))

    _install_cooperative_signal_handlers()
    _emit_event("S10901", f"RUN_STARTED pipeline_version={PIPELINE_VERSION} event_catalog={EVENT_CATALOG_VERSION}")
    mode = _resolve_mode(ns.mode)
    if ns.mode:
        mode_source = "cli"
    elif _env_str("UTXO_MODE", None):
        mode_source = "environment"
    else:
        mode_source = "default"
    _emit_event("S10902", f"startup mode={mode} mode_source={mode_source}")
    if mode in {MODE_CORE_STAGE2_PREFLIGHT, MODE_CORE_STAGE2_REBUILD}:
        _log(
            f"v40 CORE backend active version={V40_CORE_PIPELINE_VERSION} "
            f"parent_v30_sha256={V40_PARENT_V30_SHA256} script_sha256={V11_PROCESS_SCRIPT_SHA256}"
        )
    dry_run = bool(ns.dry_run or _env_bool("UTXO_DRY_RUN", False))
    window_days = max(1, _env_int("UTXO_WINDOW_DAYS", 31))
    try:
        if mode == MODE_CORE_STAGE2_PREFLIGHT:
            rc = int(_core_stage2_preflight_mode())
        elif mode == MODE_CORE_STAGE2_REBUILD:
            if dry_run:
                _log("CORE_STAGE2_REBUILD dry-run: executing source preflight only; DB will not be opened for write")
                rc = int(_core_stage2_preflight_mode())
            else:
                rc = int(_core_stage2_rebuild())
        else:
            rc = int(update_utxo_v10_14(window_days=window_days, dry_run=dry_run, mode=mode))
        if rc == 0:
            _emit_event("S18909", "RUN_COMPLETED_SUCCESSFULLY")
        else:
            _emit_event("E19905", f"RUN_FAILED exit_code={rc}", stream=sys.stderr)
        _log(f"event summary {_event_summary_text()}", stream=sys.stdout if rc == 0 else sys.stderr)
        return rc
    except ControlledStopExit as e:
        _emit_event("E19903", f"CONTROLLED_STOP exit_code={e.exit_code}: {e}", stream=sys.stderr)
        _log(f"event summary {_event_summary_text()}", stream=sys.stderr)
        return int(e.exit_code)
    except RebuildResumeBlocked as e:
        _emit_event(
            "E20929",
            f"REBUILD_RESUME_BLOCKED exit_code={e.exit_code} report={e.report_path or '<unavailable>'}: {e}",
            stream=sys.stderr,
        )
        _log(f"event summary {_event_summary_text()}", stream=sys.stderr)
        return int(e.exit_code)
    except Exception as e:
        _emit_event("E19999", f"UNHANDLED_EXCEPTION type={type(e).__name__}: {e}", stream=sys.stderr)
        _log(f"event summary {_event_summary_text()}", stream=sys.stderr)
        raise


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
